    #[pg_test]
    fn embed_batch_returns_1_based_ordinals_and_vectors() {
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            Mock::given(method("POST"))
                .and(path("/embed"))
                .and(body_json(json!({
                    "model": "multilingual-e5-large",
                    "parameters": {"input_type": "passage"},
                    "inputs": [{"text": "a"}, {"text": "b"}, {"text": "c"}],
                })))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "data": [
                        {"values": [1.0, 2.0]},
                        {"values": [3.0, 4.0]},
                        {"values": [5.0, 6.0]}
                    ]
                })))
                .mount(&control_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        let rows = Spi::connect(|client| {
            client
                .select(
                    "SELECT * FROM pinecone.embed_batch(ARRAY['a', 'b', 'c']::text[])",
                    None,
                    &[],
                )
                .expect("select from pinecone.embed_batch")
                .map(|row| {
                    (
                        row.get_by_name::<i32, _>("ordinal")
                            .expect("get ordinal")
                            .expect("ordinal is NOT NULL"),
                        row.get_by_name::<Vec<f32>, _>("embedding")
                            .expect("get embedding")
                            .expect("embedding is NOT NULL"),
                    )
                })
                .collect::<Vec<_>>()
        });

        assert_eq!(
            rows,
            vec![
                (1, vec![1.0, 2.0]),
                (2, vec![3.0, 4.0]),
                (3, vec![5.0, 6.0]),
            ]
        );
    }

