    #[pg_test]
    fn rerank_happy_path_maps_zero_based_index_to_one_based_position() {
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            Mock::given(method("POST"))
                .and(path("/rerank"))
                .and(body_json(json!({
                    "model": "bge-reranker-v2-m3",
                    "query": "what is a condiment",
                    "documents": [{"text": "ketchup"}, {"text": "mustard"}],
                    "return_documents": false,
                })))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "data": [
                        {"index": 1, "score": 0.93},
                        {"index": 0, "score": 0.21}
                    ]
                })))
                .mount(&control_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        let rows = Spi::connect(|client| {
            client
                .select(
                    "SELECT * FROM pinecone.rerank('what is a condiment', \
                     ARRAY['ketchup', 'mustard'])",
                    None,
                    &[],
                )
                .expect("select from pinecone.rerank")
                .map(|row| {
                    (
                        row.get_by_name::<i32, _>("position")
                            .expect("get position")
                            .expect("position is NOT NULL"),
                        row.get_by_name::<String, _>("document")
                            .expect("get document")
                            .expect("document is NOT NULL"),
                        row.get_by_name::<f32, _>("score")
                            .expect("get score")
                            .expect("score is NOT NULL"),
                    )
                })
                .collect::<Vec<_>>()
        });

        // Response order preserved; response index 1 -> position 2 (document
        // "mustard"), response index 0 -> position 1 (document "ketchup").
        assert_eq!(
            rows,
            vec![
                (2, "mustard".to_string(), 0.93),
                (1, "ketchup".to_string(), 0.21),
            ]
        );
    }

