    // ---- pinecone.track / pinecone.untrack / pinecone.topk / pinecone.status ----
    //
    // Local-mode only: no Pinecone account, no mocks. Every test creates
    // its own uniquely-named table and starts by ensuring pgvector is installed.

    // `storage`/`backup_gate` plus `detached_at`/
    // `detach_backup_id`/`rpo` plus `read_capacity` plus `attached`
    // are appended at the end — see `status.rs`'s own `StatusRow` for
    // why (not slotted next to `mode`, to avoid renumbering every existing
    // `status_rows()[i].N` assertion).
    #[allow(clippy::type_complexity)]
    type StatusRow = (
        String,
        String,
        String,
        String,
        String,
        i32,
        Option<String>,
        Option<String>,
        Vec<String>,
        Option<i64>,
        Option<i64>,
        Option<TimestampWithTimeZone>,
        Option<String>,
        Option<String>,
        String,
        Option<String>,
        Option<TimestampWithTimeZone>,
        Option<String>,
        Option<String>,
        Option<String>,
        bool,
    );

    fn create_extension_vector() {
        Spi::run("CREATE EXTENSION IF NOT EXISTS vector").expect("create extension vector");
    }

    fn status_rows() -> Vec<StatusRow> {
        Spi::connect(|client| {
            client
                .select(
                    "SELECT * FROM pinecone.status() ORDER BY table_name",
                    None,
                    &[],
                )
                .expect("select from pinecone.status")
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("table_name")
                            .expect("get table_name")
                            .expect("table_name is NOT NULL"),
                        row.get_by_name::<String, _>("mode")
                            .expect("get mode")
                            .expect("mode is NOT NULL"),
                        row.get_by_name::<String, _>("vector_column")
                            .expect("get vector_column")
                            .expect("vector_column is NOT NULL"),
                        row.get_by_name::<String, _>("id_column")
                            .expect("get id_column")
                            .expect("id_column is NOT NULL"),
                        row.get_by_name::<String, _>("metric")
                            .expect("get metric")
                            .expect("metric is NOT NULL"),
                        row.get_by_name::<i32, _>("dimension")
                            .expect("get dimension")
                            .expect("dimension is NOT NULL"),
                        row.get_by_name::<String, _>("index_name")
                            .expect("get index_name"),
                        row.get_by_name::<String, _>("namespace")
                            .expect("get namespace"),
                        row.get_by_name::<Vec<String>, _>("metadata_columns")
                            .expect("get metadata_columns")
                            .expect("metadata_columns is NOT NULL"),
                        row.get_by_name::<i64, _>("local_rows")
                            .expect("get local_rows"),
                        row.get_by_name::<i64, _>("backlog").expect("get backlog"),
                        row.get_by_name::<TimestampWithTimeZone, _>("oldest_enqueued")
                            .expect("get oldest_enqueued"),
                        row.get_by_name::<String, _>("last_error")
                            .expect("get last_error"),
                        row.get_by_name::<String, _>("queue_state")
                            .expect("get queue_state"),
                        row.get_by_name::<String, _>("storage")
                            .expect("get storage")
                            .expect("storage is NOT NULL"),
                        row.get_by_name::<String, _>("backup_gate")
                            .expect("get backup_gate"),
                        row.get_by_name::<TimestampWithTimeZone, _>("detached_at")
                            .expect("get detached_at"),
                        row.get_by_name::<String, _>("detach_backup_id")
                            .expect("get detach_backup_id"),
                        row.get_by_name::<String, _>("rpo").expect("get rpo"),
                        row.get_by_name::<String, _>("read_capacity")
                            .expect("get read_capacity"),
                        row.get_by_name::<bool, _>("attached")
                            .expect("get attached")
                            .expect("attached is NOT NULL"),
                    )
                })
                .collect()
        })
    }

    /// Inserts 20 rows with distinct, deterministic 3-dimensional vectors.
    fn insert_fixture_vectors(table: &str) {
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) \
             SELECT i, ARRAY[sin(i)::real, cos(i * 2)::real, (i % 7)::real]::vector \
             FROM generate_series(1, 20) AS i"
        ))
        .expect("insert fixture vectors");
    }

    /// Creates `table` with vector/category/score/active columns, populates it
    /// with 20 rows (every 5th row's `category` is NULL, to give `$exists` a
    /// non-trivial split), and tracks it with all three as metadata columns.
    fn setup_filter_fixture(table: &str) {
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3), category text, \
             score int, active bool)"
        ))
        .expect("create filter fixture table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding, category, score, active) \
             SELECT i, ARRAY[sin(i)::real, cos(i * 2)::real, (i % 7)::real]::vector, \
                    CASE WHEN i % 5 = 0 THEN NULL \
                         ELSE (ARRAY['fiction', 'drama', 'comedy'])[1 + (i % 3)] END, \
                    i, \
                    (i % 2 = 0) \
             FROM generate_series(1, 20) AS i"
        ))
        .expect("insert filter fixture rows");
        Spi::run(&format!(
            "SELECT pinecone.track({}, metadata_columns => ARRAY['category', 'score', 'active'])",
            quote_literal(table)
        ))
        .expect("track filter fixture table");
    }

    /// A direct `ORDER BY <op> LIMIT k` SPI query — the ground truth `pinecone.topk`
    /// must match exactly (same operator, same distances).
    fn ground_truth(table: &str, op: &str, query: Vec<f32>, k: i64) -> Vec<(String, f64)> {
        Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT id::text AS id, (embedding {op} $1::vector)::float8 AS distance \
                         FROM {table} ORDER BY embedding {op} $1::vector LIMIT {k}"
                    ),
                    None,
                    &[DatumWithOid::from(query)],
                )
                .expect("ground truth select")
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("id")
                            .expect("get id")
                            .expect("id NOT NULL"),
                        row.get_by_name::<f64, _>("distance")
                            .expect("get distance")
                            .expect("distance NOT NULL"),
                    )
                })
                .collect()
        })
    }

    /// Calls `pinecone.topk` with `query` bound as a genuine `$1` SPI parameter
    /// (mirroring the production code path), `filter_json` (if any) spliced in
    /// as a `jsonb` literal.
    fn topk_call(
        table: &str,
        query: Vec<f32>,
        k: i32,
        filter_json: Option<&str>,
    ) -> Vec<(String, f64)> {
        let filter_literal = match filter_json {
            Some(f) => format!("{}::jsonb", quote_literal(f)),
            None => "NULL::jsonb".to_string(),
        };
        let sql = format!(
            "SELECT id, distance FROM pinecone.topk({}::regclass, $1::real[], {k}, {filter_literal})",
            quote_literal(table)
        );
        Spi::connect(|client| {
            client
                .select(&sql, None, &[DatumWithOid::from(query)])
                .expect("select from pinecone.topk")
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("id")
                            .expect("get id")
                            .expect("id NOT NULL"),
                        row.get_by_name::<f64, _>("distance")
                            .expect("get distance")
                            .expect("distance NOT NULL"),
                    )
                })
                .collect()
        })
    }

    fn assert_topk_matches_ground_truth(table: &str, op: &str, query: Vec<f32>) {
        let want = ground_truth(table, op, query.clone(), 5);
        let got = topk_call(table, query, 5, None);
        assert_eq!(got.len(), want.len(), "got = {got:?}, want = {want:?}");
        for (g, w) in got.iter().zip(want.iter()) {
            assert_eq!(g.0, w.0, "id mismatch: got = {got:?}, want = {want:?}");
            assert!(
                (g.1 - w.1).abs() < 1e-6,
                "distance mismatch for id {}: got {}, want {}",
                g.0,
                g.1,
                w.1
            );
        }
    }

    fn matching_ids(table: &str, sql_where: &str) -> Vec<String> {
        Spi::connect(|client| {
            client
                .select(
                    &format!("SELECT id::text AS id FROM {table} WHERE {sql_where}"),
                    None,
                    &[],
                )
                .expect("matching ids select")
                .map(|row| {
                    row.get_by_name::<String, _>("id")
                        .expect("get id")
                        .expect("id NOT NULL")
                })
                .collect()
        })
    }

    /// Asserts that a `pinecone.topk` `filter` and a directly-written SQL
    /// `WHERE` clause select the same set of ids (order-independent — `k` is
    /// set to cover every fixture row, so the filter alone decides membership).
    fn assert_filter_parity(table: &str, filter_json: &str, sql_where: &str) {
        let mut want_ids = matching_ids(table, sql_where);
        want_ids.sort();

        let mut got_ids: Vec<String> =
            topk_call(table, vec![0.3, -0.2, 4.0], 20, Some(filter_json))
                .into_iter()
                .map(|(id, _)| id)
                .collect();
        got_ids.sort();

        assert_eq!(
            got_ids, want_ids,
            "filter {filter_json} vs WHERE {sql_where} disagree on matching ids"
        );
    }

    #[pg_test]
    fn track_autodetect_happy_path() {
        create_extension_vector();
        Spi::run("CREATE TABLE track_autodetect (id bigint PRIMARY KEY, embedding vector(3))")
            .expect("create table");
        Spi::run("SELECT pinecone.track('track_autodetect')").expect("track");

        let rows = status_rows();
        assert_eq!(rows.len(), 1);
        let row = &rows[0];
        assert_eq!(row.0, "public.track_autodetect");
        assert_eq!(row.1, "local");
        assert_eq!(row.2, "embedding");
        assert_eq!(row.3, "id");
        assert_eq!(row.4, "cosine");
        assert_eq!(row.5, 3);
        assert_eq!(row.6, None);
        assert_eq!(row.7, None);
        assert_eq!(row.8, Vec::<String>::new());
        assert_eq!(row.9, Some(0));
    }

