    /// pgvector-absent path: each test's `CREATE EXTENSION vector` rolls back
    /// with its transaction, so skipping `create_extension_vector()` here means
    /// pgvector genuinely is not installed — track() must name the remedy, not
    /// die on the zero-row catalog lookup.
    #[pg_test]
    fn track_without_pgvector_names_create_extension() {
        Spi::run("CREATE TABLE track_no_pgvector (id bigint PRIMARY KEY, body text)")
            .expect("create table");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run("SELECT pinecone.track('track_no_pgvector')")
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("expected an error when pgvector is absent");
        assert!(
            message.contains("pgvector is not installed"),
            "message = {message}"
        );
        assert!(
            message.contains("CREATE EXTENSION vector"),
            "message = {message}"
        );
    }

