    #[pg_test]
    fn topk_excludes_rows_with_null_vector() {
        create_extension_vector();
        Spi::run("CREATE TABLE topk_null_vec (id bigint PRIMARY KEY, embedding vector(3))")
            .expect("create table");
        Spi::run(
            "INSERT INTO topk_null_vec (id, embedding) \
             SELECT i, CASE WHEN i % 3 = 0 THEN NULL \
                            ELSE ARRAY[sin(i)::real, cos(i * 2)::real, (i % 7)::real]::vector END \
             FROM generate_series(1, 10) AS i",
        )
        .expect("insert fixture rows with some NULL embeddings");
        Spi::run("SELECT pinecone.track('topk_null_vec')").expect("track");

        // i in {3, 6, 9} have a NULL embedding, leaving 7 rows with a
        // non-NULL vector; k = 20 forces the query past that count, so a
        // missing NULL guard would either error (a NULL distance) or return
        // a NULL-vector row.
        let got = topk_call("topk_null_vec", vec![0.3, -0.2, 4.0], 20, None);

        assert_eq!(got.len(), 7, "got = {got:?}");
        let ids: std::collections::BTreeSet<String> =
            got.iter().map(|(id, _)| id.clone()).collect();
        for i in 1..=10 {
            let has_null_embedding = i % 3 == 0;
            assert_eq!(
                !has_null_embedding,
                ids.contains(&i.to_string()),
                "id {i}: ids = {ids:?}"
            );
        }
    }

