    #[pg_test]
    fn topk_filter_backslash_value_is_safe_when_scs_is_off() {
        create_extension_vector();
        setup_filter_fixture("topk_bs_scs_off");

        // An adversarial row whose category ends in a backslash, inserted via
        // a bound parameter so the value itself never passes through SQL
        // literal parsing — only pinecone.topk's `filter` argument (and its
        // quote_string) are under test here.
        Spi::run_with_args(
            "INSERT INTO topk_bs_scs_off (id, embedding, category, score, active) \
             VALUES (999, ARRAY[0.0::real, 0.0::real, 0.0::real]::vector, $1, 999, true)",
            &["adversarial\\".to_string().into()],
        )
        .expect("insert adversarial row");

        Spi::run("SET standard_conforming_strings = off")
            .expect("SET standard_conforming_strings = off");

        let filter = r#"{"category": {"$eq": "adversarial\\"}}"#;
        let got = topk_call("topk_bs_scs_off", vec![0.3, -0.2, 4.0], 25, Some(filter));

        Spi::run("RESET standard_conforming_strings").expect("RESET standard_conforming_strings");

        assert_eq!(
            got.iter().map(|(id, _)| id.as_str()).collect::<Vec<_>>(),
            vec!["999"],
            "expected only the adversarial row to match, got {got:?}"
        );

        let still_there = Spi::get_one::<i64>("SELECT count(*) FROM topk_bs_scs_off")
            .expect("count topk_bs_scs_off")
            .expect("count is NOT NULL");
        assert_eq!(
            still_there, 21,
            "table must be intact: 20 fixture rows + 1 adversarial row"
        );
    }

