    #[pg_test]
    fn status_local_rows_null_without_select_privilege() {
        create_extension_vector();
        Spi::run("CREATE TABLE status_no_select (id bigint PRIMARY KEY, embedding vector(3))")
            .expect("create table");
        insert_fixture_vectors("status_no_select");
        Spi::run("SELECT pinecone.track('status_no_select')").expect("track");

        let role = format!("pinecone_status_test_role_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        // `pinecone.status()` itself must stay callable, and it must still be
        // able to read its own registry — only `status_no_select`'s SELECT
        // privilege is under test here — so grant schema USAGE (not granted
        // to PUBLIC by default) and SELECT on the registry table pinecone.tables.
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!("GRANT SELECT ON pinecone.tables TO {role}"))
            .expect("grant registry select");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let rows = status_rows();
        Spi::run("RESET ROLE").expect("RESET ROLE");

        // DROP ROLE refuses to run while the schema/table grants above still
        // reference it; DROP OWNED revokes them (it also drops any objects
        // the role owns, of which there are none here).
        Spi::run(&format!("DROP OWNED BY {role}")).expect("drop owned by role");
        Spi::run(&format!("DROP ROLE {role}")).expect("drop role");

        let row = rows
            .iter()
            .find(|r| r.0 == "public.status_no_select")
            .expect("status_no_select present");
        assert_eq!(
            row.9, None,
            "local_rows should be NULL without SELECT privilege"
        );
    }

    // ---- pinecone.promote / pinecone.demote / pinecone.sync / pinecone.set_api_key ----
    //
    // Remote mode. Every test mocks the control/data planes with
    // MockBackend; none talk to real Pinecone.

    #[pg_test]
    fn promote_happy_path() {
        create_extension_vector();
        Spi::run(
            "CREATE TABLE promote_happy_path (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        )
        .expect("create table");
        Spi::run(
            "INSERT INTO promote_happy_path (id, embedding, category) VALUES \
             (1, '[1,0]'::vector, 'x'), (2, '[0,1]'::vector, 'y')",
        )
        .expect("insert rows");

        let order: Arc<Mutex<Vec<&'static str>>> = Arc::new(Mutex::new(Vec::new()));
        let order_for_setup = Arc::clone(&order);

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });

            Mock::given(method("POST"))
                .and(path("/indexes"))
                .and(body_json(json!({
                    "name": "pv-public-promote-happy-path",
                    "vector_type": "dense",
                    "dimension": 2,
                    "metric": "cosine",
                    "spec": {"serverless": {"cloud": "aws", "region": "us-east-1"}},
                    "deletion_protection": "disabled",
                })))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;

            Mock::given(method("GET"))
                .and(path("/indexes/pv-public-promote-happy-path"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;

            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .and(body_json(json!({
                    "deleteAll": true,
                    "namespace": "public.promote_happy_path",
                })))
                .respond_with(recording_responder(
                    "delete",
                    Arc::clone(&order_for_setup),
                    ResponseTemplate::new(200).set_body_json(json!({})),
                ))
                .mount(&data_plane)
                .await;

            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .and(body_json(json!({
                    "vectors": [
                        {"id": "1", "values": [1.0, 0.0], "metadata": {"category": "x"}},
                        {"id": "2", "values": [0.0, 1.0], "metadata": {"category": "y"}},
                    ],
                    "namespace": "public.promote_happy_path",
                })))
                .respond_with(recording_responder(
                    "upsert",
                    Arc::clone(&order_for_setup),
                    ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 2})),
                ))
                .mount(&data_plane)
                .await;

            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('promote_happy_path', metadata_columns => ARRAY['category'], \
             sync_mode => 'sync')",
        )
        .expect("promote");

        assert_eq!(
            *order.lock().expect("order lock poisoned"),
            vec!["delete", "upsert"],
            "deleteAll must fire strictly before the backfill upsert"
        );

        let rows = status_rows();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].1, "remote");
        assert_eq!(rows[0].6, Some("pv-public-promote-happy-path".to_string()));
        assert_eq!(rows[0].7, Some("public.promote_happy_path".to_string()));
    }

