    /// Regression test: a bare re-promote (after a `demote()` that
    /// keeps the registry row) must reuse the row's preserved
    /// `index_name`/`namespace` — the computed `pv-<schema>-<table>` default
    /// applies only when the row has none.
    #[pg_test]
    fn promote_bare_reuses_custom_index_name_after_demote() {
        create_extension_vector();
        Spi::run("CREATE TABLE promote_reuse_name (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let create_names: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
        let create_count: Arc<Mutex<u32>> = Arc::new(Mutex::new(0));
        let (names_for_mock, count_for_mock) =
            (Arc::clone(&create_names), Arc::clone(&create_count));

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            let index_body_for_create = index_body.clone();
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("create-index body should be JSON");
                    names_for_mock
                        .lock()
                        .expect("create_names lock poisoned")
                        .push(body["name"].as_str().unwrap_or_default().to_string());
                    let mut count = count_for_mock.lock().expect("create_count lock poisoned");
                    *count += 1;
                    if *count == 1 {
                        ResponseTemplate::new(201).set_body_json(index_body_for_create.clone())
                    } else {
                        // Second promote: the index already exists — 409,
                        // driving promote()'s describe/validate path instead
                        // of a fresh create.
                        ResponseTemplate::new(409).set_body_json(json!({
                            "error": {"code": "ALREADY_EXISTS", "message": "index already exists"},
                            "status": 409
                        }))
                    }
                })
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/indexes/custom-idx"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run("SELECT pinecone.promote('promote_reuse_name', index_name => 'custom-idx')")
            .expect("promote with a custom index_name");
        Spi::run("SELECT pinecone.demote('promote_reuse_name')").expect("demote");

        // Bare re-promote: index_name is NULL, but the registry row still
        // has 'custom-idx' from before — the default pv-<schema>-<table>
        // name must NOT apply here.
        Spi::run("SELECT pinecone.promote('promote_reuse_name')").expect("bare re-promote");

        assert_eq!(
            *create_names.lock().expect("create_names lock poisoned"),
            vec!["custom-idx".to_string(), "custom-idx".to_string()],
            "both promotes must target the custom index name, never the computed default"
        );
        assert_eq!(status_rows()[0].6, Some("custom-idx".to_string()));
    }

    #[pg_test]
    fn secret_store_key_used_when_guc_unset() {
        create_extension_vector();
        Spi::run("CREATE TABLE promote_secret_key (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });

            Mock::given(method("POST"))
                .and(path("/indexes"))
                .and(header("Api-Key", "secret-stored-key"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/indexes/pv-public-promote-secret-key"))
                .and(header("Api-Key", "secret-stored-key"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .and(header("Api-Key", "secret-stored-key"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                .mount(&data_plane)
                .await;

            (control_plane, data_plane)
        });

        // The key is stored bound to the *real* mock's URL; the session GUC
        // is left pointed at an address guaranteed not to resolve
        // (`.invalid`, reserved for exactly this by RFC 2606) — resolution
        // via the stored secret must use the *stored* control_plane_url,
        // never this session GUC, or `promote` would fail to even connect.
        Spi::run_with_args(
            "SELECT pinecone.set_api_key($1, $2)",
            &[
                "secret-stored-key".into(),
                backend.control_plane_url.clone().into(),
            ],
        )
        .expect("set_api_key");
        Spi::run("SET pinecone.control_plane_url = 'http://pg_pinecone-test.invalid'")
            .expect("SET pinecone.control_plane_url to an unrelated, unresolvable address");

        Spi::run("SELECT pinecone.promote('promote_secret_key', sync_mode => 'sync')")
            .expect("promote");

        assert_eq!(status_rows()[0].1, "remote");
    }

    /// pinecone.embed (and its siblings) must honor the stored key like every
    /// other pinecone.* remote call — bound to the *stored* URL, ignoring the
