    #[pg_test]
    fn effective_api_key_permission_denied_names_both_remedies() {
        create_extension_vector();
        Spi::run("CREATE TABLE promote_perm_denied (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let role = format!("pinecone_promote_perm_role_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!(
            "GRANT SELECT, INSERT, UPDATE ON pinecone.tables TO {role}"
        ))
        .expect("grant registry crud");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run("SELECT pinecone.promote('promote_perm_denied')")
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        Spi::run("RESET ROLE").expect("RESET ROLE");

        Spi::run(&format!("DROP OWNED BY {role}")).expect("drop owned by role");
        Spi::run(&format!("DROP ROLE {role}")).expect("drop role");

        let message = outcome.expect_err("expected an error for a role without secret access");
        assert!(
            message.contains("SET pinecone.api_key"),
            "message = {message}"
        );
        assert!(
            message.contains("GRANT SELECT ON pinecone.secret"),
            "message = {message}"
        );
    }

    /// SECURITY regression (0.2 review, HIGH): a role with registry
    /// INSERT/UPDATE but no secret access could bypass promote()'s stored-key
    /// gate by hand-forging a mode='remote' registry row for its own table and
    /// attaching pinecone._sync_trigger itself — the SECURITY DEFINER function
    /// then pushes (or TRUNCATE→deleteAll's) under the stored key. CREATE
    /// TRIGGER checks EXECUTE on the function at creation time, so the REVOKE
    /// FROM PUBLIC must make this exact sequence fail with permission denied.
    #[pg_test]
    fn sync_trigger_cannot_be_hand_attached_without_execute_grant() {
        create_extension_vector();

        let role = format!("pinecone_trigger_forge_role_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!(
            "GRANT SELECT, INSERT, UPDATE ON pinecone.tables TO {role}"
        ))
        .expect("grant registry crud");
        Spi::run(&format!("GRANT CREATE ON SCHEMA public TO {role}")).expect("grant create");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        // The attacker's own table plus the forged remote registration both
        // still succeed — the boundary is the trigger attach, not the row.
        Spi::run("CREATE TABLE forge_target (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("attacker creates own table");
        Spi::run(
            "INSERT INTO pinecone.tables (relid, vector_column, id_column, metric, dimension, \
             metadata_columns, mode, index_name, namespace) \
             VALUES ('forge_target'::regclass, 'embedding', 'id', 'cosine', 2, '{}', 'remote', \
             'victim-index', 'attacker-ns')",
        )
        .expect("forged registry row (not itself the boundary)");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(
                "CREATE TRIGGER pg_pinecone_sync_ins AFTER INSERT ON forge_target \
                 REFERENCING NEW TABLE AS new_table FOR EACH STATEMENT \
                 EXECUTE FUNCTION pinecone._sync_trigger()",
            )
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        Spi::run("RESET ROLE").expect("RESET ROLE");
        // No explicit role/table cleanup: DROP OWNED can't drop a table the
        // current SPI statement is still using, and the test transaction's
        // rollback removes the role, table, and grants anyway.

        let message =
            outcome.expect_err("hand-attaching pinecone._sync_trigger must be permission-denied");
        assert!(message.contains("permission denied"), "message = {message}");
    }

    /// Regression test: with `pinecone.secret` completely empty (nobody
    /// ever ran `pinecone.set_api_key`) and no session GUC key, resolution
    /// must raise the ordinary two-remedy error — not panic with `SpiError::
