        assert_eq!(
            trigger_names("demote_basic"),
            vec![
                "pg_pinecone_sync_del".to_string(),
                "pg_pinecone_sync_ins".to_string(),
                "pg_pinecone_sync_trunc".to_string(),
                "pg_pinecone_sync_upd".to_string(),
            ]
        );

        Spi::run("SELECT pinecone.demote('demote_basic')").expect("demote");

