    /// Regression test: `pinecone.demote` must clear any rows the
    /// demoted table still has queued in `pinecone.outbox` — an `'async'`
    /// table can have a non-empty backlog at demote time (nothing has
    /// drained it yet), and those rows must not survive the demote to
    /// replay later.
    #[pg_test]
    fn demote_clears_queued_outbox_rows() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("demote_clears_outbox", "async");

        Spi::run(
            "INSERT INTO demote_clears_outbox (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert");
        assert_eq!(
            outbox_count("demote_clears_outbox"),
            1,
            "async insert must enqueue, not drain inline"
        );
        assert!(
            upserts.lock().expect("lock poisoned").is_empty(),
            "async insert must make zero HTTP calls"
        );
        assert!(deletes.lock().expect("lock poisoned").is_empty());

        Spi::run("SELECT pinecone.demote('demote_clears_outbox')").expect("demote");

        assert_eq!(
            outbox_count("demote_clears_outbox"),
            0,
            "demote must clear the demoted relid's queued outbox rows"
        );
    }

    /// Regression test, the full divergence scenario: a stale
    /// `pinecone.outbox` row surviving `pinecone.demote` must never replay
    /// over a later re-promote's fresh backfill. Without the fix, the
    /// pre-demote row (embedding `[1,0]`) sits in the outbox untouched by
    /// `demote`; the row is then updated to `[9,9]` while local, and a
    /// `sync_mode => 'sync'` re-promote backfills that fresh value — but the
    /// very next write's inline drain would still replay the stale `[1,0]`
    /// upsert queued from before the demote, clobbering the backfill.
    #[pg_test]
    fn demote_then_repromote_never_replays_stale_outbox_row() {
        create_extension_vector();
        let (_backend, upserts, _deletes) =
            setup_sync_trigger_table_mode("demote_no_stale_replay", "async");

        Spi::run(
            "INSERT INTO demote_no_stale_replay (id, embedding, category) VALUES \
             (1, '[1,0]', 'a')",
        )
        .expect("insert enqueues under async mode");
        assert_eq!(outbox_count("demote_no_stale_replay"), 1);
        assert!(
            upserts.lock().expect("lock poisoned").is_empty(),
            "async insert must make zero HTTP calls"
        );

        Spi::run("SELECT pinecone.demote('demote_no_stale_replay')").expect("demote");
        assert_eq!(
            outbox_count("demote_no_stale_replay"),
            0,
            "demote must clear the stale queued row before it can diverge from local state"
        );

        // Diverges from the stale queued payload while demoted (no trigger
        // is installed, so this plain UPDATE never touches the outbox).
        Spi::run(
            "UPDATE demote_no_stale_replay SET embedding = '[9,9]', category = 'b' WHERE id = 1",
        )
        .expect("update while demoted");

        Spi::run("SELECT pinecone.promote('demote_no_stale_replay', sync_mode => 'sync')")
            .expect("re-promote with sync_mode => 'sync' backfills the fresh row");

        // The re-promote's own backfill should have pushed id 1 at its
        // fresh [9,9] value — assert that up front, before the next write's
        // drain could possibly add a second, stale copy.
        let after_backfill = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            vectors_by_id(after_backfill.last().expect("backfill upsert recorded"))["1"]["values"],
            json!([9.0, 9.0]),
            "backfill must push the current (post-update) row, not the stale pre-demote one"
        );
        drop(after_backfill);

        // Another write: under `sync_mode = 'sync'` this enqueues and then
        // drains inline — if the demote hadn't cleared the stale row above,
        // this drain would still find it and replay it now.
        Spi::run(
            "INSERT INTO demote_no_stale_replay (id, embedding, category) VALUES (2, '[0,1]', 'c')",
        )
        .expect("second write drains inline under sync_mode = 'sync'");

        let recorded = upserts.lock().expect("lock poisoned").clone();
        for body in &recorded {
            if let Some(vector) = vectors_by_id(body).get("1") {
                assert_eq!(
                    vector["values"],
                    json!([9.0, 9.0]),
                    "id 1 must never be pushed with its stale pre-demote [1,0] value: {recorded:?}"
                );
            }
        }
        assert_eq!(
            outbox_count("demote_no_stale_replay"),
            0,
            "sync-mode drain must leave the outbox empty"
        );
    }

    #[pg_test]
    fn sync_deletes_all_then_reupserts() {
        create_extension_vector();
        Spi::run("CREATE TABLE sync_basic (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run(
            "INSERT INTO sync_basic (id, embedding) VALUES \
             (1, '[1,0]'::vector), (2, '[0,1]'::vector)",
        )
        .expect("insert rows");

        let order: Arc<Mutex<Vec<&'static str>>> = Arc::new(Mutex::new(Vec::new()));
        let order_for_setup = Arc::clone(&order);

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/indexes/pv-public-sync-basic"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;

            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .and(body_json(json!({
                    "deleteAll": true,
                    "namespace": "public.sync_basic",
                })))
                .respond_with(recording_responder(
                    "delete",
                    Arc::clone(&order_for_setup),
                    ResponseTemplate::new(200).set_body_json(json!({})),
                ))
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .and(body_json(json!({
                    "vectors": [
                        {"id": "1", "values": [1.0, 0.0]},
                        {"id": "2", "values": [0.0, 1.0]},
                    ],
                    "namespace": "public.sync_basic",
                })))
                .respond_with(recording_responder(
                    "upsert",
                    Arc::clone(&order_for_setup),
                    ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 2})),
                ))
                .mount(&data_plane)
                .await;

            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run("SELECT pinecone.promote('sync_basic', sync_mode => 'sync')").expect("promote");
        order.lock().expect("order lock poisoned").clear();

        Spi::run("SELECT pinecone.sync('sync_basic')").expect("sync");

        assert_eq!(
            *order.lock().expect("order lock poisoned"),
            vec!["delete", "upsert"],
            "sync must deleteAll before re-upserting"
        );
    }

    /// `pinecone.sync` gets the same
    /// table-ownership gate as the lifecycle verbs — before this fix, any
    /// role with EXECUTE (PUBLIC by default) could fire a `sync_mode='sync'`
    /// table's inline `deleteAll(namespace)` against the stored account
    /// BEFORE any ACL-protected registry write was ever attempted. The gate
    /// runs before the registry read (authorization before diagnosis — same
    /// convention as `lifecycle_demote_index_requires_table_ownership`), so
    /// a merely-tracked table proves it: the non-owner gets "must own", not
    /// "is not promoted" and not a pinecone.tables permission error. The owner
    /// path staying green is covered by `sync_deletes_all_then_reupserts`
    /// (superuser passes `object_ownercheck` trivially, as the real owner
    /// would).
    #[pg_test]
    fn sync_requires_table_ownership() {
        create_extension_vector();
        let table = "sync_own_guard";
        let role = "sync_own_guard_role";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!("SELECT pinecone.track('{table}')")).expect("track");
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!("SELECT pinecone.sync('{table}')")).expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome.expect_err("a non-owner must not be able to sync");
        assert!(message.contains("must own"), "message = {message}");
    }

