    #[pg_test]
    fn sync_trigger_security_definer_allows_writer_without_key_access() {
        create_extension_vector();
        let (_backend, upserts, _deletes) = setup_sync_trigger_table("sync_secdef");

        // Simulate a writer session with no key access at all: clear the
        // session GUC. `setup_sync_trigger_table` (via `point_at_mock`) has
        // already stored the key bound to the mock's own URL, so from here
        // on it's only readable through pinecone._sync_trigger's SECURITY
        // DEFINER context.
        Spi::run("SET pinecone.api_key = ''").expect("clear api_key GUC");

        Spi::run("CREATE ROLE sync_writer_norights").expect("create role");
        Spi::run("GRANT INSERT ON sync_secdef TO sync_writer_norights").expect("grant insert");

        let can_select_secret = Spi::get_one::<bool>(
            "SELECT pg_catalog.has_table_privilege('sync_writer_norights', \
             'pinecone.secret'::regclass, 'SELECT')",
        )
        .expect("has_table_privilege query")
        .expect("has_table_privilege is NOT NULL");
        assert!(
            !can_select_secret,
            "test setup: the writer role must not have SELECT on pinecone.secret"
        );

        Spi::run("SET ROLE sync_writer_norights").expect("set role");
        Spi::run("INSERT INTO sync_secdef (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert as a role with no key access should succeed via SECURITY DEFINER");
        Spi::run("RESET ROLE").expect("reset role");

        Spi::run("REVOKE INSERT ON sync_secdef FROM sync_writer_norights").expect("revoke insert");
        Spi::run("DROP ROLE sync_writer_norights").expect("drop role");

        let recorded = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(recorded.len(), 1, "recorded = {recorded:?}");
        assert_eq!(
            vectors_by_id(&recorded[0])["1"]["values"],
            json!([1.0, 0.0])
        );
        assert_eq!(outbox_count("sync_secdef"), 0);
    }

    /// Mounts catch-all GET/POST/DELETE mocks on `server` that record every
    /// request they receive by incrementing `count` — used to prove a mock
    /// server nobody is *supposed* to talk to receives zero requests (see
    /// [`sync_trigger_stored_key_ignores_session_control_plane_url_guc`]).
    async fn mount_recording_catchall(server: &wiremock::MockServer, count: Arc<Mutex<u32>>) {
        for verb in ["GET", "POST", "DELETE"] {
            let count = Arc::clone(&count);
            Mock::given(method(verb))
                .respond_with(move |_req: &Request| {
                    *count.lock().expect("catchall count lock poisoned") += 1;
                    ResponseTemplate::new(200).set_body_json(json!({}))
                })
                .mount(server)
                .await;
        }
    }

    /// Regression test: a writer with `INSERT` on a promoted table
    /// but *no key of their own* must never have the *stored* key sent to a
    /// control-plane URL the writer's own session merely happens to have
    /// `SET` — that would let any writer exfiltrate the stored key to a
    /// server they control. Proven end-to-end: the writer session points
    /// `pinecone.control_plane_url` at a second ("attacker") mock server
    /// that records every request it receives, then inserts a row; the push
    /// must land on the *stored* URL's (legitimate) server, and the attacker
    /// server must receive zero requests.
    #[pg_test]
    fn sync_trigger_stored_key_ignores_session_control_plane_url_guc() {
        create_extension_vector();
        let (_legit, upserts, _deletes) = setup_sync_trigger_table("sync_no_exfil");

        let attacker_hits = Arc::new(Mutex::new(0u32));
        let (hits_a, hits_b) = (Arc::clone(&attacker_hits), Arc::clone(&attacker_hits));
        let attacker = MockBackend::start(move |control_plane, data_plane| async move {
            mount_recording_catchall(&control_plane, hits_a).await;
            mount_recording_catchall(&data_plane, hits_b).await;
            (control_plane, data_plane)
        });

        let role = format!("pinecone_no_exfil_writer_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT INSERT ON sync_no_exfil TO {role}")).expect("grant insert");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        Spi::run("SET pinecone.api_key = ''").expect("writer session has no key of its own");
        Spi::run(&format!(
            "SET pinecone.control_plane_url = '{}'",
            attacker.control_plane_url
        ))
        .expect("writer session points control_plane_url at the attacker server");

        Spi::run("INSERT INTO sync_no_exfil (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect(
                "insert as a role with no key access, GUC pointed at an attacker server, \
                 should still succeed via the stored key/url",
            );
        Spi::run("RESET ROLE").expect("RESET ROLE");

        Spi::run(&format!("REVOKE INSERT ON sync_no_exfil FROM {role}")).expect("revoke insert");
        Spi::run(&format!("DROP ROLE {role}")).expect("drop role");

        assert_eq!(
            *attacker_hits.lock().expect("attacker hits lock poisoned"),
            0,
            "the stored key must never be sent to the session's own control_plane_url GUC"
        );
        let recorded = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(recorded.len(), 1, "recorded = {recorded:?}");
        assert_eq!(
            vectors_by_id(&recorded[0])["1"]["values"],
            json!([1.0, 0.0])
        );
        assert_eq!(outbox_count("sync_no_exfil"), 0);
    }

    /// Runs `f` inside a Postgres subtransaction, then unconditionally rolls
    /// it back — the C-level primitive `SAVEPOINT` / `ROLLBACK TO SAVEPOINT`
    /// compile down to (`BeginInternalSubTransaction` /
    /// `RollbackAndReleaseCurrentSubTransaction`, the same mechanism
    /// PL/pgSQL's `EXCEPTION` block uses). Plain SQL `SAVEPOINT` text can't
    /// go through `Spi::run` here: SPI rejects transaction-control statements
    /// (`SpiError::Transaction`) because they're only meaningful as
    /// top-level client-protocol commands, not nested SPI-executed ones —
    /// confirmed empirically (red) before writing this helper.
    fn run_then_rollback_subtransaction(f: impl FnOnce()) {
        let oldcontext = unsafe { pg_sys::CurrentMemoryContext };
        let oldowner = unsafe { pg_sys::CurrentResourceOwner };
        unsafe {
            pg_sys::BeginInternalSubTransaction(std::ptr::null());
            pg_sys::MemoryContextSwitchTo(oldcontext);
        }
        f();
        unsafe {
            pg_sys::RollbackAndReleaseCurrentSubTransaction();
            pg_sys::MemoryContextSwitchTo(oldcontext);
            pg_sys::CurrentResourceOwner = oldowner;
        }
    }

    /// Like [`run_then_rollback_subtransaction`], but for `f`s *expected* to
    /// raise a Postgres `ERROR`: catches it (via `PgTryBuilder`, returning the
    /// message) before rolling back to the savepoint. This — not a bare
    /// `PgTryBuilder(...).execute()` with no savepoint at all — is what a test
    /// needs to keep querying the database afterward: an `AFTER STATEMENT`
    /// trigger failure (unlike a plain top-level function-call error) aborts
    /// the *whole* enclosing transaction if nothing established a savepoint
    /// first, taking down everything set up earlier in the test too
    /// (confirmed empirically — red — before writing this helper).
    fn run_in_subtransaction_expecting_error(f: impl FnOnce() + std::panic::UnwindSafe) -> String {
        let oldcontext = unsafe { pg_sys::CurrentMemoryContext };
        let oldowner = unsafe { pg_sys::CurrentResourceOwner };
        unsafe {
            pg_sys::BeginInternalSubTransaction(std::ptr::null());
            pg_sys::MemoryContextSwitchTo(oldcontext);
        }
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            f();
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        unsafe {
            pg_sys::RollbackAndReleaseCurrentSubTransaction();
            pg_sys::MemoryContextSwitchTo(oldcontext);
            pg_sys::CurrentResourceOwner = oldowner;
        }
        outcome.expect_err("expected f to raise a Postgres ERROR")
    }

    #[pg_test]
    fn sync_trigger_rollback_leaves_orphan_then_sync_repairs() {
        create_extension_vector();
        let (_backend, upserts, deletes) = setup_sync_trigger_table("sync_orphan");

        run_then_rollback_subtransaction(|| {
            Spi::run("INSERT INTO sync_orphan (id, embedding, category) VALUES (1, '[1,0]', 'a')")
                .expect("insert inside the subtransaction");
        });

        let count = Spi::get_one::<i64>("SELECT count(*) FROM sync_orphan")
            .expect("count query")
            .expect("count is NOT NULL");
        assert_eq!(count, 0, "the insert must have been rolled back locally");

        let recorded_upserts = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            recorded_upserts.len(),
            1,
            "the AFTER STATEMENT trigger's push already fired before the rollback undid the \
             insert (documented fail-closed/orphan contract) — recorded = {recorded_upserts:?}"
        );
        assert_eq!(
            outbox_count("sync_orphan"),
            0,
            "the enqueue+inline-drain+row-delete all happened inside the rolled-back \
             subtransaction — only the already-irrevocable HTTP push above is the orphan"
        );

        deletes.lock().expect("lock poisoned").clear();
        Spi::run("SELECT pinecone.sync('sync_orphan')").expect("sync repairs the orphan");

        let repair_deletes = deletes.lock().expect("lock poisoned").clone();
        assert_eq!(
            repair_deletes.len(),
            1,
            "repair_deletes = {repair_deletes:?}"
        );
        assert_eq!(repair_deletes[0]["deleteAll"], json!(true));
    }

    // ---- pinecone.outbox ----
    //
    // The `sync_trigger_*` tests above already pin the 'sync'-mode fixture
    // (immediate inline drain, byte-identical request bodies to 0.2's own
    // pinned fixtures — see `setup_sync_trigger_table`/`setup_sync_trigger_table_mode`).
    // These exercise the 'async' default instead: enqueue-only, zero HTTP.
    //
    // NOTE (deferred): `attempts`/`last_error` persistence *surviving* a
    // later rollback isn't tested here. It would need `_drain_relid`'s own
    // `attempts` update to commit independently of whatever transaction called
    // it — a true autonomous transaction, which only a separately-connected
    // worker has. Within one transaction, any subtransaction/rollback
    // wrapper that could observe the update also necessarily undoes it (see
    // `outbox_sync_mode_failure_errors_statement_and_leaves_outbox_empty`
    // below for the in-transaction half of this: a 'sync'-mode failure rolls the
    // enqueue back too, leaving the outbox empty, not a parked row).

    #[pg_test]
    fn outbox_insert_enqueues_upsert_with_zero_http() {
        create_extension_vector();
        let (_backend, upserts, deletes) = setup_sync_trigger_table_mode("outbox_ins", "async");

        Spi::run(
            "INSERT INTO outbox_ins (id, embedding, category) VALUES \
             (1, '[1,0]', 'a'), (2, '[0,1]', NULL), (3, NULL, 'c')",
        )
        .expect("multi-row insert");

        assert!(
            upserts.lock().expect("lock poisoned").is_empty(),
            "async tables must not push synchronously"
        );
        assert!(deletes.lock().expect("lock poisoned").is_empty());

        let rows = outbox_rows("outbox_ins");
        assert_eq!(rows.len(), 1, "rows = {rows:?}");
        assert_eq!(rows[0].op, "upsert");
        let vectors = batch_vectors_by_id(rows[0].payload.as_ref().expect("payload"));
        assert_eq!(vectors.len(), 2, "vectors = {vectors:?}");
        // Note: jsonb (unlike the HTTP request bodies `vectors_by_id` above
        // reads) round-trips whole-number floats without a decimal point —
        // `1.0` comes back as `1`, not `1.0`.
        assert_eq!(vectors["1"]["values"], json!([1, 0]));
        assert_eq!(vectors["1"]["metadata"], json!({"category": "a"}));
        assert_eq!(vectors["2"]["values"], json!([0, 1]));
        assert_eq!(
            vectors["2"]["metadata"],
            json!({}),
            "NULL category must be omitted from the metadata object: {:?}",
            vectors["2"]
        );
        assert!(
            !vectors.contains_key("3"),
            "row with NULL vector must be excluded: {vectors:?}"
        );
    }

