    #[pg_test]
    fn outbox_truncate_enqueues_delete_all() {
        create_extension_vector();
        let (_backend, upserts, deletes) = setup_sync_trigger_table_mode("outbox_trunc", "async");
        Spi::run("INSERT INTO outbox_trunc (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("seed row");

        Spi::run("TRUNCATE outbox_trunc").expect("truncate");

        assert!(upserts.lock().expect("lock poisoned").is_empty());
        assert!(deletes.lock().expect("lock poisoned").is_empty());

        let rows = outbox_rows("outbox_trunc");
        let last = rows.last().expect("at least the truncate's own row");
        assert_eq!(last.op, "delete_all");
        assert!(
            last.payload.is_none(),
            "delete_all payload must be NULL: {last:?}"
        );
    }

    #[pg_test]
    fn outbox_rollback_leaves_outbox_empty() {
        create_extension_vector();
        let (_backend, _upserts, _deletes) =
            setup_sync_trigger_table_mode("outbox_rollback", "async");

        run_then_rollback_subtransaction(|| {
            Spi::run(
                "INSERT INTO outbox_rollback (id, embedding, category) VALUES (1, '[1,0]', 'a')",
            )
            .expect("insert inside the subtransaction");
        });

        let count = Spi::get_one::<i64>("SELECT count(*) FROM outbox_rollback")
            .expect("count query")
            .expect("count is NOT NULL");
        assert_eq!(count, 0, "the insert must have been rolled back locally");
        assert_eq!(
            outbox_count("outbox_rollback"),
            0,
            "async tables enqueue-only — a rolled-back statement's enqueue rolls back with it, \
             so nothing is ever pushed for it (contrast \
             sync_trigger_rollback_leaves_orphan_then_sync_repairs, whose 'sync' table drains \
             inline *before* the rollback and so still leaks the HTTP push)"
        );
    }

    #[pg_test]
    fn outbox_fifo_is_independent_per_relid() {
        create_extension_vector();
        let (_backend_a, _upserts_a, _deletes_a) =
            setup_sync_trigger_table_mode("outbox_fifo_a", "async");
        let (_backend_b, _upserts_b, _deletes_b) =
            setup_sync_trigger_table_mode("outbox_fifo_b", "async");

        Spi::run("INSERT INTO outbox_fifo_a (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("a insert 1");
        Spi::run("INSERT INTO outbox_fifo_b (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("b insert 1");
        Spi::run("DELETE FROM outbox_fifo_a WHERE id = 1").expect("a delete");
        Spi::run("INSERT INTO outbox_fifo_b (id, embedding, category) VALUES (2, '[0,1]', 'b')")
            .expect("b insert 2");

        let rows_a = outbox_rows("outbox_fifo_a");
        let rows_b = outbox_rows("outbox_fifo_b");

        assert_eq!(rows_a.len(), 2, "rows_a = {rows_a:?}");
        assert_eq!(rows_a[0].op, "upsert");
        assert_eq!(rows_a[1].op, "delete");
        assert_eq!(
            batch_delete_ids(rows_a[1].payload.as_ref().expect("payload")),
            BTreeSet::from(["1".to_string()])
        );

        assert_eq!(rows_b.len(), 2, "rows_b = {rows_b:?}");
        assert_eq!(rows_b[0].op, "upsert");
        assert_eq!(
            batch_vectors_by_id(rows_b[0].payload.as_ref().expect("payload"))
                .keys()
                .cloned()
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["1".to_string()]),
            "b's first row must be its own id 1, unperturbed by a's interleaved writes"
        );
        assert_eq!(rows_b[1].op, "upsert");
        assert_eq!(
            batch_vectors_by_id(rows_b[1].payload.as_ref().expect("payload"))
                .keys()
                .cloned()
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["2".to_string()])
        );
    }

