    /// SECURITY regression test: a client error surfacing through
    /// `_drain_relid` (recorded on the outbox row, and re-raised as the
    /// statement's own error) must never carry the API key — proven with a
    /// deliberately distinctive key value.
    #[pg_test]
    fn outbox_drain_error_never_leaks_api_key() {
        create_extension_vector();
        Spi::run("CREATE TABLE outbox_no_leak (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let distinctive_key = format!("distinctive-secret-key-{}", std::process::id());
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-outbox-no-leak").await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(
                    ResponseTemplate::new(500).set_body_json(json!({"message": "internal error"})),
                )
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        Spi::run(&format!(
            "SET pinecone.control_plane_url = '{}'",
            backend.control_plane_url
        ))
        .expect("SET pinecone.control_plane_url");
        Spi::run(&format!("SET pinecone.api_key = '{distinctive_key}'"))
            .expect("SET pinecone.api_key");
        Spi::run_with_args(
            "SELECT pinecone.set_api_key($1, $2)",
            &[
                distinctive_key.clone().into(),
                backend.control_plane_url.clone().into(),
            ],
        )
        .expect("set_api_key");
        Spi::run(
            "SELECT pinecone.promote('outbox_no_leak', index_name => 'pv-public-outbox-no-leak', \
             sync_mode => 'sync')",
        )
        .expect("promote sync");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run("INSERT INTO outbox_no_leak (id, embedding) VALUES (1, '[1,0]')")
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("expected an error from the mocked 500");
        assert!(
            !message.contains(&distinctive_key),
            "raised message must not leak the api key: {message}"
        );
    }

    #[pg_test]
    fn status_reports_backlog_for_async_table_zero_for_drained_sync_table() {
        create_extension_vector();
        let (_backend_async, upserts_async, _deletes_async) =
            setup_sync_trigger_table_mode("status_outbox_async", "async");
        let (_backend_sync, upserts_sync, _deletes_sync) =
            setup_sync_trigger_table_mode("status_outbox_sync", "sync");

        Spi::run(
            "INSERT INTO status_outbox_async (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert async");
        Spi::run(
            "INSERT INTO status_outbox_sync (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert sync");

        let rows = status_rows();
        let async_row = rows
            .iter()
            .find(|r| r.0 == "public.status_outbox_async")
            .expect("async row present");
        let sync_row = rows
            .iter()
            .find(|r| r.0 == "public.status_outbox_sync")
            .expect("sync row present");

        assert_eq!(async_row.10, Some(1), "async table has one queued row");
        assert!(async_row.11.is_some(), "oldest_enqueued must be set");
        assert_eq!(
            sync_row.10,
            Some(0),
            "sync table drains inline — nothing queued"
        );
        assert!(sync_row.11.is_none());
        assert!(sync_row.12.is_none());

        assert!(upserts_async.lock().expect("lock poisoned").is_empty());
        assert_eq!(upserts_sync.lock().expect("lock poisoned").len(), 1);
    }

    /// ACL regression test, mirroring `sync_trigger_cannot_be_hand_attached_without_execute_grant`:
    /// an unprivileged role can neither touch `pinecone.outbox` directly nor
    /// call `pinecone._drain_relid` — `REVOKE ALL`/`REVOKE EXECUTE FROM PUBLIC`
    /// are the whole access model (see `outbox.rs`'s module rustdoc).
    #[pg_test]
    fn outbox_acl_denies_direct_access_and_drain() {
        create_extension_vector();
        Spi::run("CREATE TABLE outbox_acl_target (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run(
            "INSERT INTO pinecone.tables (relid, vector_column, id_column, metric, dimension, \
             metadata_columns, mode, sync_mode, index_name, namespace) \
             VALUES ('outbox_acl_target'::regclass, 'embedding', 'id', 'cosine', 2, '{}', \
             'remote', 'async', 'acl-index', 'acl-ns')",
        )
        .expect("seed registry row");

        let role = format!("pinecone_outbox_acl_role_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");

        for (label, stmt) in [
            ("SELECT", "SELECT * FROM pinecone.outbox".to_string()),
            (
                "INSERT",
                "INSERT INTO pinecone.outbox (relid, op) VALUES \
                 ('outbox_acl_target'::regclass, 'upsert')"
                    .to_string(),
            ),
            (
                "UPDATE",
                "UPDATE pinecone.outbox SET attempts = attempts + 1".to_string(),
            ),
            ("DELETE", "DELETE FROM pinecone.outbox".to_string()),
            (
                "EXECUTE _drain_relid",
                "SELECT pinecone._drain_relid('outbox_acl_target'::regclass::oid)".to_string(),
            ),
        ] {
            let outcome: Result<(), String> = PgTryBuilder::new(|| {
                Spi::run(&stmt).expect("statement should raise a Postgres ERROR, not an SpiError");
                Ok(())
            })
            .catch_others(|caught| Err(error_message(caught)))
            .execute();
            let message = outcome.expect_err(&format!("{label} on pinecone.outbox must be denied"));
            assert!(
                message.contains("permission denied"),
                "{label}: message = {message}"
            );
        }

        Spi::run("RESET ROLE").expect("RESET ROLE");
    }

    /// MINOR fix regression test: `pinecone._outbox_stats` is `SECURITY
    /// DEFINER` and answers per-table backlog/oldest_enqueued/last_error —
    /// `REVOKE EXECUTE FROM PUBLIC` (see `outbox.rs`) must deny it directly
    /// to a role with only schema `USAGE`, while `pinecone.status()` (granted
    /// `SELECT` on `pinecone.tables` too, nothing on `pinecone.outbox` or
    /// `_outbox_stats` itself) still succeeds for that same role — with NULL
    /// backlog columns, not the real numbers and not an error.
    #[pg_test]
    fn outbox_stats_denies_direct_call_but_status_degrades_to_null_for_unprivileged_role() {
        create_extension_vector();
        Spi::run(
            "CREATE TABLE outbox_stats_acl_target (id bigint PRIMARY KEY, embedding vector(2))",
        )
        .expect("create table");
        Spi::run(
            "INSERT INTO pinecone.tables (relid, vector_column, id_column, metric, dimension, \
             metadata_columns, mode, sync_mode, index_name, namespace) \
             VALUES ('outbox_stats_acl_target'::regclass, 'embedding', 'id', 'cosine', 2, '{}', \
             'remote', 'async', 'acl-stats-index', 'acl-stats-ns')",
        )
        .expect("seed registry row");
        Spi::run(
            "INSERT INTO pinecone.outbox (relid, op) VALUES \
             ('outbox_stats_acl_target'::regclass, 'upsert')",
        )
        .expect("seed one queued outbox row");

        let role = format!("pinecone_outbox_stats_acl_role_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!("GRANT SELECT ON pinecone.tables TO {role}"))
            .expect("grant tables select");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(
                "SELECT * FROM pinecone._outbox_stats('outbox_stats_acl_target'::regclass::oid)",
            )
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome.expect_err("direct call to _outbox_stats must be denied");
        assert!(message.contains("permission denied"), "message = {message}");

        let rows = status_rows();
        let row = rows
            .iter()
            .find(|r| r.0 == "public.outbox_stats_acl_target")
            .expect("status row visible to the unprivileged role");
        assert_eq!(row.10, None, "backlog must be NULL, not the real count");
        assert_eq!(row.11, None, "oldest_enqueued must be NULL");
        assert_eq!(row.12, None, "last_error must be NULL");
        assert_eq!(
            row.13, None,
            "queue_state must also degrade to NULL — it needs backlog visibility too"
        );

        Spi::run("RESET ROLE").expect("RESET ROLE");
    }

    // ---- worker drain core: drain_step/Scheduler/outbox_retry/
    // outbox_discard/queue_state/NO WORKER (launcher probe only; no
    // launcher/BGW yet) ----

    /// `table`'s `regclass` oid, for calling `outbox::drain_step`/
    /// `Scheduler::drain_round` directly (Rust-internal — no SQL surface).
    fn relid_of(table: &str) -> pg_sys::Oid {
        Spi::get_one::<pg_sys::Oid>(&format!("SELECT {}::regclass::oid", quote_literal(table)))
            .expect("relid_of query failed")
            .expect("relid_of result unexpectedly NULL")
    }

    /// Drains `relid`'s outbox to empty via repeated `drain_step(Worker)`
    /// calls, panicking on a non-`Processed` outcome (fixture setup — a real
    /// failure here means the fixture itself is broken, not the test).
    /// A fresh `sync_mode = 'async'` promote's
    /// `'delete_all'`+`'backfill'` jobs need something to drive them to
    /// convergence (`mode = 'promoting' -> 'remote'`) before test fixtures
    /// that promoted async can assume the same "fully remote, empty outbox"
    /// baseline a `'sync'` promote reaches inline.
    fn drain_until_empty(relid: pg_sys::Oid) {
        loop {
            match crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker) {
                crate::outbox::DrainOutcome::Processed(0) => return,
                crate::outbox::DrainOutcome::Processed(_) => {}
                other => panic!("drain_until_empty: unexpected outcome {other:?}"),
            }
        }
    }

    /// Creates and promotes (`sync_mode = 'async'`) a fresh 2-dimensional
    /// table against a mock whose `/vectors/upsert` endpoint always answers
    /// `status` — used to force a specific `dispatch` outcome for the
    /// drain-core tests below. Returns the `MockBackend` (keep it alive for
    /// as long as the test still expects that response).
    fn setup_async_table_with_upsert_status(table: &str, status: u16) -> MockBackend {
        setup_async_table_with_upsert_reply(table, status, "boom")
    }

    /// [`setup_async_table_with_upsert_status`] with the error message Pinecone answers with.
    fn setup_async_table_with_upsert_reply(table: &str, status: u16, message: &str) -> MockBackend {
        let message = message.to_string();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        let index_name = format!("pv-public-{}", table.replace('_', "-"));
        let index_name_for_mock = index_name.clone();
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, &index_name_for_mock).await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(
                    ResponseTemplate::new(status).set_body_json(json!({"message": message})),
                )
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote async");
        // The table is empty, so the enqueued `delete_all`+`backfill` jobs
        // converge with zero HTTP calls to `/vectors/upsert` regardless of
        // `status` — see `drain_until_empty`'s rustdoc.
        drain_until_empty(relid_of(table));
        backend
    }

    #[pg_test]
    fn drain_step_success_deletes_exactly_the_batch() {
        create_extension_vector();
        let (_backend, upserts, _deletes) = setup_sync_trigger_table_mode("drain_step_ok", "async");

        Spi::run("INSERT INTO drain_step_ok (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert 1");
        Spi::run("INSERT INTO drain_step_ok (id, embedding, category) VALUES (2, '[0,1]', 'b')")
            .expect("insert 2");
        assert_eq!(outbox_count("drain_step_ok"), 2);

        let outcome = crate::outbox::drain_step(
            relid_of("drain_step_ok"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Processed(2)),
            "outcome = {outcome:?}"
        );
        assert_eq!(
            outbox_count("drain_step_ok"),
            0,
            "the whole (2-row) batch must be deleted"
        );
        // The two consecutive 'upsert' rows coalesce into ONE
        // batched upsert call carrying both vectors, not one call per row.
        let recorded = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            recorded.len(),
            1,
            "consecutive upsert rows must coalesce into one HTTP call, got {recorded:?}"
        );
        assert_eq!(
            vectors_by_id(&recorded[0]).keys().collect::<Vec<_>>(),
            vec!["1", "2"],
            "the single coalesced call must carry both rows' vectors"
        );
    }

    /// SECURITY regression test, mirroring `outbox_drain_error_never_leaks_api_key`:
    /// a transient (500) failure must back off — leaving the head row queued
    /// — while its `last_error`/`next_retry_at` are persisted but `attempts`
    /// is *not* incremented (`pinecone.outbox_max_attempts` only ever counts
    /// permanent-class failures), and `last_error` must never carry the API
    /// key.
    #[pg_test]
    fn drain_step_transient_error_backs_off_without_incrementing_attempts_or_leaking_key() {
        create_extension_vector();
        Spi::run("CREATE TABLE drain_step_transient (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let distinctive_key = format!("distinctive-secret-key-{}", std::process::id());
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(
                &control_plane,
                &data_plane,
                "pv-public-drain-step-transient",
            )
            .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(
                    ResponseTemplate::new(500).set_body_json(json!({"message": "internal error"})),
                )
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        Spi::run(&format!(
            "SET pinecone.control_plane_url = '{}'",
            backend.control_plane_url
        ))
        .expect("SET pinecone.control_plane_url");
        Spi::run(&format!("SET pinecone.api_key = '{distinctive_key}'"))
            .expect("SET pinecone.api_key");
        Spi::run_with_args(
            "SELECT pinecone.set_api_key($1, $2)",
            &[
                distinctive_key.clone().into(),
                backend.control_plane_url.clone().into(),
            ],
        )
        .expect("set_api_key");
        Spi::run(
            "SELECT pinecone.promote('drain_step_transient', \
             index_name => 'pv-public-drain-step-transient', sync_mode => 'async')",
        )
        .expect("promote async");
        // The async promote's own `delete_all`+`backfill` jobs must converge
        // *before* the insert below — the table is still empty at this
        // point, so both converge with zero HTTP calls to `/vectors/upsert`
        // regardless of the 500 mock (see `drain_until_empty`'s rustdoc) —
        // otherwise this call's single `drain_step` below would dispatch the
        // still-queued `'backfill'` job (which, once the insert below lands,
        // would read that very row) instead of the insert's own `'upsert'`
        // row this test means to exercise.
        drain_until_empty(relid_of("drain_step_transient"));

        Spi::run("INSERT INTO drain_step_transient (id, embedding) VALUES (1, '[1,0]')")
            .expect("insert");

        let outcome = crate::outbox::drain_step(
            relid_of("drain_step_transient"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
            "outcome = {outcome:?}"
        );
        assert_eq!(
            outbox_count("drain_step_transient"),
            1,
            "the failed head row must not be deleted"
        );

        let (attempts, last_error) = Spi::get_two::<i32, String>(
            "SELECT attempts, last_error FROM pinecone.outbox \
             WHERE relid = 'drain_step_transient'::regclass",
        )
        .expect("select attempts/last_error");
        assert_eq!(
            attempts,
            Some(0),
            "a transient failure must never count toward pinecone.outbox_max_attempts"
        );
        let last_error = last_error.expect("last_error must be set");
        assert!(
            !last_error.contains(&distinctive_key),
            "last_error = {last_error}"
        );

        let next_retry_at_is_future = Spi::get_one::<bool>(
            "SELECT next_retry_at > now() FROM pinecone.outbox \
             WHERE relid = 'drain_step_transient'::regclass",
        )
        .expect("select next_retry_at")
        .expect("next_retry_at must be set (non-NULL) on a Backoff outcome");
        assert!(
            next_retry_at_is_future,
            "next_retry_at must be in the future right after Backoff"
        );
    }

    /// The 429 classifier reaches the vector outbox's `last_error` too: the monthly quota says
    /// "billing period", a rate limit says "retry in a moment", and neither counts an attempt.
    #[pg_test]
    fn drain_step_429_last_error_says_which_limit_was_hit() {
        create_extension_vector();
        let cases = [
            (
                "drain_429_quota",
                "Request failed. You've reached your write unit limit for the current month \
                 (2000000). To continue writing data, upgrade your plan.",
                "billing period",
            ),
            (
                "drain_429_rate",
                "Request failed. You've reached the max upsert requests per second per \
                 namespace. Pace your upsert requests or contact Pinecone Support to request a \
                 higher limit.",
                "retry in a moment",
            ),
        ];
        for (table, message, hint) in cases {
            let _backend = setup_async_table_with_upsert_reply(table, 429, message);
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0]')"
            ))
            .expect("insert");
            let outcome = crate::outbox::drain_step(
                relid_of(table),
                crate::backend::DrainCredentials::Worker,
            );
            assert!(
                matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
                "outcome = {outcome:?}"
            );
            let (attempts, last_error) = Spi::get_two::<i32, String>(&format!(
                "SELECT attempts, last_error FROM pinecone.outbox WHERE relid = '{table}'::regclass"
            ))
            .expect("select attempts/last_error");
            assert_eq!(attempts, Some(0), "a 429 never counts as an attempt");
            let last_error = last_error.expect("last_error is set");
            assert!(last_error.contains("429"), "last_error = {last_error}");
            assert!(last_error.contains(hint), "last_error = {last_error}");
        }
    }

    #[pg_test]
    fn drain_step_permanent_error_parks_after_max_attempts() {
        create_extension_vector();
        Spi::run("SET pinecone.outbox_max_attempts = 2").expect("set guc");
        let _backend = setup_async_table_with_upsert_status("drain_step_parks", 400);

        Spi::run("INSERT INTO drain_step_parks (id, embedding) VALUES (1, '[1,0]')")
            .expect("insert");

        let relid = relid_of("drain_step_parks");
        let first = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(first, crate::outbox::DrainOutcome::Backoff(_)),
            "first = {first:?}"
        );
        let second = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(second, crate::outbox::DrainOutcome::Parked(_)),
            "second = {second:?}"
        );

        assert_eq!(
            outbox_count("drain_step_parks"),
            1,
            "the parked head row stays queued"
        );

        let rows = status_rows();
        let row = rows
            .iter()
            .find(|r| r.0 == "public.drain_step_parks")
            .expect("row present");
        assert_eq!(row.13, Some("parked".to_string()), "row.13 = {:?}", row.13);
    }

    /// `status()`'s `queue_state` must surface `'backoff'`
    /// for a relid whose head row just recorded a future `next_retry_at`
    /// (`drain_step`'s transient path) — distinct from both `'active'`
    /// (misleadingly implies steady progress) and `'NO WORKER'` (implies
    /// nothing is even trying).
    #[pg_test]
    fn status_queue_state_backoff_after_transient_failure() {
        create_extension_vector();
        let _backend = setup_async_table_with_upsert_status("status_backoff", 500);

        Spi::run("INSERT INTO status_backoff (id, embedding) VALUES (1, '[1,0]')").expect("insert");

        let outcome = crate::outbox::drain_step(
            relid_of("status_backoff"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
            "outcome = {outcome:?}"
        );

        let row13 = status_rows()
            .into_iter()
            .find(|r| r.0 == "public.status_backoff")
            .expect("row present")
            .13;
        assert_eq!(row13, Some("backoff".to_string()), "row13 = {row13:?}");
    }

    /// A backlog with no stored API key yet must never
    /// crash-loop the worker — `drain_step`'s `Worker` path backs off
    /// cleanly instead, repeatedly, without ever incrementing `attempts` or
    /// parking the relid (it isn't the remote index rejecting anything —
    /// it's a "not configured yet" precondition that resolves the instant an
    /// operator runs `pinecone.set_api_key`).
    #[pg_test]
    fn drain_step_worker_backs_off_when_no_stored_key_without_incrementing_attempts() {
        create_extension_vector();
        let (_backend, _upserts, _deletes) = setup_sync_trigger_table_mode("drain_no_key", "async");

        Spi::run("INSERT INTO drain_no_key (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");
        assert_eq!(outbox_count("drain_no_key"), 1);

        Spi::run("SELECT pinecone.clear_api_key()").expect("clear_api_key");

        let relid = relid_of("drain_no_key");
        for round in 0..3 {
            let outcome =
                crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
            assert!(
                matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
                "round {round}: outcome = {outcome:?}"
            );
        }

        assert_eq!(
            outbox_count("drain_no_key"),
            1,
            "the row must stay queued, never parked, for a missing key"
        );

        let (attempts, last_error) = Spi::get_two::<i32, String>(
            "SELECT attempts, last_error FROM pinecone.outbox \
             WHERE relid = 'drain_no_key'::regclass",
        )
        .expect("select attempts/last_error");
        assert_eq!(
            attempts,
            Some(0),
            "a missing stored key must never count toward pinecone.outbox_max_attempts"
        );
        assert!(
            last_error
                .expect("last_error must be set")
                .contains("pinecone.set_api_key"),
            "last_error should point the operator at the fix"
        );

        let row13 = status_rows()
            .into_iter()
            .find(|r| r.0 == "public.drain_no_key")
            .expect("row present")
            .13;
        assert_ne!(
            row13,
            Some("parked".to_string()),
            "a missing stored key must never park the relid"
        );
    }

    #[pg_test]
    fn outbox_retry_unparks_and_drains_against_fixed_mock() {
        create_extension_vector();
        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("set guc");
        let _backend_a = setup_async_table_with_upsert_status("outbox_retry_park", 400);

        Spi::run("INSERT INTO outbox_retry_park (id, embedding) VALUES (1, '[1,0]')")
            .expect("insert");

        let relid = relid_of("outbox_retry_park");
        let parked = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(parked, crate::outbox::DrainOutcome::Parked(_)),
            "parked = {parked:?}"
        );
        let row13 = |label: &str| {
            status_rows()
                .into_iter()
                .find(|r| r.0 == "public.outbox_retry_park")
                .unwrap_or_else(|| panic!("row present ({label})"))
                .13
        };
        assert_eq!(row13("after park"), Some("parked".to_string()));

        Spi::run("SELECT pinecone.outbox_retry('outbox_retry_park')").expect("outbox_retry");
        assert_ne!(
            row13("after retry"),
            Some("parked".to_string()),
            "outbox_retry must unpark"
        );

        // Repoint at a fresh, always-succeeding mock — the "fixed mock" the
        // retried row should now drain against.
        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend_b = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-outbox-retry-park",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend_b);

        let drained = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(drained, crate::outbox::DrainOutcome::Processed(1)),
            "drained = {drained:?}"
        );
        assert_eq!(outbox_count("outbox_retry_park"), 0);
        assert_eq!(upserts.lock().expect("lock poisoned").len(), 1);
        assert!(deletes.lock().expect("lock poisoned").is_empty());
    }

    #[pg_test]
    fn outbox_discard_removes_prefix_and_warns() {
        create_extension_vector();
        let (_backend, _upserts, _deletes) =
            setup_sync_trigger_table_mode("outbox_discard_tbl", "async");

        Spi::run(
            "INSERT INTO outbox_discard_tbl (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert 1");
        Spi::run(
            "INSERT INTO outbox_discard_tbl (id, embedding, category) VALUES (2, '[0,1]', 'b')",
        )
        .expect("insert 2");
        assert_eq!(outbox_count("outbox_discard_tbl"), 2);

        let through_id = Spi::get_one::<i64>(
            "SELECT min(id) FROM pinecone.outbox WHERE relid = 'outbox_discard_tbl'::regclass",
        )
        .expect("select min id")
        .expect("min id unexpectedly NULL");

        let (_, warnings) = capture_warnings(|| {
            Spi::run(&format!(
                "SELECT pinecone.outbox_discard('outbox_discard_tbl', {through_id})"
            ))
            .expect("outbox_discard");
        });

        assert!(
            warnings.iter().any(|w| w.contains("pinecone.sync")),
            "warnings = {warnings:?}"
        );
        let remaining = outbox_rows("outbox_discard_tbl");
        assert_eq!(
            remaining.len(),
            1,
            "only the row through_id must be dropped: {remaining:?}"
        );
    }

    /// Fairness: a relid stuck failing every batch
    /// must never delay another relid's own drain — each
    /// `Scheduler::drain_round` call gives every eligible relid its own
    /// batch turn, and a failing one just falls into (and stays in) backoff.
    #[pg_test]
    fn scheduler_fairness_failing_relid_never_blocks_the_other() {
        create_extension_vector();
        let _backend_fail = setup_async_table_with_upsert_status("fair_fail", 500);
        let (_backend_ok, upserts_ok, _deletes_ok) =
            setup_sync_trigger_table_mode("fair_ok", "async");

        Spi::run("INSERT INTO fair_fail (id, embedding) VALUES (1, '[1,0]')").expect("insert fail");
        Spi::run("INSERT INTO fair_ok (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert ok 1");
        Spi::run("INSERT INTO fair_ok (id, embedding, category) VALUES (2, '[0,1]', 'b')")
            .expect("insert ok 2");
        Spi::run("INSERT INTO fair_ok (id, embedding, category) VALUES (3, '[1,1]', 'c')")
            .expect("insert ok 3");

        let mut scheduler = crate::outbox::Scheduler::new();
        for _ in 0..3 {
            scheduler.drain_round();
        }

        assert_eq!(
            outbox_count("fair_fail"),
            1,
            "the failing relid's head row must never be dropped"
        );
        assert_eq!(
            outbox_count("fair_ok"),
            0,
            "the other relid must fully drain despite fair_fail's failure"
        );
        // fair_ok's 3 consecutive upsert rows drain in ONE
        // coalesced call in its first round turn — the fairness guarantee is
        // that it drains fully (outbox_count == 0 above), not the call count.
        assert_eq!(upserts_ok.lock().expect("lock poisoned").len(), 1);

        let rows = status_rows();
        let fail_row = rows
            .iter()
            .find(|r| r.0 == "public.fair_fail")
            .expect("row present");
        assert_ne!(
            fail_row.13,
            Some("parked".to_string()),
            "transient 500s must never park"
        );
    }

    /// A round where every active relid is stuck inside
    /// its own backoff window must still report "active" (there *is* a
    /// backlog), not idle — `worker.rs`'s idle-round counter relies on this
    /// to never mistake "everything is backing off" for "nothing to do" and
    /// exit out from under a real backlog.
    #[pg_test]
    fn scheduler_drain_round_reports_active_when_all_relids_are_backing_off() {
        create_extension_vector();
        let _backend = setup_async_table_with_upsert_status("round_all_backoff", 500);
        Spi::run("INSERT INTO round_all_backoff (id, embedding) VALUES (1, '[1,0]')")
            .expect("insert");

        let mut scheduler = crate::outbox::Scheduler::new();
        assert!(
            scheduler.drain_round(),
            "first round: the relid is eligible and has queued rows"
        );
        assert_eq!(
            outbox_count("round_all_backoff"),
            1,
            "still queued after a failed dispatch"
        );

        assert!(
            scheduler.drain_round(),
            "second round: the relid is now inside its own backoff window, but must still \
             count as active/non-idle"
        );
        assert_eq!(
            outbox_count("round_all_backoff"),
            1,
            "the row must be untouched — no new dispatch attempt while backing off"
        );
    }

    /// FIFO preservation across a batch boundary: `DRAIN_BATCH_ROWS + 2`
    /// rows, drained via exactly two `drain_step` calls, must dispatch in
    /// strict ascending id order end to end.
    #[pg_test]
    fn drain_step_fifo_preserved_across_batches() {
        create_extension_vector();
        let (_backend, upserts, _deletes) = setup_sync_trigger_table_mode("drain_fifo", "async");

        let total = crate::outbox::DRAIN_BATCH_ROWS + 2;
        for i in 1..=total {
            Spi::run_with_args(
                "INSERT INTO drain_fifo (id, embedding, category) VALUES ($1, '[1,0]', 'a')",
                &[i.into()],
            )
            .expect("insert row");
        }
        assert_eq!(outbox_count("drain_fifo"), total);

        let relid = relid_of("drain_fifo");
        let first = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(first, crate::outbox::DrainOutcome::Processed(n) if n == crate::outbox::DRAIN_BATCH_ROWS as u64),
            "first = {first:?}"
        );
        let second = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(second, crate::outbox::DrainOutcome::Processed(2)),
            "second = {second:?}"
        );
        assert_eq!(outbox_count("drain_fifo"), 0);

        // Each drain_step coalesces its whole batch of
        // consecutive upsert rows into ONE call — so two drain_step calls
        // yield two HTTP calls (DRAIN_BATCH_ROWS vectors, then 2), not `total`
        // calls — and the vectors, read in call order, still arrive in strict
        // FIFO id order end to end.
        let recorded = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            recorded.len(),
            2,
            "one coalesced call per drain_step batch, got {recorded:?}"
        );
        let ids: Vec<i64> = recorded
            .iter()
            .flat_map(|body| {
                body["vectors"]
                    .as_array()
                    .expect("vectors should be an array")
                    .iter()
                    .map(|v| {
                        v["id"]
                            .as_str()
                            .expect("id should be a string")
                            .parse::<i64>()
                            .expect("id should parse as an integer")
                    })
                    .collect::<Vec<_>>()
            })
            .collect();
        let expected: Vec<i64> = (1..=total).collect();
        assert_eq!(
            ids, expected,
            "ids must arrive in strict FIFO id order across the batch boundary"
        );
    }

    /// Consecutive `'upsert'` outbox rows drain as ONE batched
    /// upsert_vectors call (not one HTTP round trip per row — the ~100x
    /// steady-state throughput win), with a per-id last-op-wins fold. Asserts
    /// the call COUNT via the recording mock: 40 distinct ids across 41 small
    /// writes => 1 call (ceil(40 / PUSH_MAX_ROWS)), not 41.
    #[pg_test]
    fn drain_step_coalesces_consecutive_upserts_and_folds_last_op_wins() {
        create_extension_vector();
        let (_backend, upserts, _deletes) =
            setup_sync_trigger_table_mode("drain_coalesce", "async");

        // 40 single-row insert txns (id 1..=40), then a second write to id=1 —
        // 41 consecutive 'upsert' rows, id=1 appearing twice.
        for i in 1..=40i64 {
            Spi::run_with_args(
                "INSERT INTO drain_coalesce (id, embedding, category) VALUES ($1, $2::vector, 'a')",
                &[i.into(), format!("[{i},0]").into()],
            )
            .expect("insert row");
        }
        Spi::run("UPDATE drain_coalesce SET embedding = '[9,9]' WHERE id = 1")
            .expect("update id=1 vector");
        assert_eq!(outbox_count("drain_coalesce"), 41);

        // One drain_step fetches all 41 (< DRAIN_BATCH_ROWS) and coalesces.
        let outcome = crate::outbox::drain_step(
            relid_of("drain_coalesce"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Processed(41)),
            "outcome = {outcome:?}"
        );
        assert_eq!(outbox_count("drain_coalesce"), 0);

        let recorded = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            recorded.len(),
            1,
            "41 consecutive upsert rows must coalesce into ONE call, got {} calls",
            recorded.len()
        );
        let vectors = vectors_by_id(&recorded[0]);
        assert_eq!(
            vectors.len(),
            40,
            "the same id written twice must fold to one vector (last-op-wins)"
        );
        assert_eq!(
            vectors["1"]["values"],
            json!([9.0, 9.0]),
            "id=1 must carry its LATEST value, not the earlier insert's"
        );
        let mut ids: Vec<i64> = vectors.keys().map(|k| k.parse::<i64>().unwrap()).collect();
        ids.sort_unstable();
        assert_eq!(
            ids,
            (1..=40).collect::<Vec<_>>(),
            "every distinct id 1..=40 must be present exactly once"
        );
    }

    /// Coalescing must BREAK at any non-upsert op so per-id
    /// FIFO ordering is never violated. Drains the sequence `upsert(1),
    /// upsert(2), delete(1), upsert(1)` and asserts the exact HTTP call order
    /// via a shared ordered sink: the first two upserts coalesce into one
    /// call, the delete is its own call, and id=1's re-upsert AFTER the delete
    /// is a SEPARATE later call — never folded back across the delete (which
    /// would reorder upsert-then-delete-then-upsert for id=1).
    #[pg_test]
    fn drain_step_coalesce_breaks_at_nonupsert_ops_preserving_order() {
        create_extension_vector();
        let table = "drain_coalesce_order";
        let index_name = "pv-public-drain-coalesce-order";
        let order = Arc::new(Mutex::new(Vec::<String>::new()));
        let order_for_upsert = Arc::clone(&order);
        let order_for_delete = Arc::clone(&order);
        let index_name_owned = index_name.to_string();
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path(format!("/indexes/{index_name_owned}")))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("upsert body JSON");
                    let mut ids: Vec<String> = vectors_by_id(&body).into_keys().collect();
                    ids.sort();
                    order_for_upsert
                        .lock()
                        .expect("order lock poisoned")
                        .push(format!("upsert:{}", ids.join(",")));
                    ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": ids.len()}))
                })
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("delete body JSON");
                    let mut ids: Vec<String> = delete_ids_of(&body).into_iter().collect();
                    ids.sort();
                    order_for_delete
                        .lock()
                        .expect("order lock poisoned")
                        .push(format!("delete:{}", ids.join(",")));
                    ResponseTemplate::new(200).set_body_json(json!({}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.promote('{table}', index_name => '{index_name}', sync_mode => 'async')"
        ))
        .expect("promote async");
        drain_until_empty(relid_of(table)); // drain the promote's delete_all+backfill
        order.lock().expect("order lock poisoned").clear();

        // Enqueue, in order: upsert(1), upsert(2), delete(1), upsert(1).
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0]')"
        ))
        .expect("insert 1");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (2, '[1,0]')"
        ))
        .expect("insert 2");
        Spi::run(&format!("DELETE FROM {table} WHERE id = 1")).expect("delete 1");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[3,0]')"
        ))
        .expect("re-insert 1");
        assert_eq!(outbox_count(table), 4);

        let outcome =
            crate::outbox::drain_step(relid_of(table), crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Processed(4)),
            "outcome = {outcome:?}"
        );
        assert_eq!(outbox_count(table), 0);

        let calls = order.lock().expect("order lock poisoned").clone();
        assert_eq!(
            calls,
            vec![
                "upsert:1,2".to_string(),
                "delete:1".to_string(),
                "upsert:1".to_string(),
            ],
            "the delete must break coalescing, keeping id=1's upsert->delete->upsert order"
        );
    }

    // ---- async lifecycle drills: async promote e2e, an outage drill, and
    // backfill restart/mid-flight-DML convergence. The parity half
    // (re-running 0.2's trigger-behavior fixtures through async+drain) is
    // already covered above by the `outbox_*`/`drain_step_fifo_*` tests —
    // every one of them drives the very same `_sync_trigger` enqueue path
    // 'sync' mode does, then dispatches it via `drain_step`/`Scheduler`
    // instead of the inline call, so the request bodies those mocks record
    // are the same shapes the `sync_trigger_*` fixtures assert on. ----

    /// Runs `pinecone.topk(table, query, k)` and returns just the `id` column
    /// in result order — these drills only care *which mode* answered (local
    /// ids vs. the mock's fixed, locally-impossible remote id), not exact
    /// distances.
    fn topk_ids(table: &str, query_literal: &str, k: i32) -> Vec<String> {
        Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT id FROM pinecone.topk({}, {query_literal}, {k})",
                        quote_literal(table)
                    ),
                    None,
                    &[],
                )
                .expect("select from pinecone.topk")
                .map(|row| {
                    row.get_by_name::<String, _>("id")
                        .expect("get id")
                        .expect("id is NOT NULL")
                })
                .collect()
        })
    }

    /// 7(c): an async promote of a *non-empty* table returns fast with
    /// `mode = 'promoting'` (`status()` surfaces it directly via the plain
    /// `mode` column) and must keep serving `pinecone.topk` locally — zero
    /// `/query` calls — until its `delete_all`+`backfill` jobs actually
    /// exhaust; only then does the registry row flip to `'remote'` and
    /// `topk` start hitting the mocked remote index (whose fixed,
    /// locally-impossible id `"remote-only"` proves which path answered).
    #[pg_test]
    fn async_promote_stays_local_until_backfill_exhausts_then_flips_remote() {
        create_extension_vector();
        Spi::run("CREATE TABLE async_e2e (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        for (id, vector) in [(1, "[1,0]"), (2, "[0,1]"), (3, "[1,1]")] {
            Spi::run(&format!(
                "INSERT INTO async_e2e (id, embedding) VALUES ({id}, '{vector}')"
            ))
            .expect("insert fixture row");
        }

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let queries = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock, queries_for_mock) = (
            Arc::clone(&upserts),
            Arc::clone(&deletes),
            Arc::clone(&queries),
        );
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-async-e2e",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("query body should be JSON");
                    queries_for_mock
                        .lock()
                        .expect("queries lock poisoned")
                        .push(body);
                    ResponseTemplate::new(200).set_body_json(json!({
                        "matches": [{"id": "remote-only", "score": 0.99}]
                    }))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('async_e2e', index_name => 'pv-public-async-e2e', \
             sync_mode => 'async')",
        )
        .expect("promote async");

        assert_eq!(
            status_rows()[0].1,
            "promoting",
            "async promote of a non-empty table must return fast, mode = 'promoting'"
        );

        let mut local_ids = topk_ids("async_e2e", "ARRAY[1.0, 0.0]::real[]", 3);
        local_ids.sort();
        assert_eq!(
            local_ids,
            vec!["1".to_string(), "2".to_string(), "3".to_string()],
            "must search locally while 'promoting'"
        );
        assert!(
            queries.lock().expect("queries lock poisoned").is_empty(),
            "must never call /query while 'promoting' — never serve a partial namespace"
        );

        drain_until_empty(relid_of("async_e2e"));

        assert_eq!(
            status_rows()[0].1,
            "remote",
            "backfill exhausted — must flip 'promoting' -> 'remote'"
        );

        let remote_ids = topk_ids("async_e2e", "ARRAY[1.0, 0.0]::real[]", 3);
        assert_eq!(
            remote_ids,
            vec!["remote-only".to_string()],
            "must now search remotely"
        );
        assert_eq!(
            queries.lock().expect("queries lock poisoned").len(),
            1,
            "exactly one /query call once 'remote'"
        );
    }

    /// 7(b) OUTAGE DRILL: while the mocked remote returns a 5xx storm, local
    /// writes to an async table must still succeed (writes only ever
    /// enqueue) and the backlog grows; `pinecone.status`'s `queue_state` must
    /// surface the outage (`'backoff'`), never read as idle. Once the mock
    /// recovers, draining the backlog must deliver every queued row, in
    /// strict FIFO id order, with no drops and no reordering.
    #[pg_test]
    fn outage_drill_backlog_grows_during_storm_then_drains_in_order_on_recovery() {
        create_extension_vector();
        Spi::run("CREATE TABLE outage_drill (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let failing = Arc::new(Mutex::new(true));
        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (failing_for_mock, upserts_for_mock) = (Arc::clone(&failing), Arc::clone(&upserts));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-outage-drill").await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(move |req: &Request| {
                    if *failing_for_mock.lock().expect("failing lock poisoned") {
                        return ResponseTemplate::new(500)
                            .set_body_json(json!({"message": "simulated outage"}));
                    }
                    let body: Value = req.body_json().expect("upsert body should be JSON");
                    upserts_for_mock
                        .lock()
                        .expect("upserts lock poisoned")
                        .push(body);
                    ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('outage_drill', index_name => 'pv-public-outage-drill', \
             sync_mode => 'async')",
        )
        .expect("promote async");
        // The table is empty at promote time, so the enqueued
        // `delete_all`+`backfill` jobs converge without ever touching
        // `/vectors/upsert` — see `drain_until_empty`'s rustdoc — regardless
        // of `failing`, which only affects that one endpoint.
        drain_until_empty(relid_of("outage_drill"));

        for id in 1..=5i64 {
            Spi::run_with_args(
                "INSERT INTO outage_drill (id, embedding) VALUES ($1, '[1,0]')",
                &[id.into()],
            )
            .expect("insert row");
        }
        assert_eq!(
            outbox_count("outage_drill"),
            5,
            "every local write must succeed and enqueue regardless of the remote outage"
        );

        let relid = relid_of("outage_drill");
        let outcome = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
            "outcome = {outcome:?}"
        );
        assert_eq!(
            outbox_count("outage_drill"),
            5,
            "the whole backlog must survive the outage — head-of-line halts the relid"
        );
        assert_eq!(
            status_rows()[0].13.as_deref(),
            Some("backoff"),
            "status() must surface the outage, never read as idle"
        );

        *failing.lock().expect("failing lock poisoned") = false;
        drain_until_empty(relid);

        // The 5 backlogged upsert rows drain as ONE coalesced
        // call carrying all 5 vectors (not 5 calls), still in strict FIFO id
        // order — recovery delivers every queued row exactly once, in order.
        let recorded = upserts.lock().expect("upserts lock poisoned").clone();
        assert_eq!(
            recorded.len(),
            1,
            "the healed backlog must drain as one coalesced call, got {recorded:?}"
        );
        let ids: Vec<i64> = recorded[0]["vectors"]
            .as_array()
            .expect("vectors should be an array")
            .iter()
            .map(|v| {
                v["id"]
                    .as_str()
                    .expect("id should be a string")
                    .parse::<i64>()
                    .expect("id should parse as an integer")
            })
            .collect();
        assert_eq!(
            ids,
            vec![1, 2, 3, 4, 5],
            "recovery must drain strictly in FIFO id order"
        );
    }

    /// 7(d) mid-backfill restart: drives exactly one round (one
    /// `Scheduler::drain_round` call — the same "at most one batch per
    /// relid per round" fairness contract the real worker loop uses), which
    /// dispatches the `delete_all` job to completion and the `backfill`
    /// job's *first* chunk (both rows fit in one chunk here, but the chunk
    /// read still only ever reports [`DispatchOutcome::InProgress`] on the
    /// call *before* the one that finds nothing left — see
    /// `dispatch_backfill`'s rustdoc) — persisting `payload.after_id` and
    /// leaving the job queued. A brand new [`crate::outbox::Scheduler`]
    /// (simulating a worker restart, which only ever loses in-memory backoff
    /// state, never the persisted cursor) then finishes the job from that
    /// cursor — proving the restart-safety the queue promises.
    #[pg_test]
    fn backfill_restart_resumes_from_persisted_after_id() {
        create_extension_vector();
        Spi::run("CREATE TABLE backfill_restart (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run("INSERT INTO backfill_restart (id, embedding) VALUES (1, '[1,0]'), (2, '[0,1]')")
            .expect("insert fixture rows");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-backfill-restart").await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(|_: &Request| {
                    slow_upsert(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        one_chunk_per_round();

        Spi::run(
            "SELECT pinecone.promote('backfill_restart', \
             index_name => 'pv-public-backfill-restart', sync_mode => 'async')",
        )
        .expect("promote async");

        let mut scheduler = crate::outbox::Scheduler::new();
        scheduler.drain_round();

        assert_eq!(
            status_rows()[0].1,
            "promoting",
            "the backfill job must still be mid-flight after exactly one round"
        );
        let after_id = Spi::get_one::<String>(
            "SELECT payload->>'after_id' FROM pinecone.outbox \
             WHERE relid = 'backfill_restart'::regclass AND op = 'backfill'",
        )
        .expect("select backfill after_id")
        .expect("a 'backfill' job row must still be queued");
        assert_eq!(
            after_id, "2",
            "the chunk cursor must persist past the highest id already read"
        );

        // Simulate a worker restart: the old `Scheduler` (and its in-memory
        // backoff state, which this test never even triggered) is simply
        // dropped and replaced — the persisted `after_id` above is the only
        // state that matters for correctness.
        drop(scheduler);
        let mut scheduler = crate::outbox::Scheduler::new();
        let mut rounds = 0;
        while outbox_count("backfill_restart") > 0 {
            assert!(
                scheduler.drain_round(),
                "a non-empty backlog must never report 'no active relids'"
            );
            rounds += 1;
            assert!(rounds < 100, "backfill_restart never converged");
        }

        assert_eq!(
            status_rows()[0].1,
            "remote",
            "the backfill job's exhaustion must flip 'promoting' -> 'remote'"
        );
    }

    /// `pinecone.demote` must work mid-flight, on an
    /// async promote whose backfill job hasn't drained yet — not just on a
    /// fully `'remote'` table (`promote::demotable_row`). Drops the
    /// triggers, purges the outbox (the still-in-progress `'backfill'` job
    /// included, so it can never resume against a table that's since gone
    /// back to `'local'`), and leaves the registry row `mode = 'local'`.
    #[pg_test]
    fn demote_works_mid_backfill_and_purges_the_backfill_job() {
        create_extension_vector();
        Spi::run("CREATE TABLE demote_mid_backfill (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run(
            "INSERT INTO demote_mid_backfill (id, embedding) VALUES (1, '[1,0]'), (2, '[0,1]')",
        )
        .expect("insert fixture rows");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-demote-mid-backfill")
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(|_: &Request| {
                    slow_upsert(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        one_chunk_per_round();

        Spi::run(
            "SELECT pinecone.promote('demote_mid_backfill', \
             index_name => 'pv-public-demote-mid-backfill', sync_mode => 'async')",
        )
        .expect("promote async");

        let mut scheduler = crate::outbox::Scheduler::new();
        scheduler.drain_round(); // delete_all done; backfill's first chunk still in progress.
        assert_eq!(
            status_rows()[0].1,
            "promoting",
            "must still be mid-backfill before demoting below"
        );
        assert!(
            outbox_count("demote_mid_backfill") > 0,
            "the in-progress backfill job must still be queued"
        );

        Spi::run("SELECT pinecone.demote('demote_mid_backfill')").expect("demote mid-backfill");

        assert_eq!(status_rows()[0].1, "local");
        assert!(
            trigger_names("demote_mid_backfill").is_empty(),
            "demote must drop the sync triggers"
        );
        assert_eq!(
            outbox_count("demote_mid_backfill"),
            0,
            "demote must purge the outbox, including the in-progress backfill job"
        );
    }

    /// 7(e) mid-backfill DML converges: an `INSERT` and a `DELETE` land
    /// while a table is still `mode = 'promoting'` (the backfill job's first
    /// chunk has already read-and-pushed the pre-promote rows, but hasn't
    /// exhausted yet) — both are enqueued (`sync_trigger::remote_target`
    /// accepts `'promoting'` precisely for this) and, once draining
    /// continues, dispatched in order behind the still-in-progress backfill
    /// job. The final replayed remote state (`delete_all` then every
    /// recorded `upsert`/`delete`, in true chronological HTTP-call order)
    /// must match the table's own final row set exactly — no dropped or
    /// stale write survives the interleaving.
    #[pg_test]
    fn mid_backfill_dml_converges_to_final_table_state() {
        create_extension_vector();
        Spi::run("CREATE TABLE backfill_dml (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run("INSERT INTO backfill_dml (id, embedding) VALUES (1, '[1,0]'), (2, '[0,1]')")
            .expect("insert fixture rows");

        // One combined, chronologically-ordered sink (unlike
        // `mount_sync_trigger_recording`'s two independent ones) — replaying
        // "remote" state below needs the true interleaving of upsert/delete
        // HTTP calls, not just each op's own internal order.
        let ops = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (ops_for_upsert, ops_for_delete) = (Arc::clone(&ops), Arc::clone(&ops));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            // Deliberately not `mount_promote_success` here: it mounts its
            // own fixed, non-recording `/vectors/delete` responder on the
            // same `data_plane` server, which would race the recording one
            // below for the same route (wiremock's tie-break between two
            // equal-priority mocks on one path is not something this test
            // should depend on) — only the control-plane half is reused.
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/indexes/pv-public-backfill-dml"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("upsert body should be JSON");
                    ops_for_upsert
                        .lock()
                        .expect("ops lock poisoned")
                        .push(json!({"op": "upsert", "body": body}));
                    slow_upsert(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                })
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("delete body should be JSON");
                    ops_for_delete
                        .lock()
                        .expect("ops lock poisoned")
                        .push(json!({"op": "delete", "body": body}));
                    ResponseTemplate::new(200).set_body_json(json!({}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        one_chunk_per_round();

        Spi::run(
            "SELECT pinecone.promote('backfill_dml', index_name => 'pv-public-backfill-dml', \
             sync_mode => 'async')",
        )
        .expect("promote async");

        let mut scheduler = crate::outbox::Scheduler::new();
        scheduler.drain_round(); // delete_all done; backfill's first chunk pushes ids 1,2 (InProgress).
        assert_eq!(
            status_rows()[0].1,
            "promoting",
            "must still be mid-backfill before the DML below"
        );

        Spi::run("INSERT INTO backfill_dml (id, embedding) VALUES (3, '[1,1]')")
            .expect("insert during promoting");
        Spi::run("DELETE FROM backfill_dml WHERE id = 1").expect("delete during promoting");

        let mut rounds = 0;
        while outbox_count("backfill_dml") > 0 {
            assert!(scheduler.drain_round(), "backlog must stay active");
            rounds += 1;
            assert!(rounds < 100, "backfill_dml never converged");
        }
        assert_eq!(status_rows()[0].1, "remote");

        let mut remote_ids: BTreeSet<String> = BTreeSet::new();
        for entry in ops.lock().expect("ops lock poisoned").iter() {
            match entry["op"].as_str().expect("op") {
                "upsert" => {
                    for v in entry["body"]["vectors"].as_array().expect("vectors array") {
                        remote_ids.insert(v["id"].as_str().expect("id").to_string());
                    }
                }
                "delete" => {
                    if entry["body"]["deleteAll"].as_bool() == Some(true) {
                        remote_ids.clear();
                    } else {
                        for id in entry["body"]["ids"].as_array().expect("ids array") {
                            remote_ids.remove(id.as_str().expect("id"));
                        }
                    }
                }
                other => panic!("unexpected recorded op {other}"),
            }
        }

        let table_ids: BTreeSet<String> = Spi::connect(|client| {
            client
                .select(
                    "SELECT id::text AS id FROM backfill_dml ORDER BY id",
                    None,
                    &[],
                )
                .expect("select final table ids")
                .map(|row| {
                    row.get_by_name::<String, _>("id")
                        .expect("get id")
                        .expect("id NOT NULL")
                })
                .collect()
        });
        assert_eq!(
            remote_ids, table_ids,
            "the replayed remote state must match the table's final rows exactly"
        );
    }

    /// Regression test (SQL injection into the superuser worker):
    /// `try_backfill_chunk` splices the id column's `pg_type.typname`
    /// UNQUOTED into its chunk-read SQL (a cast target). `pinecone.track`
    /// whitelists the type at registration time, but an `ALTER TABLE ...
    /// ALTER COLUMN ... TYPE <domain>` afterward swaps `typname` for the
    /// domain's own name — which an attacker can make SQL-active. Driving
    /// the backfill must park the relid with a clear reason naming the
    /// column and type, and the hostile name must never execute: the canary
    /// table survives and the mock sees zero `/vectors/upsert` calls.
    #[pg_test]
    fn backfill_hostile_id_type_parks_without_executing_it() {
        create_extension_vector();
        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("set guc");
        Spi::run("CREATE TABLE inj_canary (id int)").expect("create canary");
        Spi::run("CREATE TABLE inj_backfill (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run("INSERT INTO inj_backfill (id, embedding) VALUES (1, '[1,0]')").expect("insert");

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-inj-backfill",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(
            "SELECT pinecone.promote('inj_backfill', index_name => 'pv-public-inj-backfill', \
             sync_mode => 'async')",
        )
        .expect("promote async — backfill job queued, not yet drained");

        // The attack: a domain over the same base type whose *name* is SQL.
        // The column keeps working locally; only its `pg_type.typname`
        // changes — to exactly what a naive interpolation would execute.
        Spi::run(r#"CREATE DOMAIN "bigint; DROP TABLE inj_canary; --" AS bigint"#)
            .expect("create hostile domain");
        Spi::run(
            r#"ALTER TABLE inj_backfill ALTER COLUMN id TYPE "bigint; DROP TABLE inj_canary; --""#,
        )
        .expect("alter id column to the hostile domain");

        let relid = relid_of("inj_backfill");
        let outcome = crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Parked(_)),
            "outcome = {outcome:?}"
        );

        let row = status_rows()
            .into_iter()
            .find(|r| r.0 == "public.inj_backfill")
            .expect("row present");
        assert_eq!(row.13, Some("parked".to_string()));
        let reason = row.12.expect("parked_reason must be set");
        assert!(reason.contains("\"id\""), "reason = {reason}");
        assert!(
            reason.contains("supported id column types"),
            "reason = {reason}"
        );

        assert!(
            Spi::get_one::<bool>("SELECT to_regclass('inj_canary') IS NOT NULL")
                .expect("canary probe")
                .expect("bool NOT NULL"),
            "the hostile domain name must never have executed"
        );
        assert!(
            upserts.lock().expect("lock poisoned").is_empty(),
            "no /vectors/upsert call may have been made for the poisoned backfill"
        );
    }

    /// Uniform lock order: `pinecone.demote` and
    /// `pinecone.sync` must take the per-relid advisory *xact* lock (the same
    /// DB-scoped single-bigint key `outbox::drain_step`'s worker path takes:
    /// `(MyDatabaseId << 32) | relid`, `objsubid = 1`) FIRST — before `DROP
    /// TRIGGER`/registry/outbox writes — so they can never ABBA-deadlock
    /// against a worker round. The lock is transaction-scoped and a
    /// `#[pg_test]` body is one transaction, so after each call it must be
    /// visible as granted in `pg_locks`.
    #[pg_test]
    fn demote_and_sync_take_the_relid_advisory_lock() {
        create_extension_vector();
        let relid_lock_held = |relid: pg_sys::Oid| {
            Spi::get_one::<bool>(&format!(
                "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_locks \
                 WHERE locktype = 'advisory' AND granted AND objsubid = 1 \
                 AND classid = (SELECT oid FROM pg_catalog.pg_database \
                                WHERE datname = pg_catalog.current_database()) \
                 AND objid = {})",
                relid.to_u32()
            ))
            .expect("pg_locks probe")
            .expect("EXISTS NOT NULL")
        };

        // `'sync'`-mode fixtures on purpose: the `'async'` fixture's own
        // `drain_until_empty` (a Worker-creds `drain_step`) would already
        // have taken each relid's advisory xact lock in this same test
        // transaction, making the "not held before" baselines vacuous — the
        // inline (`Inline`-creds) drain a `'sync'` promote/write uses skips
        // that lock by design (see `drain_step`'s comment).
        let (_backend_a, _u_a, _d_a) = setup_sync_trigger_table_mode("lock_demote", "sync");
        let relid_demote = relid_of("lock_demote");
        assert!(!relid_lock_held(relid_demote), "not held before demote");
        Spi::run("SELECT pinecone.demote('lock_demote')").expect("demote");
        assert!(
            relid_lock_held(relid_demote),
            "demote must have taken lock_demote's advisory xact lock"
        );

        let (_backend_b, _u_b, _d_b) = setup_sync_trigger_table_mode("lock_sync", "sync");
        let relid_sync = relid_of("lock_sync");
        assert!(!relid_lock_held(relid_sync), "not held before sync");
        Spi::run("SELECT pinecone.sync('lock_sync')").expect("sync");
        assert!(
            relid_lock_held(relid_sync),
            "sync must have taken lock_sync's advisory xact lock"
        );
    }

    /// Async `pinecone.sync` coalescing: queued
    /// `'upsert'` rows are superseded (deleted) by the fresh
    /// `'delete_all'`+`'backfill'` pair, the registry row flips `'remote' ->
    /// 'promoting'` in the same transaction (so `topk` serves local while
    /// the rebuild's `delete_all` may have already emptied the namespace),
    /// and draining converges: the namespace is rebuilt from the live rows
    /// and the mode flips back to `'remote'`.
    #[pg_test]
    fn sync_async_coalesces_flips_promoting_and_drains_to_convergence() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("sync_async_coalesce", "async");

        Spi::run(
            "INSERT INTO sync_async_coalesce (id, embedding, category) VALUES \
             (1, '[1,0]', 'a'), (2, '[0,1]', 'b')",
        )
        .expect("insert");
        let queued: Vec<String> = outbox_rows("sync_async_coalesce")
            .iter()
            .map(|r| r.op.clone())
            .collect();
        assert_eq!(queued, vec!["upsert"], "one queued upsert batch");

        Spi::run("SELECT pinecone.sync('sync_async_coalesce')").expect("sync");

        let after: Vec<String> = outbox_rows("sync_async_coalesce")
            .iter()
            .map(|r| r.op.clone())
            .collect();
        assert_eq!(
            after,
            vec!["delete_all".to_string(), "backfill".to_string()],
            "the queued upsert must be superseded (deleted), replaced by the rebuild pair"
        );
        assert_eq!(
            status_rows()[0].1,
            "promoting",
            "sync on an async table must flip 'remote' -> 'promoting' with the enqueue"
        );
        assert!(
            upserts.lock().expect("lock poisoned").is_empty(),
            "sync itself must not push anything inline for an async table"
        );

        drain_until_empty(relid_of("sync_async_coalesce"));

        assert_eq!(
            status_rows()[0].1,
            "remote",
            "the drained rebuild must flip 'promoting' -> 'remote'"
        );
        let recorded_deletes = deletes.lock().expect("lock poisoned").clone();
        assert_eq!(recorded_deletes.len(), 1, "deletes = {recorded_deletes:?}");
        assert_eq!(recorded_deletes[0]["deleteAll"], json!(true));
        let recorded_upserts = upserts.lock().expect("lock poisoned").clone();
        assert_eq!(
            recorded_upserts.len(),
            1,
            "one backfill chunk — upserts = {recorded_upserts:?}"
        );
        let vectors = vectors_by_id(&recorded_upserts[0]);
        assert_eq!(
            vectors.keys().cloned().collect::<Vec<_>>(),
            vec!["1".to_string(), "2".to_string()],
            "the rebuilt namespace must hold exactly the live rows"
        );
    }

    /// 6(c) multi-chunk backfill drill: `BACKFILL_MAX_ROWS + 1` rows force
    /// the `'backfill'` job across three drain rounds — a full first chunk,
    /// a one-row second chunk, then the empty read that flips the mode. The
    /// persisted `payload.after_id` cursor must advance to each chunk's last
    /// id (natively ordered — bigint, not text), and the `'promoting' ->
    /// 'remote'` flip must happen exactly once, only at exhaustion.
    #[pg_test]
    fn multi_chunk_backfill_advances_cursor_and_flips_once_at_exhaustion() {
        create_extension_vector();
        let rows = crate::promote::BACKFILL_MAX_ROWS as i64 + 1;
        Spi::run("CREATE TABLE backfill_chunks (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");
        Spi::run_with_args(
            "INSERT INTO backfill_chunks (id, embedding) \
             SELECT i, ARRAY[i::real, 0.0]::vector FROM generate_series(1, $1) AS i",
            &[rows.into()],
        )
        .expect("insert fixture rows");

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-backfill-chunks",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        one_chunk_per_round();
        Spi::run(
            "SELECT pinecone.promote('backfill_chunks', index_name => 'pv-public-backfill-chunks', \
             sync_mode => 'async')",
        )
        .expect("promote async");

        let after_id = || {
            Spi::get_one::<String>(
                "SELECT payload->>'after_id' FROM pinecone.outbox \
                 WHERE relid = 'backfill_chunks'::regclass AND op = 'backfill'",
            )
            .expect("select after_id")
        };
        let mode = || status_rows()[0].1.clone();
        let batch_sizes = || -> Vec<usize> {
            upserts
                .lock()
                .expect("lock poisoned")
                .iter()
                .map(|body| body["vectors"].as_array().expect("vectors array").len())
                .collect()
        };

        let mut scheduler = crate::outbox::Scheduler::new();

        scheduler.drain_round(); // delete_all + first (full) chunk
        assert_eq!(mode(), "promoting", "still mid-backfill after chunk 1");
        assert_eq!(
            after_id().as_deref(),
            Some("1000"),
            "cursor must sit at the first chunk's last id"
        );
        assert_eq!(batch_sizes(), vec![1000], "chunk 1 pushes a full batch");

        scheduler.drain_round(); // second (one-row) chunk
        assert_eq!(mode(), "promoting", "still mid-backfill after chunk 2");
        assert_eq!(
            after_id().as_deref(),
            Some("1001"),
            "cursor must advance to the second chunk's last id"
        );
        assert_eq!(
            batch_sizes(),
            vec![1000, 1],
            "chunk 2 pushes the one leftover row"
        );

        scheduler.drain_round(); // empty read — exhaustion, single flip
        assert_eq!(
            mode(),
            "remote",
            "the empty chunk read must flip 'promoting' -> 'remote' exactly once, at exhaustion"
        );
        assert_eq!(outbox_count("backfill_chunks"), 0);
        assert_eq!(
            batch_sizes(),
            vec![1000, 1],
            "the exhausting read must push nothing further"
        );
    }

    /// Dropped-relid purge: a `DROP TABLE` with a
    /// still-queued `'backfill'` job must not crash-loop the worker
    /// (`PgRelation::with_lock` on a dead oid raises) — the next drain
    /// purges every queued row for that relid with a `WARNING`, and the same
    /// round still drains other relids. Both tables share ONE mock backend:
    /// the worker drains every relid with the single stored key/URL, so a
    /// second backend's indexes would be unreachable mid-round.
    #[pg_test]
    fn dropped_table_backfill_purges_outbox_with_warning_and_round_continues() {
        create_extension_vector();
        Spi::run("CREATE TABLE drop_backfill (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create dropped table");
        Spi::run("INSERT INTO drop_backfill (id, embedding) VALUES (1, '[1,0]')").expect("insert");
        Spi::run("CREATE TABLE drop_backfill_ok (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create healthy table");

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            // One recording mount pair for both tables; the second index's
            // describe route is added by hand (the helper mounts only one).
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-drop-backfill",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("GET"))
                .and(path("/indexes/pv-public-drop-backfill-ok"))
                .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                .mount(&control_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('drop_backfill_ok', \
             index_name => 'pv-public-drop-backfill-ok', sync_mode => 'async')",
        )
        .expect("promote healthy table");
        drain_until_empty(relid_of("drop_backfill_ok"));
        Spi::run("INSERT INTO drop_backfill_ok (id, embedding) VALUES (1, '[1,0]')")
            .expect("insert healthy row");
        upserts.lock().expect("lock poisoned").clear();

        Spi::run(
            "SELECT pinecone.promote('drop_backfill', index_name => 'pv-public-drop-backfill', \
             sync_mode => 'async')",
        )
        .expect("promote dropped-to-be table — delete_all+backfill queued");
        let dropped_relid = relid_of("drop_backfill");

        Spi::run("DROP TABLE drop_backfill").expect("drop the table out from under its job");

        let backlog_by_oid = |relid: pg_sys::Oid| {
            Spi::get_one::<i64>(&format!(
                "SELECT count(*) FROM pinecone.outbox WHERE relid::oid = {}",
                relid.to_u32()
            ))
            .expect("count by oid")
            .expect("count NOT NULL")
        };
        assert!(
            backlog_by_oid(dropped_relid) > 0,
            "job still queued pre-drain"
        );

        let mut scheduler = crate::outbox::Scheduler::new();
        let (_, warnings) = capture_warnings(|| {
            scheduler.drain_round();
        });

        assert!(
            warnings.iter().any(|w| w.contains("no longer resolves")),
            "warnings = {warnings:?}"
        );
        assert_eq!(
            backlog_by_oid(dropped_relid),
            0,
            "every queued row for the dropped relid must be purged"
        );
        assert_eq!(
            outbox_count("drop_backfill_ok"),
            0,
            "the same round must still drain the healthy relid"
        );
        assert_eq!(
            upserts.lock().expect("lock poisoned").len(),
            1,
            "the healthy relid's queued upsert must have been pushed this round"
        );
    }

    /// Defensive backfill dispatch: a metadata column
    /// dropped after an async promote is a permanent-class failure — the
    /// relid parks with a reason naming the column, instead of the raised
    /// `ERROR` that would crash-loop the worker round.
    #[pg_test]
    fn dropped_metadata_column_parks_backfill_with_clear_reason() {
        create_extension_vector();
        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("set guc");
        Spi::run(
            "CREATE TABLE drop_meta_col (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        )
        .expect("create table");
        Spi::run("INSERT INTO drop_meta_col (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-drop-meta-col").await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})))
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(
            "SELECT pinecone.promote('drop_meta_col', index_name => 'pv-public-drop-meta-col', \
             metadata_columns => ARRAY['category'], sync_mode => 'async')",
        )
        .expect("promote async — backfill job queued");

        Spi::run("ALTER TABLE drop_meta_col DROP COLUMN category").expect("drop metadata column");

        let outcome = crate::outbox::drain_step(
            relid_of("drop_meta_col"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Parked(_)),
            "outcome = {outcome:?}"
        );

        let row = status_rows()
            .into_iter()
            .find(|r| r.0 == "public.drop_meta_col")
            .expect("row present");
        assert_eq!(row.13, Some("parked".to_string()));
        let reason = row.12.expect("parked_reason must be set");
        assert!(reason.contains("category"), "reason = {reason}");
        assert!(reason.contains("no longer exists"), "reason = {reason}");
    }

    // ---- worker/launcher-advisory-lock test synchronization ----
    //
    // `promote_async_with_no_worker_warns`, `status_queue_state_no_worker_
    // then_active_via_launcher_lock_probe`, `worker_singleton_lock_guard_
    // exits_when_already_held`, `worker_singleton_lock_guard_acquires_when_
    // free`, and the `flush_*` tests below all read or write the *same*
    // cluster-wide `outbox::WORKER_LOCK_MAGIC`/`outbox::LAUNCHER_LOCK_MAGIC`
    // advisory locks this crate's real code uses to detect "is a worker/
    // launcher running". `cargo pgrx test` runs `#[pg_test]`s in parallel by
    // default, and each one is its own separate Postgres backend *process*
    // (see e.g. this file's own `distinctive-secret-key-{pid}`/`*_role_{pid}`
    // naming patterns, and `worker_bgw_drain_against_mock`'s rustdoc, which
    // calls this suite "parallel-by-default" outright) — so a plain
    // in-process `std::sync::Mutex` can't serialize these tests against each
    // other; only a lock Postgres's own (genuinely cross-process) lock
    // manager understands can. `TestSerializeGuard` is exactly that: a
    // separate, dedicated advisory lock all of them hold for their entire
    // lock-touching section, so at most one ever runs that section at a time.

    /// Dedicated advisory-lock key for [`TestSerializeGuard`] — distinct
    /// from `outbox::WORKER_LOCK_MAGIC` itself (the lock being
    /// tested/simulated here), so acquiring this one never contends with
    /// whatever a test is about to do to *that* lock.
    const TEST_SERIALIZE_LOCK_MAGIC: i64 = 0x5056_5453; // b"PVTS"

    /// RAII guard for [`TEST_SERIALIZE_LOCK_MAGIC`]: blocks (a plain,
    /// session-scoped `pg_advisory_lock` — not `pg_try_advisory_lock`) until
    /// no other guard-holding test is mid-flight, and releases on every exit
    /// path via `Drop` (which still runs during a panic's unwind), rather
    /// than only after every assertion in the guarded section happens to
    /// pass.
    struct TestSerializeGuard;

    impl TestSerializeGuard {
        fn acquire() -> Self {
            Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_lock({TEST_SERIALIZE_LOCK_MAGIC})"
            ))
            .expect("acquire test-serialize lock");
            Self
        }
    }

    impl Drop for TestSerializeGuard {
        fn drop(&mut self) {
            // Best-effort, like `SmokeIndex`'s own `Drop` (`smoke.rs`): a
            // failure releasing this must never mask whatever the test
            // itself was already panicking about.
            let _ = Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_unlock({TEST_SERIALIZE_LOCK_MAGIC})"
            ));
        }
    }

    /// RAII guard for `outbox::WORKER_LOCK_MAGIC` itself. [`Self::acquire`]
    /// takes it directly via `pg_advisory_lock` (bypassing
    /// `pg_try_advisory_lock`/`worker::try_take_singleton_lock`) to simulate
    /// "another worker already holds this database's lock"; for a lock
    /// `try_take_singleton_lock` itself already took, construct the guard
    /// directly (it's a unit struct) purely for the `Drop`-based release.
    /// Released on every exit path via `Drop` rather than a manual
    /// `pg_advisory_unlock` call an earlier failed assertion could skip —
    /// this lock is session-scoped, so unlike everything else these tests
    /// touch, it doesn't roll back with the test's own transaction.
    struct WorkerLockTestGuard;

    impl WorkerLockTestGuard {
        fn acquire() -> Self {
            Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_lock({}, (SELECT oid::int4 FROM \
                 pg_catalog.pg_database WHERE datname = pg_catalog.current_database()))",
                crate::outbox::WORKER_LOCK_MAGIC
            ))
            .expect("acquire worker lock");
            Self
        }
    }

    impl Drop for WorkerLockTestGuard {
        fn drop(&mut self) {
            let _ = Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_unlock({}, (SELECT oid::int4 FROM \
                 pg_catalog.pg_database WHERE datname = pg_catalog.current_database()))",
                crate::outbox::WORKER_LOCK_MAGIC
            ));
        }
    }

    /// Like [`WorkerLockTestGuard`], but for the LAUNCHER's own cluster-wide
    /// liveness lock (`outbox::LAUNCHER_LOCK_MAGIC`, second key `0`) —
    /// simulates "a launcher is alive and enabled in this cluster", the
    /// signal `status()`'s `queue_state`, `pinecone.flush`, and `promote()`'s
    /// async warning now probe (the real launcher in this
    /// test cluster never takes it, since `pinecone.worker_enabled` boots
    /// `off` here). Same rules as the other guards: acquire under
    /// [`TestSerializeGuard`], release via `Drop` on every exit path.
    struct LauncherLockTestGuard;

    impl LauncherLockTestGuard {
        fn acquire() -> Self {
            Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_lock({}, 0)",
                crate::outbox::LAUNCHER_LOCK_MAGIC
            ))
            .expect("acquire launcher lock");
            Self
        }
    }

    impl Drop for LauncherLockTestGuard {
        fn drop(&mut self) {
            let _ = Spi::run(&format!(
                "SELECT pg_catalog.pg_advisory_unlock({}, 0)",
                crate::outbox::LAUNCHER_LOCK_MAGIC
            ));
        }
    }

    #[pg_test]
    fn promote_async_with_no_worker_warns() {
        let _serialize = TestSerializeGuard::acquire();
        create_extension_vector();
        Spi::run("CREATE TABLE promote_no_worker (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-promote-no-worker").await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        let (_, warnings) = capture_warnings(|| {
            Spi::run("SELECT pinecone.promote('promote_no_worker', sync_mode => 'async')")
                .expect("promote");
        });

        assert!(
            warnings.iter().any(|w| w.contains("no pg_pinecone worker")),
            "warnings = {warnings:?}"
        );
    }

    /// `queue_state`'s liveness signal is the LAUNCHER's
    /// own lock, not the per-database worker's — that worker idle-exits
    /// between backlogs by design, so its lock being free must never read as
    /// `'NO WORKER'` while a live launcher would respawn one for this
    /// backlog. Conversely, holding only the *worker* lock must no longer
    /// flip the state to `'active'`.
    #[pg_test]
    fn status_queue_state_no_worker_then_active_via_launcher_lock_probe() {
        let _serialize = TestSerializeGuard::acquire();
        create_extension_vector();
        let (_backend, _upserts, _deletes) =
            setup_sync_trigger_table_mode("status_no_worker", "async");

        Spi::run("INSERT INTO status_no_worker (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");

        let row13 = || {
            status_rows()
                .into_iter()
                .find(|r| r.0 == "public.status_no_worker")
                .expect("row present")
                .13
        };
        assert_eq!(
            row13(),
            Some("NO WORKER".to_string()),
            "no session holds the launcher lock yet"
        );

        {
            let _worker_lock = WorkerLockTestGuard::acquire();
            assert_eq!(
                row13(),
                Some("NO WORKER".to_string()),
                "the per-database worker lock alone must not read as 'active' — an idle-exited \
                 worker is normal; only launcher liveness matters"
            );
        }

        let _launcher_lock = LauncherLockTestGuard::acquire();

        assert_eq!(
            row13(),
            Some("active".to_string()),
            "backlog > 0 and the launcher lock is now held"
        );
        // `_launcher_lock`/`_serialize` drop here (and on any earlier panic
        // via unwind), releasing both locks.
    }

    /// Single-worker guard: simulates another worker
    /// already holding this database's advisory lock by taking it in this
    /// same session first (see `worker::try_take_singleton_lock`'s rustdoc
    /// for why a probe-then-acquire shape, not a bare re-acquire attempt, is
    /// what makes this deterministic from one `#[pg_test]` connection), then
    /// asserts the worker's own startup guard fn refuses to run.
    #[pg_test]
    fn worker_singleton_lock_guard_exits_when_already_held() {
        let _serialize = TestSerializeGuard::acquire();
        let _worker_lock = WorkerLockTestGuard::acquire();

        assert!(
            !crate::worker::try_take_singleton_lock(),
            "guard must refuse to run while another backend holds the lock"
        );
    }

    /// The other half of [`worker_singleton_lock_guard_exits_when_already_held`]:
    /// with nobody holding the lock, the guard both reports success and
    /// actually takes it (so `outbox::worker_lock_held` now sees it granted).
    #[pg_test]
    fn worker_singleton_lock_guard_acquires_when_free() {
        let _serialize = TestSerializeGuard::acquire();
        assert!(
            crate::worker::try_take_singleton_lock(),
            "guard must succeed when nobody holds the lock"
        );
        // Already held by the `try_take_singleton_lock()` call above — this
        // guard only owns its (eventual) release.
        let _worker_lock = WorkerLockTestGuard;
        assert!(
            crate::outbox::worker_lock_held(),
            "the lock this guard just took must now be visible as held"
        );
    }

    /// The worker version guard's skip path, driven as the worker drives it (`worker::guarded`
    /// around the drain) with a forced mismatch: nothing is drained, and the same round with the
    /// real version drains.
    #[pg_test]
    fn worker_version_guard_skips_the_drain_while_the_versions_differ() {
        create_extension_vector();
        let (_backend, upserts, _deletes) = setup_sync_trigger_table_mode("wvg_skip", "async");
        Spi::run("INSERT INTO wvg_skip (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");
        assert_eq!(outbox_count("wvg_skip"), 1);

        let mut scheduler = crate::outbox::Scheduler::new();
        let mut guard = crate::worker::VersionGuard::new();
        let skipped =
            crate::worker::guarded(&mut guard, "0.0.0-forced", || scheduler.drain_round());
        assert_eq!(skipped, None, "a version mismatch must skip the round");
        assert_eq!(
            outbox_count("wvg_skip"),
            1,
            "a skipped round drains nothing"
        );
        assert!(upserts.lock().expect("upserts lock poisoned").is_empty());

        let ran = crate::worker::guarded(&mut guard, env!("CARGO_PKG_VERSION"), || {
            scheduler.drain_round()
        });
        assert!(ran.is_some(), "matching versions run the round");
        assert_eq!(outbox_count("wvg_skip"), 0);
        assert_eq!(upserts.lock().expect("upserts lock poisoned").len(), 1);
    }

    /// On a fresh install the library and the catalog agree, so the worker does not idle.
    /// `worker_version()` is STABLE and keeps the default PUBLIC `EXECUTE`.
    #[pg_test]
    fn worker_version_reports_matching_versions_on_a_fresh_install() {
        let (compiled, installed, idle) = Spi::get_three::<String, String, bool>(
            "SELECT compiled, installed, idle FROM pinecone.worker_version()",
        )
        .expect("worker_version");
        assert_eq!(compiled.as_deref(), Some(env!("CARGO_PKG_VERSION")));
        assert_eq!(
            installed, compiled,
            "installed == compiled on a fresh install"
        );
        assert_eq!(idle, Some(false));

        let extversion = Spi::get_one::<String>(
            "SELECT extversion::text FROM pg_catalog.pg_extension WHERE extname = 'pg_pinecone'",
        )
        .expect("extversion");
        assert_eq!(installed, extversion);

        let (volatility, public_execute) = Spi::get_two::<String, bool>(
            "SELECT provolatile::text, proacl IS NULL FROM pg_catalog.pg_proc \
             WHERE oid = 'pinecone.worker_version()'::regprocedure",
        )
        .expect("pg_proc");
        assert_eq!(volatility.as_deref(), Some("s"));
        assert_eq!(public_execute, Some(true));
    }

    // ---- pinecone.flush ----

    /// `pinecone.flush` on a drained queue returns `true` immediately — no
    /// launcher lock needed (the backlog check short-circuits before the
    /// liveness probe, so a `sync_mode = 'sync'`-style already-empty queue
    /// never even asks whether anything could drain it).
    #[pg_test]
    fn flush_returns_true_once_drained() {
        create_extension_vector();
        let (_backend, _upserts, _deletes) =
            setup_sync_trigger_table_mode("flush_drained", "async");

        Spi::run("INSERT INTO flush_drained (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");
        assert_eq!(outbox_count("flush_drained"), 1);
        drain_until_empty(relid_of("flush_drained"));

        let flushed = Spi::get_one::<bool>("SELECT pinecone.flush('flush_drained')")
            .expect("select pinecone.flush")
            .expect("flush is NOT NULL");
        assert!(flushed, "an empty backlog must flush true immediately");
    }

    /// A backlog with no launcher alive-and-enabled will never drain —
    /// `pinecone.flush` must return `false` immediately (its own `WARNING`),
    /// not wait out the full timeout for nothing.
    #[pg_test]
    fn flush_no_launcher_returns_false_immediately() {
        let _serialize = TestSerializeGuard::acquire();
        create_extension_vector();
        let (_backend, _upserts, _deletes) =
            setup_sync_trigger_table_mode("flush_no_launcher", "async");

        Spi::run(
            "INSERT INTO flush_no_launcher (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert");
        assert_eq!(outbox_count("flush_no_launcher"), 1);

        let started = std::time::Instant::now();
        let (flushed, warnings) = capture_warnings(|| {
            Spi::get_one::<bool>("SELECT pinecone.flush('flush_no_launcher', 60000)")
                .expect("select pinecone.flush")
                .expect("flush is NOT NULL")
        });
        assert!(!flushed, "no launcher: flush must return false");
        assert!(
            started.elapsed() < std::time::Duration::from_secs(5),
            "must fast-fail, not wait out the 60s timeout"
        );
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("no pg_pinecone launcher")),
            "warnings = {warnings:?}"
        );
        assert_eq!(
            outbox_count("flush_no_launcher"),
            1,
            "flush never drains anything itself"
        );
    }

    /// 6(a) storm case: with a live launcher (simulated via its liveness
    /// lock) but a remote stuck in a 5xx storm, nothing drains the backlog —
    /// `pinecone.flush` must keep polling to its (small) timeout and then
    /// return `false` with the timed-out `WARNING`, not fast-fail: the
    /// machinery is alive; it just hasn't succeeded yet.
    #[pg_test]
    fn flush_times_out_false_during_storm_with_live_launcher() {
        let _serialize = TestSerializeGuard::acquire();
        create_extension_vector();
        let _backend = setup_async_table_with_upsert_status("flush_storm", 500);

        Spi::run("INSERT INTO flush_storm (id, embedding) VALUES (1, '[1,0]')").expect("insert");
        let outcome = crate::outbox::drain_step(
            relid_of("flush_storm"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Backoff(_)),
            "outcome = {outcome:?}"
        );

        let _launcher_lock = LauncherLockTestGuard::acquire();

        let (flushed, warnings) = capture_warnings(|| {
            Spi::get_one::<bool>("SELECT pinecone.flush('flush_storm', 500)")
                .expect("select pinecone.flush")
                .expect("flush is NOT NULL")
        });
        assert!(
            !flushed,
            "the storm never drains — flush must time out false"
        );
        assert!(
            warnings.iter().any(|w| w.contains("timed out")),
            "warnings = {warnings:?}"
        );
        assert_eq!(
            outbox_count("flush_storm"),
            1,
            "the backlog must survive the timed-out flush untouched"
        );
    }

    /// 6(a) parked case: a parked queue is skipped by a live worker on
    /// purpose, so no amount of waiting drains it — `pinecone.flush` must
    /// return `false` immediately with a parked-specific `WARNING`, even
    /// with a live launcher and a generous timeout.
    #[pg_test]
    fn flush_parked_returns_false_immediately() {
        let _serialize = TestSerializeGuard::acquire();
        create_extension_vector();
        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("set guc");
        let _backend = setup_async_table_with_upsert_status("flush_parked", 400);

        Spi::run("INSERT INTO flush_parked (id, embedding) VALUES (1, '[1,0]')").expect("insert");
        let outcome = crate::outbox::drain_step(
            relid_of("flush_parked"),
            crate::backend::DrainCredentials::Worker,
        );
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Parked(_)),
            "outcome = {outcome:?}"
        );

        let _launcher_lock = LauncherLockTestGuard::acquire();

        let started = std::time::Instant::now();
        let (flushed, warnings) = capture_warnings(|| {
            Spi::get_one::<bool>("SELECT pinecone.flush('flush_parked', 60000)")
                .expect("select pinecone.flush")
                .expect("flush is NOT NULL")
        });
        assert!(!flushed, "parked: flush must return false");
        assert!(
            started.elapsed() < std::time::Duration::from_secs(5),
            "parked must fast-fail even with a live launcher and a 60s timeout"
        );
        assert!(
            warnings.iter().any(|w| w.contains("parked")),
            "warnings = {warnings:?}"
        );
    }

    /// A `dblink` conninfo string pointing back at this same test cluster —
    /// `dblink_exec(conninfo, sql)` opens a brand-new backend, runs `sql` in
    /// its own autocommitted statement, and closes it. Needed because
    /// `pgrx-tests` wraps an *entire* `#[pg_test]` body in one transaction
    /// that's always rolled back client-side (win or lose) — so nothing a
    /// test does through its own `Spi::run`/`Spi::get_one` calls is *ever*
    /// visible to another backend, e.g. a real, separately-spawned worker
    /// process. Routing setup through `dblink_exec` instead gives genuinely
    /// committed, cross-backend-visible state (verified empirically while
    /// building this — see `worker_bgw_drain_against_mock`'s rustdoc), and
    /// also sidesteps `ALTER SYSTEM cannot run inside a transaction block`
    /// (a `dblink_exec` call isn't inside one, from its own connection's
    /// point of view).
    fn dblink_conninfo() -> String {
        Spi::run("CREATE EXTENSION IF NOT EXISTS dblink").expect("create dblink");
        let port = Spi::get_one::<String>("SHOW port")
            .expect("show port")
            .unwrap();
        let dbname = Spi::get_one::<String>("SELECT current_database()::text")
            .expect("current_database")
            .unwrap();
        let user = Spi::get_one::<String>("SELECT current_user::text")
            .expect("current_user")
            .unwrap();
        format!("host=127.0.0.1 port={port} dbname={dbname} user={user}")
    }

    /// Runs `sql` to completion through [`dblink_conninfo`]'s standalone,
    /// autocommitting connection — panics with `sql` and the error on
    /// failure, so a broken fixture step is easy to place.
    fn dblink_exec(conninfo: &str, sql: &str) {
        Spi::run(&format!(
            "SELECT dblink_exec('{conninfo}', $ddl${sql}$ddl$)"
        ))
        .unwrap_or_else(|e| panic!("dblink_exec failed for {sql:?}: {e}"));
    }

    /// Like [`dblink_exec`], but for calling a function whose return value is
    /// discarded (`pinecone.set_api_key`/`promote`/`demote`,
    /// `pg_catalog.pg_reload_conf`) — `dblink_exec` itself rejects any
    /// statement that returns a result set, which a bare `SELECT expr` always
    /// does (even for a `void`-returning function), so this wraps `expr` in a
    /// `DO`/`PERFORM` block instead, which never returns rows.
    fn dblink_perform(conninfo: &str, expr: &str) {
        dblink_exec(conninfo, &format!("DO $pv$ BEGIN PERFORM {expr}; END $pv$"));
    }

    /// RAII guard flipping `pinecone.worker_enabled` on for a test that needs
    /// the real background worker running, and back to this test cluster's
    /// own baseline (`off`, from `pg_test::postgresql_conf_options`) on every
    /// exit path, including a panic partway through.
    ///
    /// [`Self::enable`] restores with `ALTER SYSTEM SET ... = off`, *not*
    /// `ALTER SYSTEM RESET`: this suite's `off` baseline was itself written
    /// into `postgresql.auto.conf` by `pgrx-tests`' own `initdb` (from
    /// `postgresql_conf_options()`), the very same file `ALTER SYSTEM SET`
    /// rewrites — so `RESET` doesn't restore that baseline, it *deletes* the
    /// override entirely, unmasking this GUC's compiled-in default (`true`
    /// — see its `_PG_init` registration in `lib.rs`) and leaving the worker
    /// enabled for the rest of this cluster's process lifetime instead.
    struct WorkerEnabledGuard {
        conninfo: String,
    }

    impl WorkerEnabledGuard {
        fn enable(conninfo: &str) -> Self {
            dblink_exec(conninfo, "ALTER SYSTEM SET pinecone.worker_enabled = on");
            dblink_perform(conninfo, "pg_catalog.pg_reload_conf()");
            Self {
                conninfo: conninfo.to_string(),
            }
        }
    }

    impl Drop for WorkerEnabledGuard {
        fn drop(&mut self) {
            dblink_exec(
                &self.conninfo,
                "ALTER SYSTEM SET pinecone.worker_enabled = off",
            );
            dblink_perform(&self.conninfo, "pg_catalog.pg_reload_conf()");
        }
    }

    /// Timeboxed BGW integration test. Builds its whole fixture — table, mocked
    /// promote, stored key, the enqueuing insert — through [`dblink_exec`]
    /// (see its rustdoc for why: a plain same-session fixture is *never*
    /// visible to the real worker `pgrx-tests` would otherwise hide it
    /// from), flips `pinecone.worker_enabled` on for real (also via
    /// `dblink_exec`, since `ALTER SYSTEM` can't run in this test's own
    /// transaction), and polls this session's own (read-committed, so it
    /// *does* see other backends' commits) queries for the row to drain.
    ///
    /// `#[ignore]`d: `pinecone.worker_enabled` is a cluster-wide GUC and the
    /// fixture above is genuinely committed (not rolled back like a normal
    /// test) — running this inside the shared, parallel-by-default
    /// `#[pg_test]` suite risks a real worker draining some *other*,
    /// concurrently-running test's outbox rows (or racing `pinecone.secret`,
    /// a single-row table both would touch), and leaves committed debris
    /// behind for the rest of that run. Verified in isolation (`cargo pgrx
    /// test pg17 worker_bgw_drain_against_mock -- --ignored
    /// --test-threads=1`), where it passes end to end against the real BGW
    /// machinery (launcher spawn → singleton lock → `stored_credentials` →
    /// per-round commit). `scripts/smoke.sh`'s `live_worker_drain` (its own
    /// dedicated, single-test cluster, against a real Pinecone index) is the
    /// primary, always-on real-BGW proof.
    #[pg_test]
    #[ignore]
    fn worker_bgw_drain_against_mock() {
        let conninfo = dblink_conninfo();
        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        // `mount_sync_trigger_recording` mounts everything `promote` itself
        // needs (index create/describe + `pinecone.promote`'s own deleteAll)
        // *and* records every later `/vectors/upsert`/`/vectors/delete` —
        // including the worker's own drain, since it's the same real TCP
        // listener regardless of which OS process connects to it.
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-worker-bgw-drain",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });

        dblink_exec(
            &conninfo,
            "CREATE EXTENSION IF NOT EXISTS vector; \
             CREATE TABLE worker_bgw_drain (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        );
        dblink_perform(
            &conninfo,
            &format!(
                "pinecone.set_api_key('test-key', '{}')",
                backend.control_plane_url
            ),
        );
        dblink_perform(
            &conninfo,
            "pinecone.promote('worker_bgw_drain', index_name => \
             'pv-public-worker-bgw-drain', metadata_columns => ARRAY['category'], \
             sync_mode => 'async')",
        );
        dblink_exec(
            &conninfo,
            "INSERT INTO worker_bgw_drain (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        );
        // 3, not 1: the async promote above itself
        // enqueued a `delete_all`+`backfill` job pair (the table was empty at
        // promote time) — the insert's own `upsert` row is the third.
        assert_eq!(outbox_count("worker_bgw_drain"), 3);

        // `Drop` restores `pinecone.worker_enabled = off` on every exit path
        // below, including the panic in the timeout branch — see its
        // rustdoc for why `ALTER SYSTEM SET ... = off`, not `RESET`.
        let _worker_enabled_guard = WorkerEnabledGuard::enable(&conninfo);

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        loop {
            let drained = outbox_count("worker_bgw_drain") == 0;
            let mock_saw_it = !upserts.lock().expect("upserts lock poisoned").is_empty();
            if drained && mock_saw_it {
                break;
            }
            if std::time::Instant::now() >= deadline {
                dblink_exec(&conninfo, "DROP TABLE worker_bgw_drain");
                panic!(
                    "the background worker never drained worker_bgw_drain within 30s \
                     (drained={drained}, mock_saw_it={mock_saw_it})"
                );
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_millis(200));
        }

        // 2, not 1: the still-live `backfill` job's own chunk read picks up
        // the same row the plain trigger-enqueued `upsert` row also carries
        // (the insert landed before the worker ever started draining) — both
        // push it, so the mock sees id=1 twice (idempotent on the real
        // Pinecone side; the "mid-backfill DML
        // converges" case, exercised live here instead of mocked in-process).
        assert_eq!(upserts.lock().expect("upserts lock poisoned").len(), 2);
        // Committed by `dblink_exec`, so — unlike everything else this test
        // suite creates — this needs an explicit, genuine cleanup rather
        // than relying on the harness's per-test rollback.
        dblink_perform(&conninfo, "pinecone.demote('worker_bgw_drain')");
        dblink_exec(&conninfo, "DELETE FROM pinecone.secret");
        dblink_exec(&conninfo, "DROP TABLE worker_bgw_drain");
        // `_worker_enabled_guard` drops here (and on any earlier panic via
        // unwind), restoring `pinecone.worker_enabled = off`.
    }

    /// Restores the worker pacing GUCs `worker_bgw_backfill_does_not_nap_between_rounds` sets.
    struct WorkerPacingGuard {
        conninfo: String,
    }

    impl Drop for WorkerPacingGuard {
        fn drop(&mut self) {
            for guc in ["pinecone.worker_naptime_ms", "pinecone.backfill_round_ms"] {
                dblink_exec(&self.conninfo, &format!("ALTER SYSTEM RESET {guc}"));
            }
            dblink_perform(&self.conninfo, "pg_catalog.pg_reload_conf()");
        }
    }

    /// A SIGTERM to the real worker ends a backfill round after the chunk in flight: with a 60 s
    /// round budget and 300 ms upserts the worker is gone well inside two seconds, a few chunks
    /// into a 20-chunk job, which stays queued at its cursor. `#[ignore]`d like
    /// `worker_bgw_drain_against_mock`: run it alone with
    /// `cargo pgrx test pg17 worker_bgw_sigterm -- --ignored --test-threads=1`.
    #[pg_test]
    #[ignore]
    fn worker_bgw_sigterm_ends_a_backfill_round() {
        let conninfo = dblink_conninfo();
        let vectors = VectorsHandle::new();
        let backend = start_with_vectors(&vectors);
        vectors.set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(300));
        dblink_exec(
            &conninfo,
            "CREATE EXTENSION IF NOT EXISTS vector; \
             CREATE TABLE worker_bgw_term (id bigint PRIMARY KEY, embedding vector(2))",
        );
        dblink_exec(
            &conninfo,
            "INSERT INTO worker_bgw_term SELECT i, \
             ARRAY[cos(i * 0.005), sin(i * 0.005)]::real[]::vector FROM generate_series(1, 20000) i",
        );
        dblink_perform(
            &conninfo,
            &format!(
                "pinecone.set_api_key('test-key', '{}')",
                backend.control_plane_url
            ),
        );
        dblink_perform(
            &conninfo,
            "pinecone.promote('worker_bgw_term', index_name => 'pv-public-worker-bgw-term', \
             sync_mode => 'async')",
        );
        let _pacing = WorkerPacingGuard {
            conninfo: conninfo.clone(),
        };
        dblink_exec(
            &conninfo,
            "ALTER SYSTEM SET pinecone.backfill_round_ms = 60000",
        );
        let worker = WorkerEnabledGuard::enable(&conninfo);

        let worker_pid = || {
            Spi::run("SELECT pg_stat_clear_snapshot()").expect("fresh activity snapshot");
            Spi::get_one::<i32>(
                "SELECT (SELECT pid FROM pg_stat_activity \
                 WHERE backend_type LIKE 'pg_pinecone worker%' ORDER BY pid LIMIT 1)",
            )
            .expect("read pg_stat_activity")
        };
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(40);
        while vectors.count(VecEndpoint::Upsert) < 2 || worker_pid().is_none() {
            if std::time::Instant::now() >= deadline {
                drop(worker);
                dblink_exec(&conninfo, "DROP TABLE worker_bgw_term");
                panic!("the worker did not start its backfill within 40 s");
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_millis(50));
        }
        let pid = worker_pid().expect("a worker is running");

        let signalled = std::time::Instant::now();
        Spi::run(&format!("SELECT pg_terminate_backend({pid})")).expect("SIGTERM the worker");
        while worker_pid() == Some(pid) {
            if signalled.elapsed() > std::time::Duration::from_secs(30) {
                break;
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_millis(25));
        }
        let took = signalled.elapsed();

        let sent = vectors.count(VecEndpoint::Upsert);
        let queued = outbox_count("worker_bgw_term");
        drop(worker);
        dblink_perform(&conninfo, "pinecone.demote('worker_bgw_term')");
        dblink_exec(&conninfo, "DELETE FROM pinecone.secret");
        dblink_exec(&conninfo, "DROP TABLE worker_bgw_term");
        assert!(
            took < std::time::Duration::from_secs(2),
            "the worker took {took:?} to stop: after the round's 60 s budget, or the job, it takes 5 s or more"
        );
        assert!(sent < 20, "{sent} chunks went out: the job ran to its end");
        assert!(
            queued >= 1,
            "the backfill job is still queued at its cursor"
        );
    }

    /// The real worker starts the next backfill round at once: 3,000 rows are three chunks and the
    /// read that ends the job, one round each (50 ms rounds, 60 ms requests), so with an 8 s naptime
    /// they take about a second, not 16 s or more. `#[ignore]`d like `worker_bgw_drain_against_mock`:
    /// run it alone with `cargo pgrx test pg17 worker_bgw_backfill -- --ignored --test-threads=1`.
    #[pg_test]
    #[ignore]
    fn worker_bgw_backfill_does_not_nap_between_rounds() {
        let conninfo = dblink_conninfo();
        let vectors = VectorsHandle::new();
        let backend = start_with_vectors(&vectors);
        vectors.set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));
        dblink_exec(
            &conninfo,
            "CREATE EXTENSION IF NOT EXISTS vector; \
             CREATE TABLE worker_bgw_rounds (id bigint PRIMARY KEY, embedding vector(2))",
        );
        dblink_exec(
            &conninfo,
            "INSERT INTO worker_bgw_rounds SELECT i, \
             ARRAY[cos(i * 0.005), sin(i * 0.005)]::real[]::vector FROM generate_series(1, 3000) i",
        );
        dblink_perform(
            &conninfo,
            &format!(
                "pinecone.set_api_key('test-key', '{}')",
                backend.control_plane_url
            ),
        );
        dblink_perform(
            &conninfo,
            "pinecone.promote('worker_bgw_rounds', index_name => 'pv-public-worker-bgw-rounds', \
             sync_mode => 'async')",
        );
        let _pacing = WorkerPacingGuard {
            conninfo: conninfo.clone(),
        };
        dblink_exec(
            &conninfo,
            "ALTER SYSTEM SET pinecone.worker_naptime_ms = 8000",
        );
        dblink_exec(
            &conninfo,
            "ALTER SYSTEM SET pinecone.backfill_round_ms = 50",
        );
        let started = std::time::Instant::now();
        let _worker = WorkerEnabledGuard::enable(&conninfo);

        let deadline = started + std::time::Duration::from_secs(40);
        while outbox_count("worker_bgw_rounds") > 0 {
            if std::time::Instant::now() >= deadline {
                dblink_exec(&conninfo, "DROP TABLE worker_bgw_rounds");
                panic!("the worker did not finish the backfill within 40 s");
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_millis(100));
        }
        let took = started.elapsed();

        let upserts = vectors.count(VecEndpoint::Upsert);
        dblink_perform(&conninfo, "pinecone.demote('worker_bgw_rounds')");
        dblink_exec(&conninfo, "DELETE FROM pinecone.secret");
        dblink_exec(&conninfo, "DROP TABLE worker_bgw_rounds");
        assert_eq!(upserts, 3, "three chunks of 1,000 rows");
        assert!(
            took < std::time::Duration::from_secs(8),
            "{took:?}: with a nap after each round it takes 16 s or more"
        );
    }

    #[pg_test]
    fn promote_sync_mode_invalid_value_errors() {
        create_extension_vector();
        Spi::run("CREATE TABLE promote_bad_sync_mode (id bigint PRIMARY KEY, embedding vector(2))")
            .expect("create table");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run("SELECT pinecone.promote('promote_bad_sync_mode', sync_mode => 'whenever')")
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("invalid sync_mode must error");
        assert!(message.contains("async"), "message = {message}");
        assert!(message.contains("sync"), "message = {message}");
    }

    /// `pinecone.sync_mode`'s current value is the default for a genuinely
    /// *new* promotion when the `sync_mode` argument is omitted.
    #[pg_test]
    fn promote_sync_mode_guc_default_used_when_arg_omitted() {
        create_extension_vector();
        Spi::run(
            "CREATE TABLE promote_guc_sync (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        )
        .expect("create table");

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-promote-guc-sync",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run("SET pinecone.sync_mode = 'sync'").expect("set GUC default to sync");
        Spi::run(
            "SELECT pinecone.promote('promote_guc_sync', index_name => 'pv-public-promote-guc-sync', \
             metadata_columns => ARRAY['category'])",
        )
        .expect("promote with no explicit sync_mode arg");
        upserts.lock().expect("lock poisoned").clear();
        deletes.lock().expect("lock poisoned").clear();

        Spi::run("INSERT INTO promote_guc_sync (id, embedding, category) VALUES (1, '[1,0]', 'a')")
            .expect("insert");

        assert_eq!(
            upserts.lock().expect("lock poisoned").len(),
            1,
            "GUC default 'sync' must drain inline"
        );
        assert_eq!(outbox_count("promote_guc_sync"), 0);
    }

    /// Regression test: a bare re-promote (after a `demote()` that
    /// keeps the registry row) must reuse the row's already-stored
    /// `sync_mode` — even if the `pinecone.sync_mode` GUC default has changed
    /// in the meantime — the same preserve-registration convention
    /// `index_name`/`namespace` use (`promote_bare_reuses_custom_index_name_after_demote`).
    #[pg_test]
    fn promote_bare_reuse_preserves_sync_mode_over_guc_change() {
        create_extension_vector();
        Spi::run(
            "CREATE TABLE promote_keep_sync_mode (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        )
        .expect("create table");

        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let deletes = Arc::new(Mutex::new(Vec::<Value>::new()));
        let (upserts_for_mock, deletes_for_mock) = (Arc::clone(&upserts), Arc::clone(&deletes));
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_sync_trigger_recording(
                &control_plane,
                &data_plane,
                "pv-public-promote-keep-sync-mode",
                upserts_for_mock,
                deletes_for_mock,
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('promote_keep_sync_mode', \
             index_name => 'pv-public-promote-keep-sync-mode', \
             metadata_columns => ARRAY['category'], sync_mode => 'sync')",
        )
        .expect("promote sync");
        Spi::run("SELECT pinecone.demote('promote_keep_sync_mode')").expect("demote");

        // Change the GUC default *after* the first promote — a bare
        // re-promote must still honor the row's own preserved 'sync', not
        // flip to this new default.
        Spi::run("SET pinecone.sync_mode = 'async'").expect("change GUC default");
        Spi::run("SELECT pinecone.promote('promote_keep_sync_mode')").expect("bare re-promote");

        upserts.lock().expect("lock poisoned").clear();
        deletes.lock().expect("lock poisoned").clear();

        Spi::run(
            "INSERT INTO promote_keep_sync_mode (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("insert");

        assert_eq!(
            upserts.lock().expect("lock poisoned").len(),
            1,
            "bare re-promote must preserve sync_mode='sync' from before, not reset to the new \
             GUC default"
        );
        assert_eq!(outbox_count("promote_keep_sync_mode"), 0);
    }

    // ---- Parity suite: local vs remote pinecone.topk ----
    //
    // One fixed fixture (12 vectors, dimension 4, `category` text + `views`
    // int metadata) driven through BOTH modes: a real pgvector table for
    // local, a table promoted against a MockBackend for remote, whose
    // `/query` mock returns scores computed by this file's own
    // `parity_score` — the textbook formula per metric, not a call into
    // pgvector — so a real bug in either the local SQL path or the remote
    // score->distance conversion in `topk.rs` shows up as a mismatch here
    // rather than two independently-wrong-but-agreeing implementations.

    const PARITY_N: i64 = 12;
    const PARITY_QUERY: [f32; 4] = [0.35, -0.15, 0.2, 0.05];
    const PARITY_CATEGORIES: [&str; 3] = ["drama", "comedy", "action"];

    fn parity_vector(i: i64) -> [f32; 4] {
        let x = i as f64;
        [
            x.sin() as f32,
            x.cos() as f32,
            (2.0 * x).sin() as f32,
            (3.0 * x).cos() as f32,
        ]
    }

    fn parity_category(i: i64) -> &'static str {
        PARITY_CATEGORIES[(i.rem_euclid(3)) as usize]
    }

    fn parity_views(i: i64) -> i64 {
        i * 7
    }

    fn cosine_similarity(a: &[f32; 4], b: &[f32; 4]) -> f64 {
        let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
        let norm_a: f64 = a.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
        let norm_b: f64 = b.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
        dot / (norm_a * norm_b)
    }

    fn squared_l2(a: &[f32; 4], b: &[f32; 4]) -> f64 {
        a.iter()
            .zip(b)
            .map(|(x, y)| (*x as f64 - *y as f64).powi(2))
            .sum()
    }

    fn dot_product(a: &[f32; 4], b: &[f32; 4]) -> f64 {
        a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum()
    }

    /// The score real Pinecone would report for `vector` against
    /// [`PARITY_QUERY`] under `metric`: cosine similarity, squared L2 distance, or raw dot product.
    fn parity_score(metric: &str, vector: &[f32; 4]) -> f64 {
        match metric {
            "cosine" => cosine_similarity(&PARITY_QUERY, vector),
            "l2" => squared_l2(&PARITY_QUERY, vector),
            "ip" => dot_product(&PARITY_QUERY, vector),
            other => panic!("parity: unknown metric {other}"),
        }
    }

    /// The fixture's `(id, score)` pairs matching `filter`, in the order real
    /// Pinecone would return them for `metric` (descending score for
    /// cosine/ip; ascending for l2, since a lower squared distance is better).
    fn parity_sorted_matches(metric: &str, filter: impl Fn(i64) -> bool) -> Vec<(String, f64)> {
        let mut scored: Vec<(String, f64)> = (1..=PARITY_N)
            .filter(|i| filter(*i))
            .map(|i| (i.to_string(), parity_score(metric, &parity_vector(i))))
            .collect();
        if metric == "l2" {
            scored.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap());
        } else {
            scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        }
        scored
    }

    /// Creates and populates `table` with the parity fixture (does not track
    /// or promote it — callers do that themselves, differently per mode).
    fn setup_parity_table(table: &str) {
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(4), category text, \
             views int)"
        ))
        .expect("create parity table");
        for i in 1..=PARITY_N {
            let [a, b, c, d] = parity_vector(i);
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding, category, views) \
                 VALUES ({i}, ARRAY[{a}, {b}, {c}, {d}]::real[]::vector, {}, {})",
                quote_literal(parity_category(i)),
                parity_views(i),
            ))
            .expect("insert parity fixture row");
        }
    }

    /// Mounts control/data-plane mocks for promoting a table to a mocked
    /// index of the given `dimension`/`metric`, with a wildcard-accepting
    /// `/vectors/upsert` (the parity fixture always backfills real rows,
    /// unlike `mount_promote_success`).
    async fn mount_parity_promote(
        control_plane: &wiremock::MockServer,
        data_plane: &wiremock::MockServer,
        index_name: &str,
        dimension: u32,
        metric: &str,
    ) {
        let index_body = json!({
            "host": data_plane.uri(),
            "dimension": dimension,
            "metric": metric,
            "vector_type": "dense",
            "status": {"ready": true, "state": "Ready"},
        });
        // minor regression (parity suite): pins the Pinecone-side metric name
        // ("euclidean"/"dotproduct", not pg_pinecone's internal "l2"/"ip") in the
        // actual outgoing POST /indexes body — every parity test uses the
        // default cloud/region, so the whole body is known exactly.
        Mock::given(method("POST"))
            .and(path("/indexes"))
            .and(body_json(json!({
                "name": index_name,
                "vector_type": "dense",
                "dimension": dimension,
                "metric": metric,
                "spec": {"serverless": {"cloud": "aws", "region": "us-east-1"}},
                "deletion_protection": "disabled",
            })))
            .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
            .mount(control_plane)
            .await;
        Mock::given(method("GET"))
            .and(path(format!("/indexes/{index_name}")))
            .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
            .mount(control_plane)
            .await;
        Mock::given(method("POST"))
            .and(path("/vectors/delete"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
            .mount(data_plane)
            .await;
        Mock::given(method("POST"))
            .and(path("/vectors/upsert"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 12})))
            .mount(data_plane)
            .await;
    }

    /// Runs `pinecone.topk` on `table` expecting a Postgres `ERROR`, returning
    /// its message. `query_literal` is a raw `ARRAY[...]::real[]` SQL
    /// fragment (not a bound parameter — these tests only need fixed values).
    fn expect_topk_error(table: &str, query_literal: &str, filter_json: &str) -> String {
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT * FROM pinecone.topk({}, {query_literal}, 5, {}::jsonb)",
                quote_literal(table),
                quote_literal(filter_json)
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        outcome.expect_err("expected pinecone.topk to raise an error")
    }

    fn parity_query_array_literal() -> String {
        format!(
            "ARRAY[{}]::real[]",
            PARITY_QUERY
                .iter()
                .map(|v| v.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        )
    }

    /// (a)+(b): local topk on a real pgvector table vs. remote topk against a
    /// MockBackend whose `/query` mock returns `parity_score`'s values for
    /// the same fixture — asserts identical id order and distances within 1e-4.
    fn assert_parity_metric(metric: &str, pinecone_metric: &str, suffix: &str) {
        create_extension_vector();
        let local_table = format!("parity_local_{suffix}");
        let remote_table = format!("parity_remote_{suffix}");
        let index_name = format!("pv-public-parity-remote-{suffix}");

        setup_parity_table(&local_table);
        Spi::run(&format!(
            "SELECT pinecone.track({}, metric => {})",
            quote_literal(&local_table),
            quote_literal(metric)
        ))
        .expect("track local parity table");

        setup_parity_table(&remote_table);

        let expected = parity_sorted_matches(metric, |_| true);
        let matches_json: Vec<Value> = expected
            .iter()
            .map(|(id, score)| json!({"id": id, "score": score}))
            .collect();

        let index_name_for_mock = index_name.clone();
        let pinecone_metric = pinecone_metric.to_string();
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_parity_promote(
                &control_plane,
                &data_plane,
                &index_name_for_mock,
                4,
                &pinecone_metric,
            )
            .await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .respond_with(
                    ResponseTemplate::new(200).set_body_json(json!({"matches": matches_json})),
                )
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metric => {}, sync_mode => 'sync')",
            quote_literal(&remote_table),
            quote_literal(&index_name),
            quote_literal(metric)
        ))
        .expect("promote remote parity table");

        let want = topk_call(&local_table, PARITY_QUERY.to_vec(), PARITY_N as i32, None);
        let got = topk_call(&remote_table, PARITY_QUERY.to_vec(), PARITY_N as i32, None);

        assert_eq!(
            got.len(),
            want.len(),
            "metric = {metric}: got = {got:?}, want = {want:?}"
        );
        for (g, w) in got.iter().zip(want.iter()) {
            assert_eq!(
                g.0, w.0,
                "metric = {metric}: id order mismatch, got = {got:?}, want = {want:?}"
            );
            assert!(
                (g.1 - w.1).abs() < 1e-4,
                "metric = {metric}: distance mismatch for id {}: got {}, want {}",
                g.0,
                g.1,
                w.1
            );
        }
    }

    #[pg_test]
    fn parity_metric_cosine() {
        assert_parity_metric("cosine", "cosine", "cos");
    }

    #[pg_test]
    fn parity_metric_l2() {
        assert_parity_metric("l2", "euclidean", "l2");
    }

    #[pg_test]
    fn parity_metric_ip() {
        assert_parity_metric("ip", "dotproduct", "ip");
    }

    /// (c): the same jsonb filter, in both modes, selects the same id set.
    #[pg_test]
    fn parity_filter_same_id_set_both_modes() {
        create_extension_vector();
        let local_table = "parity_filter_local";
        let remote_table = "parity_filter_remote";
        let index_name = "pv-public-parity-filter-remote";
        let filter_json = r#"{"category": {"$eq": "drama"}}"#;

        setup_parity_table(local_table);
        Spi::run(&format!(
            "SELECT pinecone.track({}, metric => 'cosine', \
             metadata_columns => ARRAY['category', 'views'])",
            quote_literal(local_table)
        ))
        .expect("track local parity table");

        setup_parity_table(remote_table);

        let filtered = parity_sorted_matches("cosine", |i| parity_category(i) == "drama");
        let matches_json: Vec<Value> = filtered
            .iter()
            .map(|(id, score)| json!({"id": id, "score": score}))
            .collect();
        let expected_filter = json!({"category": {"$eq": "drama"}});
        let expected_body = json!({
            "vector": PARITY_QUERY.to_vec(),
            "topK": PARITY_N,
            "includeMetadata": false,
            "namespace": format!("public.{remote_table}"),
            "filter": expected_filter,
        });

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_parity_promote(
                &control_plane,
                &data_plane,
                "pv-public-parity-filter-remote",
                4,
                "cosine",
            )
            .await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .and(body_json(expected_body))
                .respond_with(
                    ResponseTemplate::new(200).set_body_json(json!({"matches": matches_json})),
                )
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metric => 'cosine', \
             metadata_columns => ARRAY['category', 'views'], sync_mode => 'sync')",
            quote_literal(remote_table),
            quote_literal(index_name)
        ))
        .expect("promote remote parity table");

        let want_ids: BTreeSet<String> = topk_call(
            local_table,
            PARITY_QUERY.to_vec(),
            PARITY_N as i32,
            Some(filter_json),
        )
        .into_iter()
        .map(|(id, _)| id)
        .collect();
        let got_ids: BTreeSet<String> = topk_call(
            remote_table,
            PARITY_QUERY.to_vec(),
            PARITY_N as i32,
            Some(filter_json),
        )
        .into_iter()
        .map(|(id, _)| id)
        .collect();

        assert_eq!(
            got_ids, want_ids,
            "local/remote filter must select the same id set"
        );
        assert!(
            !want_ids.is_empty(),
            "test fixture should have at least one 'drama' row"
        );
    }

    /// (c, error half): a filter on a column outside `metadata_columns`
    /// works locally (any column is filterable) but errors remotely with the
    /// "add it to metadata_columns and re-promote" hint.
    #[pg_test]
    fn parity_unregistered_column_errors_remote_only() {
        create_extension_vector();
        let local_table = "parity_unreg_local";
        let remote_table = "parity_unreg_remote";
        let index_name = "pv-public-parity-unreg-remote";

        setup_parity_table(local_table);
        Spi::run(&format!(
            "SELECT pinecone.track({}, metric => 'cosine')",
            quote_literal(local_table)
        ))
        .expect("track local parity table (no metadata_columns restriction)");

        setup_parity_table(remote_table);
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_parity_promote(
                &control_plane,
                &data_plane,
                "pv-public-parity-unreg-remote",
                4,
                "cosine",
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metric => 'cosine', \
             metadata_columns => ARRAY['category'], sync_mode => 'sync')",
            quote_literal(remote_table),
            quote_literal(index_name)
        ))
        .expect("promote remote parity table (metadata_columns excludes 'views')");

        let query_literal = parity_query_array_literal();
        let local_ok = topk_call(
            local_table,
            PARITY_QUERY.to_vec(),
            5,
            Some(r#"{"views": {"$gte": 10}}"#),
        );
        assert!(
            !local_ok.is_empty(),
            "local filter on a column outside metadata_columns should still work"
        );

        let message = expect_topk_error(remote_table, &query_literal, r#"{"views": {"$gte": 10}}"#);
        assert!(message.contains("views"), "message = {message}");
        assert!(
            message.contains("add it to metadata_columns and re-promote"),
            "message = {message}"
        );
    }

    /// (d): an unsupported filter operator errors identically in both modes.
    #[pg_test]
    fn parity_bad_operator_errors_identically_in_both_modes() {
        create_extension_vector();
        let local_table = "parity_badop_local";
        let remote_table = "parity_badop_remote";
        let index_name = "pv-public-parity-badop-remote";

        setup_parity_table(local_table);
        Spi::run(&format!(
            "SELECT pinecone.track({}, metric => 'cosine', metadata_columns => ARRAY['category'])",
            quote_literal(local_table)
        ))
        .expect("track local parity table");

        setup_parity_table(remote_table);
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_parity_promote(
                &control_plane,
                &data_plane,
                "pv-public-parity-badop-remote",
                4,
                "cosine",
            )
            .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metric => 'cosine', \
             metadata_columns => ARRAY['category'], sync_mode => 'sync')",
            quote_literal(remote_table),
            quote_literal(index_name)
        ))
        .expect("promote remote parity table");

        let query_literal = parity_query_array_literal();
        let bad_filter = r#"{"category": {"$bogus": "x"}}"#;

        let local_message = expect_topk_error(local_table, &query_literal, bad_filter);
        let remote_message = expect_topk_error(remote_table, &query_literal, bad_filter);

        for message in [&local_message, &remote_message] {
            assert!(message.contains("unknown operator"), "message = {message}");
            assert!(message.contains("$bogus"), "message = {message}");
        }
    }

    /// Regression test: `k => 0` must short-circuit to an empty result
    /// in *both* modes before dispatch — no local SQL execution, and (for
    /// remote) no `/query` HTTP call at all.
    #[pg_test]
    fn parity_k_zero_short_circuits_both_modes_without_remote_query() {
        create_extension_vector();
        let local_table = "parity_k_zero_local";
        let remote_table = "parity_k_zero_remote";
        let index_name = "pv-public-parity-k-zero-remote";

        setup_parity_table(local_table);
        Spi::run(&format!(
            "SELECT pinecone.track({}, metric => 'cosine')",
            quote_literal(local_table)
        ))
        .expect("track local parity table");

        setup_parity_table(remote_table);
        let query_calls: Arc<Mutex<u32>> = Arc::new(Mutex::new(0));
        let query_calls_for_mock = Arc::clone(&query_calls);
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_parity_promote(&control_plane, &data_plane, index_name, 4, "cosine").await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .respond_with(move |_req: &Request| {
                    *query_calls_for_mock
                        .lock()
                        .expect("query_calls lock poisoned") += 1;
                    ResponseTemplate::new(200).set_body_json(json!({"matches": []}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metric => 'cosine', sync_mode => 'sync')",
            quote_literal(remote_table),
            quote_literal(index_name)
        ))
        .expect("promote remote parity table");

        assert!(topk_call(local_table, PARITY_QUERY.to_vec(), 0, None).is_empty());
        assert!(topk_call(remote_table, PARITY_QUERY.to_vec(), 0, None).is_empty());
        assert_eq!(
            *query_calls.lock().expect("query_calls lock poisoned"),
            0,
            "k => 0 must never reach the remote /query endpoint"
        );
    }

    /// Regression test: a metadata column dropped from the table after
    /// `track`/`promote` registered it must be a clear, user-facing error
    /// when a filter actually references it — not a panic — while unfiltered
    /// remote `topk` (which never touches metadata columns at all) keeps
    /// working.
    #[pg_test]
    fn topk_remote_dropped_metadata_column_errors_only_when_filtered() {
        create_extension_vector();
        Spi::run(
            "CREATE TABLE topk_dropped_meta (id bigint PRIMARY KEY, embedding vector(2), \
             category text)",
        )
        .expect("create table");
        Spi::run(
            "INSERT INTO topk_dropped_meta (id, embedding, category) VALUES (1, '[1,0]', 'x')",
        )
        .expect("insert row");

        let backend = MockBackend::start(|control_plane, data_plane| async move {
            mount_promote_success(&control_plane, &data_plane, "pv-public-topk-dropped-meta").await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})))
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "matches": [{"id": "1", "score": 0.9}]
                })))
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.promote('topk_dropped_meta', metadata_columns => ARRAY['category'], \
             sync_mode => 'sync')",
        )
        .expect("promote");

        Spi::run("ALTER TABLE topk_dropped_meta DROP COLUMN category").expect("drop column");

        // Unfiltered remote topk must still work: it never touches metadata columns.
        let rows = topk_call("topk_dropped_meta", vec![1.0, 0.0], 5, None);
        assert_eq!(rows.len(), 1, "rows = {rows:?}");

        // Filtered remote topk referencing the dropped column: a clear error, not a panic.
        let message = expect_topk_error(
            "topk_dropped_meta",
            "ARRAY[1.0, 0.0]::real[]",
            r#"{"category": {"$eq": "x"}}"#,
        );
        assert!(message.contains("category"), "message = {message}");
        assert!(
            message.contains("re-track") || message.contains("re-promote"),
            "message = {message}"
        );
    }

    // ---- pinecone.create_doc_index / pinecone.drop_doc_index / pinecone.upsert_docs /
    // pinecone.search_doc_index ----
    //
    // Document-schema (full-text-search) indexes: control-plane create/drop and
    // data-plane upsert/search, all requiring the `2026-07` header. Same
    // credential resolution as `pinecone.promote` (`point_at_mock` sets both the
    // session GUC and the stored secret).

    #[pg_test]
    fn create_doc_index_happy_path() {
        let backend = MockBackend::start(|control_plane, data_plane| async move {
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .and(header("X-Pinecone-Api-Version", "2026-07"))
                .and(body_json(json!({
                    "name": "articles",
                    "deployment": {"deployment_type": "managed", "cloud": "aws", "region": "us-east-1"},
                    "schema": {
                        "fields": {"title": {"type": "string", "full_text_search": {"language": "en"}}}
                    },
                    "deletion_protection": "disabled",
                })))
                .respond_with(ResponseTemplate::new(201).set_body_json(json!({
                    "name": "articles",
                    "host": data_plane.uri(),
                    "schema": {"fields": {}},
                })))
                .mount(&control_plane)
                .await;

            // `pinecone.create_doc_index` polls readiness after the 201; ready on
            // the first poll so the test doesn't actually sleep.
            Mock::given(method("GET"))
                .and(path("/indexes/articles"))
                .and(header("X-Pinecone-Api-Version", "2026-07"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "name": "articles",
                    "host": data_plane.uri(),
                    "status": {"ready": true, "state": "Ready"},
                })))
                .mount(&control_plane)
                .await;

            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.create_doc_index('articles', \
             '{\"fields\": {\"title\": {\"type\": \"string\", \
             \"full_text_search\": {\"language\": \"en\"}}}}'::jsonb)",
        )
        .expect("create_doc_index");
    }

    /// `pinecone.create_doc_index` must actually wait for readiness, not just
    /// fire the create and return: the describe mock reports not-ready once
    /// before ready, and the assertion is that both polls happened (proving
    /// the not-ready response didn't short-circuit as success).
    #[pg_test]
    fn create_doc_index_polls_readiness_until_ready() {
        let call_count = Arc::new(Mutex::new(0u32));
        let counter = Arc::clone(&call_count);
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(json!({
                    "name": "articles",
                    "host": data_plane.uri(),
                    "schema": {"fields": {}},
                })))
                .mount(&control_plane)
                .await;

            let data_plane_uri = data_plane.uri();
            Mock::given(method("GET"))
                .and(path("/indexes/articles"))
                .and(header("X-Pinecone-Api-Version", "2026-07"))
                .respond_with(move |_req: &Request| {
                    let mut count = counter.lock().expect("call count lock poisoned");
                    *count += 1;
                    let ready = *count >= 2;
                    ResponseTemplate::new(200).set_body_json(json!({
                        "name": "articles",
                        "host": data_plane_uri,
                        "status": {"ready": ready, "state": if ready { "Ready" } else { "Initializing" }},
                    }))
                })
                .expect(2)
                .mount(&control_plane)
                .await;

            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(
            "SELECT pinecone.create_doc_index('articles', \
             '{\"fields\": {\"title\": {\"type\": \"string\"}}}'::jsonb)",
        )
        .expect("create_doc_index");

        assert_eq!(*call_count.lock().expect("call count lock poisoned"), 2);
    }

