    /// The key a live test calls Pinecone with, or `None` with a NOTICE saying why it skips
    /// ([`crate::smoke::live_gate`]).
    fn live_api_key() -> Option<String> {
        let opt_in = std::env::var("PG_PINECONE_LIVE_TESTS").ok();
        let key = std::env::var("PINECONE_API_KEY").ok();
        match crate::smoke::live_gate(opt_in.as_deref(), key) {
            Ok(key) => Some(key),
            Err(why) => {
                pgrx::notice!("{why}");
                None
            }
        }
    }

