    /// Skippable live end-to-end test: local pgvector table -> `track` ->
    /// `promote` (real serverless index) -> insert (sync trigger fires) ->
    /// remote `topk` -> `demote`. Run via `scripts/smoke.sh`.
    #[pg_test]
    fn live_promote_roundtrip() {
        let Some(api_key) = live_api_key() else {
            return;
        };

        let index_name = format!("pg-pinecone-smoke-promote-{}", std::process::id());
        // Cleans up the real index on every exit path, including a panic
        // unwind — even though `pinecone.promote` below, not this helper, is
        // what creates it.
        let _index_guard = SmokeIndex::adopt(&api_key, &index_name);

        create_extension_vector();
        Spi::run(
            "CREATE TABLE live_promote_roundtrip (id bigint PRIMARY KEY, embedding vector(3))",
        )
        .expect("create table");
        Spi::run("SELECT pinecone.track('live_promote_roundtrip')").expect("track");

        Spi::run(&format!(
            "SELECT pinecone.set_api_key({})",
            quote_literal(&api_key)
        ))
        .expect("pinecone.set_api_key");

        // sync_mode => 'sync': this test's synchronous poll loop below needs
        // the trigger to have pushed by the time the INSERT statement
        // returns, not just enqueued (0.3's async default would leave these
        // rows sitting undrained — there's no worker yet to drain them).
        Spi::run(&format!(
            "SELECT pinecone.promote('live_promote_roundtrip', index_name => {}, \
             cloud => 'aws', region => 'us-east-1', sync_mode => 'sync')",
            quote_literal(&index_name)
        ))
        .expect("promote");

        Spi::run(
            "INSERT INTO live_promote_roundtrip (id, embedding) VALUES \
             (1, '[1,0,0]'::vector), (2, '[0,1,0]'::vector)",
        )
        .expect("insert rows (fires the sync trigger)");

        // Pinecone's data plane is eventually consistent, so poll `topk()`
        // (up to ~60s) instead of asserting on the first try.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
        let mut ids: Vec<String> = loop {
            let ids: Vec<String> = Spi::connect(|client| {
                client
                    .select(
                        "SELECT id FROM pinecone.topk('live_promote_roundtrip', \
                         ARRAY[1.0, 0.0, 0.0]::real[], 2)",
                        None,
                        &[],
                    )
                    .expect("select from pinecone.topk")
                    .map(|row| {
                        row.get_by_name::<String, _>("id")
                            .expect("get id")
                            .expect("id NOT NULL")
                    })
                    .collect()
            });
            if ids.len() == 2 {
                break ids;
            }
            if std::time::Instant::now() >= deadline {
                panic!("pinecone.topk never returned both synced rows within 60s (got {ids:?})");
            }
            std::thread::sleep(std::time::Duration::from_secs(2));
        };
        ids.sort();
        assert_eq!(ids, vec!["1".to_string(), "2".to_string()]);

        Spi::run("SELECT pinecone.demote('live_promote_roundtrip')").expect("demote");
        // `_index_guard` drops here (and on any earlier panic via unwind), deleting the real index.
    }

    /// Skippable live end-to-end test proving the **background worker**
    /// itself drains an async table, against a real Pinecone index — unlike
    /// `live_promote_roundtrip` (`sync_mode => 'sync'`, drained inline by the
    /// writer's own statement), this promotes with `sync_mode => 'async'`
    /// and never drains manually: the poll loop below only succeeds if the
    /// real launcher/per-database worker BGW picked the enqueued rows up on
    /// its own. Needs a cluster actually running with
    /// `shared_preload_libraries = 'pg_pinecone'` *and* `pinecone.worker_enabled
    /// = on` — `pg_test::postgresql_conf_options` only turns the latter on
    /// when `PG_PINECONE_TEST_ENABLE_WORKER` is set, and `scripts/smoke.sh` runs
    /// this test as its own isolated `cargo pgrx test` invocation (a fresh
    /// cluster, this one test) with that variable set, so it never races the
    /// deterministic `#[pg_test]` suite's own mock fixtures the way running
    /// it inline would. Run via `scripts/smoke.sh`.
    ///
    /// Setup and the enqueuing `INSERT` all go through [`dblink_exec`]/
    /// [`dblink_perform`] rather than a plain `Spi::run` (see
    /// `worker_bgw_drain_against_mock`'s rustdoc for why): `pgrx-tests` wraps
    /// this whole test body in one transaction that's always rolled back
    /// client-side, so the real background worker — a separate backend with
    /// its own snapshot — could otherwise never see the row this test
    /// enqueues at all, no matter how long the poll loop below waited.
    #[pg_test]
    fn live_worker_drain() {
        let Some(api_key) = live_api_key() else {
            return;
        };
        // Unlike this file's other `live_*` tests, this one fundamentally
        // needs the real background worker running — which the shared,
        // deterministic `#[pg_test]` cluster deliberately keeps disabled
        // (see `pg_test::postgresql_conf_options`), so a caller who has opted in
        // to the live tests (e.g. running the plain, unfiltered suite locally)
        // must not make this test attempt — and then time out — the live flow
        // anyway.
        if !crate::worker::worker_enabled() {
            pgrx::notice!(
                "SKIPPED: pinecone.worker_enabled is off — run via scripts/smoke.sh \
                 (PG_PINECONE_LIVE_TESTS=1 PG_PINECONE_TEST_ENABLE_WORKER=1 cargo pgrx test pg17 live_worker_drain)"
            );
            return;
        }

        let index_name = format!("pg-pinecone-smoke-worker-{}", std::process::id());
        let _index_guard = SmokeIndex::adopt(&api_key, &index_name);

        let conninfo = dblink_conninfo();
        dblink_exec(
            &conninfo,
            "CREATE EXTENSION IF NOT EXISTS vector; \
             CREATE TABLE live_worker_drain (id bigint PRIMARY KEY, embedding vector(3))",
        );
        dblink_perform(
            &conninfo,
            &format!("pinecone.set_api_key({})", quote_literal(&api_key)),
        );
        dblink_perform(
            &conninfo,
            &format!(
                "pinecone.promote('live_worker_drain', index_name => {}, \
                 cloud => 'aws', region => 'us-east-1', sync_mode => 'async')",
                quote_literal(&index_name)
            ),
        );
        dblink_exec(
            &conninfo,
            "INSERT INTO live_worker_drain (id, embedding) VALUES \
             (1, '[1,0,0]'::vector), (2, '[0,1,0]'::vector)",
        );

        // Poll `pinecone.topk()` (a real remote query once `mode = 'remote'`)
        // up to ~90s: worker naptime + drain + Pinecone's own eventual-
        // consistency lag, combined. This only ever succeeds via the
        // background worker's own drain. This session's own `SELECT`s are
        // fine here (unlike the setup above): read-committed, so they *do*
        // see the dblink connection's already-committed writes.
        let cleanup = |conninfo: &str| {
            // Same-session `Spi`, NOT `dblink`: `demote()` (and the `DROP
            // TABLE` below) take an exclusive lock on the table, and this
            // session may itself be the one holding a lock on it — a
            // *separate* dblink backend blocking on that lock is invisible
            // to the deadlock detector (from this session's point of view
            // it's just a synchronous socket read, not a lock wait), so the
            // pair hangs forever rather than one side erroring out. A
            // same-session, same-transaction lock upgrade never conflicts
            // with itself.
            Spi::run("SELECT pinecone.demote('live_worker_drain')").expect("demote");
            dblink_exec(conninfo, "DELETE FROM pinecone.secret");
            Spi::run("DROP TABLE live_worker_drain").expect("drop table");
        };
        let relid = relid_of("live_worker_drain");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(90);
        let mut ids: Vec<String> = loop {
            // The registry row must have flipped to `'remote'` *first*: while
            // `mode` is still `'local'`/`'promoting'`, `pinecone.topk` serves
            // from the local pgvector table (`topk::topk`'s mode dispatch) —
            // and the `INSERT` above already put both rows there. Checking
            // `topk`'s result alone, without this, would be a vacuous
            // success: it could pass from the local answer without the real
            // background worker ever having drained anything to Pinecone.
            let mode = Spi::get_one_with_args::<String>(
                "SELECT mode FROM pinecone.tables WHERE relid::oid = $1::oid",
                &[relid.into()],
            )
            .expect("select mode")
            .expect("mode NOT NULL");
            if mode == "remote" {
                let ids: Vec<String> = Spi::connect(|client| {
                    client
                        .select(
                            "SELECT id FROM pinecone.topk('live_worker_drain', \
                             ARRAY[1.0, 0.0, 0.0]::real[], 2)",
                            None,
                            &[],
                        )
                        .expect("select from pinecone.topk")
                        .map(|row| {
                            row.get_by_name::<String, _>("id")
                                .expect("get id")
                                .expect("id NOT NULL")
                        })
                        .collect()
                });
                if ids.len() == 2 {
                    break ids;
                }
            }
            if std::time::Instant::now() >= deadline {
                cleanup(&conninfo);
                panic!(
                    "pinecone.topk never returned both worker-drained rows within 90s \
                     (mode = {mode:?}) — is this cluster actually running with \
                     pinecone.worker_enabled = on (PG_PINECONE_TEST_ENABLE_WORKER)?"
                );
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_secs(2));
        };
        ids.sort();
        assert_eq!(ids, vec!["1".to_string(), "2".to_string()]);
        cleanup(&conninfo);
        // `_index_guard` drops here, deleting the real index.
    }

    /// Skippable live end-to-end test for the **pg_pinecone access method**:
    /// `CREATE INDEX ... USING pinecone` on a real table, then an
    /// *unmodified* `ORDER BY ... LIMIT` (no `pinecone.topk()` rewrite — the
    /// whole point of the AM) served from a real Pinecone index, then `DROP
    /// INDEX` detaching cleanly (registry/outbox purged, plan reverts to a
    /// plain seqscan). Like `live_worker_drain`, `aminsert` only enqueues —
    /// there's no `sync_mode` for an AM table to drain inline — so the whole
    /// fixture goes through [`dblink_exec`]/[`dblink_perform`] (see that
    /// test's rustdoc for why) and this needs the real background worker
    /// running. Run via `scripts/smoke.sh`
    /// (`PG_PINECONE_LIVE_TESTS=1 PG_PINECONE_TEST_ENABLE_WORKER=1 cargo pgrx test pg17 live_am_roundtrip`).
    #[pg_test]
    fn live_am_roundtrip() {
        let Some(api_key) = live_api_key() else {
            return;
        };
        if !crate::worker::worker_enabled() {
            pgrx::notice!(
                "SKIPPED: pinecone.worker_enabled is off — run via scripts/smoke.sh \
                 (PG_PINECONE_LIVE_TESTS=1 PG_PINECONE_TEST_ENABLE_WORKER=1 cargo pgrx test pg17 live_am_roundtrip)"
            );
            return;
        }

        let table = "live_am_roundtrip";
        let conninfo = dblink_conninfo();
        dblink_exec(
            &conninfo,
            &format!(
                "CREATE EXTENSION IF NOT EXISTS vector; \
                 CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
            ),
        );
        dblink_perform(&conninfo, "pinecone._install_opclasses()");
        dblink_perform(
            &conninfo,
            &format!("pinecone.set_api_key({})", quote_literal(&api_key)),
        );
        dblink_exec(
            &conninfo,
            &format!(
                "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
            ),
        );

        // `ambuild` derives the Pinecone index name itself (`pv-<schema>-
        // <table>`) — there's no `WITH` option to pass one, unlike
        // `pinecone.promote`. Read the real one back rather than recomputing
        // `promote::default_index_name`, so this test can't drift from it.
        let relid = relid_of(table);
        let index_name = Spi::get_one_with_args::<String>(
            "SELECT index_name FROM pinecone.tables WHERE relid::oid = $1::oid",
            &[relid.into()],
        )
        .expect("select index_name")
        .expect("index_name NOT NULL for an access-method row");
        let _index_guard = SmokeIndex::adopt(&api_key, &index_name);

        dblink_exec(
            &conninfo,
            &format!(
                "INSERT INTO {table} (id, embedding) VALUES \
                 (1, '[1,0,0]'::vector), (2, '[0,1,0]'::vector)"
            ),
        );

        // Forces the planner off a seqscan+sort plan, which may otherwise
        // legitimately cost less on a 2-row table (`am::amcostestimate`'s
        // rustdoc) — this test's point is that the *unmodified* `ORDER BY`
        // genuinely goes through the AM, not a coincidentally-correct local
        // answer.
        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        // `id::text AS id`, not bare `id`: `id` is `bigint`, and
        // `get_by_name::<String, _>` below would fail against an int8 datum
        // — every other live/local topk query in this file reads ids back
        // through the same `::text` cast for that reason.
        let query = format!(
            "SELECT id::text AS id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector LIMIT 2"
        );

        let cleanup = |conninfo: &str| {
            dblink_exec(conninfo, "DELETE FROM pinecone.secret");
            // Same-session `Spi`, NOT `dblink` — see `live_worker_drain`'s
            // cleanup for why a dblink DDL against a table this session may
            // hold a lock on (from the `SELECT` polling loop just above) is
            // a self-deadlock hazard invisible to the deadlock detector.
            Spi::run(&format!("DROP TABLE {table}")).expect("drop table");
        };
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(90);
        loop {
            let plan = explain_lines(&query);
            let ids: Vec<String> = Spi::connect(|client| {
                client
                    .select(&query, None, &[])
                    .expect("select from the raw ORDER BY")
                    .map(|row| {
                        row.get_by_name::<String, _>("id")
                            .expect("get id")
                            .expect("id NOT NULL")
                    })
                    .collect()
            });
            if ids == vec!["1".to_string(), "2".to_string()]
                && plan
                    .iter()
                    .any(|l| l.contains("Index Scan") && l.contains(&format!("{table}_idx")))
            {
                break;
            }
            if std::time::Instant::now() >= deadline {
                cleanup(&conninfo);
                panic!(
                    "the unmodified ORDER BY never returned both worker-drained rows via the \
                     AM index within 90s (plan = {plan:?}, ids = {ids:?})"
                );
            }
            crate::backend::interruptible_sleep(std::time::Duration::from_secs(2));
        }

        // Same-session `Spi`, NOT `dblink` — the `SELECT` polling loop above
        // just ran against `{table}` in this very session/transaction, so a
        // *separate* dblink backend's `DROP INDEX` (which needs a
        // conflicting lock) could block on it in a way the deadlock
        // detector can't see (`live_worker_drain`'s cleanup rustdoc has the
        // full explanation) — escalating the lock in this same session
        // instead is always safe.
        Spi::run(&format!("DROP INDEX {table}_idx")).expect("drop index");
        assert!(
            !am_registry_row_exists(relid),
            "DROP INDEX must purge the registry row"
        );
        let plan_after_drop = explain_lines(&query);
        assert!(
            plan_after_drop.iter().any(|l| l.contains("Seq Scan")),
            "plan_after_drop = {plan_after_drop:?}"
        );
        assert!(
            !plan_after_drop.iter().any(|l| l.contains("Index Scan")),
            "plan_after_drop = {plan_after_drop:?}"
        );

        cleanup(&conninfo);
        // `_index_guard` drops here, deleting the real index.
    }

    // ---- table-bound full-text search: document sync (track_docs, triggers, drain, DDL guard) ----
    //
    // Black box: SQL in, the documents mock's recorded requests out; the queue table is read
    // directly only where the enqueue contract itself is the subject.
    use crate::mock_backend::docs::{DocsHandle, EXPECTED_API_VERSION, Endpoint, start_with_docs};

    const FTS_TRACK: &str = "pinecone.track_docs";
    const FTS_UNTRACK: &str = "pinecone.untrack_docs";
    const FTS_FLUSH: &str = "pinecone.flush_docs";
    const FTS_RETRY_FAILED: &str = "pinecone.retry_failed_docs";
    const FTS_SEARCH: &str = "pinecone.search_docs";
    const FTS_SEARCH_PASSTHROUGH: &str = "pinecone.search_doc_index";
    /// Test seam: runs one worker round of the docs lane of a table in the caller's
    /// transaction and returns `idle`, `processed`, `backoff` or `parked`.
    const FTS_ROUND: &str = "pinecone._docs_round";
    const FTS_OP_UPSERT: &str = "doc_upsert";
    const FTS_OP_DELETE: &str = "doc_delete";
    const FTS_OP_TRUNCATE: &str = "doc_delete_all";
    const FTS_OP_FAILED: &str = "doc_failed";
    const FTS_TRUNCATED_MARKER: &str = "pg_pinecone_truncated";
    /// Analyzer defaults (still open): language 'en', stemming and stop words on.
    const FTS_DEFAULT_LANGUAGE: &str = "en";
    const FTS_DEFAULT_STEMMING: bool = true;
    const FTS_DEFAULT_STOP_WORDS: bool = true;

    /// The design's example declaration, used by most tests.
    const FTS_TEXT_COLUMNS: &str = r#"{"title": {"language": "en"},
        "body": {"language": "en", "stemming": true, "on_oversize": "truncate"},
        "sku": {"stemming": false, "stop_words": false}}"#;

    /// A full-text field of a derived schema, as the mock describes it back.
    fn fts_field(language: &str, stemming: bool, stop_words: bool) -> Value {
        json!({"type": "string", "full_text_search":
            {"language": language, "stemming": stemming, "stop_words": stop_words}})
    }

    /// The schema the design's example declaration must derive (vector column `embedding vector(3)`).
    fn fts_golden_schema(metric: &str) -> Value {
        let (stem, stop) = (FTS_DEFAULT_STEMMING, FTS_DEFAULT_STOP_WORDS);
        json!({"fields": {
            "title": fts_field(FTS_DEFAULT_LANGUAGE, stem, stop),
            "body": fts_field("en", true, stop),
            "sku": fts_field(FTS_DEFAULT_LANGUAGE, false, false),
            "embedding": {"type": "dense_vector", "dimension": 3, "metric": metric},
        }})
    }

    /// A function name without its schema, as error messages and hints spell it.
    fn fts_bare(name: &str) -> &str {
        name.trim_start_matches("pinecone.")
    }

    fn fts_index_name(table: &str) -> String {
        format!("fts-{}", table.replace('_', "-"))
    }

    fn fts_namespace(table: &str) -> String {
        format!("public.{table}")
    }

    /// `'<table>'::regclass`, for building SQL.
    fn fts_rel(table: &str) -> String {
        format!("{}::regclass", quote_literal(table))
    }

    /// Starts a mock that answers the documents API and points the session at it.
    fn fts_mock() -> (MockBackend, DocsHandle) {
        let docs = DocsHandle::new();
        let backend = start_with_docs(&docs);
        point_at_mock(&backend);
        (backend, docs)
    }

    /// The `articles`-shaped table: every declared column kind plus two undeclared columns.
    fn fts_create_table(table: &str) {
        create_extension_vector();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, title text, body text, sku text, \
             author text, published_at timestamptz, tags text[], note text, embedding vector(3))"
        ))
        .expect("create fts table");
    }

    /// The `track_docs` call with the design's example declaration.
    fn fts_track_standard_sql(table: &str, index: &str) -> String {
        format!(
            "SELECT {FTS_TRACK}({}, text_columns => {}::jsonb, \
             metadata_columns => ARRAY['author', 'published_at', 'tags'], \
             vector_column => 'embedding', index_name => {})",
            fts_rel(table),
            quote_literal(FTS_TEXT_COLUMNS),
            quote_literal(index),
        )
    }

    fn fts_track_standard(table: &str, index: &str) {
        fts_run(&fts_track_standard_sql(table, index));
    }

    fn fts_round(table: &str) -> String {
        let sql = format!("SELECT {FTS_ROUND}({})", fts_rel(table));
        let outcome = Spi::get_one::<String>(&sql).expect("docs lane round");
        outcome.expect("round outcome is NOT NULL")
    }

    /// Runs rounds until the lane reports `idle`; fails on `backoff`/`parked`.
    fn fts_drain(table: &str) {
        for _ in 0..200 {
            match fts_round(table).as_str() {
                "idle" => return,
                "processed" => {}
                other => panic!("fts_drain({table}): a round ended '{other}'"),
            }
        }
        panic!("fts_drain({table}): not idle after 200 rounds");
    }

    /// Rows of the docs queue of `table`, oldest first, as JSON objects (`op`, `payload`, ...).
    fn fts_queue(table: &str) -> Vec<Value> {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id), '[]'::jsonb) \
             FROM {FTS_QUEUE} q WHERE q.relid = {}",
            fts_rel(table)
        );
        let rows = Spi::get_one::<JsonB>(&sql).expect("read the docs queue");
        let rows = rows.expect("aggregate is NOT NULL").0;
        rows.as_array().cloned().unwrap_or_default()
    }

    /// The ids carried by the queue rows with operation `op`, in queue order, flattened.
    fn fts_queue_ids(table: &str, op: &str) -> Vec<String> {
        let rows = fts_queue(table)
            .into_iter()
            .filter(|r| r["op"] == json!(op));
        let payloads = rows.filter_map(|r| r["payload"].as_array().cloned());
        let ids = payloads
            .flatten()
            .filter_map(|id| id.as_str().map(str::to_string));
        ids.collect()
    }

    fn fts_queue_ops(table: &str) -> Vec<String> {
        let ops = fts_queue(table).into_iter();
        ops.filter_map(|r| r["op"].as_str().map(str::to_string))
            .collect()
    }

    /// The dead letters of `table` as `pinecone.failed_docs` reports them (`id`, `error`, `failed_at`).
    fn fts_failed_docs(table: &str) -> Vec<Value> {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(to_jsonb(f)), '[]'::jsonb) FROM pinecone.failed_docs({}) f",
            fts_rel(table)
        );
        let rows = Spi::get_one::<JsonB>(&sql).expect("failed_docs");
        let rows = rows.expect("aggregate is NOT NULL").0;
        rows.as_array().cloned().unwrap_or_default()
    }

    /// Whether the docs lane of `table` is parked, as the registry records it.
    fn fts_lane_parked(table: &str) -> bool {
        let sql = format!(
            "SELECT queue_parked FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(table)
        );
        let parked = Spi::get_one::<bool>(&sql).expect("registry lookup");
        parked.unwrap_or_else(|| panic!("{table} is not registered"))
    }

    /// Ids of the rows in the table itself.
    fn fts_heap_ids(table: &str) -> BTreeSet<String> {
        let sql = format!("SELECT coalesce(jsonb_agg(id::text), '[]'::jsonb) FROM {table}");
        let ids = Spi::get_one::<JsonB>(&sql).expect("read heap ids");
        let ids = ids.expect("aggregate is NOT NULL").0;
        let ids = ids.as_array().cloned().unwrap_or_default();
        ids.iter()
            .filter_map(|id| id.as_str().map(str::to_string))
            .collect()
    }

    /// A caught Postgres ERROR with everything an error-table row pins.
    #[derive(Debug)]
    struct FtsError {
        message: String,
        detail: Option<String>,
        hint: Option<String>,
        sqlstate: String,
    }

    /// The five-character SQLSTATE of `code` (the inverse of `MAKE_SQLSTATE`).
    fn fts_sqlstate_of(code: PgSqlErrorCode) -> String {
        let packed = code as i32;
        let digit = |i: u32| (((packed >> (6 * i)) & 0x3F) as u8 + b'0') as char;
        (0..5).map(digit).collect()
    }

    fn fts_caught(caught: CaughtError) -> FtsError {
        let report = match caught {
            CaughtError::PostgresError(e) | CaughtError::ErrorReport(e) => e,
            CaughtError::RustPanic { ereport, .. } => ereport,
        };
        FtsError {
            message: report.message().to_string(),
            detail: report.detail().map(str::to_string),
            hint: report.hint().map(str::to_string),
            sqlstate: fts_sqlstate_of(report.sql_error_code()),
        }
    }

    /// Runs `f` in a subtransaction that is always rolled back and returns the ERROR it raised
    /// (like [`run_in_subtransaction_expecting_error`], but with SQLSTATE, DETAIL and HINT).
    fn fts_error_of(f: impl FnOnce() + std::panic::UnwindSafe) -> FtsError {
        let oldcontext = unsafe { pg_sys::CurrentMemoryContext };
        let oldowner = unsafe { pg_sys::CurrentResourceOwner };
        unsafe {
            pg_sys::BeginInternalSubTransaction(std::ptr::null());
            pg_sys::MemoryContextSwitchTo(oldcontext);
        }
        let outcome: Result<(), FtsError> = PgTryBuilder::new(|| {
            f();
            Ok(())
        })
        .catch_others(|caught| Err(fts_caught(caught)))
        .execute();
        unsafe {
            pg_sys::RollbackAndReleaseCurrentSubTransaction();
            pg_sys::MemoryContextSwitchTo(oldcontext);
            pg_sys::CurrentResourceOwner = oldowner;
        }
        match outcome {
            Err(error) => error,
            Ok(()) => panic!("expected the statement to raise an ERROR, but it succeeded"),
        }
    }

    /// The ERROR `sql` raises (rolled back afterwards).
    fn fts_sql_error(sql: &str) -> FtsError {
        fts_error_of(|| {
            Spi::run(sql).expect("statement should raise a Postgres ERROR, not an SpiError");
        })
    }

    /// Asserts the SQLSTATE and that the message contains every part.
    fn fts_assert_error(error: &FtsError, sqlstate: &str, message_parts: &[&str]) {
        assert_eq!(error.sqlstate, sqlstate, "wrong SQLSTATE: {error:?}");
        for part in message_parts {
            assert!(
                error.message.contains(part),
                "message lacks {part:?}: {error:?}"
            );
        }
    }

    fn fts_assert_hint(error: &FtsError, part: &str) {
        let hint = error.hint.as_deref().unwrap_or_default();
        assert!(hint.contains(part), "hint lacks {part:?}: {error:?}");
    }

    /// The document ids of the upsert calls the mock answered 202, in arrival order.
    fn fts_delivered_ids(docs: &DocsHandle) -> Vec<String> {
        let calls = docs
            .calls_to(Endpoint::Upsert)
            .into_iter()
            .filter(|c| c.status == 202);
        let bodies = calls.filter_map(|c| c.body);
        let documents = bodies
            .filter_map(|b| b["documents"].as_array().cloned())
            .flatten();
        documents
            .filter_map(|d| d["_id"].as_str().map(str::to_string))
            .collect()
    }

    fn fts_set(ids: &[&str]) -> BTreeSet<String> {
        ids.iter().map(|id| id.to_string()).collect()
    }

    fn fts_run(sql: &str) {
        Spi::run(sql).unwrap_or_else(|e| panic!("{sql}: {e:?}"));
    }

    /// A table against a fresh documents mock, tracked with the design's example declaration.
    struct FtsEnv {
        _backend: MockBackend,
        docs: DocsHandle,
        table: String,
        index: String,
        namespace: String,
    }

    impl FtsEnv {
        /// Table and mock, nothing tracked yet.
        fn untracked(table: &str) -> Self {
            fts_create_table(table);
            let (backend, docs) = fts_mock();
            Self {
                _backend: backend,
                docs,
                table: table.to_string(),
                index: fts_index_name(table),
                namespace: fts_namespace(table),
            }
        }

        /// Tracked, backfill of the empty table done, the mock's call log cleared: tests start
        /// from a steady state in which only what they do shows up.
        fn tracked(table: &str) -> Self {
            let env = Self::untracked(table);
            fts_track_standard(&env.table, &env.index);
            fts_drain(&env.table);
            env.docs.clear_calls();
            env
        }

        /// `tracked` plus rows `1..=n` (`title 'title i'`, `body 'body i'`), delivered.
        fn seeded(table: &str, n: i64) -> Self {
            let env = Self::tracked(table);
            fts_run(&format!(
                "INSERT INTO {table} (id, title, body, author) \
                 SELECT i, 'title ' || i, 'body ' || i, 'ann' FROM generate_series(1, {n}) i"
            ));
            env.drain();
            env.docs.clear_calls();
            env
        }

        fn round(&self) -> String {
            fts_round(&self.table)
        }

        fn drain(&self) {
            fts_drain(&self.table)
        }

        fn queue(&self) -> Vec<Value> {
            fts_queue(&self.table)
        }

        fn remote_ids(&self) -> BTreeSet<String> {
            self.docs.remote_ids(&self.namespace)
        }

        fn remote_doc(&self, id: &str) -> Value {
            let doc = self.docs.remote_doc(&self.namespace, id);
            doc.unwrap_or_else(|| panic!("the remote holds no document {id}"))
        }

        fn run(&self, sql: &str) {
            fts_run(sql)
        }
    }

    // ---- enqueue contract: same transaction, id-keyed rows, no HTTP in the writer ----

    /// One INSERT statement enqueues one `doc_upsert` row that carries ids only; the
    /// writer makes no HTTP call (document text never enters the queue).
    #[pg_test]
    fn doc_outbox_insert_enqueues_one_id_keyed_upsert_row() {
        let env = FtsEnv::tracked("fts_t1_insert");
        env.run(
            "INSERT INTO fts_t1_insert (id, title, body, author) VALUES \
             (1, 'alpha', 'secret body one', 'ann'), (2, 'beta', 'secret body two', NULL), \
             (3, NULL, 'only a body', NULL)",
        );

        let rows = env.queue();
        assert_eq!(rows.len(), 1, "one statement, one chunk, one row: {rows:?}");
        assert_eq!(rows[0]["op"], json!(FTS_OP_UPSERT));
        let ids: BTreeSet<String> = fts_queue_ids("fts_t1_insert", FTS_OP_UPSERT)
            .into_iter()
            .collect();
        assert_eq!(
            ids,
            fts_set(&["1", "2", "3"]),
            "payload = canonical primary keys"
        );
        let payload = rows[0]["payload"].to_string();
        assert!(
            !payload.contains("secret"),
            "no document text in the queue: {payload}"
        );
        assert!(
            env.docs.calls().is_empty(),
            "the writer talks to Postgres only"
        );
    }

    /// A rolled-back statement leaves nothing behind; inside the subtransaction the row
    /// is queued, so the enqueue is part of the writer's own transaction.
    #[pg_test]
    fn doc_outbox_rollback_leaves_no_queue_rows() {
        let env = FtsEnv::tracked("fts_t1_rollback");
        run_then_rollback_subtransaction(|| {
            fts_run("INSERT INTO fts_t1_rollback (id, title, body) VALUES (1, 'a', 'b')");
            assert_eq!(
                fts_queue("fts_t1_rollback").len(),
                1,
                "queued inside the transaction"
            );
        });
        assert!(
            env.queue().is_empty(),
            "rollback must take the queue row with it"
        );
        assert!(fts_heap_ids("fts_t1_rollback").is_empty());
    }

    /// An UPDATE of a declared text column enqueues an upsert for that id.
    #[pg_test]
    fn doc_outbox_update_of_declared_text_column_enqueues_upsert() {
        let env = FtsEnv::seeded("fts_t2_text", 2);
        env.run("UPDATE fts_t2_text SET body = 'rewritten' WHERE id = 1");
        let rows = env.queue();
        assert_eq!(rows.len(), 1, "rows = {rows:?}");
        assert_eq!(rows[0]["op"], json!(FTS_OP_UPSERT));
        assert_eq!(
            fts_queue_ids("fts_t2_text", FTS_OP_UPSERT),
            vec!["1".to_string()]
        );
    }

    /// An UPDATE that touches no declared column enqueues nothing and sends nothing.
    #[pg_test]
    fn doc_outbox_update_of_undeclared_column_enqueues_nothing() {
        let env = FtsEnv::seeded("fts_t2_noop", 2);
        env.run("UPDATE fts_t2_noop SET note = 'touched' WHERE id = 1");
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
        assert_eq!(env.round(), "idle");
        assert!(
            env.docs.calls().is_empty(),
            "zero HTTP calls: {:?}",
            env.docs.calls()
        );
    }

    /// Rewriting a declared column with the value it already has is not a change.
    #[pg_test]
    fn doc_outbox_update_to_the_same_value_enqueues_nothing() {
        let env = FtsEnv::seeded("fts_t2_same", 2);
        env.run("UPDATE fts_t2_same SET body = body, author = author WHERE id = 1");
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
    }

    /// A metadata-only UPDATE is a full upsert of the
    /// whole document, asserted on the request body; `documents/update` is never called.
    #[pg_test]
    fn doc_outbox_metadata_only_update_sends_a_full_upsert_never_an_update() {
        let env = FtsEnv::seeded("fts_t2_meta", 2);
        env.run("UPDATE fts_t2_meta SET author = 'bob' WHERE id = 1");
        assert_eq!(
            fts_queue_ids("fts_t2_meta", FTS_OP_UPSERT),
            vec!["1".to_string()]
        );

        env.drain();
        let upserts = env.docs.calls_to(Endpoint::Upsert);
        assert_eq!(upserts.len(), 1, "calls = {:?}", env.docs.calls());
        let documents = upserts[0].body.clone().expect("body")["documents"].clone();
        assert_eq!(
            documents.as_array().map(Vec::len),
            Some(1),
            "documents = {documents}"
        );
        let doc = &documents[0];
        assert_eq!(doc["_id"], json!("1"));
        assert_eq!(doc["author"], json!("bob"), "the changed metadata");
        assert_eq!(
            doc["title"],
            json!("title 1"),
            "the unchanged text rides along: {doc}"
        );
        assert_eq!(doc["body"], json!("body 1"));
        assert_eq!(env.docs.count(Endpoint::Update), 0, "no partial updates");
    }

    /// DELETE enqueues a `doc_delete` for the deleted ids; delivery removes them remotely.
    #[pg_test]
    fn doc_outbox_delete_enqueues_delete_by_id() {
        let env = FtsEnv::seeded("fts_t3_delete", 3);
        assert_eq!(
            env.remote_ids(),
            fts_set(&["1", "2", "3"]),
            "setup: delivered"
        );
        env.run("DELETE FROM fts_t3_delete WHERE id IN (1, 2)");
        assert_eq!(
            fts_queue_ops("fts_t3_delete"),
            vec![FTS_OP_DELETE.to_string()]
        );
        let ids: BTreeSet<String> = fts_queue_ids("fts_t3_delete", FTS_OP_DELETE)
            .into_iter()
            .collect();
        assert_eq!(ids, fts_set(&["1", "2"]));

        env.drain();
        let deletes = env.docs.calls_to(Endpoint::Delete);
        assert_eq!(deletes.len(), 1, "calls = {:?}", env.docs.calls());
        let sent = deletes[0].body.clone().expect("body")["ids"].clone();
        let sent: BTreeSet<String> = serde_json::from_value(sent).expect("ids array");
        assert_eq!(sent, fts_set(&["1", "2"]));
        assert_eq!(env.remote_ids(), fts_set(&["3"]));
    }

    /// TRUNCATE enqueues a delete-all of the table's namespace and nothing else.
    #[pg_test]
    fn doc_outbox_truncate_enqueues_delete_all_for_the_namespace() {
        let env = FtsEnv::seeded("fts_t3_truncate", 3);
        env.run("TRUNCATE fts_t3_truncate");
        assert_eq!(
            fts_queue_ops("fts_t3_truncate"),
            vec![FTS_OP_TRUNCATE.to_string()]
        );

        env.drain();
        let deletes = env.docs.calls_to(Endpoint::Delete);
        assert_eq!(deletes.len(), 1, "calls = {:?}", env.docs.calls());
        assert_eq!(deletes[0].body, Some(json!({"delete_all": true})));
        assert_eq!(
            deletes[0].namespace.as_deref(),
            Some(env.namespace.as_str())
        );
        assert!(env.remote_ids().is_empty());
    }

    /// Changing the primary key deletes the old id and upserts the new one, in one round.
    #[pg_test]
    fn doc_outbox_primary_key_update_deletes_old_id_and_upserts_new_id() {
        let env = FtsEnv::seeded("fts_t4_pk", 1);
        env.run("UPDATE fts_t4_pk SET id = 99 WHERE id = 1");
        assert_eq!(
            fts_queue_ids("fts_t4_pk", FTS_OP_DELETE),
            vec!["1".to_string()]
        );
        assert_eq!(
            fts_queue_ids("fts_t4_pk", FTS_OP_UPSERT),
            vec!["99".to_string()]
        );

        assert_eq!(env.round(), "processed");
        assert_eq!(
            env.remote_ids(),
            fts_set(&["99"]),
            "old id gone, new id present, one round"
        );
        assert_eq!(env.remote_doc("99")["body"], json!("body 1"));
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
    }

    /// `INSERT ... ON CONFLICT DO UPDATE` fires the INSERT and the UPDATE trigger; each
    /// row is delivered exactly once, in a single request.
    #[pg_test]
    fn doc_outbox_on_conflict_do_update_delivers_each_row_once() {
        let env = FtsEnv::seeded("fts_t5_conflict", 2);
        env.run(
            "INSERT INTO fts_t5_conflict (id, title, body) VALUES (2, 'two', 'changed'), \
             (3, 'three', 'new') ON CONFLICT (id) DO UPDATE SET body = EXCLUDED.body",
        );
        let queued: BTreeSet<String> = fts_queue_ids("fts_t5_conflict", FTS_OP_UPSERT)
            .into_iter()
            .collect();
        assert_eq!(
            queued,
            fts_set(&["2", "3"]),
            "the updated and the inserted row"
        );

        env.drain();
        let delivered = fts_delivered_ids(&env.docs);
        assert_eq!(delivered.len(), 2, "no duplicate delivery: {delivered:?}");
        assert_eq!(
            env.docs.count(Endpoint::Upsert),
            1,
            "one request: {:?}",
            env.docs.calls()
        );
        assert_eq!(env.remote_doc("2")["body"], json!("changed"));
        assert_eq!(env.remote_doc("3")["body"], json!("new"));
    }

    /// T6 (scaled down from 100 KB bodies to 2 KB so it stays cheap): a COPY of 10,000 rows
    /// is one statement-level trigger call with a 20 MB transition table. It must succeed
    /// and queue ids only, 1,000 per row; payload size must not depend on the body size.
    #[pg_test]
    fn doc_outbox_copy_of_ten_thousand_rows_enqueues_bounded_id_chunks() {
        let env = FtsEnv::tracked("fts_t6_copy");
        let program = r#"awk 'BEGIN { b = sprintf("%2000s", ""); gsub(/ /, "x", b); for (i = 1; i <= 10000; i++) printf "%d\ttitle %d\t%s\n", i, i, b }'"#;
        env.run(&format!(
            "COPY fts_t6_copy (id, title, body) FROM PROGRAM $prog${program}$prog$"
        ));
        assert_eq!(
            fts_heap_ids("fts_t6_copy").len(),
            10_000,
            "setup: the COPY itself succeeded"
        );

        let rows = env.queue();
        let sizes: Vec<usize> = rows
            .iter()
            .map(|r| r["payload"].as_array().map_or(0, Vec::len))
            .collect();
        assert_eq!(rows.len(), 10, "ceil(10000 / 1000) rows, sizes = {sizes:?}");
        assert!(rows.iter().all(|r| r["op"] == json!(FTS_OP_UPSERT)));
        assert!(
            sizes.iter().all(|n| *n <= 1000),
            "at most 1,000 ids per row: {sizes:?}"
        );
        let all: BTreeSet<String> = fts_queue_ids("fts_t6_copy", FTS_OP_UPSERT)
            .into_iter()
            .collect();
        assert_eq!(all.len(), 10_000, "every id queued exactly once");
        let largest = rows
            .iter()
            .map(|r| r["payload"].to_string().len())
            .max()
            .unwrap_or(0);
        assert!(
            largest < 20_000,
            "ids only, not 2 MB of bodies: largest payload = {largest} bytes"
        );
    }

    /// Upsert A, delete B, upsert A again, delete A, insert C: one claimed batch becomes
    /// one upsert request (C only: A is gone at drain time) and one delete request (A and B).
    #[pg_test]
    fn doc_drain_mixed_ops_in_one_batch_send_one_upsert_and_one_delete() {
        let env = FtsEnv::seeded("fts_t7_mixed", 2);
        env.run("INSERT INTO fts_t7_mixed (id, title, body) VALUES (3, 'c', 'row c')");
        env.run("UPDATE fts_t7_mixed SET body = 'a1' WHERE id = 1");
        env.run("DELETE FROM fts_t7_mixed WHERE id = 2");
        env.run("UPDATE fts_t7_mixed SET body = 'a2' WHERE id = 1");
        env.run("DELETE FROM fts_t7_mixed WHERE id = 1");

        env.drain();
        assert_eq!(
            fts_delivered_ids(&env.docs),
            vec!["3".to_string()],
            "A is deleted at drain time"
        );
        assert_eq!(
            env.docs.count(Endpoint::Upsert),
            1,
            "calls = {:?}",
            env.docs.calls()
        );
        let deletes = env.docs.calls_to(Endpoint::Delete);
        assert_eq!(deletes.len(), 1, "calls = {:?}", env.docs.calls());
        let sent = deletes[0].body.clone().expect("body")["ids"].clone();
        let sent: BTreeSet<String> = serde_json::from_value(sent).expect("ids array");
        assert_eq!(sent, fts_set(&["1", "2"]));
        assert_eq!(
            env.remote_ids(),
            fts_heap_ids("fts_t7_mixed"),
            "remote = heap"
        );
    }

    /// A row upserted in one round and deleted before the next is absent remotely.
    #[pg_test]
    fn doc_drain_upsert_then_delete_across_rounds_leaves_the_id_absent() {
        let env = FtsEnv::tracked("fts_t8_across");
        env.run("INSERT INTO fts_t8_across (id, title, body) VALUES (1, 'a', 'first')");
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1"]));
        env.run("DELETE FROM fts_t8_across WHERE id = 1");
        env.drain();
        assert!(
            env.remote_ids().is_empty(),
            "remote = {:?}",
            env.remote_ids()
        );
    }

    /// Delete then re-insert the same id before a drain: the new text wins.
    #[pg_test]
    fn doc_drain_delete_then_reinsert_ends_with_the_new_text() {
        let env = FtsEnv::seeded("fts_t8_reinsert", 1);
        env.run("DELETE FROM fts_t8_reinsert WHERE id = 1");
        env.run("INSERT INTO fts_t8_reinsert (id, title, body) VALUES (1, 'again', 'new text')");
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1"]));
        assert_eq!(env.remote_doc("1")["body"], json!("new text"));
    }

    /// TRUNCATE is a barrier: rows inserted after it survive its delete-all, rows inserted
    /// before it do not, even though both are materialised at drain time.
    #[pg_test]
    fn doc_drain_truncate_orders_before_later_inserts() {
        let env = FtsEnv::seeded("fts_t8_truncate", 2);
        env.run("TRUNCATE fts_t8_truncate");
        env.run("INSERT INTO fts_t8_truncate (id, title, body) VALUES (1, 'fresh', 'after the truncate')");
        env.drain();
        assert_eq!(
            env.remote_ids(),
            fts_set(&["1"]),
            "id 2 is gone, id 1 was re-inserted"
        );
        assert_eq!(env.remote_doc("1")["body"], json!("after the truncate"));

        env.run("INSERT INTO fts_t8_truncate (id, title, body) VALUES (5, 'doomed', 'before')");
        env.run("TRUNCATE fts_t8_truncate");
        env.drain();
        assert!(
            env.remote_ids().is_empty(),
            "remote = {:?}",
            env.remote_ids()
        );
    }

    /// A NULL declared column is left out of the full upsert, so the
    /// replaced remote document cannot keep stale text or metadata.
    #[pg_test]
    fn doc_drain_null_columns_are_omitted_from_the_document() {
        let env = FtsEnv::seeded("fts_x_nulls", 1);
        assert_eq!(
            env.remote_doc("1")["body"],
            json!("body 1"),
            "setup: delivered with a body"
        );
        env.run("UPDATE fts_x_nulls SET body = NULL, author = NULL WHERE id = 1");
        env.drain();
        let doc = env.remote_doc("1");
        assert!(
            doc.get("body").is_none(),
            "NULL text must be absent, not null or empty: {doc}"
        );
        assert!(
            doc.get("author").is_none(),
            "NULL metadata must be absent: {doc}"
        );
        assert_eq!(doc["title"], json!("title 1"));
    }

    /// Extra (security): a role that may only INSERT can write to a tracked table; the trigger
    /// queues the row under its own privileges, as the vector path does.
    #[pg_test]
    fn doc_outbox_insert_by_a_writer_role_without_pg_pinecone_grants_enqueues() {
        let env = FtsEnv::tracked("fts_x_writer");
        let role = format!("fts_writer_{}", std::process::id());
        env.run(&format!("CREATE ROLE {role}"));
        env.run(&format!("GRANT INSERT ON fts_x_writer TO {role}"));
        env.run(&format!("SET ROLE {role}"));
        env.run("INSERT INTO fts_x_writer (id, title, body) VALUES (1, 'a', 'b')");
        env.run("RESET ROLE");
        env.run(&format!("REVOKE INSERT ON fts_x_writer FROM {role}"));
        env.run(&format!("DROP ROLE {role}"));
        assert_eq!(
            fts_queue_ids("fts_x_writer", FTS_OP_UPSERT),
            vec!["1".to_string()]
        );
    }

    // ---- identity ----

    /// Tracks `table` with one declared text column `body` and default analyzers.
    fn fts_track_minimal(table: &str) {
        fts_run(&format!(
            "SELECT {FTS_TRACK}({}, text_columns => '{{\"body\": {{}}}}'::jsonb, \
             index_name => {})",
            fts_rel(table),
            quote_literal(fts_index_name(table)),
        ));
    }

    /// Supported key types give canonical, session-independent ids.
    #[pg_test]
    fn track_docs_canonical_ids_for_supported_key_types() {
        let (_backend, docs) = fts_mock();
        fts_run("SET DateStyle = 'German, DMY'");
        fts_run("SET extra_float_digits = 3");
        let cases = [
            ("smallint", "7", "7"),
            ("integer", "42", "42"),
            ("bigint", "9223372036854775807", "9223372036854775807"),
            (
                "uuid",
                "'123E4567-E89B-12D3-A456-426614174000'",
                "123e4567-e89b-12d3-a456-426614174000",
            ),
            ("text", "'Café Ünï-1'", "Café Ünï-1"),
            ("varchar(20)", "'abc-1'", "abc-1"),
            ("char(6)", "'ab'", "ab"),
        ];
        for (n, (key_type, literal, expected)) in cases.iter().enumerate() {
            let table = format!("fts_t9_key_{n}");
            fts_run(&format!(
                "CREATE TABLE {table} (id {key_type} PRIMARY KEY, body text)"
            ));
            fts_track_minimal(&table);
            fts_drain(&table);
            fts_run(&format!(
                "INSERT INTO {table} (id, body) VALUES ({literal}, 'text')"
            ));
            fts_drain(&table);
            let remote = docs.remote_ids(&fts_namespace(&table));
            assert_eq!(remote, fts_set(&[expected]), "{key_type} key {literal}");
        }
    }

    /// `table` has no registry row and no docs triggers.
    fn fts_assert_unregistered(table: &str) {
        let sql = format!(
            "SELECT EXISTS (SELECT 1 FROM {FTS_REGISTRY} WHERE relid = {})",
            fts_rel(table)
        );
        let registered = Spi::get_one::<bool>(&sql).expect("registry lookup");
        assert_eq!(registered, Some(false), "{table} must not be registered");
        let triggers = trigger_names(table).into_iter();
        let docs_triggers: Vec<String> = triggers
            .filter(|t| t.starts_with("pg_pinecone_docs_"))
            .collect();
        assert!(
            docs_triggers.is_empty(),
            "docs triggers installed: {docs_triggers:?}"
        );
    }

    /// A refused `track_docs` registers nothing and made no HTTP call (the declaration is
    /// validated locally, before Pinecone is asked anything).
    fn fts_assert_untouched(table: &str, docs: &DocsHandle) {
        fts_assert_unregistered(table);
        assert!(
            docs.calls().is_empty(),
            "no HTTP before validation: {:?}",
            docs.calls()
        );
    }

    /// Keys that cannot give a canonical id are refused at `track_docs` with a HINT.
    #[pg_test]
    fn track_docs_refuses_keys_without_a_canonical_id() {
        let (_backend, docs) = fts_mock();
        // (table, columns, SQLSTATE, message parts, hint part)
        let cases: [(&str, &str, &str, &[&str], &str); 4] = [
            (
                "fts_t9_nokey",
                "id bigint, body text",
                "42P16",
                &["has no primary key"],
                "id_column",
            ),
            (
                "fts_t9_composite",
                "a int, b int, body text, PRIMARY KEY (a, b)",
                "0A000",
                &["2 columns", "single-column"],
                "id_column",
            ),
            (
                "fts_t9_float",
                "id float8 PRIMARY KEY, body text",
                "0A000",
                &["id column \"id\" has type"],
                "",
            ),
            (
                "fts_t9_ts",
                "id timestamptz PRIMARY KEY, body text",
                "0A000",
                &["id column \"id\" has type", "timestamp"],
                "",
            ),
        ];
        for (table, columns, sqlstate, parts, hint) in cases {
            fts_run(&format!("CREATE TABLE {table} ({columns})"));
            let sql = format!(
                "SELECT {FTS_TRACK}({}, text_columns => '{{\"body\": {{}}}}'::jsonb)",
                fts_rel(table)
            );
            let error = fts_sql_error(&sql);
            fts_assert_error(&error, sqlstate, parts);
            if !hint.is_empty() {
                fts_assert_hint(&error, hint);
            }
            fts_assert_untouched(table, &docs);
        }
    }

    /// An id over 512 bytes fails the writer's statement at enqueue (bytes, not characters);
    /// 512 bytes is fine, and a refused statement leaves neither row nor queue entry.
    #[pg_test]
    fn doc_outbox_ids_over_512_bytes_fail_at_enqueue() {
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_t9_long (id text PRIMARY KEY, body text)");
        fts_track_minimal("fts_t9_long");
        fts_drain("fts_t9_long");

        fts_run("INSERT INTO fts_t9_long VALUES (repeat('x', 512), 'at the limit')");
        assert_eq!(fts_queue("fts_t9_long").len(), 1, "512 bytes is accepted");
        let too_long = [("repeat('x', 513)", "513"), ("repeat('é', 257)", "514")];
        for (id_expr, bytes) in too_long {
            let error = fts_sql_error(&format!(
                "INSERT INTO fts_t9_long VALUES ({id_expr}, 'too long')"
            ));
            fts_assert_error(&error, "54000", &["512", bytes]);
        }
        assert_eq!(
            fts_heap_ids("fts_t9_long").len(),
            1,
            "refused statements leave no rows"
        );
        assert_eq!(fts_queue("fts_t9_long").len(), 1, "and no queue entries");
    }

    // ---- schema derivation and attach ----

    fn fts_track_sql(table: &str, args: &str) -> String {
        format!("SELECT {FTS_TRACK}({}, {args})", fts_rel(table))
    }

    /// The body of the `POST /indexes` call that created `index`.
    fn fts_created_index_body(docs: &DocsHandle, index: &str) -> Value {
        let creates = docs.calls_to(Endpoint::IndexCreate);
        let created = creates.iter().find(|c| c.index.as_deref() == Some(index));
        let created =
            created.unwrap_or_else(|| panic!("no create call for {index}: {:?}", docs.calls()));
        created.body.clone().expect("create call body")
    }

    /// The design's example declaration derives exactly the documented schema: three
    /// full-text fields with filled-in analyzers, one dense field, no metadata fields, and
    /// no local-only options (`on_oversize`) leaking into it.
    #[pg_test]
    fn track_docs_derives_the_documented_schema_for_the_example_declaration() {
        let env = FtsEnv::untracked("fts_t11_golden");
        fts_track_standard(&env.table, &env.index);

        let creates = env.docs.calls_to(Endpoint::IndexCreate);
        assert_eq!(creates.len(), 1, "calls = {:?}", env.docs.calls());
        let body = fts_created_index_body(&env.docs, &env.index);
        assert_eq!(body["schema"], fts_golden_schema("cosine"));
        assert!(
            body.get("read_capacity").is_none(),
            "on-demand by default: {body}"
        );
        assert_eq!(
            env.docs.count(Endpoint::Upsert),
            0,
            "tracking sends no documents itself"
        );
    }

    /// The dense field's dimension comes from the column, for `vector` and `halfvec`.
    #[pg_test]
    fn track_docs_derives_the_dense_field_from_vector_and_halfvec_columns() {
        create_extension_vector();
        let (_backend, docs) = fts_mock();
        for (table, column_type, dimension) in [
            ("fts_t11_vec", "vector(3)", 3),
            ("fts_t11_half", "halfvec(4)", 4),
        ] {
            fts_run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, body text, embedding {column_type})"
            ));
            let args = "text_columns => '{\"body\": {}}'::jsonb, vector_column => 'embedding', index_name => ";
            fts_run(&fts_track_sql(
                table,
                &format!("{args}{}", quote_literal(fts_index_name(table))),
            ));
            let schema = fts_created_index_body(&docs, &fts_index_name(table))["schema"].clone();
            let (stem, stop) = (FTS_DEFAULT_STEMMING, FTS_DEFAULT_STOP_WORDS);
            assert_eq!(
                schema,
                json!({"fields": {
                    "body": fts_field(FTS_DEFAULT_LANGUAGE, stem, stop),
                    "embedding": {"type": "dense_vector", "dimension": dimension, "metric": "cosine"},
                }}),
                "{column_type} column"
            );
        }
    }

    /// The metric follows the opclass of an index on the vector column.
    #[pg_test]
    fn track_docs_derives_the_metric_from_the_vector_opclass() {
        create_extension_vector();
        let (_backend, docs) = fts_mock();
        let cases = [
            ("fts_t11_l2", "vector(3)", "vector_l2_ops", "euclidean"),
            ("fts_t11_ip", "vector(3)", "vector_ip_ops", "dotproduct"),
            (
                "fts_t11_half_l2",
                "halfvec(3)",
                "halfvec_l2_ops",
                "euclidean",
            ),
        ];
        for (table, column_type, opclass, metric) in cases {
            fts_run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, body text, embedding {column_type})"
            ));
            fts_run(&format!(
                "CREATE INDEX ON {table} USING hnsw (embedding {opclass})"
            ));
            let args = "text_columns => '{\"body\": {}}'::jsonb, vector_column => 'embedding', index_name => ";
            fts_run(&fts_track_sql(
                table,
                &format!("{args}{}", quote_literal(fts_index_name(table))),
            ));
            let schema = fts_created_index_body(&docs, &fts_index_name(table))["schema"].clone();
            assert_eq!(
                schema["fields"]["embedding"]["metric"],
                json!(metric),
                "{opclass}"
            );
        }
    }

    /// A declared column whose name Pinecone would reject, or that collides with the
    /// reserved `pg_pinecone_` fields, is refused before any HTTP call.
    #[pg_test]
    fn track_docs_refuses_field_names_pinecone_rejects_or_pg_pinecone_reserves() {
        let (_backend, docs) = fts_mock();
        let marker = FTS_TRUNCATED_MARKER;
        fts_run(&format!(
            "CREATE TABLE fts_t12_names (id bigint PRIMARY KEY, body text, \"_body\" text, \
             \"_tag\" text, \"$price\" text, {marker} text, pg_pinecone_extra text)"
        ));
        let body = "text_columns => '{\"body\": {}}'::jsonb";
        let reserved = format!("text_columns => '{{\"{marker}\": {{}}}}'::jsonb");
        let cases: Vec<(String, Vec<String>)> = vec![
            (
                "text_columns => '{\"_body\": {}}'::jsonb".to_string(),
                vec!["\"_body\" is not a valid Pinecone field name".to_string()],
            ),
            (
                format!("{body}, metadata_columns => ARRAY['_tag']"),
                vec!["\"_tag\"".to_string(), "field name".to_string()],
            ),
            (
                format!("{body}, metadata_columns => ARRAY['$price']"),
                vec!["\"$price\"".to_string(), "field name".to_string()],
            ),
            (
                reserved,
                vec![format!("\"{marker}\" collides with a reserved field name")],
            ),
            (
                "text_columns => '{\"pg_pinecone_extra\": {}}'::jsonb".to_string(),
                vec!["\"pg_pinecone_extra\"".to_string(), "reserved".to_string()],
            ),
        ];
        for (args, parts) in cases {
            let parts: Vec<&str> = parts.iter().map(String::as_str).collect();
            let error = fts_sql_error(&fts_track_sql("fts_t12_names", &args));
            fts_assert_error(&error, "42602", &parts);
            fts_assert_untouched("fts_t12_names", &docs);
        }
    }

    /// Ngram excludes stemming and stop words, and an unknown analyzer option is named;
    /// both are caught locally and the HINT says what to do.
    #[pg_test]
    fn track_docs_refuses_invalid_analyzer_declarations() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_t12_analyzer (id bigint PRIMARY KEY, body text, sku text)");
        let ngram = r#""ngram": {"min_gram": 2, "max_gram": 4}"#;
        let combination = ["column \"sku\": ngram cannot be combined with stemming or stop_words"];
        let cases: [(String, &[&str], &str); 3] = [
            (
                format!(r#"{{"sku": {{{ngram}, "stemming": true}}}}"#),
                &combination,
                "stemming => false",
            ),
            (
                format!(r#"{{"sku": {{{ngram}, "stop_words": true}}}}"#),
                &combination,
                "stop_words => false",
            ),
            (
                r#"{"body": {"stemmer": true}}"#.to_string(),
                &["column \"body\": unknown option \"stemmer\""],
                "on_oversize",
            ),
        ];
        for (declaration, parts, hint) in cases {
            let args = format!("text_columns => {}::jsonb", quote_literal(&declaration));
            let error = fts_sql_error(&fts_track_sql("fts_t12_analyzer", &args));
            fts_assert_error(&error, "22023", parts);
            fts_assert_hint(&error, hint);
            fts_assert_untouched("fts_t12_analyzer", &docs);
        }
    }

    /// An ngram column that says nothing about stemming does not inherit the stemming and
    /// stop-word defaults (they would make the declaration invalid).
    #[pg_test]
    fn track_docs_ngram_column_does_not_inherit_the_stemming_defaults() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_t12_ngram (id bigint PRIMARY KEY, sku text)");
        let declaration = r#"{"sku": {"ngram": {"min_gram": 2, "max_gram": 4}}}"#;
        let args = format!(
            "text_columns => {}::jsonb, index_name => 'fts-t12-ngram'",
            quote_literal(declaration)
        );
        fts_run(&fts_track_sql("fts_t12_ngram", &args));

        let schema = fts_created_index_body(&docs, "fts-t12-ngram")["schema"].clone();
        let sku = &schema["fields"]["sku"]["full_text_search"];
        assert_eq!(
            sku["ngram"],
            json!({"min_gram": 2, "max_gram": 4}),
            "schema = {schema}"
        );
        assert_ne!(
            sku["stemming"],
            json!(true),
            "ngram excludes stemming: {schema}"
        );
        assert_ne!(
            sku["stop_words"],
            json!(true),
            "ngram excludes stop words: {schema}"
        );
    }

    /// The remote `schema.fields` matching `text_columns => {"title": {}, "body": {"language": <l>, "stemming": true}}`.
    fn fts_attach_fields(body_language: &str) -> Value {
        let (stem, stop) = (FTS_DEFAULT_STEMMING, FTS_DEFAULT_STOP_WORDS);
        json!({
            "title": fts_field(FTS_DEFAULT_LANGUAGE, stem, stop),
            "body": fts_field(body_language, true, stop),
        })
    }

    /// `track_docs` arguments for the attach tests' `(title, body)` tables.
    fn fts_attach_args(index: &str, extra: &str) -> String {
        let columns = r#"{"title": {}, "body": {"language": "en", "stemming": true}}"#;
        format!(
            "text_columns => {}::jsonb, index_name => {}{extra}",
            quote_literal(columns),
            quote_literal(index)
        )
    }

    fn fts_create_attach_table(table: &str) {
        fts_run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, title text, body text)"
        ));
        fts_run(&format!(
            "INSERT INTO {table} VALUES (1, 'one', 'first'), (2, 'two', 'second')"
        ));
    }

    fn fts_assert_registered(table: &str) {
        let sql = format!(
            "SELECT EXISTS (SELECT 1 FROM {FTS_REGISTRY} WHERE relid = {})",
            fts_rel(table)
        );
        let registered = Spi::get_one::<bool>(&sql).expect("registry lookup");
        assert_eq!(registered, Some(true), "{table} must be registered");
    }

    fn fts_created_indexes(docs: &DocsHandle) -> usize {
        let creates = docs.calls_to(Endpoint::IndexCreate);
        creates.iter().filter(|c| c.status == 201).count()
    }

    /// An existing index whose field specs match is attached with `adopt_existing => true`
    /// (document indexes have no namespace describe, so an attach is always an
    /// explicit opt-in), not created. Server-applied analyzer keys (`lowercase`, ...) do not
    /// count as a difference. Tracking sends no documents itself; the backfill fills the
    /// existing index with the rows 1 and 2 that exist, the live path with the later row 3.
    #[pg_test]
    fn track_docs_attaches_an_index_whose_schema_matches() {
        let (_backend, docs) = fts_mock();
        let table = "fts_t13_attach";
        fts_create_attach_table(table);
        let index = fts_index_name(table);
        docs.preload_index(&index, fts_attach_fields("en"));
        fts_run(&fts_track_sql(
            table,
            &fts_attach_args(&index, ", adopt_existing => true"),
        ));
        fts_assert_registered(table);
        assert_eq!(
            fts_created_indexes(&docs),
            0,
            "attached, never created: {:?}",
            docs.calls()
        );
        assert_eq!(
            docs.count(Endpoint::Upsert),
            0,
            "tracking sends no documents"
        );

        fts_run(&format!("INSERT INTO {table} VALUES (3, 'three', 'third')"));
        fts_drain(table);
        let remote = docs.remote_ids(&fts_namespace(table));
        assert_eq!(
            remote,
            fts_set(&["1", "2", "3"]),
            "backfilled and live rows in the existing index"
        );
    }

    /// An analyzer mismatch (here language) is an error that names the field, both
    /// specs and the way out; nothing is registered.
    #[pg_test]
    fn track_docs_refuses_to_attach_an_index_with_a_different_analyzer() {
        let (_backend, docs) = fts_mock();
        fts_create_attach_table("fts_t13_mismatch");
        let index = fts_index_name("fts_t13_mismatch");
        docs.preload_index(&index, fts_attach_fields("de"));

        let error = fts_sql_error(&fts_track_sql(
            "fts_t13_mismatch",
            &fts_attach_args(&index, ""),
        ));
        fts_assert_error(
            &error,
            "42P16",
            &["exists with a different schema", "\"body\"", "de", "en"],
        );
        fts_assert_hint(&error, "index_name");
        fts_assert_unregistered("fts_t13_mismatch");
        assert_eq!(
            docs.count(Endpoint::Upsert),
            0,
            "calls = {:?}",
            docs.calls()
        );
    }

    /// Document indexes have no namespace describe, so emptiness cannot be checked: attaching
    /// an existing index needs `adopt_existing => true` even when its schema matches, because
    /// ids without a row would never join back.
    #[pg_test]
    fn track_docs_refuses_to_attach_an_existing_index_unless_adopt_existing() {
        let (_backend, docs) = fts_mock();
        fts_create_attach_table("fts_t13_adopt");
        let index = fts_index_name("fts_t13_adopt");
        docs.preload_index(&index, fts_attach_fields("en"));

        let error = fts_sql_error(&fts_track_sql(
            "fts_t13_adopt",
            &fts_attach_args(&index, ""),
        ));
        fts_assert_error(&error, "55000", &["already exists", &index]);
        fts_assert_hint(&error, "adopt_existing => true");
        fts_assert_unregistered("fts_t13_adopt");

        let adopt = fts_attach_args(&index, ", adopt_existing => true");
        fts_run(&fts_track_sql("fts_t13_adopt", &adopt));
        fts_assert_registered("fts_t13_adopt");
    }

    /// T13 (minor m2): every call the docs lane makes, control plane and data plane alike,
    /// carries `X-Pinecone-Api-Version: 2026-07`; the preview version appears nowhere. (The
    /// search call joins this scenario with `search_docs`; there is no namespace describe.)
    #[pg_test]
    fn docs_lane_sends_the_api_version_header_on_every_call() {
        let env = FtsEnv::untracked("fts_t13_version");
        env.run(
            "INSERT INTO fts_t13_version (id, title, body) VALUES (1, 'a', 'b'), (2, 'c', 'd')",
        );
        fts_track_standard(&env.table, &env.index);
        env.drain();
        env.run("DELETE FROM fts_t13_version WHERE id = 1");
        env.run("INSERT INTO fts_t13_version (id, title, body) VALUES (3, 'e', 'f')");
        env.drain();
        env.run("TRUNCATE fts_t13_version");
        env.drain();

        fts_create_attach_table("fts_t13_version_attach");
        let attach_index = fts_index_name("fts_t13_version_attach");
        env.docs
            .preload_index(&attach_index, fts_attach_fields("en"));
        fts_run(&fts_track_sql(
            "fts_t13_version_attach",
            &fts_attach_args(&attach_index, ", adopt_existing => true"),
        ));

        let calls = env.docs.calls();
        let seen: BTreeSet<String> = calls.iter().map(|c| format!("{:?}", c.endpoint)).collect();
        for endpoint in ["IndexCreate", "IndexDescribe", "Upsert", "Delete"] {
            assert!(
                seen.contains(endpoint),
                "the scenario never called {endpoint}: {seen:?}"
            );
        }
        for call in &calls {
            let version = call.api_version.as_deref();
            assert_eq!(
                version,
                Some(EXPECTED_API_VERSION),
                "{} {}",
                call.method,
                call.path
            );
        }
    }

    /// A schema Pinecone rejects after local validation passed is reported with the
    /// derived schema, nothing stays registered, and the same call works once the cause is fixed.
    #[pg_test]
    fn track_docs_reports_a_schema_pinecone_rejects_and_registers_nothing() {
        let env = FtsEnv::untracked("fts_x_rejected");
        env.docs.fail_next(
            Endpoint::IndexCreate,
            1,
            400,
            "field 'sku': unsupported language",
        );

        let error = fts_sql_error(&fts_track_standard_sql(&env.table, &env.index));
        fts_assert_error(
            &error,
            "22023",
            &["Pinecone rejected the derived schema for index", &env.index],
        );
        assert!(
            error
                .detail
                .as_deref()
                .unwrap_or_default()
                .contains("schema:"),
            "{error:?}"
        );
        fts_assert_hint(&error, "nothing was registered");
        fts_assert_unregistered(&env.table);

        fts_track_standard(&env.table, &env.index);
        fts_assert_registered(&env.table);
    }

    /// Extra (minor m4): metadata columns ride on the document with Pinecone-compatible types:
    /// timestamps as epoch seconds whatever the session time zone, `text[]` as a list.
    #[pg_test]
    fn doc_drain_sends_metadata_with_pinecone_compatible_types() {
        let (_backend, docs) = fts_mock();
        fts_run(
            "CREATE TABLE fts_x_types (id bigint PRIMARY KEY, body text, published_at timestamptz, \
             tags text[], views int, rating numeric, featured boolean, score float8)",
        );
        let metadata = "ARRAY['published_at', 'tags', 'views', 'rating', 'featured', 'score']";
        let args = format!(
            "text_columns => '{{\"body\": {{}}}}'::jsonb, metadata_columns => {metadata}, index_name => 'fts-x-types'"
        );
        fts_run(&fts_track_sql("fts_x_types", &args));
        fts_drain("fts_x_types");

        fts_run("SET TimeZone = 'Asia/Tokyo'");
        fts_run(
            "INSERT INTO fts_x_types VALUES (1, 'b', '2026-01-01 00:00:00+00', ARRAY['a', 'b'], \
             5, 4.5, true, 0.25)",
        );
        fts_drain("fts_x_types");
        let doc = docs
            .remote_doc(&fts_namespace("fts_x_types"), "1")
            .expect("delivered");
        assert_eq!(
            doc["published_at"].as_f64(),
            Some(1767225600.0),
            "epoch seconds: {doc}"
        );
        assert_eq!(doc["tags"], json!(["a", "b"]));
        assert_eq!(doc["views"].as_f64(), Some(5.0), "{doc}");
        assert_eq!(doc["rating"].as_f64(), Some(4.5), "{doc}");
        assert_eq!(doc["featured"], json!(true));
        assert_eq!(doc["score"].as_f64(), Some(0.25), "{doc}");
    }

    /// Extra (minor m4): a jsonb metadata column has no Pinecone type and is refused up front.
    #[pg_test]
    fn track_docs_refuses_jsonb_metadata_columns() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_jsonb (id bigint PRIMARY KEY, body text, payload jsonb)");
        let args = "text_columns => '{\"body\": {}}'::jsonb, metadata_columns => ARRAY['payload']";
        let error = fts_sql_error(&fts_track_sql("fts_x_jsonb", args));
        assert!(
            ["42804", "0A000"].contains(&error.sqlstate.as_str()),
            "{error:?}"
        );
        assert!(
            error.message.contains("payload") && error.message.contains("jsonb"),
            "{error:?}"
        );
        fts_assert_untouched("fts_x_jsonb", &docs);
    }

    // ---- size policy and fault isolation ----

    /// An oversized text column is cut under `on_oversize => 'truncate'`, by bytes (a
    /// 150 KB body) and by tokens (66 KB of 2-byte tokens, 22,000 tokens), and the delivered
    /// document says so; a small document in the same batch is untouched.
    #[pg_test]
    fn doc_drain_truncates_oversized_text_and_marks_the_document() {
        let env = FtsEnv::tracked("fts_t15_truncate");
        env.run(
            "INSERT INTO fts_t15_truncate (id, title, body) VALUES \
             (1, 't', repeat('abcdefghi ', 15000)), (2, 't', repeat('ab ', 22000)), \
             (3, 't', 'a short body')",
        );
        env.drain();
        let calls = env.docs.calls_to(Endpoint::Upsert);
        assert!(
            calls.iter().all(|c| c.status == 202),
            "Pinecone must accept every request: {calls:?}"
        );

        for (id, original) in [
            ("1", "abcdefghi ".repeat(15000)),
            ("2", "ab ".repeat(22000)),
        ] {
            let doc = env.remote_doc(id);
            let body = doc["body"].as_str().expect("body is a string");
            assert!(body.len() < original.len(), "doc {id} was not cut");
            assert!(body.len() <= 102_400, "doc {id}: {} bytes", body.len());
            assert!(
                body.split_whitespace().count() <= 9_000,
                "doc {id}: too many tokens"
            );
            assert!(
                original.starts_with(body.trim_end()),
                "doc {id}: a prefix of the original"
            );
            assert_eq!(
                doc[FTS_TRUNCATED_MARKER],
                json!(true),
                "doc {id} carries the marker"
            );
        }
        let small = env.remote_doc("3");
        assert_eq!(small["body"], json!("a short body"));
        assert_ne!(
            small[FTS_TRUNCATED_MARKER],
            json!(true),
            "untouched documents are not marked"
        );
    }

    /// Under `on_oversize => 'error'` the writer's statement fails with the table's
    /// message, for the same two shapes of oversize; nothing is stored or queued.
    #[pg_test]
    fn doc_outbox_oversized_text_under_the_error_policy_fails_the_statement() {
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_t15_error (id bigint PRIMARY KEY, body text)");
        let args = "text_columns => '{\"body\": {\"on_oversize\": \"error\"}}'::jsonb";
        fts_run(&fts_track_sql("fts_t15_error", args));
        fts_drain("fts_t15_error");

        fts_run("INSERT INTO fts_t15_error VALUES (1, 'fits')");
        for body in ["repeat('abcdefghi ', 15000)", "repeat('ab ', 22000)"] {
            let error = fts_sql_error(&format!("INSERT INTO fts_t15_error VALUES (2, {body})"));
            fts_assert_error(&error, "54000", &["column \"body\"", "bytes", "100 KB"]);
            fts_assert_hint(&error, "on_oversize => 'truncate'");
        }
        assert_eq!(
            fts_heap_ids("fts_t15_error"),
            fts_set(&["1"]),
            "refused rows are not stored"
        );
        assert_eq!(fts_queue("fts_t15_error").len(), 1, "and not queued");
    }

    /// Metadata over 40 KB cannot be sent, so the statement fails.
    #[pg_test]
    fn doc_outbox_oversized_metadata_fails_the_statement() {
        let env = FtsEnv::tracked("fts_x_big_meta");
        let error = fts_sql_error(
            "INSERT INTO fts_x_big_meta (id, title, body, author) VALUES (1, 't', 'b', repeat('a', 52000))",
        );
        fts_assert_error(&error, "54000", &["metadata", "40 KB"]);
        fts_assert_hint(&error, "metadata_columns");
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
    }

    /// Pinecone rejects a request because of one document. The worker narrows the request
    /// down, delivers the others, dead-letters the culprit and never parks the lane (even with
    /// `outbox_max_attempts = 1`, which would park on any permanent failure); `retry_failed_docs`
    /// puts the culprit back in the queue.
    #[pg_test]
    fn doc_drain_bisects_a_rejected_request_into_dead_letters_without_parking() {
        let env = FtsEnv::tracked("fts_t16_poison");
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs.fail_ids(
            Endpoint::Upsert,
            &["2"],
            400,
            "document 2: field 'body' is invalid",
        );
        env.run(
            "INSERT INTO fts_t16_poison (id, title, body) VALUES (1, 'a', 'one'), (2, 'b', 'two'), \
             (3, 'c', 'three')",
        );

        env.drain();
        assert_eq!(
            env.remote_ids(),
            fts_set(&["1", "3"]),
            "everything but the culprit is delivered"
        );
        let attempts = env.docs.count(Endpoint::Upsert);
        assert!(
            (3..=8).contains(&attempts),
            "bisecting, not retrying blindly: {attempts} requests"
        );
        let dead: Vec<Value> = env
            .queue()
            .into_iter()
            .filter(|r| r["op"] == json!(FTS_OP_FAILED))
            .collect();
        assert_eq!(dead.len(), 1, "one dead letter: {:?}", env.queue());
        let letter = dead[0]["payload"].to_string();
        assert!(
            letter.contains('2') && letter.contains("field 'body' is invalid"),
            "letter = {letter}"
        );
        let failed = fts_failed_docs(&env.table);
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        assert_eq!(failed[0]["id"], json!("2"));
        let error = failed[0]["error"].as_str().unwrap_or_default();
        assert!(
            error.contains("field 'body' is invalid"),
            "error = {error:?}"
        );
        assert!(
            !failed[0]["failed_at"].is_null(),
            "failed_docs = {failed:?}"
        );
        assert!(
            !fts_lane_parked(&env.table),
            "a per-document 400 never parks"
        );

        fts_run(&format!(
            "SELECT {FTS_RETRY_FAILED}({})",
            fts_rel(&env.table)
        ));
        assert!(
            fts_queue_ops(&env.table)
                .iter()
                .all(|op| op != FTS_OP_FAILED),
            "dead letters re-enqueued"
        );
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["2".to_string()]
        );
        assert!(fts_failed_docs(&env.table).is_empty());
        env.docs.heal(Endpoint::Upsert);
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1", "2", "3"]));
    }

    /// During a 429 storm writes keep succeeding and queue up, rounds back off without
    /// counting attempts (429 is transient) and without leaking the key, and once Pinecone
    /// recovers the backlog is delivered in the order it was written.
    #[pg_test]
    fn doc_drain_429_storm_keeps_writes_succeeding_then_drains_in_order() {
        let env = FtsEnv::tracked("fts_t17_storm");
        env.docs
            .fail_always(Endpoint::Upsert, 429, "Pace your requests per second");
        for id in 1..=5 {
            env.run(&format!(
                "INSERT INTO fts_t17_storm (id, title, body) VALUES ({id}, 't', 'b')"
            ));
        }
        assert_eq!(env.queue().len(), 5, "every write succeeded and queued");

        for _ in 0..3 {
            assert_eq!(env.round(), "backoff");
        }
        let rows = env.queue();
        assert_eq!(rows.len(), 5, "the whole backlog survives: {rows:?}");
        assert!(
            rows.iter().all(|r| r["attempts"] == json!(0)),
            "429 never counts as an attempt: {rows:?}"
        );
        let last_error = rows[0]["last_error"].as_str().unwrap_or_default();
        assert!(last_error.contains("429"), "last_error = {last_error:?}");
        assert!(
            !last_error.contains("test-key"),
            "the key must never be recorded: {last_error:?}"
        );
        assert!(!fts_lane_parked(&env.table), "a 429 never parks");

        env.docs.heal_all();
        env.drain();
        let delivered = fts_delivered_ids(&env.docs);
        assert_eq!(
            delivered,
            ["1", "2", "3", "4", "5"],
            "in write order, each once"
        );
        assert!(env.queue().is_empty());
    }

    // ---- query translation and results ----

    /// Rows of `SELECT * FROM pinecone.search_docs(<args>)` as JSON objects, in output order.
    fn fts_search_rows(args: &str) -> Vec<Value> {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) FROM {FTS_SEARCH}({args}) s"
        );
        let rows = Spi::get_one::<JsonB>(&sql).expect("search_docs");
        rows.expect("aggregate is NOT NULL")
            .0
            .as_array()
            .cloned()
            .unwrap_or_default()
    }

    /// `<table>::regclass, <query>::text` plus `rest` (named arguments), for `search_docs`.
    fn fts_search_args(table: &str, query: &str, rest: &str) -> String {
        let query = if query == "NULL" {
            "NULL::text".to_string()
        } else {
            format!("{}::text", quote_literal(query))
        };
        let rest = if rest.is_empty() {
            String::new()
        } else {
            format!(", {rest}")
        };
        format!("{}, {query}{rest}", fts_rel(table))
    }

    /// The most recent search request the mock saw.
    fn fts_last_search(docs: &DocsHandle) -> Value {
        let call = docs
            .calls_to(Endpoint::Search)
            .pop()
            .expect("a search call reached Pinecone");
        call.body.expect("search body")
    }

    /// The `score_by` clauses of `request`.
    fn fts_clauses(request: &Value) -> Vec<Value> {
        request["score_by"].as_array().expect("score_by").clone()
    }

    /// The names a clause's `fields` array lists, sorted so declared-column order is irrelevant.
    /// The singular `field` is deprecated in the 2026-07 API and must never be sent.
    fn fts_clause_fields(clause: &Value) -> Vec<String> {
        assert!(clause.get("field").is_none(), "clause = {clause}");
        let mut names: Vec<String> = clause["fields"]
            .as_array()
            .expect("fields array")
            .iter()
            .filter_map(|f| f.as_str().map(str::to_string))
            .collect();
        names.sort();
        names
    }

    fn fts_f64s(values: &Value) -> Vec<Option<f64>> {
        values
            .as_array()
            .expect("an array")
            .iter()
            .map(Value::as_f64)
            .collect()
    }

    /// A plain query is ONE BM25 `text` clause naming every declared text column (the 2026-07
    /// `fields` array); the request asks for ids and scores only, over the table's own namespace.
    #[pg_test]
    fn search_docs_table_text_query_searches_every_declared_text_column() {
        let env = FtsEnv::tracked("fts_t20_text");
        env.docs.set_search_matches(&[("1", 2.0)]);
        fts_search_rows(&fts_search_args(&env.table, "postgres vector search", ""));

        let request = fts_last_search(&env.docs);
        let clauses = fts_clauses(&request);
        assert_eq!(clauses.len(), 1, "one clause for all columns: {request}");
        assert_eq!(clauses[0]["type"], json!("text"));
        assert_eq!(clauses[0]["query"], json!("postgres vector search"));
        assert_eq!(fts_clause_fields(&clauses[0]), ["body", "sku", "title"]);
        assert_eq!(request["top_k"], json!(10));
        assert_eq!(request["include_fields"], json!([]), "ids and scores only");
        assert!(request.get("filter").is_none(), "request = {request}");
        let search = env.docs.calls_to(Endpoint::Search);
        assert_eq!(search[0].namespace.as_deref(), Some(env.namespace.as_str()));
    }

    /// `field` narrows the search to one column and `k` is the request's `top_k`.
    #[pg_test]
    fn search_docs_table_field_narrows_the_query_to_one_column() {
        let env = FtsEnv::tracked("fts_t20_field");
        fts_search_rows(&fts_search_args(
            &env.table,
            "growling bear",
            "field => 'body', k => 3",
        ));
        let request = fts_last_search(&env.docs);
        assert_eq!(
            request["score_by"],
            json!([{"type": "text", "fields": ["body"], "query": "growling bear"}])
        );
        assert_eq!(request["top_k"], json!(3));
    }

    /// `must` and `filter` are sent as one `$and` (must first); either one
    /// alone is sent as it is.
    #[pg_test]
    fn search_docs_table_merges_must_and_filter_with_and() {
        let env = FtsEnv::tracked("fts_t20_merge");
        let must = json!({"body": {"$match_all": "TensorFlow"}});
        let filter = json!({"author": {"$eq": "ann"}});
        let both = format!(
            "must => {}::jsonb, filter => {}::jsonb",
            quote_literal(must.to_string()),
            quote_literal(filter.to_string())
        );
        let only_must = format!("must => {}::jsonb", quote_literal(must.to_string()));
        let only_filter = format!("filter => {}::jsonb", quote_literal(filter.to_string()));
        for rest in [&both, &only_must, &only_filter] {
            fts_search_rows(&fts_search_args(&env.table, "ml", rest));
        }
        let sent: Vec<Value> = env
            .docs
            .calls_to(Endpoint::Search)
            .into_iter()
            .filter_map(|c| c.body)
            .collect();
        assert_eq!(sent.len(), 3);
        assert_eq!(sent[0]["filter"], json!({"$and": [must, filter]}));
        assert_eq!(sent[1]["filter"], must);
        assert_eq!(sent[2]["filter"], filter);
    }

    /// `vector` alone ranks by the dense field named after the vector column.
    #[pg_test]
    fn search_docs_table_vector_only_ranks_by_the_dense_field() {
        let env = FtsEnv::tracked("fts_t20_vector");
        fts_search_rows(&fts_search_args(
            &env.table,
            "NULL",
            "vector => '[0.5, -0.25, 2]'::vector",
        ));
        let request = fts_last_search(&env.docs);
        let clauses = request["score_by"].as_array().expect("score_by").clone();
        assert_eq!(clauses.len(), 1, "request = {request}");
        assert_eq!(clauses[0]["type"], json!("dense_vector"));
        assert_eq!(fts_clause_fields(&clauses[0]), ["embedding"]);
        assert_eq!(
            fts_f64s(&clauses[0]["values"]),
            [Some(0.5), Some(-0.25), Some(2.0)]
        );
        assert!(request.get("filter").is_none(), "request = {request}");
    }

    /// `vector` with `must` ranks densely and filters lexically, in one request.
