    /// Every argument problem is refused before Pinecone is asked, with its SQLSTATE.
    #[pg_test]
    fn search_docs_table_refuses_bad_arguments_before_any_call() {
        let env = FtsEnv::tracked("fts_x_args");
        let jsonb = |name: &str, json: &str| format!("{name} => {}::jsonb", quote_literal(json));
        let cases: Vec<(&str, String, &str, &str)> = vec![
            ("q", "engine => 'quantum'".into(), "22023", "engine"),
            ("q", "mode => 'fuzzy'".into(), "22023", "mode"),
            ("q", "mode => NULL".into(), "22004", "mode"),
            ("q", "k => NULL".into(), "22004", "k"),
            ("NULL", String::new(), "22023", "query"),
            ("  ", String::new(), "22023", "must not be empty"),
            ("q", "field => 'nope'".into(), "42703", "\"nope\""),
            ("q", "field => 'author'".into(), "42703", "text column"),
            (
                "q",
                "field => 'body', mode => 'query_string'".into(),
                "22023",
                "query_string",
            ),
            ("q", jsonb("must", r#"["body"]"#), "22023", "must"),
            ("q", jsonb("must", "{}"), "22023", "must"),
            (
                "q",
                jsonb("must", r#"{"author": {"$match_all": "a"}}"#),
                "22023",
                "author",
            ),
            (
                "q",
                jsonb("must", r#"{"body": {"$eq": "a"}}"#),
                "22023",
                "$eq",
            ),
            (
                "q",
                jsonb("must", r#"{"body": {"$match_all": 3}}"#),
                "22023",
                "body",
            ),
            ("q", jsonb("filter", "[1]"), "22023", "filter"),
            (
                "q",
                jsonb("filter", r#"{"body": {"$eq": "a"}}"#),
                "22023",
                "body",
            ),
            (
                "q",
                jsonb("filter", r#"{"note": {"$eq": "a"}}"#),
                "22023",
                "note",
            ),
            (
                "q",
                jsonb("filter", r#"{"author": {"$regex": "a"}}"#),
                "22023",
                "$regex",
            ),
            (
                "q",
                jsonb("filter", r#"{"author": {"$gt": "a"}}"#),
                "22023",
                "range",
            ),
            (
                "q",
                jsonb("filter", r#"{"published_at": {"$gt": "next tuesday-ish"}}"#),
                "22023",
                "published_at",
            ),
            (
                "NULL",
                "vector => '{1,NULL,3}'::real[]".into(),
                "22004",
                "vector",
            ),
            (
                "NULL",
                "vector => '{1,NaN,3}'::real[]".into(),
                "22023",
                "vector",
            ),
        ];
        for (query, rest, sqlstate, part) in cases {
            let sql = format!(
                "SELECT * FROM {FTS_SEARCH}({})",
                fts_search_args(&env.table, query, &rest)
            );
            let error = fts_sql_error(&sql);
            fts_assert_error(&error, sqlstate, &["pinecone.search_docs", part]);
        }
        assert_eq!(
            env.docs.count(Endpoint::Search),
            0,
            "refused before the call"
        );
    }

    /// `vector` on a table that declared no vector column says how to get one.
