    /// Each declared column is searched with the configuration of its own language, and a column
    /// that declares no stemming is matched as written (`simple`).
    #[pg_test]
    fn search_docs_local_engine_uses_the_declared_language_of_each_column() {
        let env = FtsEnv::untracked("fts_x_local_lang");
        let declared = r#"{"title": {"language": "de"}, "body": {"language": "en"},
            "sku": {"stemming": false, "stop_words": false}}"#;
        env.run(&fts_track_sql(
            &env.table,
            &format!(
                "text_columns => {}::jsonb, index_name => {}",
                quote_literal(declared),
                quote_literal(&env.index)
            ),
        ));
        env.run(
            "INSERT INTO fts_x_local_lang (id, title, body, sku) VALUES \
             (1, 'Die Katzen schlafen', NULL, NULL), (2, NULL, 'The Katzen sleep', NULL), \
             (3, NULL, 'The house is big', NULL), (4, NULL, NULL, 'Running'), \
             (5, NULL, NULL, 'runs')",
        );
        let found = |query: &str, rest: &str| {
            let rest = format!("engine => 'local'{rest}");
            fts_row_ids(&fts_search_rows(&fts_search_args(&env.table, query, &rest)))
        };
        assert_eq!(found("Katze", ""), ["1"], "German stems Katzen to Katze");
        assert_eq!(found("houses", ""), ["3"], "English stems houses to house");
        assert_eq!(found("running", ""), ["4"], "sku is matched as written");
        assert_eq!(found("runs", ""), ["5"]);
        assert_eq!(found("Running", ", field => 'sku'"), ["4"]);
        assert!(
            found("Katze", ", field => 'body'").is_empty(),
            "body is English"
        );
    }

    /// A row may match through any configuration, and a row that matches through several ranks
    /// above one that matches through one.
    #[pg_test]
    fn search_docs_local_engine_adds_up_the_ranks_of_the_configurations() {
        let env = FtsEnv::tracked("fts_x_local_sum");
        env.run(
            "INSERT INTO fts_x_local_sum (id, title, body, sku) VALUES (1, 'a', 'postgres', NULL), \
             (2, 'b', 'postgres', 'postgres'), (3, 'c', 'd', 'postgres')",
        );
        let args = fts_search_args(&env.table, "postgres", "engine => 'local'");
        let rows = fts_search_rows(&args);
        assert_eq!(fts_row_ids(&rows), ["2", "1", "3"], "{rows:?}");
        let score = |at: usize| rows[at]["score"].as_f64().expect("a score");
        assert!(score(0) > score(1), "both configurations: {rows:?}");
        assert_eq!(score(1), score(2), "one configuration each: {rows:?}");
    }

    /// `field` narrows the search to one declared column; an undeclared one is refused like the
    /// remote engine refuses it, with the declared columns in the HINT.
    #[pg_test]
    fn search_docs_local_engine_field_narrows_to_one_declared_column() {
        let env = FtsEnv::tracked("fts_x_local_field");
        env.run(
            "INSERT INTO fts_x_local_field (id, title, body, note) VALUES \
             (1, 'postgres', 'x', NULL), (2, 'y', 'postgres', NULL), (3, 'z', 'q', 'postgres')",
        );
        let found = |rest: &str| {
            let args = fts_search_args(&env.table, "postgres", &format!("engine => 'local'{rest}"));
            fts_row_ids(&fts_search_rows(&args))
        };
        assert_eq!(found(""), ["1", "2"]);
        assert_eq!(found(", field => 'title'"), ["1"]);
        assert_eq!(found(", field => 'body'"), ["2"]);

        let args = fts_search_args(&env.table, "postgres", "engine => 'local', field => 'note'");
        let error = fts_sql_error(&format!("SELECT * FROM {FTS_SEARCH}({args})"));
        fts_assert_error(&error, "42703", &["note", "not a declared text column"]);
        fts_assert_hint(&error, "body, sku, title");
    }

    /// The result is the remote one in shape: `(id text, score real, rank integer)`, ranks from 1,
    /// and the ids are the ones the documents carry.
    #[pg_test]
    fn search_docs_local_engine_returns_the_remote_shape_and_the_ids_the_remote_holds() {
        let env = FtsEnv::tracked("fts_x_local_shape");
        env.run(
            "INSERT INTO fts_x_local_shape (id, title, body) VALUES \
             (1, 'a', 'postgres'), (2, 'b', 'postgres postgres')",
        );
        env.drain();
        env.docs.set_search_matches(&[("2", 2.0), ("1", 1.0)]);
        let types = |engine: &str| {
            let args = fts_search_args(&env.table, "postgres", &format!("engine => '{engine}'"));
            let sql = format!(
                "SELECT jsonb_build_array(pg_typeof(id)::text, pg_typeof(score)::text, \
                 pg_typeof(rank)::text) FROM {FTS_SEARCH}({args}) LIMIT 1"
            );
            Spi::get_one::<JsonB>(&sql)
                .expect("types")
                .expect("a row")
                .0
        };
        assert_eq!(types("local"), json!(["text", "real", "integer"]));
        assert_eq!(types("local"), types("remote"));

        let rows = |engine: &str| {
            let args = fts_search_args(&env.table, "postgres", &format!("engine => '{engine}'"));
            fts_search_rows(&args)
        };
        let (local, remote) = (rows("local"), rows("remote"));
        assert_eq!(fts_row_ids(&local), ["2", "1"]);
        assert_eq!(fts_row_ids(&local), fts_row_ids(&remote));
        let ranks = |rows: &[Value]| -> Vec<Option<i64>> {
            rows.iter().map(|row| row["rank"].as_i64()).collect()
        };
        assert_eq!(ranks(&local), [Some(1), Some(2)]);
        assert_eq!(ranks(&local), ranks(&remote));
        let held = env.remote_ids();
        assert_eq!(
            fts_row_ids(&local).into_iter().collect::<BTreeSet<_>>(),
            held
        );
    }

    #[pg_test]
    fn search_docs_local_engine_renders_ids_like_the_documents_it_syncs() {
        let (_backend, docs) = fts_mock();
        let cases = [
            ("smallint", "7"),
            ("integer", "42"),
            ("bigint", "9223372036854775807"),
            ("uuid", "'123E4567-E89B-12D3-A456-426614174000'"),
            ("text", "'Café Ünï-1'"),
            ("varchar(20)", "'abc-1'"),
            ("char(6)", "'ab'"),
        ];
        for (n, (key_type, literal)) in cases.iter().enumerate() {
            let table = format!("fts_x_local_key_{n}");
            fts_run(&format!(
                "CREATE TABLE {table} (id {key_type} PRIMARY KEY, body text)"
            ));
            fts_track_minimal(&table);
            fts_drain(&table);
            fts_run(&format!(
                "INSERT INTO {table} (id, body) VALUES ({literal}, 'needle')"
            ));
            fts_drain(&table);
            let args = fts_search_args(&table, "needle", "engine => 'local'");
            let local: BTreeSet<String> =
                fts_row_ids(&fts_search_rows(&args)).into_iter().collect();
            let remote = docs.remote_ids(&fts_namespace(&table));
            assert_eq!(local, remote, "{key_type} key {literal}");
            let untracked = format!("{args}, field => 'body'");
            fts_run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&table)));
            let rows = fts_search_rows(&untracked);
            assert_eq!(
                fts_row_ids(&rows).into_iter().collect::<BTreeSet<_>>(),
                remote
            );
        }
    }

    #[pg_test]
    fn search_docs_local_engine_honours_k() {
        let env = FtsEnv::tracked("fts_x_local_k");
        env.run(
            "INSERT INTO fts_x_local_k (id, title, body) VALUES (1, 'a', 'postgres'), \
             (2, 'b', 'postgres postgres'), (3, 'c', 'postgres postgres postgres'), \
             (4, 'd', 'nothing')",
        );
        let found = |k: &str| {
            let args = fts_search_args(
                &env.table,
                "postgres",
                &format!("engine => 'local', k => {k}"),
            );
            fts_row_ids(&fts_search_rows(&args))
        };
        assert_eq!(found("2"), ["3", "2"]);
        assert_eq!(found("10"), ["3", "2", "1"]);
        assert!(found("0").is_empty());
        let args = fts_search_args(&env.table, "q", "engine => 'local', k => 10001");
        let error = fts_sql_error(&format!("SELECT * FROM {FTS_SEARCH}({args})"));
        fts_assert_error(&error, "22023", &["k must be between 0 and 10000"]);
    }

    /// The query is read as web search syntax, so quotes, `or` and `-` work and a query of
    /// nothing but stop words finds nothing instead of failing.
    #[pg_test]
    fn search_docs_local_engine_reads_the_query_as_websearch_syntax() {
        let env = FtsEnv::tracked("fts_x_local_web");
        env.run(
            "INSERT INTO fts_x_local_web (id, title, body) VALUES \
             (1, 'a', 'postgres vector search'), (2, 'b', 'postgres full text'), \
             (3, 'c', 'vector only')",
        );
        let found = |query: &str| {
            let args = fts_search_args(&env.table, query, "engine => 'local'");
            fts_row_ids(&fts_search_rows(&args))
        };
        assert_eq!(found("postgres vector"), ["1"], "terms are ANDed");
        assert_eq!(found("postgres or vector"), ["1", "2", "3"]);
        assert_eq!(found("postgres -vector"), ["2"]);
        assert_eq!(found("\"vector search\""), ["1"], "a phrase");
        assert!(
            found("the").is_empty(),
            "stop words only: no match, no error"
        );
    }

    #[pg_test]
    fn search_docs_local_engine_refuses_a_missing_or_blank_query() {
        let env = FtsEnv::tracked("fts_x_local_blank");
        for (query, part) in [
            ("NULL", "nothing to search"),
            ("   ", "query must not be empty"),
        ] {
            let args = fts_search_args(&env.table, query, "engine => 'local'");
            let error = fts_sql_error(&format!("SELECT * FROM {FTS_SEARCH}({args})"));
            fts_assert_error(&error, "22023", &["pinecone.search_docs", part]);
        }
    }

    /// The engine creates no index but uses the ones the table has: one GIN index per
    /// configuration, over the expression the docs name, serves the query (this transaction's
    /// `idx_scan` counts it).
    #[pg_test]
    fn search_docs_local_engine_uses_gin_indexes_on_the_documented_expressions() {
        let env = FtsEnv::tracked("fts_x_local_gin");
        env.run(
            "INSERT INTO fts_x_local_gin (id, title, body, sku) VALUES (1, 'postgres', 'a', NULL), \
             (2, 'b', 'postgres', NULL), (3, 'c', 'd', 'Postgres'), (4, 'e', 'f', NULL)",
        );
        env.run("SET LOCAL enable_seqscan = off");
        let scans = || {
            let sql = "SELECT coalesce(max(idx_scan), 0)::bigint FROM pg_stat_xact_user_tables \
                       WHERE relname = 'fts_x_local_gin'";
            Spi::get_one::<i64>(sql).expect("scans").expect("a count")
        };
        let args = fts_search_args(&env.table, "postgres", "engine => 'local'");
        let before = scans();
        assert_eq!(fts_row_ids(&fts_search_rows(&args)), ["1", "2", "3"]);
        assert_eq!(scans(), before, "without indexes it is a sequential scan");

        env.run(
            "CREATE INDEX ON fts_x_local_gin USING gin ((to_tsvector('english', coalesce(body, '')) \
             || to_tsvector('english', coalesce(title, ''))))",
        );
        env.run(
            "CREATE INDEX ON fts_x_local_gin USING gin (to_tsvector('simple', coalesce(sku, '')))",
        );
        let before = scans();
        assert_eq!(fts_row_ids(&fts_search_rows(&args)), ["1", "2", "3"]);
        assert!(scans() > before, "the indexes serve the query");
    }

    /// `pinecone.headline` is core `ts_headline` with the declared language of the column
    /// (`english` for an undeclared one), run on text the caller passes: after the join, for
    /// any engine.
    #[pg_test]
    fn headline_highlights_with_the_declared_language_of_the_column() {
        let env = FtsEnv::tracked("fts_x_headline");
        let headline = |column: &str, document: &str, query: &str, options: &str| {
            let sql = format!(
                "SELECT pinecone.headline({}, {}, {}, {}, {})",
                fts_rel(&env.table),
                quote_literal(column),
                quote_literal(document),
                quote_literal(query),
                quote_literal(options)
            );
            Spi::get_one::<String>(&sql).expect("headline")
        };
        let text = "The dog runs fast";
        let english = Some("The <b>dog</b> <b>runs</b> fast".to_string());
        assert_eq!(headline("body", text, "running dogs", ""), english);
        assert_eq!(
            headline("note", text, "running dogs", ""),
            english,
            "undeclared: english"
        );
        assert_eq!(
            headline("sku", text, "running dogs", ""),
            Some(text.to_string()),
            "sku declares stemming => false, so nothing stems"
        );
        assert_eq!(
            headline("body", text, "dogs", "StartSel=<mark>, StopSel=</mark>"),
            Some("The <mark>dog</mark> runs fast".to_string())
        );
        let sql = format!(
            "SELECT pinecone.headline({}, 'body', NULL, 'dogs')",
            fts_rel(&env.table)
        );
        assert_eq!(Spi::get_one::<String>(&sql).expect("headline"), None);
        let error = fts_sql_error(&format!(
            "SELECT pinecone.headline({}, 'bod', 'x', 'x')",
            fts_rel(&env.table)
        ));
        fts_assert_error(&error, "42703", &["pinecone.headline", "bod"]);
    }

    /// The snippet works after the join of any engine's ids and in the four-argument form; a
    /// table that is not tracked gets English.
    #[pg_test]
    fn headline_works_after_the_join_of_any_engine() {
        let env = FtsEnv::tracked("fts_x_headline_join");
        env.run(
            "INSERT INTO fts_x_headline_join (id, title, body) VALUES \
             (1, 'a', 'The dog runs fast'), (2, 'b', 'A cat sleeps')",
        );
        env.docs.set_search_matches(&[("1", 2.0), ("2", 1.0)]);
        let query = "dogs or sleeping";
        let snippets = |engine: &str| {
            let sql = format!(
                "SELECT jsonb_agg(pinecone.headline({rel}, 'body', a.body, {q}) ORDER BY s.rank) \
                 FROM {FTS_SEARCH}({args}) s JOIN {table} a ON a.id = s.id::bigint",
                rel = fts_rel(&env.table),
                q = quote_literal(query),
                args = fts_search_args(&env.table, query, &format!("engine => '{engine}'")),
                table = env.table
            );
            Spi::get_one::<JsonB>(&sql).expect("join").expect("a row").0
        };
        let expected = json!(["The <b>dog</b> runs fast", "A cat <b>sleeps</b>"]);
        assert_eq!(snippets("remote"), expected);
        assert_eq!(snippets("local"), expected);

        fts_run("CREATE TABLE fts_x_headline_free (id bigint PRIMARY KEY, body text)");
        let sql = "SELECT pinecone.headline('fts_x_headline_free', 'body', 'The dog runs', 'dogs')";
        let found = Spi::get_one::<String>(sql).expect("headline");
        assert_eq!(found.as_deref(), Some("The <b>dog</b> runs"));
    }

    /// The classifier reaches the document lane's `last_error`: a monthly quota is not "retry in a
    /// moment", and a rate limit is not "upgrade your plan".
    #[pg_test]
    fn doc_drain_429_last_error_says_which_limit_was_hit() {
        let env = FtsEnv::tracked("fts_x_lane_429");
        env.run("INSERT INTO fts_x_lane_429 (id, title) VALUES (1, 'a')");
        let cases = [
            (
                "Request failed. You've reached your write unit limit for the current month \
                 (2000000). To continue writing data, upgrade your plan.",
                "billing period",
            ),
            (
                "Request failed. You've reached the max upsert requests per second per \
                 namespace. Pace your upsert requests or contact Pinecone Support to request a \
                 higher limit.",
                "retry in a moment",
            ),
        ];
        for (message, hint) in cases {
            env.docs.heal_all();
            env.docs.fail_always(Endpoint::Upsert, 429, message);
            assert_eq!(env.round(), "backoff");
            let rows = env.queue();
            let last_error = rows[0]["last_error"].as_str().unwrap_or_default();
            assert!(last_error.contains("429"), "last_error = {last_error:?}");
            assert!(last_error.contains(hint), "last_error = {last_error:?}");
            assert!(last_error.contains("write unit limit") || last_error.contains("Pace your"));
            assert_eq!(rows[0]["attempts"], json!(0), "429 never counts: {rows:?}");
        }
    }

    /// A role with the whole grant bundle the document verbs need: schema usage. Its own
    /// privileges on the tables it works with come on top (SELECT for a reader, ownership
    /// for an owner); nothing on the registry or the queue, for anyone.
    fn fts_create_reader(role_prefix: &str) -> String {
        let role = format!("{role_prefix}_{}", std::process::id());
        fts_run(&format!("CREATE ROLE {role}"));
        fts_run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}"));
        role
    }

    fn fts_drop_role(role: &str) {
        fts_run(&format!("DROP OWNED BY {role}"));
        fts_run(&format!("DROP ROLE {role}"));
    }

    // ---- DDL guard and lifecycle ----

    /// DROP, RENAME and TYPE of a declared column, the id column or the
    /// vector column are refused with 2BP01 and the way out; the table keeps working.
    #[pg_test]
    fn track_docs_ddl_guard_refuses_changes_to_declared_columns() {
        let env = FtsEnv::tracked("fts_t25_guard");
        let t = &env.table;
        let mut statements: Vec<(String, &str, &str)> = Vec::new();
        for column in [
            "title",
            "body",
            "sku",
            "author",
            "published_at",
            "tags",
            "embedding",
            "id",
        ] {
            statements.push((
                format!("ALTER TABLE {t} DROP COLUMN {column}"),
                "drop",
                column,
            ));
        }
        for column in ["title", "author", "embedding", "id"] {
            statements.push((
                format!("ALTER TABLE {t} RENAME COLUMN {column} TO {column}_2"),
                "alter",
                column,
            ));
        }
        statements.push((
            format!("ALTER TABLE {t} ALTER COLUMN body TYPE varchar"),
            "alter",
            "body",
        ));
        statements.push((
            format!("ALTER TABLE {t} ALTER COLUMN author TYPE varchar"),
            "alter",
            "author",
        ));
        statements.push((
            format!("ALTER TABLE {t} ALTER COLUMN embedding TYPE vector(4)"),
            "alter",
            "embedding",
        ));
        for (sql, verb, column) in statements {
            let error = fts_sql_error(&sql);
            fts_assert_error(
                &error,
                "2BP01",
                &[
                    &format!("cannot {verb} column \"{column}\""),
                    fts_bare(FTS_TRACK),
                ],
            );
            fts_assert_hint(&error, fts_bare(FTS_UNTRACK));
        }

        env.run(&format!("ALTER TABLE {t} ADD COLUMN extra int"));
        env.run(&format!("ALTER TABLE {t} RENAME COLUMN note TO memo"));
        env.run(&format!("ALTER TABLE {t} ALTER COLUMN memo TYPE varchar"));
        env.run(&format!("ALTER TABLE {t} DROP COLUMN memo"));
        env.run(&format!(
            "INSERT INTO {t} (id, title, body) VALUES (1, 'a', 'b')"
        ));
        assert_eq!(
            fts_queue_ids(t, FTS_OP_UPSERT),
            vec!["1".to_string()],
            "writes still queue"
        );
    }

    /// A tracked table cannot be dropped until it is untracked.
    #[pg_test]
    fn track_docs_ddl_guard_refuses_dropping_a_tracked_table() {
        let env = FtsEnv::tracked("fts_t25_drop");
        let error = fts_sql_error(&format!("DROP TABLE {}", env.table));
        fts_assert_error(
            &error,
            "2BP01",
            &[
                "cannot drop",
                &env.table,
                &format!("tracked by {FTS_TRACK}"),
            ],
        );
        fts_assert_hint(&error, fts_bare(FTS_UNTRACK));
        fts_assert_hint(&error, "drop_index => true");

        env.run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table)));
        env.run(&format!("DROP TABLE {}", env.table));
    }

    /// `untrack_docs` leaves the remote index alone by default and deletes it with `drop_index`.
    #[pg_test]
    fn untrack_docs_drops_the_remote_index_only_when_asked() {
        let env = FtsEnv::tracked("fts_t25_untrack");
        env.run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table)));
        assert_eq!(
            env.docs.count(Endpoint::IndexDelete),
            0,
            "calls = {:?}",
            env.docs.calls()
        );
        fts_assert_unregistered(&env.table);

        let again = FtsEnv::tracked("fts_t25_untrack_drop");
        again.run(&format!(
            "SELECT {FTS_UNTRACK}({}, drop_index => true)",
            fts_rel(&again.table)
        ));
        let deletes = again.docs.calls_to(Endpoint::IndexDelete);
        assert_eq!(deletes.len(), 1, "calls = {:?}", again.docs.calls());
        assert_eq!(deletes[0].index.as_deref(), Some(again.index.as_str()));
        fts_assert_unregistered(&again.table);
    }

    /// A table in both registries: promoted (vector lane, async) and tracked for documents.
    /// The documents mock answers 2026-07 calls, the vector mocks everything else; the vector
    /// upsert answers whatever status `vector_status` holds.
    struct FtsDualEnv {
        _backend: MockBackend,
        docs: DocsHandle,
        vector_upserts: BodySink,
        vector_status: Arc<Mutex<u16>>,
        table: String,
        vector_triggers: Vec<String>,
    }

    fn fts_dual_env(table: &str) -> FtsDualEnv {
        create_extension_vector();
        fts_run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, body text, embedding vector(2))"
        ));
        let docs = DocsHandle::new();
        let vector_upserts: BodySink = Arc::new(Mutex::new(Vec::new()));
        let vector_status = Arc::new(Mutex::new(200u16));
        let vector_index = format!("pv-public-{}", table.replace('_', "-"));
        let (docs_mock, upserts_mock) = (docs.clone(), Arc::clone(&vector_upserts));
        let (status_mock, index_mock) = (Arc::clone(&vector_status), vector_index.clone());
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            docs_mock
                .mount_for_version(&control_plane, &data_plane, EXPECTED_API_VERSION)
                .await;
            mount_promote_success(&control_plane, &data_plane, &index_mock).await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("upsert body should be JSON");
                    upserts_mock
                        .lock()
                        .expect("upserts lock poisoned")
                        .push(body);
                    let status = *status_mock.lock().expect("status lock poisoned");
                    ResponseTemplate::new(status)
                        .set_body_json(json!({"upsertedCount": 1, "message": "vector upsert"}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        fts_run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&vector_index)
        ));
        drain_until_empty(relid_of(table));
        let vector_triggers = trigger_names(table);

        let args = format!(
            "text_columns => '{{\"body\": {{}}}}'::jsonb, index_name => {}",
            quote_literal(fts_index_name(table))
        );
        fts_run(&fts_track_sql(table, &args));
        fts_drain(table);
        docs.clear_calls();
        vector_upserts
            .lock()
            .expect("upserts lock poisoned")
            .clear();
        FtsDualEnv {
            _backend: backend,
            docs,
            vector_upserts,
            vector_status,
            table: table.to_string(),
            vector_triggers,
        }
    }

    /// `untrack_docs` removes the docs triggers, queue and registry row and nothing of the
    /// vector lane's, on a table that is in both registries.
    #[pg_test]
    fn untrack_docs_removes_only_the_docs_triggers_and_registry_row() {
        let env = fts_dual_env("fts_t25_dual");
        let t = &env.table;
        let all = trigger_names(t);
        assert!(
            all.iter().any(|n| n.starts_with("pg_pinecone_docs_")),
            "docs triggers: {all:?}"
        );
        assert!(
            env.vector_triggers.iter().all(|n| all.contains(n)),
            "vector triggers kept: {all:?}"
        );
        fts_run(&format!(
            "INSERT INTO {t} (id, body, embedding) VALUES (1, 'b', '[1, 0]')"
        ));
        assert_eq!(
            (outbox_count(t), fts_queue(t).len()),
            (1, 1),
            "one queued row in each lane"
        );

        fts_run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(t)));
        assert_eq!(
            trigger_names(t),
            env.vector_triggers,
            "only the docs triggers are gone"
        );
        fts_assert_unregistered(t);
        assert!(
            fts_queue(t).is_empty(),
            "the docs lane's queued work goes with it"
        );
        assert_eq!(outbox_count(t), 1, "the vector lane's queue is untouched");
        let mode = Spi::get_one::<String>(&format!(
            "SELECT mode FROM pinecone.tables WHERE relid = {}",
            fts_rel(t)
        ));
        assert_eq!(
            mode.expect("vector registry row"),
            Some("remote".to_string())
        );
    }

    /// A parked docs lane does not stall vector sync on the same table.
    #[pg_test]
    fn docs_lane_parked_does_not_stall_vector_sync_on_the_same_table() {
        let env = fts_dual_env("fts_t25_docs_parked");
        let t = &env.table;
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        fts_run(&format!(
            "INSERT INTO {t} (id, body, embedding) VALUES (1, 'b', '[1, 0]')"
        ));
        assert_eq!(fts_round(t), "parked");

        let outcome =
            crate::outbox::drain_step(relid_of(t), crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Processed(1)),
            "outcome = {outcome:?}"
        );
        let sent = env
            .vector_upserts
            .lock()
            .expect("upserts lock poisoned")
            .clone();
        assert_eq!(sent.len(), 1, "sent = {sent:?}");
        assert!(vectors_by_id(&sent[0]).contains_key("1"));
        assert_eq!(outbox_count(t), 0, "the vector queue drained");
        assert_eq!(fts_queue(t).len(), 1, "the parked docs queue keeps its row");
    }

    /// A parked vector lane does not stall document sync on the same table.
    #[pg_test]
    fn vector_lane_parked_does_not_stall_docs_sync_on_the_same_table() {
        let env = fts_dual_env("fts_t25_vector_parked");
        let t = &env.table;
        fts_run("SET pinecone.outbox_max_attempts = 1");
        *env.vector_status.lock().expect("status lock poisoned") = 400;
        fts_run(&format!(
            "INSERT INTO {t} (id, body, embedding) VALUES (1, 'b', '[1, 0]')"
        ));
        let outcome =
            crate::outbox::drain_step(relid_of(t), crate::backend::DrainCredentials::Worker);
        assert!(
            matches!(outcome, crate::outbox::DrainOutcome::Parked(_)),
            "outcome = {outcome:?}"
        );

        fts_drain(t);
        let remote = env.docs.remote_ids(&fts_namespace(t));
        assert_eq!(
            remote,
            fts_set(&["1"]),
            "documents flow while the vector lane is parked"
        );
    }

    // ---- refusals from the error table ----

    /// A declared column that does not exist, or is not a text type, is refused by name.
    #[pg_test]
    fn track_docs_refuses_unknown_and_mistyped_text_columns() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_cols (id bigint PRIMARY KEY, body text, payload jsonb)");
        let cases: [(&str, &str, &[&str]); 2] = [
            (
                r#"{"bod": {}}"#,
                "42703",
                &["column \"bod\" does not exist in"],
            ),
            (
                r#"{"payload": {}}"#,
                "42804",
                &["text column \"payload\" has type jsonb"],
            ),
        ];
        for (declaration, sqlstate, parts) in cases {
            let args = format!("text_columns => {}::jsonb", quote_literal(declaration));
            let error = fts_sql_error(&fts_track_sql("fts_x_cols", &args));
            fts_assert_error(&error, sqlstate, parts);
            fts_assert_untouched("fts_x_cols", &docs);
        }
    }

    /// Partitioned tables and tables with inheritance children are refused,
    /// because statement triggers do not see writes to partitions or children.
    #[pg_test]
    fn track_docs_refuses_partitioned_and_inherited_tables() {
        let (_backend, docs) = fts_mock();
        fts_run(
            "CREATE TABLE fts_x_part (id bigint, body text, PRIMARY KEY (id)) PARTITION BY RANGE (id)",
        );
        fts_run("CREATE TABLE fts_x_part_1 PARTITION OF fts_x_part FOR VALUES FROM (0) TO (1000)");
        fts_run("CREATE TABLE fts_x_parent (id bigint PRIMARY KEY, body text)");
        fts_run("CREATE TABLE fts_x_child () INHERITS (fts_x_parent)");
        for (table, parts) in [
            ("fts_x_part", &["partitioned table"][..]),
            ("fts_x_parent", &["fts_x_parent"][..]),
        ] {
            let args = "text_columns => '{\"body\": {}}'::jsonb";
            let error = fts_sql_error(&fts_track_sql(table, args));
            fts_assert_error(&error, "0A000", parts);
            fts_assert_untouched(table, &docs);
        }
    }

    /// Only the owner may track, checked before any HTTP call; a table that is
    /// already tracked cannot be tracked again.
    #[pg_test]
    fn track_docs_requires_ownership_and_refuses_double_tracking() {
        let env = FtsEnv::tracked("fts_x_owner");
        let error = fts_sql_error(&fts_track_standard_sql(&env.table, &env.index));
        fts_assert_error(
            &error,
            "42710",
            &["is already tracked", fts_bare(FTS_UNTRACK)],
        );

        fts_run("CREATE TABLE fts_x_not_mine (id bigint PRIMARY KEY, body text)");
        let role = fts_create_reader("fts_nonowner");
        env.run(&format!("SET ROLE {role}"));
        let calls_before = env.docs.calls().len();
        let error = fts_sql_error(&fts_track_sql(
            "fts_x_not_mine",
            "text_columns => '{\"body\": {}}'::jsonb",
        ));
        let untrack_error =
            fts_sql_error(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table)));
        env.run("RESET ROLE");
        fts_drop_role(&role);
        fts_assert_error(&error, "42501", &["must be owner of"]);
        fts_assert_error(&untrack_error, "42501", &["must be owner of"]);
        fts_assert_registered(&env.table);
        assert_eq!(
            env.docs.calls().len(),
            calls_before,
            "no HTTP before the ownership check"
        );
        fts_assert_unregistered("fts_x_not_mine");
    }

    /// Without a primary key the id can be a NOT NULL UNIQUE column named by
    /// `id_column` (the escape hatch the "no primary key" HINT offers); changing its value is a
    /// delete of the old id and an upsert of the new one; a column that may be NULL or repeat is refused.
    #[pg_test]
    fn track_docs_accepts_a_not_null_unique_id_column_instead_of_a_primary_key() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_idcol (code text NOT NULL UNIQUE, body text)");
        let args = format!(
            "text_columns => '{{\"body\": {{}}}}'::jsonb, id_column => 'code', index_name => {}",
            quote_literal(fts_index_name("fts_x_idcol"))
        );
        fts_run(&fts_track_sql("fts_x_idcol", &args));
        fts_drain("fts_x_idcol");
        fts_run("INSERT INTO fts_x_idcol VALUES ('abc-1', 'first')");
        fts_drain("fts_x_idcol");
        let namespace = fts_namespace("fts_x_idcol");
        assert_eq!(docs.remote_ids(&namespace), fts_set(&["abc-1"]));
        fts_run("UPDATE fts_x_idcol SET code = 'abc-2' WHERE code = 'abc-1'");
        fts_drain("fts_x_idcol");
        assert_eq!(docs.remote_ids(&namespace), fts_set(&["abc-2"]));

        fts_run("CREATE TABLE fts_x_idcol_bad (code text, body text)");
        let calls_before = docs.calls().len();
        let args = "text_columns => '{\"body\": {}}'::jsonb, id_column => 'code'";
        let error = fts_sql_error(&fts_track_sql("fts_x_idcol_bad", args));
        assert!(error.message.contains("code"), "{error:?}");
        fts_assert_unregistered("fts_x_idcol_bad");
        assert_eq!(
            docs.calls().len(),
            calls_before,
            "no HTTP for a refused declaration"
        );
    }

    /// The dense field is part of the attach comparison too; a different
    /// dimension would only fail later, as a 400 per document.
    #[pg_test]
    fn track_docs_refuses_to_attach_an_index_with_a_different_dense_dimension() {
        let env = FtsEnv::untracked("fts_x_dense");
        let mut fields = fts_golden_schema("cosine")["fields"].clone();
        fields["embedding"]["dimension"] = json!(4);
        env.docs.preload_index(&env.index, fields);

        let error = fts_sql_error(&fts_track_standard_sql(&env.table, &env.index));
        fts_assert_error(
            &error,
            "42P16",
            &["exists with a different schema", "embedding"],
        );
        fts_assert_unregistered(&env.table);
        assert_eq!(
            fts_created_indexes(&env.docs),
            0,
            "calls = {:?}",
            env.docs.calls()
        );
    }

    /// Extra (design: "only declared columns leave Postgres"): an undeclared column is never part
    /// of a document; only `pg_pinecone_*` fields (reserved for the extension) may be added to the declared ones.
    #[pg_test]
    fn doc_drain_sends_only_declared_columns() {
        let env = FtsEnv::tracked("fts_x_declared");
        env.run(
            "INSERT INTO fts_x_declared (id, title, body, sku, author, published_at, tags, note, \
             embedding) VALUES (1, 't', 'b', 's', 'a', '2026-01-01 00:00:00+00', ARRAY['x'], \
             'private note', '[1, 2, 3]')",
        );
        env.drain();
        let doc = env.remote_doc("1");
        let keys = doc.as_object().expect("a document").keys();
        let keys: BTreeSet<String> = keys
            .filter(|k| !k.starts_with("pg_pinecone_"))
            .cloned()
            .collect();
        let declared = [
            "_id",
            "title",
            "body",
            "sku",
            "author",
            "published_at",
            "tags",
            "embedding",
        ];
        assert_eq!(keys, fts_set(&declared), "doc = {doc}");
    }

    /// Extra (design: namespace derived from `schema.table`): a table outside `public` gets the
    /// namespace of its own schema and name.
    #[pg_test]
    fn track_docs_derives_the_namespace_from_schema_and_table() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE SCHEMA fts_x_schema");
        fts_run("CREATE TABLE fts_x_schema.items (id bigint PRIMARY KEY, body text)");
        let args = "text_columns => '{\"body\": {}}'::jsonb, index_name => 'fts-x-schema-items'";
        fts_run(&fts_track_sql("fts_x_schema.items", args));
        fts_drain("fts_x_schema.items");
        fts_run("INSERT INTO fts_x_schema.items VALUES (1, 'x')");
        fts_drain("fts_x_schema.items");
        assert_eq!(docs.remote_ids("fts_x_schema.items"), fts_set(&["1"]));
    }

    /// A statement of 2,500 rows (about 2.6 MB of documents) is
    /// delivered in requests Pinecone accepts: at most 1,000 documents and 2 MB each.
    #[pg_test]
    fn doc_drain_packs_requests_within_pinecone_limits() {
        let env = FtsEnv::tracked("fts_x_packing");
        env.run(
            "INSERT INTO fts_x_packing (id, title, body) \
             SELECT i, 'title ' || i, repeat('x', 1000) FROM generate_series(1, 2500) i",
        );
        env.drain();

        let upserts = env.docs.calls_to(Endpoint::Upsert);
        assert!(
            upserts.len() >= 3,
            "1,000 documents per request at most: {} requests",
            upserts.len()
        );
        for call in &upserts {
            let body = call.body.as_ref().expect("body");
            let documents = body["documents"].as_array().map_or(0, Vec::len);
            assert!(
                call.status == 202,
                "Pinecone rejected a request of {documents} documents"
            );
            assert!(documents <= 1000, "{documents} documents in one request");
            assert!(
                body.to_string().len() <= 2 * 1024 * 1024,
                "a request over 2 MB"
            );
        }
        assert_eq!(env.remote_ids().len(), 2500);
    }

    // ---- status() and flush_docs ----

    fn fts_flush(table: &str, timeout_ms: i32) -> (bool, Vec<String>) {
        let sql = format!("SELECT {FTS_FLUSH}({}, {timeout_ms})", fts_rel(table));
        let (flushed, warnings) = capture_warnings(|| Spi::get_one::<bool>(&sql));
        (
            flushed
                .expect("flush_docs")
                .expect("flush_docs is NOT NULL"),
            warnings,
        )
    }

    /// `flush_docs` on a drained lane is true at once.
    #[pg_test]
    fn flush_docs_returns_true_once_the_lane_is_drained() {
        let env = FtsEnv::seeded("fts_t27_flush_ok", 2);
        let (flushed, warnings) = fts_flush(&env.table, 60_000);
        assert!(flushed, "warnings = {warnings:?}");
    }

    /// With a backlog and no launcher nothing will ever drain it, so `flush_docs` says so at
    /// once instead of waiting out the timeout, and points at `status()`.
    #[pg_test]
    fn flush_docs_with_a_backlog_and_no_launcher_returns_false_immediately() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::tracked("fts_t27_flush_idle");
        env.run("INSERT INTO fts_t27_flush_idle (id, title, body) VALUES (1, 'a', 'b')");
        let started = std::time::Instant::now();
        let (flushed, warnings) = fts_flush(&env.table, 60_000);
        assert!(!flushed);
        assert!(
            started.elapsed() < std::time::Duration::from_secs(5),
            "must not wait out 60 s"
        );
        assert!(
            warnings.iter().any(|w| w.contains("pinecone.status()")),
            "warnings = {warnings:?}"
        );
        assert_eq!(env.queue().len(), 1, "flush never drains anything itself");
    }

    /// With a live launcher but a lane that cannot deliver, `flush_docs` waits
    /// out its timeout, returns false and the WARNING points at `status()`.
    #[pg_test]
    fn flush_docs_times_out_false_and_the_warning_points_at_status() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::tracked("fts_t27_flush_timeout");
        env.docs
            .fail_always(Endpoint::Upsert, 503, "service unavailable");
        env.run("INSERT INTO fts_t27_flush_timeout (id, title, body) VALUES (1, 'a', 'b')");
        assert_eq!(env.round(), "backoff");

        let _launcher = LauncherLockTestGuard::acquire();
        let started = std::time::Instant::now();
        let (flushed, warnings) = fts_flush(&env.table, 500);
        assert!(!flushed);
        assert!(
            started.elapsed() >= std::time::Duration::from_millis(400),
            "it waited for the timeout"
        );
        let timed_out = warnings
            .iter()
            .any(|w| w.contains("timed out") && w.contains("pinecone.status()"));
        assert!(timed_out, "warnings = {warnings:?}");
    }

    /// A parked lane will not drain by itself, so `flush_docs` returns false at once.
    #[pg_test]
    fn flush_docs_parked_returns_false_immediately() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::tracked("fts_t27_flush_parked");
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        env.run("INSERT INTO fts_t27_flush_parked (id, title, body) VALUES (1, 'a', 'b')");
        assert_eq!(env.round(), "parked");

        let _launcher = LauncherLockTestGuard::acquire();
        let started = std::time::Instant::now();
        let (flushed, warnings) = fts_flush(&env.table, 60_000);
        assert!(!flushed);
        assert!(
            started.elapsed() < std::time::Duration::from_secs(5),
            "a parked lane fast-fails"
        );
        assert!(
            warnings.iter().any(|w| w.contains("parked")),
            "warnings = {warnings:?}"
        );
    }

    // ---- additions of the sync PR: list declarations, launcher warning, drain-time guarantees ----

    /// `text_columns` as a list of names means defaults for each column; a list that mixes in
    /// anything but names is refused with 22023 before any HTTP call.
    #[pg_test]
    fn track_docs_accepts_a_list_of_text_column_names() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_list (id bigint PRIMARY KEY, title text, body text)");
        let args = r#"text_columns => '["title", "body"]'::jsonb, index_name => 'fts-x-list'"#;
        fts_run(&fts_track_sql("fts_x_list", args));
        let schema = fts_created_index_body(&docs, "fts-x-list")["schema"].clone();
        let (stem, stop) = (FTS_DEFAULT_STEMMING, FTS_DEFAULT_STOP_WORDS);
        let default_field = fts_field(FTS_DEFAULT_LANGUAGE, stem, stop);
        assert_eq!(
            schema,
            json!({"fields": {"title": default_field, "body": default_field}})
        );

        fts_run("CREATE TABLE fts_x_list_bad (id bigint PRIMARY KEY, title text, body text)");
        let calls = docs.calls().len();
        for declaration in [r#"["title", {"body": {}}]"#, r#"["title", 5]"#] {
            let args = format!("text_columns => {}::jsonb", quote_literal(declaration));
            let error = fts_sql_error(&fts_track_sql("fts_x_list_bad", &args));
            fts_assert_error(&error, "22023", &["text_columns", "column names"]);
        }
        fts_assert_unregistered("fts_x_list_bad");
        assert_eq!(
            docs.calls().len(),
            calls,
            "no HTTP for a refused declaration"
        );
    }

    /// Writes are queued even where no worker runs, so `track_docs` says so (a WARNING, not an
    /// error) when no launcher is registered in the cluster.
    #[pg_test]
    fn track_docs_warns_when_no_worker_launcher_is_running() {
        let _serialize = TestSerializeGuard::acquire();
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_warn (id bigint PRIMARY KEY, body text)");
        let (_, warnings) = capture_warnings(|| fts_track_minimal("fts_x_warn"));
        let warned = warnings.iter().any(|w| {
            w.contains("nothing will be synced until the worker runs")
                && w.contains("pinecone.status()")
        });
        assert!(warned, "warnings = {warnings:?}");
        fts_assert_registered("fts_x_warn");
    }

    #[pg_test]
    fn track_docs_does_not_warn_while_a_launcher_is_running() {
        let _serialize = TestSerializeGuard::acquire();
        let _launcher = LauncherLockTestGuard::acquire();
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_nowarn (id bigint PRIMARY KEY, body text)");
        let (_, warnings) = capture_warnings(|| fts_track_minimal("fts_x_nowarn"));
        let warned = warnings
            .iter()
            .any(|w| w.contains("nothing will be synced"));
        assert!(!warned, "warnings = {warnings:?}");
    }

    /// The drain reads the table under a fresh snapshot, not the draining statement's. Here
    /// an earlier part of the very statement that drains rewrites the row after the statement
    /// began; the newest text is what Pinecone gets.
    #[pg_test]
    fn doc_drain_reads_the_newest_row_not_the_statements_snapshot() {
        let env = FtsEnv::seeded("fts_x_fresh", 1);
        env.run("UPDATE fts_x_fresh SET body = 'enqueued' WHERE id = 1");
        env.run(
            "CREATE FUNCTION fts_x_fresh_bump() RETURNS int LANGUAGE plpgsql AS $$ \
             BEGIN UPDATE fts_x_fresh SET body = 'newest' WHERE id = 1; RETURN 1; END $$",
        );
        env.run(&format!(
            "SELECT {FTS_ROUND}({}) FROM (SELECT fts_x_fresh_bump()) s",
            fts_rel(&env.table)
        ));
        assert_eq!(env.remote_doc("1")["body"], json!("newest"));
    }

    /// A failure half way through a big claimed batch keeps what was delivered: only rows whose
    /// ids all went through are deleted, so the retry does not resend them (a rate-limited lane
    /// that never got past the first requests would otherwise never drain).
    #[pg_test]
    fn doc_drain_keeps_the_progress_of_a_batch_that_fails_half_way() {
        let env = FtsEnv::tracked("fts_x_partial");
        env.run(
            "INSERT INTO fts_x_partial (id, title, body) \
             SELECT i, 't', 'b' FROM generate_series(1, 2500) i",
        );
        assert_eq!(env.queue().len(), 3, "1,000 ids per queue row");
        env.docs
            .fail_ids(Endpoint::Upsert, &["1001"], 503, "unavailable");
        assert_eq!(env.round(), "backoff");
        let left: Vec<usize> = (env.queue().iter())
            .map(|r| r["payload"].as_array().map_or(0, Vec::len))
            .collect();
        assert_eq!(
            left,
            [1000, 500],
            "the delivered row is gone, the rest waits"
        );
        assert!(
            env.queue()[0]["last_error"]
                .as_str()
                .is_some_and(|e| e.contains("503")),
            "the failure is recorded on the oldest row left: {:?}",
            env.queue()
        );

        env.docs.heal_all();
        env.drain();
        assert_eq!(env.remote_ids().len(), 2500);
        assert_eq!(
            fts_delivered_ids(&env.docs).len(),
            2500,
            "nothing was sent twice"
        );
    }

    /// A row that reached the table past the trigger (here: with the trigger off) and is
    /// refused by the `error` policy at drain time is dead-lettered with the reason, without a
    /// doomed request, and the lane carries on.
    #[pg_test]
    fn doc_drain_dead_letters_a_row_the_error_policy_refuses() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_policy (id bigint PRIMARY KEY, body text)");
        let args = "text_columns => '{\"body\": {\"on_oversize\": \"error\"}}'::jsonb";
        fts_run(&fts_track_sql("fts_x_policy", args));
        fts_drain("fts_x_policy");
        fts_run("SET session_replication_role = replica");
        fts_run("INSERT INTO fts_x_policy VALUES (1, repeat('abcdefghi ', 15000)), (2, 'fine')");
        fts_run("RESET session_replication_role");
        fts_run(&format!(
            "INSERT INTO {FTS_QUEUE} (relid, op, payload) VALUES ({}, '{FTS_OP_UPSERT}', '[\"1\", \"2\"]')",
            fts_rel("fts_x_policy")
        ));
        docs.clear_calls();

        fts_drain("fts_x_policy");
        assert_eq!(
            docs.remote_ids(&fts_namespace("fts_x_policy")),
            fts_set(&["2"])
        );
        let failed = fts_failed_docs("fts_x_policy");
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        assert_eq!(failed[0]["id"], json!("1"));
        let error = failed[0]["error"].as_str().unwrap_or_default();
        assert!(
            error.contains("column \"body\"") && error.contains("100 KB"),
            "{error}"
        );
        assert_eq!(
            docs.count(Endpoint::Upsert),
            1,
            "one request, for the row that fits"
        );
    }

    /// A document that fails again is still one dead letter, with the newest message.
    #[pg_test]
    fn doc_drain_keeps_one_dead_letter_per_document() {
        let env = FtsEnv::tracked("fts_x_letters");
        env.docs
            .fail_ids(Endpoint::Upsert, &["1"], 400, "first reason");
        env.run("INSERT INTO fts_x_letters (id, title, body) VALUES (1, 'a', 'b')");
        env.drain();
        env.docs.heal(Endpoint::Upsert);
        env.docs
            .fail_ids(Endpoint::Upsert, &["1"], 400, "second reason");
        env.run("UPDATE fts_x_letters SET body = 'c' WHERE id = 1");
        env.drain();
        let failed = fts_failed_docs(&env.table);
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        let error = failed[0]["error"].as_str().unwrap_or_default();
        assert!(error.contains("second reason"), "error = {error:?}");
    }

    /// A column change of the vector column is a change like any other; the same vector again is not.
    #[pg_test]
    fn doc_outbox_update_of_the_vector_column_enqueues_an_upsert_only_when_it_changes() {
        let env = FtsEnv::seeded("fts_x_vec", 1);
        env.run("UPDATE fts_x_vec SET embedding = '[1, 2, 3]' WHERE id = 1");
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["1".to_string()]
        );
        env.drain();
        assert_eq!(env.remote_doc("1")["embedding"], json!([1, 2, 3]));
        env.run("UPDATE fts_x_vec SET embedding = '[1, 2, 3]' WHERE id = 1");
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
    }

    /// The DDL guard's event triggers are members of the extension, so `DROP EXTENSION` drops
    /// them together with the registry they read instead of tripping over it.
    #[pg_test]
    fn docs_ddl_guard_event_triggers_belong_to_the_extension() {
        let sql = "SELECT coalesce(jsonb_agg(t.evtname ORDER BY t.evtname), '[]'::jsonb) \
                   FROM pg_event_trigger t JOIN pg_depend d ON d.classid = 'pg_event_trigger'::regclass \
                    AND d.objid = t.oid AND d.deptype = 'e' \
                   JOIN pg_extension e ON e.oid = d.refobjid AND e.extname = 'pg_pinecone' \
                   WHERE t.evtname LIKE 'pg_pinecone_docs_%'";
        let members = Spi::get_one::<JsonB>(sql)
            .expect("event triggers")
            .expect("aggregate")
            .0;
        assert_eq!(
            members,
            json!([
                "pg_pinecone_docs_on_ddl_end",
                "pg_pinecone_docs_on_sql_drop"
            ])
        );
    }

    /// `drop_index` is refused, before anything is torn down, while another tracked table still
    /// uses the index.
    #[pg_test]
    fn untrack_docs_refuses_to_drop_an_index_another_table_uses() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_shared_a (id bigint PRIMARY KEY, body text)");
        fts_run("CREATE TABLE fts_x_shared_b (id bigint PRIMARY KEY, body text)");
        let args = "text_columns => '{\"body\": {}}'::jsonb, index_name => 'fts-x-shared'";
        fts_run(&fts_track_sql("fts_x_shared_a", args));
        fts_run(&fts_track_sql(
            "fts_x_shared_b",
            &format!("{args}, adopt_existing => true"),
        ));
        let error = fts_sql_error(&format!(
            "SELECT {FTS_UNTRACK}({}, drop_index => true)",
            fts_rel("fts_x_shared_a")
        ));
        fts_assert_error(&error, "55006", &["fts-x-shared", "another tracked table"]);
        fts_assert_registered("fts_x_shared_a");
        assert_eq!(docs.count(Endpoint::IndexDelete), 0);
    }

    /// Untracking ends the protection: the declared columns can be changed afterwards.
    #[pg_test]
    fn untrack_docs_ends_the_ddl_guard() {
        let env = FtsEnv::tracked("fts_x_unguard");
        env.run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table)));
        env.run("ALTER TABLE fts_x_unguard RENAME COLUMN body TO text_body");
        env.run("ALTER TABLE fts_x_unguard DROP COLUMN title");
    }

    /// The queue reveals ids and error texts of the table's rows, so reading it takes SELECT on
    /// the table; requeueing dead letters is the owner's (no role holds a grant
    /// on the queue to change that).
    #[pg_test]
    fn failed_docs_and_flush_require_select_and_retry_requires_ownership() {
        let env = FtsEnv::tracked("fts_x_select");
        let role = fts_create_reader("fts_noselect");
        let rel = fts_rel(&env.table);
        env.run(&format!("SET ROLE {role}"));
        let readers: Vec<FtsError> = [
            format!("SELECT * FROM pinecone.failed_docs({rel})"),
            format!("SELECT {FTS_FLUSH}({rel}, 100)"),
        ]
        .iter()
        .map(|sql| fts_sql_error(sql))
        .collect();
        let retry = fts_sql_error(&format!("SELECT {FTS_RETRY_FAILED}({rel})"));
        env.run("RESET ROLE");
        for error in &readers {
            fts_assert_error(
                error,
                "42501",
                &["permission denied for table fts_x_select"],
            );
        }
        fts_assert_error(&retry, "42501", &["must be owner of", "fts_x_select"]);

        env.run(&format!("GRANT SELECT ON {} TO {role}", env.table));
        env.run(&format!("SET ROLE {role}"));
        let failed = fts_failed_docs(&env.table);
        env.run("RESET ROLE");
        fts_drop_role(&role);
        assert!(failed.is_empty(), "failed_docs = {failed:?}");
    }

    /// Queue rows of a table that is no longer tracked are purged with a WARNING, not retried
    /// forever (the worker must not trip over them).
    #[pg_test]
    fn doc_drain_purges_the_queue_of_a_table_that_is_no_longer_tracked() {
        let env = FtsEnv::seeded("fts_x_purge", 1);
        env.run("INSERT INTO fts_x_purge (id, title, body) VALUES (2, 'a', 'b')");
        env.run(&format!(
            "DELETE FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(&env.table)
        ));
        let (outcome, warnings) =
            capture_warnings(|| crate::docs_drain::drain_doc_step(relid_of(&env.table)));
        let purged =
            matches!(&outcome, crate::docs_outbox::DocDrainOutcome::Processed(n) if *n > 0);
        assert!(purged, "outcome = {outcome:?}");
        assert!(
            warnings.iter().any(|w| w.contains("purged")),
            "{warnings:?}"
        );
        assert!(env.queue().is_empty());
    }

    /// Without a stored key the worker waits (no attempt counted) instead of raising.
    #[pg_test]
    fn doc_drain_backs_off_without_a_stored_api_key() {
        let env = FtsEnv::tracked("fts_x_nokey");
        env.run("INSERT INTO fts_x_nokey (id, title, body) VALUES (1, 'a', 'b')");
        env.run("DELETE FROM pinecone.secret");
        assert_eq!(env.round(), "backoff");
        let rows = env.queue();
        assert_eq!(rows[0]["attempts"], json!(0));
        let error = rows[0]["last_error"].as_str().unwrap_or_default();
        assert!(error.contains("no stored API key"), "rows = {rows:?}");
        assert!(env.docs.calls().is_empty());
    }

    /// A declared column that is gone (the guard was switched off) is a lane error that parks
    /// the queue with the reason, never a Postgres ERROR that would abort the worker's round.
    #[pg_test]
    fn doc_drain_parks_instead_of_crashing_when_a_declared_column_is_gone() {
        let env = FtsEnv::tracked("fts_x_gone");
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.run("INSERT INTO fts_x_gone (id, title, body) VALUES (1, 'a', 'b')");
        env.run("ALTER EVENT TRIGGER pg_pinecone_docs_on_sql_drop DISABLE");
        env.run("ALTER EVENT TRIGGER pg_pinecone_docs_on_ddl_end DISABLE");
        env.run("ALTER TABLE fts_x_gone DROP COLUMN body");
        assert_eq!(env.round(), "parked");
        assert!(fts_lane_parked(&env.table));
        let sql = format!(
            "SELECT parked_reason FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(&env.table)
        );
        let reason = Spi::get_one::<String>(&sql)
            .expect("reason")
            .unwrap_or_default();
        assert!(reason.contains("body"), "reason = {reason:?}");
        assert!(env.docs.calls().is_empty(), "nothing was sent");
    }

    // ---- backfill, the repair verbs and the circuit breaker ----

    const FTS_BACKFILL: &str = "pinecone.backfill_docs";
    const FTS_UNPARK: &str = "pinecone.unpark_docs";
    const FTS_GUC_ROUND_MS: &str = "pinecone.backfill_round_ms";
    const FTS_OP_BACKFILL: &str = "doc_backfill";

    /// `(backfill_done, backfill_total, state)` as the registry records them (`status()` shows
    /// the same numbers from a later change on).
    fn fts_backfill_progress(table: &str) -> (i64, Option<i64>, String) {
        let sql = format!(
            "SELECT jsonb_build_object('done', backfill_done, 'total', backfill_total, \
             'state', state) FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(table)
        );
        let row = Spi::get_one::<JsonB>(&sql).expect("registry progress");
        let row = row.unwrap_or_else(|| panic!("{table} is not registered")).0;
        (
            row["done"].as_i64().expect("backfill_done"),
            row["total"].as_i64(),
            row["state"].as_str().unwrap_or_default().to_string(),
        )
    }

    /// The `doc_backfill` rows of the queue of `table` (there is never more than one).
    fn fts_backfill_jobs(table: &str) -> Vec<Value> {
        let rows = fts_queue(table).into_iter();
        rows.filter(|r| r["op"] == json!(FTS_OP_BACKFILL)).collect()
    }

    /// Inserts rows `1..=n` (`title 'title i'`, `body 'body i'`).
    fn fts_insert_series(table: &str, n: i64) {
        fts_run(&format!(
            "INSERT INTO {table} (id, title, body) \
             SELECT i, 'title ' || i, 'body ' || i FROM generate_series(1, {n}) i"
        ));
    }

    /// How often each document id appears across all upsert requests, failed ones included.
    fn fts_sent_counts(docs: &DocsHandle) -> BTreeMap<String, usize> {
        let documents = docs.upsert_bodies().into_iter();
        let documents = documents
            .filter_map(|b| b["documents"].as_array().cloned())
            .flatten();
        let mut counts = BTreeMap::new();
        for id in documents.filter_map(|d| d["_id"].as_str().map(str::to_string)) {
            *counts.entry(id).or_insert(0) += 1;
        }
        counts
    }

    /// The ids Pinecone accepted, as a set. The client re-sends a request after a transport
    /// error, and on Linux a signal can interrupt the read of a slow response and cause one
    /// (seen on CI with 1.2 s of latency), so what the tests check about deliveries are sets
    /// and the registry, never request counts.
    fn fts_delivered_set(docs: &DocsHandle) -> BTreeSet<String> {
        fts_delivered_ids(docs).into_iter().collect()
    }

    /// The document ids `from..=to`.
    fn fts_id_range(from: i64, to: i64) -> BTreeSet<String> {
        (from..=to).map(|id| id.to_string()).collect()
    }

    /// Sets this session's round budget, which `_docs_round` runs chunks for. The mock's latency
    /// is a floor on how long a chunk takes, so a latency above the budget ends every round
    /// after one chunk, and a latency times the chunk count below it lets a round run them all,
    /// however slow or fast the machine is.
    fn fts_set_round_budget(ms: i32) {
        fts_run(&format!("SET {FTS_GUC_ROUND_MS} = {ms}"));
    }

    fn fts_latency(docs: &DocsHandle, ms: u64) {
        docs.set_latency(Endpoint::Upsert, std::time::Duration::from_millis(ms));
    }

    /// A round ends when its budget is spent, not at the end of a 10,000-row table, and a
    /// round with budget left runs chunks back to back. With 300 ms per request and a 1.5 s
    /// budget at most five chunks fit (a request cannot answer faster than the mock's latency);
    /// under a 60 s budget the rest of the table goes out in one round. Both bounds hold on any
    /// machine: a lower bound on how many chunks fit a short budget would depend on its speed.
    /// Changed from the archived test: the budgets are set instead of leaning on the default
    /// against a slow mock, and the checks read the registry instead of request counts and
    /// elapsed time.
    #[pg_test]
    fn doc_backfill_round_budget_sends_several_requests_per_round_but_not_all() {
        let env = FtsEnv::untracked("fts_t18_budget");
        fts_insert_series(&env.table, 10_000);
        fts_set_round_budget(1_500);
        fts_latency(&env.docs, 300);
        fts_track_standard(&env.table, &env.index);
        env.docs.clear_calls();

        assert_eq!(env.round(), "processed");
        let (done, total, state) = fts_backfill_progress(&env.table);
        assert_eq!(total, Some(10_000), "total = the row count at enqueue");
        assert!(
            (1_000..=5_000).contains(&done),
            "at least one chunk, at most 1,500 / 300 of them: {done}"
        );
        assert_eq!(state, "backfilling");
        assert_eq!(fts_delivered_set(&env.docs).len() as i64, done);

        fts_set_round_budget(60_000);
        assert_eq!(env.round(), "processed");
        assert_eq!(
            fts_backfill_progress(&env.table),
            (10_000, Some(10_000), "ready".to_string()),
            "the rest of the table in one round, and done = total"
        );
        assert_eq!(env.remote_ids().len(), 10_000);
        assert_eq!(env.round(), "idle");
    }

    /// A chunk that fails mid-backfill leaves the persisted cursor behind the last
    /// delivered chunk; later rounds resume there. Nothing is skipped and nothing delivered is
    /// sent again (the failed chunk was never accepted, so it goes out once, later). Changed from
    /// the archived test: the client now retries a 5xx itself, so one failed call (`fail_nth`)
    /// is absorbed and the chunk's requests keep failing instead (`fail_ids`); what was
    /// delivered is read as sets, because the client may re-send a request.
    #[pg_test]
    fn doc_backfill_resumes_after_a_failed_chunk_without_skipping() {
        let env = FtsEnv::untracked("fts_t18_resume");
        fts_insert_series(&env.table, 3_500);
        fts_track_standard(&env.table, &env.index);
        env.docs
            .fail_ids(Endpoint::Upsert, &["2500"], 503, "service unavailable");

        let mut outcomes = Vec::new();
        while outcomes.last().map(String::as_str) != Some("backoff") && outcomes.len() < 10 {
            outcomes.push(env.round());
        }
        assert_eq!(
            outcomes.last().map(String::as_str),
            Some("backoff"),
            "outcomes = {outcomes:?}"
        );
        assert_eq!(
            fts_backfill_progress(&env.table),
            (2_000, Some(3_500), "backfilling".to_string()),
            "progress survives the failure"
        );
        let jobs = fts_backfill_jobs(&env.table);
        assert_eq!(jobs.len(), 1, "the job stays queued: {jobs:?}");
        assert_eq!(jobs[0]["payload"], json!({"after_id": "2000"}));
        assert_eq!(jobs[0]["attempts"], json!(0), "a 5xx is no attempt");
        let error = jobs[0]["last_error"].as_str().unwrap_or_default();
        assert!(error.contains("503"), "last_error = {error:?}");
        assert_eq!(
            fts_delivered_set(&env.docs),
            fts_id_range(1, 2_000),
            "the failed chunk was never accepted"
        );

        env.docs.heal_all();
        env.docs.clear_calls();
        env.drain();
        assert_eq!(
            fts_delivered_set(&env.docs),
            fts_id_range(2_001, 3_500),
            "resumed after the cursor: nothing skipped, nothing delivered sent again"
        );
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
        let (done, total, state) = fts_backfill_progress(&env.table);
        assert_eq!((done, total, state.as_str()), (3_500, Some(3_500), "ready"));
        assert!(fts_backfill_jobs(&env.table).is_empty());
    }

    /// A live UPDATE of a row the backfill has not reached yet is delivered before the
    /// backfill continues (live rows first) and is never overwritten by older text. The first
    /// round (300 ms budget, 100 ms per request) runs three chunks at most.
    #[pg_test]
    fn doc_backfill_live_update_in_an_unreached_range_is_never_overwritten() {
        let env = FtsEnv::untracked("fts_t18_live");
        fts_insert_series(&env.table, 10_000);
        fts_set_round_budget(300);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        assert_eq!(env.round(), "processed");
        assert!(
            !env.remote_ids().contains("10000"),
            "setup: the last row is not reached yet"
        );

        env.run("UPDATE fts_t18_live SET body = 'NEW text' WHERE id = 10000");
        env.docs.clear_calls();
        env.drain();

        let uppers = env.docs.calls_to(Endpoint::Upsert);
        let first = uppers
            .first()
            .and_then(|c| c.body.clone())
            .expect("an upsert after the update");
        let first_ids: Vec<&str> = first["documents"]
            .as_array()
            .expect("documents")
            .iter()
            .filter_map(|d| d["_id"].as_str())
            .collect();
        assert!(
            first_ids.contains(&"10000"),
            "live rows go first: the first request after the update carries the live row, \
             got {} ids starting {:?}",
            first_ids.len(),
            first_ids.first()
        );
        assert_eq!(env.remote_doc("10000")["body"], json!("NEW text"));
        let texts: Vec<String> = uppers
            .iter()
            .filter_map(|c| c.body.clone())
            .filter_map(|b| b["documents"].as_array().cloned())
            .flatten()
            .filter(|d| d["_id"] == json!("10000"))
            .filter_map(|d| d["body"].as_str().map(str::to_string))
            .collect();
        assert!(
            texts.iter().all(|t| t == "NEW text"),
            "an older text was sent after the update: {texts:?}"
        );
    }

    /// Rows deleted while the backfill is running are not sent afterwards, and rows it
    /// had already sent are removed: the remote id set ends equal to the table's. The first
    /// round (300 ms budget, 100 ms per request) runs three chunks at most.
    #[pg_test]
    fn doc_backfill_does_not_send_rows_deleted_mid_backfill() {
        let env = FtsEnv::untracked("fts_t19_deleted");
        fts_insert_series(&env.table, 10_000);
        fts_set_round_budget(300);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        assert_eq!(env.round(), "processed");
        assert!(
            env.remote_ids().contains("1"),
            "setup: the first row was sent"
        );
        assert!(
            !env.remote_ids().contains("10000"),
            "setup: the last row was not"
        );

        env.run("DELETE FROM fts_t19_deleted WHERE id IN (1, 10000)");
        env.drain();
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table), "remote = heap");
        assert!(
            !fts_sent_counts(&env.docs).contains_key("10000"),
            "a deleted row is never sent"
        );
    }

    /// The round budget GUC exists with its documented default.
    #[pg_test]
    fn guc_backfill_round_ms_defaults_to_one_second() {
        let value = Spi::get_one::<String>(&format!("SHOW {FTS_GUC_ROUND_MS}"));
        assert_eq!(
            value.expect("SHOW the round budget GUC"),
            Some("1000".to_string())
        );
    }

    /// The budget is a user setting (a session can tune what `_docs_round` runs for; the worker
    /// reads the cluster's value) bounded to 50 ms .. 60 s.
    #[pg_test]
    fn guc_backfill_round_ms_is_a_user_setting_from_50_ms_to_60_s() {
        let sql = format!(
            "SELECT jsonb_build_array(context, min_val, max_val) FROM pg_settings \
             WHERE name = {}",
            quote_literal(FTS_GUC_ROUND_MS)
        );
        let row = Spi::get_one::<JsonB>(&sql).expect("pg_settings");
        let row = row.expect("the GUC is registered").0;
        assert_eq!(row, json!(["user", "50", "60000"]));

        for value in [49, 60_001] {
            let error = fts_sql_error(&format!("SET {FTS_GUC_ROUND_MS} = {value}"));
            fts_assert_error(&error, "22023", &["outside the valid range"]);
        }
        fts_set_round_budget(50);
        fts_set_round_budget(60_000);
    }

    /// `backfill_docs` rebuilds a lost remote index from the table and
    /// refuses to queue behind a parked lane.
    #[pg_test]
    fn backfill_docs_rebuilds_a_lost_index_and_refuses_a_parked_lane() {
        let env = FtsEnv::seeded("fts_x_repair", 3);
        env.docs.wipe_namespace(&env.namespace);
        fts_run(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(&env.table)));
        env.drain();
        assert_eq!(
            env.remote_ids(),
            fts_set(&["1", "2", "3"]),
            "rebuilt from the table"
        );

        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        env.run("INSERT INTO fts_x_repair (id, title, body) VALUES (4, 'd', 'four')");
        assert_eq!(env.round(), "parked");
        let error = fts_sql_error(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(&env.table)));
        fts_assert_error(&error, "55000", &["parked"]);
    }

    /// A request slower than the round budget ends the round after its chunk: exactly one chunk
    /// per round, the cursor and the progress advancing each time. The budget is 50 ms and the
    /// mock answers no faster than 150 ms, so this holds on any machine; the checks read what
    /// was delivered and the registry, not request counts or elapsed time.
    #[pg_test]
    fn doc_backfill_a_request_slower_than_the_budget_leaves_one_chunk_per_round() {
        let env = FtsEnv::untracked("fts_x_slow");
        fts_insert_series(&env.table, 2_500);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 150);
        fts_track_standard(&env.table, &env.index);
        env.docs.clear_calls();

        for (round, last_id) in [(1, 1_000), (2, 2_000), (3, 2_500)] {
            assert_eq!(env.round(), "processed", "round {round}");
            assert_eq!(
                fts_delivered_set(&env.docs),
                fts_id_range(1, last_id),
                "round {round}: one more chunk"
            );
            let (done, _, state) = fts_backfill_progress(&env.table);
            assert_eq!(
                (done, state.as_str()),
                (last_id, "backfilling"),
                "round {round}"
            );
        }
        assert_eq!(env.round(), "processed", "the empty page ends the job");
        assert_eq!(fts_backfill_progress(&env.table).2, "ready");
        assert_eq!(env.round(), "idle");
        assert_eq!(env.remote_ids().len(), 2_500);
    }

    /// Under a long budget (60 s) one round runs every chunk, including the empty one that
    /// completes the job.
    #[pg_test]
    fn doc_backfill_runs_every_chunk_in_one_round_under_a_long_budget() {
        let env = FtsEnv::untracked("fts_x_fast");
        fts_insert_series(&env.table, 3_500);
        fts_set_round_budget(60_000);
        fts_track_standard(&env.table, &env.index);
        env.docs.clear_calls();

        assert_eq!(env.round(), "processed");
        assert_eq!(
            fts_backfill_progress(&env.table),
            (3_500, Some(3_500), "ready".to_string())
        );
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
        assert_eq!(env.round(), "idle");
    }

    /// The cursor is committed per chunk, so a restart loses at most the chunk whose cursor was
    /// not committed: here the cursor is put back one chunk, as a crash between the request and
    /// its commit would leave it. That chunk is sent once more, the chunks before it are not,
    /// and nothing is skipped. A 50 ms budget against 100 ms requests runs one chunk per round
    /// (on any machine), so each step is observed in the job's cursor and in what was
    /// delivered, as sets.
    #[pg_test]
    fn doc_backfill_survives_a_restart_between_the_request_and_the_cursor_commit() {
        let env = FtsEnv::untracked("fts_x_restart");
        fts_insert_series(&env.table, 2_100);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        let cursor = |env: &FtsEnv| fts_backfill_jobs(&env.table)[0]["payload"].clone();

        assert_eq!(env.round(), "processed");
        assert_eq!(cursor(&env), json!({"after_id": "1000"}));
        assert_eq!(env.round(), "processed");
        assert_eq!(cursor(&env), json!({"after_id": "2000"}));
        assert_eq!(fts_backfill_progress(&env.table).0, 2_000);

        env.run(&format!(
            "UPDATE {FTS_QUEUE} SET payload = '{{\"after_id\": \"1000\"}}' WHERE op = '{FTS_OP_BACKFILL}'"
        ));
        env.run(&format!(
            "UPDATE {FTS_REGISTRY} SET backfill_done = 1000 WHERE relid = {}",
            fts_rel(&env.table)
        ));
        env.docs.clear_calls();

        assert_eq!(env.round(), "processed");
        assert_eq!(
            cursor(&env),
            json!({"after_id": "2000"}),
            "the lost chunk again"
        );
        assert_eq!(fts_delivered_set(&env.docs), fts_id_range(1_001, 2_000));
        assert_eq!(env.round(), "processed");
        assert_eq!(cursor(&env), json!({"after_id": "2100"}));
        assert_eq!(
            fts_delivered_set(&env.docs),
            fts_id_range(1_001, 2_100),
            "the first chunk is not sent again and nothing is skipped"
        );
        assert_eq!(env.round(), "processed", "the empty page ends the job");
        assert_eq!(
            fts_backfill_progress(&env.table),
            (2_100, Some(2_100), "ready".to_string()),
            "the cursor and the count travel together, so the re-sent chunk is counted once"
        );
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
    }

    /// `track_docs` records the exact number of rows at enqueue, sends nothing itself and
    /// queues one job; the job's completion makes the table ready with `done = total`.
    #[pg_test]
    fn track_docs_records_the_row_count_and_queues_one_backfill_job() {
        let env = FtsEnv::untracked("fts_x_total");
        fts_insert_series(&env.table, 7);
        fts_track_standard(&env.table, &env.index);
        assert_eq!(
            fts_backfill_progress(&env.table),
            (0, Some(7), "backfilling".to_string())
        );
        let jobs = fts_backfill_jobs(&env.table);
        assert_eq!(jobs.len(), 1, "queue = {:?}", env.queue());
        assert_eq!(jobs[0]["payload"], json!({"after_id": null}));
        assert_eq!(
            env.docs.count(Endpoint::Upsert),
            0,
            "tracking sends nothing"
        );

        env.drain();
        assert_eq!(
            fts_backfill_progress(&env.table),
            (7, Some(7), "ready".to_string())
        );
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
        assert!(env.queue().is_empty());
    }

    /// A TRUNCATE while the backfill is half way wipes the namespace (live ops go first) and the
    /// next chunk finds nothing left: the job ends instead of resurrecting rows.
    #[pg_test]
    fn doc_backfill_ends_cleanly_when_the_table_is_truncated_mid_backfill() {
        let env = FtsEnv::untracked("fts_x_trunc");
        fts_insert_series(&env.table, 1_500);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        assert_eq!(env.round(), "processed");
        assert_eq!(env.remote_ids().len(), 1_000, "setup: one chunk is out");

        env.run("TRUNCATE fts_x_trunc");
        env.drain();
        assert!(env.remote_ids().is_empty(), "remote = the empty table");
        assert_eq!(fts_backfill_progress(&env.table).2, "ready");
        assert!(env.queue().is_empty());
    }

    /// `backfill_docs(.., clear => true)` queues the namespace wipe first and the job second:
    /// the wipe request precedes the first upsert, a document the table no longer has is gone
    /// afterwards, and the progress restarts from the table's current size.
    #[pg_test]
    fn backfill_docs_clear_wipes_the_namespace_before_the_first_upsert() {
        let env = FtsEnv::seeded("fts_x_clear", 3);
        env.run("INSERT INTO fts_x_clear (id, title, body) VALUES (4, 'stale', 'stale')");
        env.drain();
        env.run("SET session_replication_role = replica");
        env.run("DELETE FROM fts_x_clear WHERE id = 4");
        env.run("RESET session_replication_role");
        assert_eq!(
            env.remote_ids(),
            fts_set(&["1", "2", "3", "4"]),
            "setup: the index holds a document the table lost"
        );
        assert!(env.queue().is_empty(), "queue = {:?}", env.queue());

        env.run(&format!(
            "SELECT {FTS_BACKFILL}({}, clear => true)",
            fts_rel(&env.table)
        ));
        assert_eq!(
            fts_queue_ops(&env.table),
            [FTS_OP_TRUNCATE, FTS_OP_BACKFILL]
        );
        assert_eq!(
            fts_backfill_progress(&env.table),
            (0, Some(3), "backfilling".to_string())
        );
        env.docs.clear_calls();
        env.drain();

        let writes: Vec<_> = (env.docs.calls().into_iter())
            .filter(|c| matches!(c.endpoint, Endpoint::Upsert | Endpoint::Delete))
            .collect();
        let first_upsert = writes.iter().position(|c| c.endpoint == Endpoint::Upsert);
        let first_upsert = first_upsert.unwrap_or_else(|| panic!("no rows sent: {writes:?}"));
        assert!(first_upsert >= 1, "the wipe goes first: {writes:?}");
        assert!(
            writes[..first_upsert]
                .iter()
                .all(|c| c.body == Some(json!({"delete_all": true}))),
            "only the wipe before the first row: {writes:?}"
        );
        assert!(
            writes[first_upsert..]
                .iter()
                .all(|c| c.endpoint == Endpoint::Upsert),
            "only upserts after the wipe: {writes:?}"
        );
        assert_eq!(env.remote_ids(), fts_set(&["1", "2", "3"]));
        assert_eq!(
            fts_backfill_progress(&env.table),
            (3, Some(3), "ready".to_string())
        );
    }

    /// A second `backfill_docs` while a job is half done replaces it: one job, cursor back at
    /// the start, total re-counted, and the table is walked again from the first row.
    #[pg_test]
    fn backfill_docs_replaces_the_queued_job_and_starts_over() {
        let env = FtsEnv::untracked("fts_x_rejob");
        fts_insert_series(&env.table, 2_500);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        assert_eq!(env.round(), "processed");
        assert_eq!(fts_backfill_progress(&env.table).0, 1_000);

        env.run("SET session_replication_role = replica");
        env.run("DELETE FROM fts_x_rejob WHERE id > 2400");
        env.run("RESET session_replication_role");
        env.run(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(&env.table)));
        let jobs = fts_backfill_jobs(&env.table);
        assert_eq!(jobs.len(), 1, "queue = {:?}", env.queue());
        assert_eq!(jobs[0]["payload"], json!({"after_id": null}));
        assert_eq!(
            fts_backfill_progress(&env.table),
            (0, Some(2_400), "backfilling".to_string())
        );

        fts_latency(&env.docs, 0);
        env.docs.clear_calls();
        env.drain();
        assert_eq!(
            fts_delivered_set(&env.docs),
            fts_heap_ids(&env.table),
            "the whole table again"
        );
        assert_eq!(
            fts_backfill_progress(&env.table),
            (2_400, Some(2_400), "ready".to_string())
        );
    }

    /// A parked lane is refused with the cause and the way out; `unpark_docs` clears the park
    /// flag and the failed attempt, after which the lane drains and `backfill_docs` works again.
    #[pg_test]
    fn backfill_docs_refuses_a_parked_lane_until_unpark_docs_reopens_it() {
        let env = FtsEnv::seeded("fts_x_unpark", 2);
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        env.run("INSERT INTO fts_x_unpark (id, title, body) VALUES (3, 'c', 'three')");
        assert_eq!(env.round(), "parked");
        assert!(fts_lane_parked(&env.table));

        let rel = fts_rel(&env.table);
        let error = fts_sql_error(&format!("SELECT {FTS_BACKFILL}({rel})"));
        fts_assert_error(
            &error,
            "55000",
            &["fts_x_unpark", "parked", "authentication"],
        );
        fts_assert_hint(&error, "unpark_docs");
        assert!(
            fts_backfill_jobs(&env.table).is_empty(),
            "nothing was queued"
        );
        assert_eq!(env.round(), "parked", "a parked lane is skipped");

        env.docs.heal_all();
        env.run(&format!("SELECT {FTS_UNPARK}({rel})"));
        assert!(!fts_lane_parked(&env.table));
        let rows = env.queue();
        assert_eq!(rows[0]["attempts"], json!(0), "rows = {rows:?}");
        assert!(rows[0]["last_error"].is_null(), "rows = {rows:?}");
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1", "2", "3"]));

        env.run(&format!("SELECT {FTS_BACKFILL}({rel})"));
        assert_eq!(fts_backfill_jobs(&env.table).len(), 1);
    }

    /// Both verbs need ownership of the table and a tracked table, checked before anything is
    /// queued or unparked.
    #[pg_test]
    fn backfill_docs_and_unpark_docs_need_ownership_and_a_tracked_table() {
        let env = FtsEnv::tracked("fts_x_owner");
        let role = fts_create_reader("fts_notowner");
        env.run(&format!("GRANT SELECT ON {} TO {role}", env.table));
        let rel = fts_rel(&env.table);
        env.run(&format!("SET ROLE {role}"));
        let errors: Vec<FtsError> = [FTS_BACKFILL, FTS_UNPARK]
            .iter()
            .map(|function| fts_sql_error(&format!("SELECT {function}({rel})")))
            .collect();
        env.run("RESET ROLE");
        fts_drop_role(&role);
        for error in &errors {
            fts_assert_error(error, "42501", &["must be owner of"]);
        }
        assert!(
            fts_backfill_jobs(&env.table).is_empty(),
            "nothing was queued"
        );

        fts_run("CREATE TABLE fts_x_owner_plain (id bigint PRIMARY KEY, body text)");
        for function in [FTS_BACKFILL, FTS_UNPARK] {
            let sql = format!("SELECT {function}({})", fts_rel("fts_x_owner_plain"));
            let error = fts_sql_error(&sql);
            fts_assert_error(&error, "42704", &["not tracked by pinecone.track_docs"]);
            fts_assert_hint(&error, "track_docs");
        }
    }

    /// An index pg_pinecone did not create is not pg_pinecone's to delete: `drop_index => true` is
    /// refused for an attached one unless `force => true`; an index it created needs no force.
    #[pg_test]
    fn untrack_docs_refuses_to_drop_an_attached_index_unless_forced() {
        // The extension before the stored key, like every other test: the opposite order can
        // deadlock with them (each waits for the other's uncommitted row).
        create_extension_vector();
        let (_backend, docs) = fts_mock();
        let table = "fts_x_attached";
        fts_create_attach_table(table);
        let index = fts_index_name(table);
        docs.preload_index(&index, fts_attach_fields("en"));
        let adopt = fts_attach_args(&index, ", adopt_existing => true");
        fts_run(&fts_track_sql(table, &adopt));
        let rel = fts_rel(table);

        let error = fts_sql_error(&format!("SELECT {FTS_UNTRACK}({rel}, drop_index => true)"));
        fts_assert_error(&error, "55000", &["attached", &index]);
        fts_assert_hint(&error, "attached, not created by pg_pinecone");
        fts_assert_registered(table);
        assert_eq!(docs.count(Endpoint::IndexDelete), 0, "nothing was deleted");

        fts_run(&format!(
            "SELECT {FTS_UNTRACK}({rel}, drop_index => true, force => true)"
        ));
        fts_assert_unregistered(table);
        assert_eq!(docs.count(Endpoint::IndexDelete), 1, "force deletes it");

        fts_create_table("fts_x_created");
        fts_track_standard("fts_x_created", &fts_index_name("fts_x_created"));
        fts_run(&format!(
            "SELECT {FTS_UNTRACK}({}, drop_index => true)",
            fts_rel("fts_x_created")
        ));
        assert_eq!(docs.count(Endpoint::IndexDelete), 2, "no force for its own");
    }

    /// The worker's backfill step serves the tables with a queued job and an open lane: a
    /// queued live row does not hold the job back (a table written to all the time would starve
    /// it), a queued wipe does, a parked lane and dead letters do not count.
    #[pg_test]
    fn doc_backfill_candidates_are_tables_with_a_job_an_open_lane_and_no_queued_wipe() {
        let env = FtsEnv::untracked("fts_x_cand");
        fts_insert_series(&env.table, 5);
        fts_track_standard(&env.table, &env.index);
        let relid = relid_of(&env.table);
        let candidate = || crate::docs_backfill::candidates().contains(&relid);
        assert!(candidate(), "a job and nothing else queued");

        env.run("INSERT INTO fts_x_cand (id, title, body) VALUES (6, 'a', 'b')");
        assert!(candidate(), "a live row does not hold the job back");
        env.run("TRUNCATE fts_x_cand");
        assert!(!candidate(), "a queued wipe goes first");
        crate::docs_drain::drain_doc_step(relid);
        assert!(candidate(), "delivered, the job is next");
        assert!(!fts_backfill_jobs(&env.table).is_empty());

        crate::docs_outbox::enqueue_failed(relid, "1", "refused");
        assert!(candidate(), "a dead letter is not work");
        crate::docs_registry::set_parked(relid, "test");
        assert!(!candidate(), "a parked lane is skipped");
        crate::docs_registry::unpark(relid);
        env.drain();
        assert!(!candidate(), "no job left");
    }

    /// The worker idles when there is nothing to do and not before: a queued job keeps its
    /// lane active, also after a round ran out of budget, and a parked lane drops out.
    #[pg_test]
    fn doc_queue_a_pending_backfill_keeps_the_lane_active_until_it_is_done() {
        let env = FtsEnv::untracked("fts_x_active");
        fts_insert_series(&env.table, 1_500);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 100);
        fts_track_standard(&env.table, &env.index);
        let relid = relid_of(&env.table);
        let active = || crate::docs_outbox::active_relids().contains(&relid);
        assert!(active(), "a queued job is work");

        assert_eq!(env.round(), "processed");
        assert_eq!(fts_backfill_progress(&env.table).2, "backfilling");
        assert!(active(), "out of budget, the job stays queued and active");

        fts_latency(&env.docs, 0);
        env.drain();
        assert!(!active(), "done: nothing is left to do");

        env.run(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(&env.table)));
        assert!(active());
        crate::docs_registry::set_parked(relid, "test");
        assert!(!active(), "a parked lane is not active");
    }

    const FTS_SYSTEMIC_MESSAGE: &str = "field 'body' does not match the index schema";

    /// Systemic 400 (live path): every document is refused because the schema or the declaration
    /// drifted outside pg_pinecone. Bisecting must stop after 100 refusals in a row, keep the rows
    /// queued, and record ONE lane error that counts as an attempt: no dead letter per document.
    #[pg_test]
    fn doc_drain_a_systemic_400_writes_one_lane_error_instead_of_dead_letters() {
        let env = FtsEnv::tracked("fts_x_systemic");
        env.docs
            .fail_always(Endpoint::Upsert, 400, FTS_SYSTEMIC_MESSAGE);
        env.run(
            "INSERT INTO fts_x_systemic (id, title, body) \
             SELECT i, 't', 'b' FROM generate_series(1, 300) i",
        );

        assert_eq!(env.round(), "backoff");
        assert!(fts_failed_docs(&env.table).is_empty(), "no dead letters");
        let rows = env.queue();
        assert_eq!(rows.len(), 1, "the batch stays queued: {rows:?}");
        assert_eq!(rows[0]["attempts"], json!(1), "a lane failure counts");
        let error = rows[0]["last_error"].as_str().unwrap_or_default();
        assert!(
            error.contains(FTS_SYSTEMIC_MESSAGE),
            "last_error = {error:?}"
        );
        let requests = env.docs.count(Endpoint::Upsert);
        assert!(
            requests < 300,
            "bisecting stopped early: {requests} requests for 300 documents"
        );
        assert!(!fts_lane_parked(&env.table), "one attempt of ten");
    }

    /// The lane error counts like any permanent failure: the lane parks after
    /// `outbox_max_attempts`, with Pinecone's message as the reason, and once the cause is fixed
    /// and the lane unparked every document is still there to be delivered.
    #[pg_test]
    fn doc_drain_a_systemic_400_parks_the_lane_and_loses_nothing() {
        let env = FtsEnv::tracked("fts_x_systemic_park");
        fts_run("SET pinecone.outbox_max_attempts = 2");
        env.docs
            .fail_always(Endpoint::Upsert, 400, FTS_SYSTEMIC_MESSAGE);
        env.run(
            "INSERT INTO fts_x_systemic_park (id, title, body) \
             SELECT i, 't', 'b' FROM generate_series(1, 150) i",
        );
        assert_eq!(env.round(), "backoff");
        assert_eq!(env.round(), "parked");
        let sql = format!(
            "SELECT parked_reason FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(&env.table)
        );
        let reason = Spi::get_one::<String>(&sql).expect("reason");
        let reason = reason.unwrap_or_default();
        assert!(reason.contains(FTS_SYSTEMIC_MESSAGE), "reason = {reason:?}");
        assert!(fts_failed_docs(&env.table).is_empty());

        env.docs.heal_all();
        env.run(&format!("SELECT {FTS_UNPARK}({})", fts_rel(&env.table)));
        env.drain();
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
    }

    /// Systemic 400 (backfill): the same breaker on a chunk. The cursor stays where it was and
    /// the error is on the job; once healed, the table is delivered completely.
    #[pg_test]
    fn doc_backfill_a_systemic_400_writes_one_lane_error_on_the_job() {
        let env = FtsEnv::untracked("fts_x_systemic_bf");
        fts_insert_series(&env.table, 300);
        env.docs
            .fail_always(Endpoint::Upsert, 400, FTS_SYSTEMIC_MESSAGE);
        fts_track_standard(&env.table, &env.index);

        assert_eq!(env.round(), "backoff");
        assert!(fts_failed_docs(&env.table).is_empty(), "no dead letters");
        let jobs = fts_backfill_jobs(&env.table);
        assert_eq!(jobs.len(), 1, "queue = {:?}", env.queue());
        assert_eq!(jobs[0]["attempts"], json!(1));
        assert_eq!(jobs[0]["payload"], json!({"after_id": null}), "no progress");
        let error = jobs[0]["last_error"].as_str().unwrap_or_default();
        assert!(
            error.contains(FTS_SYSTEMIC_MESSAGE),
            "last_error = {error:?}"
        );
        assert!(env.docs.count(Endpoint::Upsert) < 300);
        assert_eq!(
            fts_backfill_progress(&env.table),
            (0, Some(300), "backfilling".to_string())
        );

        env.docs.heal_all();
        env.drain();
        assert_eq!(env.remote_ids(), fts_heap_ids(&env.table));
        assert_eq!(fts_backfill_progress(&env.table).2, "ready");
        let jobs_left = fts_backfill_jobs(&env.table);
        assert!(jobs_left.is_empty(), "queue = {:?}", env.queue());
    }

    /// Refusals that are not systemic (ten documents of a thousand, never 100 in a row) stay
    /// per-document: dead letters, everything else delivered, no lane error, never parked.
    #[pg_test]
    fn doc_drain_scattered_rejections_stay_dead_letters_and_never_trip_the_breaker() {
        let env = FtsEnv::tracked("fts_x_scatter");
        let poison: Vec<String> = (1..=10).map(|n| (n * 100).to_string()).collect();
        let poison: Vec<&str> = poison.iter().map(String::as_str).collect();
        env.docs
            .fail_ids(Endpoint::Upsert, &poison, 400, "bad document");
        env.run(
            "INSERT INTO fts_x_scatter (id, title, body) \
             SELECT i, 't', 'b' FROM generate_series(1, 1000) i",
        );

        env.drain();
        assert_eq!(env.remote_ids().len(), 990);
        assert_eq!(fts_failed_docs(&env.table).len(), 10);
        let rows = env.queue();
        assert!(
            rows.iter().all(|r| r["op"] == json!(FTS_OP_FAILED)),
            "only dead letters are left: {rows:?}"
        );
        assert!(!fts_lane_parked(&env.table));
    }

    /// Dead-letter hygiene: a later successful delivery of the id removes its dead letter, be it
    /// an upsert of the corrected row or the delete of a row that was removed instead.
    #[pg_test]
    fn doc_drain_a_later_successful_delivery_removes_the_dead_letter() {
        let env = FtsEnv::tracked("fts_x_hygiene");
        env.docs
            .fail_ids(Endpoint::Upsert, &["1", "2"], 400, "bad document");
        env.run(
            "INSERT INTO fts_x_hygiene (id, title, body) VALUES (1, 'a', 'one'), (2, 'b', 'two'), \
             (3, 'c', 'three')",
        );
        env.drain();
        assert_eq!(fts_failed_docs(&env.table).len(), 2);
        assert_eq!(env.remote_ids(), fts_set(&["3"]));

        env.docs.heal(Endpoint::Upsert);
        env.run("UPDATE fts_x_hygiene SET body = 'fixed' WHERE id = 1");
        env.drain();
        let failed = fts_failed_docs(&env.table);
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        assert_eq!(failed[0]["id"], json!("2"));

        env.run("DELETE FROM fts_x_hygiene WHERE id = 2");
        env.drain();
        assert!(fts_failed_docs(&env.table).is_empty());
        assert_eq!(env.remote_ids(), fts_set(&["1", "3"]));
    }

    /// The backfill is a delivery like any other: re-running it after the cause is fixed
    /// delivers the refused document and its dead letter goes away.
    #[pg_test]
    fn doc_backfill_removes_the_dead_letter_of_a_document_it_delivers() {
        let env = FtsEnv::untracked("fts_x_hygiene_bf");
        fts_insert_series(&env.table, 3);
        env.docs
            .fail_ids(Endpoint::Upsert, &["2"], 400, "bad document");
        fts_track_standard(&env.table, &env.index);
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1", "3"]));
        let failed = fts_failed_docs(&env.table);
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        assert_eq!(
            fts_backfill_progress(&env.table),
            (3, Some(3), "ready".to_string()),
            "a refused row is passed, not stuck on"
        );

        env.docs.heal_all();
        env.run(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(&env.table)));
        env.drain();
        assert!(fts_failed_docs(&env.table).is_empty());
        assert_eq!(env.remote_ids(), fts_set(&["1", "2", "3"]));
    }

    /// The backfill and the live path share the row-to-document code: the same row, every kind
    /// of declared column, yields the same document whichever way it reached Pinecone.
    #[pg_test]
    fn doc_backfill_sends_the_same_document_as_the_live_path() {
        let env = FtsEnv::untracked("fts_x_same_bf");
        let values = "(1, 'A title', 'a body of text', 'SKU-1', 'ann', '2026-01-02 03:04:05+00', \
                      ARRAY['x', 'y'], 'private note', '[0.5, 1, 2]')";
        let insert = |table: &str| {
            format!(
                "INSERT INTO {table} (id, title, body, sku, author, published_at, tags, note, \
                 embedding) VALUES {values}"
            )
        };
        env.run(&insert("fts_x_same_bf"));
        fts_track_standard("fts_x_same_bf", &env.index);
        env.drain();

        fts_create_table("fts_x_same_live");
        fts_track_standard("fts_x_same_live", &fts_index_name("fts_x_same_live"));
        fts_drain("fts_x_same_live");
        env.run(&insert("fts_x_same_live"));
        fts_drain("fts_x_same_live");

        let backfilled = env.remote_doc("1");
        let live = env.docs.remote_doc(&fts_namespace("fts_x_same_live"), "1");
        assert_eq!(Some(&backfilled), live.as_ref(), "the same document");
        assert_eq!(backfilled["author"], json!("ann"));
        assert_eq!(backfilled["tags"], json!(["x", "y"]));
        assert_eq!(backfilled["embedding"], json!([0.5, 1, 2]));
        assert!(
            backfilled.get("note").is_none(),
            "undeclared columns stay home"
        );
    }

    /// The cursor compares in the id column's own type and order: text ids (where "10" sorts
    /// before "2"), uuids, blank-padded `char(n)` and `smallint` are walked chunk by chunk
    /// without skipping a row.
    #[pg_test]
    fn doc_backfill_walks_text_uuid_char_and_smallint_ids_in_their_own_order() {
        let (_backend, docs) = fts_mock();
        let tables = [
            ("fts_x_ids_text", "text", "i::text"),
            ("fts_x_ids_uuid", "uuid", "md5(i::text)::uuid"),
            ("fts_x_ids_char", "char(8)", "'k' || i"),
            ("fts_x_ids_small", "smallint", "i"),
        ];
        for (table, id_type, id) in tables {
            fts_run(&format!(
                "CREATE TABLE {table} (id {id_type} PRIMARY KEY, body text)"
            ));
            fts_run(&format!(
                "INSERT INTO {table} SELECT {id}, 'b' || i FROM generate_series(1, 2500) i"
            ));
            fts_run(&fts_track_sql(table, "text_columns => '[\"body\"]'::jsonb"));
            fts_drain(table);
            let remote = docs.remote_ids(&fts_namespace(table));
            assert_eq!(remote, fts_heap_ids(table), "{table}");
            assert_eq!(remote.len(), 2_500, "{table}");
            assert_eq!(
                fts_backfill_progress(table),
                (2_500, Some(2_500), "ready".to_string()),
                "{table}"
            );
        }
    }

    /// A row the `error` policy refuses is a dead letter without a request; the cursor passes
    /// it and the rest of the page is sent.
    #[pg_test]
    fn doc_backfill_dead_letters_rows_the_error_policy_refuses_and_sends_the_rest() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_x_bf_policy (id bigint PRIMARY KEY, body text)");
        fts_run("INSERT INTO fts_x_bf_policy VALUES (1, repeat('abcdefghi ', 15000)), (2, 'fine')");
        let args = "text_columns => '{\"body\": {\"on_oversize\": \"error\"}}'::jsonb";
        fts_run(&fts_track_sql("fts_x_bf_policy", args));
        docs.clear_calls();

        fts_drain("fts_x_bf_policy");
        let remote = docs.remote_ids(&fts_namespace("fts_x_bf_policy"));
        assert_eq!(remote, fts_set(&["2"]));
        let failed = fts_failed_docs("fts_x_bf_policy");
        assert_eq!(failed.len(), 1, "failed_docs = {failed:?}");
        assert_eq!(failed[0]["id"], json!("1"));
        let error = failed[0]["error"].as_str().unwrap_or_default();
        assert!(error.contains("column \"body\""), "{error}");
        assert!(
            !fts_sent_counts(&docs).contains_key("1"),
            "the refused row never went out: {:?}",
            fts_sent_counts(&docs)
        );
        assert_eq!(
            fts_backfill_progress("fts_x_bf_policy"),
            (2, Some(2), "ready".to_string())
        );
    }

    /// Without a stored key the backfill waits (no attempt counted) instead of raising.
    #[pg_test]
    fn doc_backfill_backs_off_without_a_stored_api_key() {
        let env = FtsEnv::untracked("fts_x_bf_nokey");
        fts_insert_series(&env.table, 3);
        fts_track_standard(&env.table, &env.index);
        env.run("DELETE FROM pinecone.secret");
        assert_eq!(env.round(), "backoff");
        let jobs = fts_backfill_jobs(&env.table);
        assert_eq!(jobs[0]["attempts"], json!(0), "jobs = {jobs:?}");
        let error = jobs[0]["last_error"].as_str().unwrap_or_default();
        assert!(error.contains("no stored API key"), "jobs = {jobs:?}");
        assert!(env.docs.calls_to(Endpoint::Upsert).is_empty());
    }

    /// A declared column that is gone (the guard was switched off) is a lane error of the job
    /// that parks the queue with the reason, never a Postgres ERROR in the worker's transaction.
    #[pg_test]
    fn doc_backfill_parks_instead_of_crashing_when_a_declared_column_is_gone() {
        let env = FtsEnv::untracked("fts_x_bf_gone");
        fts_insert_series(&env.table, 3);
        fts_track_standard(&env.table, &env.index);
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.run("ALTER EVENT TRIGGER pg_pinecone_docs_on_sql_drop DISABLE");
        env.run("ALTER EVENT TRIGGER pg_pinecone_docs_on_ddl_end DISABLE");
        env.run("ALTER TABLE fts_x_bf_gone DROP COLUMN body");
        assert_eq!(env.round(), "parked");
        assert!(fts_lane_parked(&env.table));
        let sql = format!(
            "SELECT parked_reason FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(&env.table)
        );
        let reason = Spi::get_one::<String>(&sql).expect("reason");
        let reason = reason.unwrap_or_default();
        assert!(reason.contains("body"), "reason = {reason:?}");
        assert!(
            env.docs.calls_to(Endpoint::Upsert).is_empty(),
            "nothing was sent"
        );
    }

    // ---- PR8 status ----

    /// The document columns of `pinecone.status()` for `table`, as a JSON object.
    fn fts_status(table: &str) -> Value {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) FROM (\
               SELECT docs_backlog, docs_oldest_enqueued, docs_last_delivered_at, \
                      docs_backfill_done, docs_backfill_total, docs_failed, docs_queue_state \
               FROM pinecone.status() WHERE table_name = {}) s",
            quote_literal(fts_namespace(table))
        );
        let rows = Spi::get_one::<JsonB>(&sql).expect("status columns");
        let rows = rows.expect("aggregate is NOT NULL").0;
        rows.as_array()
            .and_then(|rows| rows.first().cloned())
            .unwrap_or_else(|| panic!("pinecone.status() has no row for {table}"))
    }

    /// The document columns of `status()` report delivery: backlog and its age, the last
    /// delivery, backfill progress, dead letters and the queue state. Copied from the archive;
    /// the finished backfill is asserted as 5 of 5 (the registry sets total = done), and the
    /// launcher guard is taken at the start because `NO WORKER` and `active` read the cluster's
    /// launcher lock.
    #[pg_test]
    fn status_docs_columns_report_delivery_progress() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::untracked("fts_t27_status");
        fts_insert_series(&env.table, 5);
        fts_track_standard(&env.table, &env.index);

        let status = fts_status(&env.table);
        assert!(
            status["docs_backlog"].as_i64().is_some_and(|n| n > 0),
            "pending backfill is backlog: {status}"
        );
        assert!(
            !status["docs_oldest_enqueued"].is_null(),
            "status = {status}"
        );
        assert!(
            status["docs_last_delivered_at"].is_null(),
            "nothing delivered yet: {status}"
        );
        assert_eq!(
            status["docs_backfill_total"].as_i64(),
            Some(5),
            "status = {status}"
        );
        assert_eq!(
            status["docs_backfill_done"].as_i64(),
            Some(0),
            "status = {status}"
        );
        assert_eq!(status["docs_failed"].as_i64(), Some(0), "status = {status}");
        assert_eq!(
            status["docs_queue_state"],
            json!("NO WORKER"),
            "backlog and no launcher"
        );

        env.drain();
        let status = fts_status(&env.table);
        assert_eq!(
            status["docs_backlog"].as_i64(),
            Some(0),
            "status = {status}"
        );
        assert!(
            status["docs_oldest_enqueued"].is_null(),
            "status = {status}"
        );
        assert!(
            !status["docs_last_delivered_at"].is_null(),
            "something was delivered: {status}"
        );
        assert_eq!(status["docs_backfill_done"].as_i64(), Some(5));
        assert_eq!(status["docs_backfill_total"].as_i64(), Some(5));
        assert_eq!(status["docs_queue_state"], json!("idle"));

        env.run("INSERT INTO fts_t27_status (id, title, body) VALUES (6, 'f', 'six')");
        let _launcher = LauncherLockTestGuard::acquire();
        assert_eq!(
            fts_status(&env.table)["docs_queue_state"],
            json!("active"),
            "a live launcher will drain it"
        );
    }

    /// The whole `pinecone.status()` row of `table` as a JSON object.
    fn fts_status_row(table: &str) -> Value {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) FROM pinecone.status() s \
             WHERE table_name = {}",
            quote_literal(fts_namespace(table))
        );
        let rows = Spi::get_one::<JsonB>(&sql).expect("status row");
        let rows = rows.expect("aggregate is NOT NULL").0;
        let rows = rows.as_array().cloned().unwrap_or_default();
        assert_eq!(rows.len(), 1, "one status row for {table}: {rows:?}");
        rows[0].clone()
    }

    /// Whether `column` is in `row` and SQL NULL (a missing column must not pass as NULL).
    fn fts_null(row: &Value, column: &str) -> bool {
        row.get(column) == Some(&Value::Null)
    }

    /// A document Pinecone refuses is a dead letter. `docs_failed` counts it, it is not
    /// backlog, the lane stays `idle` (never `parked`), and `retry_failed_docs` moves it from
    /// the failed count back to the backlog.
    #[pg_test]
    fn status_docs_failed_counts_dead_letters_until_retried() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::tracked("fts_pr8_dead");
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs.fail_ids(
            Endpoint::Upsert,
            &["2"],
            400,
            "document 2: field 'body' is invalid",
        );
        env.run(
            "INSERT INTO fts_pr8_dead (id, title, body) VALUES (1, 'a', 'one'), (2, 'b', 'two'), \
             (3, 'c', 'three')",
        );
        env.drain();

        let status = fts_status(&env.table);
        assert_eq!(status["docs_failed"], json!(1), "status = {status}");
        assert_eq!(status["docs_backlog"], json!(0), "not work: {status}");
        assert_eq!(status["docs_queue_state"], json!("idle"), "{status}");
        assert!(!status["docs_last_delivered_at"].is_null(), "{status}");

        fts_run(&format!(
            "SELECT {FTS_RETRY_FAILED}({})",
            fts_rel(&env.table)
        ));
        let status = fts_status(&env.table);
        assert_eq!(status["docs_failed"], json!(0), "status = {status}");
        assert_eq!(status["docs_backlog"], json!(1), "requeued: {status}");
    }

    /// A 429 storm is `backoff` (the rows stay, no attempt is counted) and the error shows
    /// in `last_error`; a rejected key parks the lane (`parked`, with the reason); after
    /// `unpark_docs` and a healed mock the queue drains to `idle` with no error left.
    #[pg_test]
    fn status_docs_queue_state_follows_backoff_park_and_recovery() {
        let _serialize = TestSerializeGuard::acquire();
        let env = FtsEnv::tracked("fts_pr8_states");
        env.docs
            .fail_always(Endpoint::Upsert, 429, "Pace your requests per second");
        env.run("INSERT INTO fts_pr8_states (id, title, body) VALUES (1, 't', 'b')");
        assert_eq!(env.round(), "backoff");
        let row = fts_status_row(&env.table);
        assert_eq!(row["docs_queue_state"], json!("backoff"), "row = {row}");
        assert_eq!(row["docs_backlog"], json!(1), "row = {row}");
        let error = row["last_error"].as_str().unwrap_or_default();
        assert!(error.contains("429"), "last_error = {error:?}");

        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs.heal_all();
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        assert_eq!(env.round(), "parked");
        let row = fts_status_row(&env.table);
        assert_eq!(row["docs_queue_state"], json!("parked"), "row = {row}");
        let reason = row["last_error"].as_str().unwrap_or_default();
        assert!(
            reason.contains("authentication failed"),
            "last_error = {reason:?}"
        );

        env.docs.heal_all();
        fts_run(&format!("SELECT {FTS_UNPARK}({})", fts_rel(&env.table)));
        let row = fts_status_row(&env.table);
        assert_eq!(row["docs_queue_state"], json!("NO WORKER"), "row = {row}");
        assert!(row["last_error"].is_null(), "unpark clears it: {row}");
        env.drain();
        let row = fts_status_row(&env.table);
        assert_eq!(row["docs_queue_state"], json!("idle"), "row = {row}");
        assert!(row["last_error"].is_null(), "row = {row}");
    }

    /// A table declared only with `track_docs` is a row of its own: `mode = 'docs'`, its
    /// registry values, empty placeholders for the vector fields and `NULL` for the vector
    /// lane's queue columns.
    #[pg_test]
    fn status_docs_only_table_is_a_docs_row() {
        let env = FtsEnv::seeded("fts_pr8_only", 3);
        let row = fts_status_row(&env.table);
        assert_eq!(row["mode"], json!("docs"), "row = {row}");
        assert_eq!(row["id_column"], json!("id"), "row = {row}");
        assert_eq!(row["vector_column"], json!(""), "row = {row}");
        assert_eq!(row["metric"], json!(""), "row = {row}");
        assert_eq!(row["dimension"], json!(0), "row = {row}");
        assert_eq!(row["index_name"], json!(env.index), "row = {row}");
        assert_eq!(row["namespace"], json!(env.namespace), "row = {row}");
        let metadata = json!(["author", "published_at", "tags"]);
        assert_eq!(row["metadata_columns"], metadata, "row = {row}");
        assert_eq!(row["local_rows"], json!(3), "row = {row}");
        assert_eq!(row["storage"], json!("full"), "row = {row}");
        assert_eq!(row["attached"], json!(false), "row = {row}");
        for column in [
            "backlog",
            "oldest_enqueued",
            "last_error",
            "queue_state",
            "backup_gate",
            "detached_at",
            "detach_backup_id",
            "rpo",
            "read_capacity",
        ] {
            assert!(fts_null(&row, column), "{column} is NULL: {row}");
        }
        assert_eq!(row["docs_failed"], json!(0), "row = {row}");
        assert_eq!(row["docs_queue_state"], json!("idle"), "row = {row}");
    }

    /// A table in both registries is one row with both lanes: the vector columns keep their
    /// meaning and the document columns describe the other lane, so a parked docs lane next to
    /// an idle vector lane shows as that, with the docs lane's reason in `last_error`.
    #[pg_test]
    fn status_docs_both_lanes_of_a_table_in_both_registries() {
        let _serialize = TestSerializeGuard::acquire();
        let env = fts_dual_env("fts_pr8_dual");
        let t = &env.table;
        let row = fts_status_row(t);
        assert_eq!(row["mode"], json!("remote"), "row = {row}");
        assert_eq!(row["vector_column"], json!("embedding"), "row = {row}");
        assert_eq!(row["queue_state"], json!("idle"), "row = {row}");
        assert_eq!(row["docs_queue_state"], json!("idle"), "row = {row}");

        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        fts_run(&format!(
            "INSERT INTO {t} (id, body, embedding) VALUES (1, 'b', '[1, 0]')"
        ));
        let row = fts_status_row(t);
        assert_eq!(row["backlog"], json!(1), "vector row queued: {row}");
        assert_eq!(row["docs_backlog"], json!(1), "document row queued: {row}");

        assert_eq!(fts_round(t), "parked");
        let outcome =
            crate::outbox::drain_step(relid_of(t), crate::backend::DrainCredentials::Worker);
        assert!(matches!(outcome, crate::outbox::DrainOutcome::Processed(1)));
        let row = fts_status_row(t);
        assert_eq!(row["backlog"], json!(0), "row = {row}");
        assert_eq!(row["queue_state"], json!("idle"), "row = {row}");
        assert_eq!(row["docs_queue_state"], json!("parked"), "row = {row}");
        let reason = row["last_error"].as_str().unwrap_or_default();
        assert!(
            reason.contains("authentication failed"),
            "last_error = {reason:?}"
        );
    }

    /// A table that only has a vector registration reports `NULL` in every document column.
    #[pg_test]
    fn status_docs_columns_are_null_for_a_vector_only_table() {
        create_extension_vector();
        fts_run("CREATE TABLE fts_pr8_vec (id bigint PRIMARY KEY, embedding vector(3))");
        fts_run("SELECT pinecone.track('fts_pr8_vec')");
        let row = fts_status_row("fts_pr8_vec");
        assert_eq!(row["mode"], json!("local"), "row = {row}");
        for column in [
            "docs_backlog",
            "docs_oldest_enqueued",
            "docs_last_delivered_at",
            "docs_backfill_done",
            "docs_backfill_total",
            "docs_failed",
            "docs_queue_state",
        ] {
            assert!(fts_null(&row, column), "{column} is NULL: {row}");
        }
    }

    /// The queue numbers need EXECUTE on `_doc_outbox_stats`, like the vector ones on
    /// `_outbox_stats`: without it they are `NULL` (progress and the last delivery come from the
    /// registry and stay), and a parked lane still says `parked`, with its reason. The lane is
    /// shown to a role that can SELECT the table; nobody needs a grant on the registry.
    #[pg_test]
    fn status_docs_queue_columns_need_execute_on_the_stats_function() {
        let env = FtsEnv::seeded("fts_pr8_gate", 2);
        env.run("INSERT INTO fts_pr8_gate (id, title, body) VALUES (3, 'c', 'three')");
        let role = format!("pinecone_pr8_status_{}", std::process::id());
        fts_run(&format!("CREATE ROLE {role}"));
        fts_run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}"));
        fts_run(&format!(
            "GRANT SELECT ON pinecone.tables, {} TO {role}",
            env.table
        ));
        let as_role = |table: &str| {
            fts_run(&format!("SET ROLE {role}"));
            let row = fts_status_row(table);
            fts_run("RESET ROLE");
            row
        };

        let row = as_role(&env.table);
        for column in ["docs_backlog", "docs_oldest_enqueued", "docs_failed"] {
            assert!(fts_null(&row, column), "{column} is NULL: {row}");
        }
        assert!(fts_null(&row, "docs_queue_state"), "row = {row}");
        assert!(!row["docs_last_delivered_at"].is_null(), "row = {row}");
        assert_eq!(row["local_rows"], json!(3), "row = {row}");

        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        assert_eq!(env.round(), "parked");
        let row = as_role(&env.table);
        assert_eq!(row["docs_queue_state"], json!("parked"), "row = {row}");
        let reason = row["last_error"].as_str().unwrap_or_default();
        assert!(
            reason.contains("authentication failed"),
            "last_error = {reason:?}"
        );

        fts_run(&format!(
            "GRANT EXECUTE ON FUNCTION pinecone._doc_outbox_stats(oid) TO {role}"
        ));
        let row = as_role(&env.table);
        assert_eq!(row["docs_backlog"], json!(1), "row = {row}");
        assert_eq!(row["docs_failed"], json!(0), "row = {row}");
        fts_drop_role(&role);
    }

    /// The registry is nobody's to read, so `status()` shows a document lane only for the tables
    /// the caller can SELECT: a docs-only table is no row at all for a role that cannot, and a
    /// table in both registries keeps its vector row with `NULL` document columns.
    #[pg_test]
    fn status_docs_lane_is_shown_only_for_tables_the_caller_can_select() {
        let env = FtsEnv::seeded("fts_pr8_hidden", 2);
        let role = format!("pinecone_pr8_hidden_{}", std::process::id());
        fts_run(&format!("CREATE ROLE {role}"));
        fts_run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}"));
        fts_run(&format!("GRANT SELECT ON pinecone.tables TO {role}"));
        let rows_for = |table: &str| -> i64 {
            fts_run(&format!("SET ROLE {role}"));
            let sql = format!(
                "SELECT count(*) FROM pinecone.status() WHERE table_name = {}",
                quote_literal(fts_namespace(table))
            );
            let rows = Spi::get_one::<i64>(&sql).expect("status rows");
            fts_run("RESET ROLE");
            rows.unwrap_or_default()
        };

        assert_eq!(rows_for(&env.table), 0, "no SELECT, no docs-only row");
        fts_run(&format!("GRANT SELECT ON {} TO {role}", env.table));
        assert_eq!(rows_for(&env.table), 1);
        fts_drop_role(&role);
    }

    /// While the backfill job is pending a remote search says its results are partial: once per
    /// call, with the delivered count. The local engine searches the heap and a finished
    /// backfill is complete, so neither says anything.
    #[pg_test]
    fn search_docs_notices_while_the_lane_is_backfilling() {
        let env = FtsEnv::untracked("fts_pr8_notice");
        fts_insert_series(&env.table, 2_500);
        fts_set_round_budget(50);
        fts_latency(&env.docs, 150);
        fts_track_standard(&env.table, &env.index);
        let partial = |notices: &[String]| -> Vec<String> {
            let found = notices.iter().filter(|n| n.contains("still backfilling"));
            found.cloned().collect()
        };
        let remote = format!(
            "SELECT count(*) FROM {FTS_SEARCH}({})",
            fts_search_args(&env.table, "title", "")
        );

        let (_, notices) = capture_notices(|| fts_run(&remote));
        let found = partial(&notices);
        assert_eq!(found.len(), 1, "one per call: {notices:?}");
        assert!(found[0].contains("pinecone.search_docs"), "{}", found[0]);
        assert!(found[0].contains("fts_pr8_notice"), "{}", found[0]);
        assert!(
            found[0].contains("0 of 2500 rows delivered"),
            "{}",
            found[0]
        );
        assert!(found[0].contains("results are partial"), "{}", found[0]);

        assert_eq!(env.round(), "processed", "one chunk");
        let (done, total, state) = fts_backfill_progress(&env.table);
        assert_eq!(
            (state.as_str(), total),
            ("backfilling", Some(2_500)),
            "{done}"
        );
        let (_, notices) = capture_notices(|| fts_run(&remote));
        let found = partial(&notices);
        assert_eq!(found.len(), 1, "notices = {notices:?}");
        assert!(found[0].contains(&format!("{done} of 2500 rows delivered")));

        let local = format!(
            "SELECT count(*) FROM {FTS_SEARCH}({})",
            fts_search_args(&env.table, "title", "engine => 'local'")
        );
        let (_, notices) = capture_notices(|| fts_run(&local));
        assert!(
            partial(&notices).is_empty(),
            "the heap is complete: {notices:?}"
        );

        fts_set_round_budget(60_000);
        env.drain();
        let (_, notices) = capture_notices(|| fts_run(&remote));
        assert!(partial(&notices).is_empty(), "finished: {notices:?}");
    }

    // ---- live smoke (skipped unless PG_PINECONE_LIVE_TESTS=1 and PINECONE_API_KEY are set) ----

    /// Skippable live end-to-end test of the document lane against a real Pinecone project:
    /// `track_docs` creates a document index, three rows are delivered (`_docs_round` stands in
    /// for the worker, which the pgrx cluster does not run), `flush_docs` finds the queue empty,
    /// `search_docs` finds the right row once Pinecone has indexed it (polled for up to two
    /// minutes), and `untrack_docs(drop_index => true)` deletes the index. Run via
    /// `scripts/smoke.sh`.
    #[pg_test]
    fn live_docs_roundtrip() {
        let Some(api_key) = live_api_key() else {
            return;
        };

        let index_name = format!("pg-pinecone-smoke-docs-{}", std::process::id());
        // Deletes the real index on every exit path, including a panic unwind.
        let _index_guard = SmokeDocIndex::adopt(&api_key, &index_name);

        Spi::run("CREATE TABLE live_docs_roundtrip (id bigint PRIMARY KEY, title text, body text)")
            .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.set_api_key({})",
            quote_literal(&api_key)
        ))
        .expect("pinecone.set_api_key");
        Spi::run(&format!(
            "SELECT pinecone.track_docs('live_docs_roundtrip', \
             text_columns => '[\"title\", \"body\"]', index_name => {})",
            quote_literal(&index_name)
        ))
        .expect("track_docs");

        Spi::run(
            "INSERT INTO live_docs_roundtrip (id, title, body) VALUES \
             (1, 'Vector search', 'Keep embeddings next to your rows.'), \
             (2, 'Full text', 'BM25 ranking over the declared columns.'), \
             (3, 'Hybrid retrieval', 'Combine keyword and vector search.')",
        )
        .expect("insert rows (the trigger queues their ids)");
        fts_drain("live_docs_roundtrip");
        let flushed =
            Spi::get_one::<bool>("SELECT pinecone.flush_docs('live_docs_roundtrip', 10000)")
                .expect("flush_docs");
        assert_eq!(flushed, Some(true), "everything was delivered");

        // Delivered is not searchable: Pinecone indexes for up to about a minute.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(120);
        let ids: Vec<String> = loop {
            let ids: Vec<String> = Spi::connect(|client| {
                client
                    .select(
                        "SELECT id FROM pinecone.search_docs('live_docs_roundtrip', 'hybrid', \
                         k => 3) ORDER BY rank",
                        None,
                        &[],
                    )
                    .expect("select from pinecone.search_docs")
                    .map(|row| {
                        row.get_by_name::<String, _>("id")
                            .expect("get id")
                            .expect("id NOT NULL")
                    })
                    .collect()
            });
            if ids.first().map(String::as_str) == Some("3") {
                break ids;
            }
            if std::time::Instant::now() >= deadline {
                panic!("pinecone.search_docs never ranked row 3 first within 120s (got {ids:?})");
            }
            std::thread::sleep(std::time::Duration::from_secs(3));
        };
        assert_eq!(ids[0], "3");

        Spi::run("SELECT pinecone.untrack_docs('live_docs_roundtrip', drop_index => true)")
            .expect("untrack_docs");
        // `_index_guard` drops here (and on any earlier panic via unwind), deleting the real index.
    }

    // ---- review fixes: privilege model, worker isolation, lock discipline ----

    /// Statements a role without any grant on the registry or the queue must be refused.
    fn fts_direct_access_statements(rel: &str) -> Vec<String> {
        vec![
            "SELECT * FROM pinecone.doc_tables".to_string(),
            "SELECT * FROM pinecone.doc_outbox".to_string(),
            format!("INSERT INTO {FTS_QUEUE} (relid, op) VALUES ({rel}, '{FTS_OP_TRUNCATE}')"),
            format!(
                "UPDATE {FTS_REGISTRY} SET metadata_columns = ARRAY['ssn'] WHERE relid = {rel}"
            ),
            format!("DELETE FROM {FTS_REGISTRY} WHERE relid = {rel}"),
        ]
    }

    /// Every verb works for the role that may call it with nothing but schema usage and the
    /// table's own privileges: no grant on the registry, the queue or the internal functions.
    #[pg_test]
    fn docs_verbs_need_no_grant_on_the_registry_or_the_queue() {
        let (_backend, docs) = fts_mock();
        let role = fts_create_reader("fts_m1_owner");
        fts_run(&format!("GRANT CREATE ON SCHEMA public TO {role}"));
        fts_run(&format!("SET ROLE {role}"));
        fts_run("CREATE TABLE fts_m1_own (id bigint PRIMARY KEY, title text, body text)");
        let rel = fts_rel("fts_m1_own");
        let args =
            "text_columns => '{\"title\": {}, \"body\": {}}'::jsonb, index_name => 'fts-m1-own'";
        fts_run(&fts_track_sql("fts_m1_own", args));
        fts_run("INSERT INTO fts_m1_own VALUES (1, 'a', 'b'), (2, 'c', 'd')");
        fts_run("RESET ROLE");
        fts_drain("fts_m1_own");
        let namespace = fts_namespace("fts_m1_own");
        assert_eq!(docs.remote_ids(&namespace), fts_set(&["1", "2"]));

        docs.set_search_matches(&[("2", 2.0), ("1", 1.0)]);
        fts_run(&format!("SET ROLE {role}"));
        let found = fts_search_rows(&fts_search_args("fts_m1_own", "b", ""));
        let failed = fts_failed_docs("fts_m1_own");
        let flushed = Spi::get_one::<bool>(&format!("SELECT {FTS_FLUSH}({rel}, 100)"));
        let retried = Spi::get_one::<i64>(&format!("SELECT {FTS_RETRY_FAILED}({rel})"));
        let (flushed, retried) = (flushed.expect("flush_docs"), retried.expect("retry"));
        fts_run(&format!("SELECT {FTS_UNPARK}({rel})"));
        fts_run(&format!("SELECT {FTS_BACKFILL}({rel})"));
        let denied: Vec<(String, FtsError)> = fts_direct_access_statements(&rel)
            .into_iter()
            .map(|sql| (sql.clone(), fts_sql_error(&sql)))
            .collect();
        fts_run(&format!("SELECT {FTS_UNTRACK}({rel}, drop_index => true)"));
        fts_run("RESET ROLE");
        fts_assert_unregistered("fts_m1_own");
        fts_drop_role(&role);

        assert_eq!(found.len(), 2, "search_docs needs only SELECT: {found:?}");
        assert!(failed.is_empty());
        assert_eq!(flushed, Some(true), "flush_docs needs no stats grant");
        assert_eq!(retried, Some(0));
        for (sql, error) in &denied {
            assert_eq!(error.sqlstate, "42501", "{sql}: {error:?}");
            assert!(
                error.message.contains("permission denied"),
                "{sql}: {error:?}"
            );
        }
        assert_eq!(docs.count(Endpoint::IndexDelete), 1);
    }

    /// A second owner cannot enqueue a `doc_delete_all` for another table, touch its registry
    /// row, or run a verb on it: the review's namespace-wipe and global-DDL-denial scenarios.
    #[pg_test]
    fn docs_a_second_owner_cannot_touch_another_tables_registry_or_queue() {
        let env = FtsEnv::seeded("fts_m1_victim", 2);
        let role = fts_create_reader("fts_m1_tenant");
        fts_run(&format!("GRANT CREATE ON SCHEMA public TO {role}"));
        fts_run(&format!("SET ROLE {role}"));
        fts_run("CREATE TABLE fts_m1_mine (id bigint PRIMARY KEY, body text)");
        let victim = fts_rel(&env.table);
        let mine = fts_rel("fts_m1_mine");
        let owner_only = [
            fts_track_standard_sql(&env.table, "fts-m1-hijack"),
            format!("SELECT {FTS_UNTRACK}({victim}, drop_index => true, force => true)"),
            format!("SELECT {FTS_BACKFILL}({victim}, clear => true)"),
            format!("SELECT {FTS_UNPARK}({victim})"),
            format!("SELECT {FTS_RETRY_FAILED}({victim})"),
        ];
        let readers = [
            format!("SELECT {FTS_FLUSH}({victim}, 100)"),
            format!("SELECT * FROM pinecone.failed_docs({victim})"),
            format!("SELECT * FROM {FTS_SEARCH}({victim}, 'q')"),
        ];
        let mut direct = fts_direct_access_statements(&victim);
        direct.push(format!(
            "INSERT INTO {FTS_REGISTRY} (relid, id_column, id_type, text_columns, index_name, \
             namespace, schema, column_types, state) VALUES ({mine}, 'id', 'int8', '{{}}', 'x', 'y', \
             '{{}}', '{{\"x\": \"bogus\"}}', 'ready')"
        ));
        let errors = |statements: &[String]| -> Vec<(String, FtsError)> {
            let all = statements.iter();
            all.map(|sql| (sql.clone(), fts_sql_error(sql))).collect()
        };
        let (owner_errors, reader_errors, direct_errors) =
            (errors(&owner_only), errors(&readers), errors(&direct));
        fts_run("RESET ROLE");
        fts_drop_role(&role);

        for (sql, error) in &owner_errors {
            fts_assert_error(error, "42501", &["must be owner of", &env.table]);
            assert!(!sql.is_empty());
        }
        for (sql, error) in &reader_errors {
            let table = format!("permission denied for table {}", env.table);
            assert_eq!(error.sqlstate, "42501", "{sql}: {error:?}");
            assert!(error.message.contains(&table), "{sql}: {error:?}");
        }
        for (sql, error) in &direct_errors {
            let message = error.message.as_str();
            assert!(message.contains("permission denied"), "{sql}: {error:?}");
            assert_eq!(error.sqlstate, "42501", "{sql}");
        }
        assert!(env.queue().is_empty(), "nothing queued: {:?}", env.queue());
        assert_eq!(env.docs.count(Endpoint::Delete), 0, "no namespace wipe");
        assert_eq!(env.docs.count(Endpoint::IndexDelete), 0);
        assert_eq!(env.remote_ids(), fts_set(&["1", "2"]));
        let sql = format!("SELECT metadata_columns FROM {FTS_REGISTRY} WHERE relid = {victim}");
        let columns = Spi::get_one::<Vec<Option<String>>>(&sql).expect("registry row");
        assert_eq!(columns.expect("a row").len(), 3, "the row is untouched");
    }

    /// The DDL guard looks only at the tables a statement alters. A registry row that no
    /// longer matches its table (here: a bogus declared column) does not block `ALTER TABLE` on
    /// any other table; the drifted table itself is still guarded.
    #[pg_test]
    fn docs_ddl_guard_ignores_a_drifted_row_of_an_unrelated_table() {
        let env = FtsEnv::tracked("fts_m1_guard_a");
        fts_run("CREATE TABLE fts_m1_guard_b (id bigint PRIMARY KEY, body text)");
        fts_run("CREATE TABLE fts_m1_guard_c (id bigint PRIMARY KEY, body text)");
        let row = doc_registry_row("fts_m1_guard_b", "fts-m1-guard-b", "public.fts_m1_guard_b");
        crate::docs_registry::insert(&row);
        let relid = relid_of("fts_m1_guard_b");
        crate::docs_registry::set_column_types(relid, &json!({"x": "bogus:-1"}));

        env.run("ALTER TABLE fts_m1_guard_c ADD COLUMN extra int");
        env.run("ALTER TABLE fts_m1_guard_c RENAME COLUMN body TO text_body");
        env.run(&format!("ALTER TABLE {} ADD COLUMN extra int", env.table));
        let error = fts_sql_error("ALTER TABLE fts_m1_guard_b ADD COLUMN extra int");
        fts_assert_error(
            &error,
            "2BP01",
            &["cannot alter column \"x\"", "fts_m1_guard_b"],
        );
    }

    /// Readers need nothing beyond SELECT on the table (and schema usage): the registry is
    /// read for them, and every verb that changes anything stays with the owner.
    #[pg_test]
    fn docs_readers_need_only_select_on_the_table() {
        let env = FtsEnv::seeded("fts_m1_reader", 2);
        let role = fts_create_reader("fts_m1_reader");
        env.run(&format!("GRANT SELECT ON {} TO {role}", env.table));
        env.docs.set_search_matches(&[("1", 1.0)]);
        let rel = fts_rel(&env.table);
        env.run(&format!("SET ROLE {role}"));
        let remote = fts_search_rows(&fts_search_args(&env.table, "q", ""));
        let local = fts_search_rows(&fts_search_args(&env.table, "title", "engine => 'local'"));
        let failed = fts_failed_docs(&env.table);
        let headline = format!("SELECT pinecone.headline({rel}, 'body', 'a body text', 'body')");
        let marked = Spi::get_one::<String>(&headline).expect("headline");
        let owner_only = [
            format!("SELECT {FTS_RETRY_FAILED}({rel})"),
            format!("SELECT {FTS_UNPARK}({rel})"),
            format!("SELECT {FTS_BACKFILL}({rel})"),
            format!("SELECT {FTS_UNTRACK}({rel})"),
        ];
        let refused: Vec<FtsError> = owner_only.iter().map(|sql| fts_sql_error(sql)).collect();
        env.run("RESET ROLE");
        fts_drop_role(&role);

        assert_eq!(remote.len(), 1, "{remote:?}");
        assert_eq!(
            local.len(),
            2,
            "the local engine runs as the reader: {local:?}"
        );
        assert!(failed.is_empty());
        assert_eq!(marked.as_deref(), Some("a <b>body</b> text"));
        for error in &refused {
            fts_assert_error(error, "42501", &["must be owner of"]);
        }
        fts_assert_registered(&env.table);
    }

    /// A table with a `numeric` metadata column, tracked against the current mock; the column
    /// can hold a value (`1e400`) that no `float8` can, which fails the SQL that reads the row.
    fn fts_numeric_table(table: &str) {
        fts_run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, body text, price numeric)"
        ));
        let args = format!(
            "text_columns => '{{\"body\": {{}}}}'::jsonb, metadata_columns => ARRAY['price'], \
             index_name => {}",
            quote_literal(fts_index_name(table))
        );
        fts_run(&fts_track_sql(table, &args));
    }

    /// One worker round of the document lane over every active table, with no memory of earlier
    /// rounds' backoff windows.
    fn fts_worker_round() -> bool {
        let mut scheduler = crate::docs_outbox::DocScheduler::new();
        crate::docs_outbox::drain_doc_round(&mut scheduler)
    }

    fn fts_parked_reason(table: &str) -> String {
        let sql = format!(
            "SELECT parked_reason FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(table)
        );
        let reason = Spi::get_one::<String>(&sql).expect("parked_reason");
        reason.unwrap_or_default()
    }

    /// A statement on the queue that raises for one table (the safety net of a step: the table's
    /// own rows are read where a poison row is found).
    fn fts_fail_queue_statements(table: &str, event: &str, condition: &str) {
        fts_run(&format!(
            "CREATE FUNCTION fts_boom_{table}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN \
             IF {condition} THEN RAISE EXCEPTION 'queue statement failed'; END IF; \
             RETURN COALESCE(NEW, OLD); END $$"
        ));
        fts_run(&format!(
            "CREATE TRIGGER fts_boom_{table} BEFORE {event} ON {FTS_QUEUE} FOR EACH ROW \
             EXECUTE FUNCTION fts_boom_{table}()"
        ));
    }

    /// A SQL error in the queue statements of one table's step is that lane's failure: the
    /// message lands on the queue row, the lane parks after `outbox_max_attempts` rounds, and
    /// another table drains in the same rounds.
    #[pg_test]
    fn doc_worker_round_survives_a_sql_error_in_one_table_and_parks_its_lane() {
        let (_backend, docs) = fts_mock();
        fts_numeric_table("fts_m2_bad");
        fts_numeric_table("fts_m2_good");
        fts_drain("fts_m2_bad");
        fts_drain("fts_m2_good");
        fts_run("SET pinecone.outbox_max_attempts = 2");
        fts_fail_queue_statements(
            "fts_m2_bad",
            "DELETE",
            &format!("OLD.relid = {}", fts_rel("fts_m2_bad")),
        );
        fts_run("INSERT INTO fts_m2_bad VALUES (1, 'queue fault', 1)");
        fts_run("INSERT INTO fts_m2_good VALUES (1, 'fine', 2.5)");

        for _ in 0..3 {
            fts_worker_round();
        }

        assert!(fts_lane_parked("fts_m2_bad"), "the failing lane parks");
        let reason = fts_parked_reason("fts_m2_bad");
        assert!(
            reason.contains("queue statement failed"),
            "parked_reason = {reason:?}"
        );
        let rows = fts_queue("fts_m2_bad");
        let row = rows.iter().find(|r| r["op"] == json!(FTS_OP_UPSERT));
        let row = row.unwrap_or_else(|| panic!("the row stays queued: {rows:?}"));
        let error = row["last_error"].as_str().unwrap_or_default();
        assert!(error.contains("queue statement failed"), "{error}");
        assert_eq!(row["attempts"], json!(2), "{row:?}");
        assert!(!fts_lane_parked("fts_m2_good"));
        assert_eq!(
            docs.remote_ids(&fts_namespace("fts_m2_good")),
            fts_set(&["1"])
        );
        assert!(
            fts_queue_ids("fts_m2_good", FTS_OP_UPSERT).is_empty(),
            "the other table delivered in the same rounds"
        );
    }

    /// A backfill chunk is isolated the same way: the SQL error becomes the job's failure.
    #[pg_test]
    fn doc_backfill_chunk_survives_a_sql_error_and_parks_the_lane() {
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_m2_chunk (id bigint PRIMARY KEY, body text, price numeric)");
        fts_run("INSERT INTO fts_m2_chunk VALUES (1, 'row', 1)");
        let args = "text_columns => '{\"body\": {}}'::jsonb, metadata_columns => ARRAY['price']";
        fts_run(&fts_track_sql("fts_m2_chunk", args));
        fts_run("SET pinecone.outbox_max_attempts = 1");
        fts_fail_queue_statements(
            "fts_m2_chunk",
            "UPDATE",
            "NEW.payload IS DISTINCT FROM OLD.payload",
        );

        let relid = relid_of("fts_m2_chunk");
        let outcome = crate::docs_backfill::chunk_isolated(relid, &mut None);

        let parked = matches!(
            &outcome,
            crate::docs_backfill::ChunkOutcome::Failed(
                crate::docs_outbox::DocDrainOutcome::Parked(_)
            )
        );
        assert!(parked, "outcome = {outcome:?}");
        assert!(fts_parked_reason("fts_m2_chunk").contains("queue statement failed"));
        let jobs = fts_backfill_jobs("fts_m2_chunk");
        assert_eq!(jobs.len(), 1, "the job stays for the retry: {jobs:?}");
        assert!(
            jobs[0]["last_error"]
                .as_str()
                .unwrap_or_default()
                .contains("queue statement failed")
        );
    }

    fn fts_share_lock_held(relid: pg_sys::Oid) -> bool {
        let share = pg_sys::AccessShareLock as pg_sys::LOCKMODE;
        unsafe { pg_sys::CheckRelationOidLockedByMe(relid, share, false) }
    }

    /// Gives back the share locks this test transaction took on the table itself (tracking it
    /// counted its rows, a helper read it): a worker round starts without any.
    fn fts_release_share_locks(relid: pg_sys::Oid) {
        let share = pg_sys::AccessShareLock as pg_sys::LOCKMODE;
        for _ in 0..50 {
            if !fts_share_lock_held(relid) {
                return;
            }
            unsafe { pg_sys::UnlockRelationOid(relid, share) };
        }
        panic!("could not release the share locks on {relid}");
    }

    /// The worker holds no lock on the user table while it talks to Pinecone, however it got
    /// there (reading the rows takes a lock that lives to the end of the transaction unless it is
    /// given back): a DDL statement queued behind that lock blocks every reader of the table.
    #[pg_test]
    fn doc_drain_holds_no_lock_on_the_table_while_sending() {
        let env = FtsEnv::tracked("fts_m3_nolock");
        env.run("INSERT INTO fts_m3_nolock (id, title) SELECT i, 'a' FROM generate_series(1, 5) i");
        env.run("DELETE FROM fts_m3_nolock WHERE id = 5");
        let relid = relid_of(&env.table);
        fts_release_share_locks(relid);
        let requests = std::rc::Rc::new(std::cell::Cell::new(0));
        let seen = std::rc::Rc::clone(&requests);
        crate::docs_drain::hooks::set_before_request(Some(Box::new(move || {
            seen.set(seen.get() + 1);
            assert!(
                !fts_share_lock_held(relid),
                "AccessShareLock is held across a request to Pinecone"
            );
        })));

        let outcome = crate::docs_drain::drain_doc_step(relid);

        crate::docs_drain::hooks::set_before_request(None);
        let processed = matches!(&outcome, DocDrainOutcome::Processed(rows) if *rows > 0);
        assert!(processed, "outcome = {outcome:?}");
        assert!(requests.get() >= 2, "an upsert and a delete went out");
        assert!(!fts_share_lock_held(relid), "nor does the step keep it");
        assert_eq!(env.remote_ids(), fts_set(&["1", "2", "3", "4"]));
    }

    /// A batch stops when its time is spent (after at least one slice), keeps what it
    /// delivered and leaves the rest queued, so a rate-limited batch cannot hold the lane, its
    /// claimed rows and an `untrack_docs` for minutes.
    #[pg_test]
    fn doc_drain_a_spent_budget_ends_the_batch_and_the_next_step_resumes() {
        let env = FtsEnv::tracked("fts_m3_budget");
        fts_insert_series(&env.table, 2_500);
        let relid = relid_of(&env.table);

        let spent = crate::docs_drain::Budget::new(std::time::Duration::ZERO);
        let first = crate::docs_drain::drain_doc_step_with(relid, spent);

        let processed = matches!(&first, DocDrainOutcome::Processed(rows) if *rows >= 1);
        assert!(processed, "first = {first:?}");
        assert_eq!(env.remote_ids().len(), 1_000, "one slice went out");
        assert_eq!(
            env.queue().len(),
            2,
            "its queue row is done, the others wait"
        );
        env.drain();
        assert_eq!(env.remote_ids(), fts_id_range(1, 2_500));
    }

    /// A table that DDL has locked ends the batch where it is, without losing or resending
    /// anything, and is simply tried again next round.
    #[pg_test]
    fn doc_drain_a_busy_table_ends_the_batch_without_losing_anything() {
        let env = FtsEnv::tracked("fts_m3_busy");
        fts_insert_series(&env.table, 2_500);
        let relid = relid_of(&env.table);
        let hooks = crate::docs_drain::hooks::set_table_busy;
        crate::docs_drain::hooks::set_before_request(Some(Box::new(move || hooks(true))));

        let first = crate::docs_drain::drain_doc_step(relid);

        crate::docs_drain::hooks::set_before_request(None);
        let processed = matches!(&first, DocDrainOutcome::Processed(rows) if *rows >= 1);
        assert!(processed, "first = {first:?}");
        assert_eq!(
            env.remote_ids().len(),
            1_000,
            "busy from the second slice on"
        );
        env.docs.clear_calls();
        let again = crate::docs_drain::drain_doc_step(relid);
        assert!(
            matches!(again, DocDrainOutcome::Processed(0)),
            "again = {again:?}"
        );
        assert!(
            env.docs.calls_to(Endpoint::Upsert).is_empty(),
            "nothing is sent"
        );

        crate::docs_drain::hooks::set_table_busy(false);
        env.drain();
        assert_eq!(env.remote_ids(), fts_id_range(1, 2_500));
    }

    /// A 429 storm ends the batch at the first request that cannot get through; nothing
    /// stays locked, so `untrack_docs` goes through at once and DDL on the table is not held up.
    #[pg_test]
    fn doc_drain_a_429_storm_leaves_nothing_locked_and_untrack_goes_through() {
        let env = FtsEnv::tracked("fts_m3_storm");
        fts_insert_series(&env.table, 3);
        let relid = relid_of(&env.table);
        fts_release_share_locks(relid);
        env.docs.fail_always(Endpoint::Upsert, 429, "slow down");

        assert_eq!(env.round(), "backoff");

        assert!(!fts_share_lock_held(relid));
        assert_eq!(env.queue().len(), 1, "the row waits for the next round");
        env.run(&format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table)));
        fts_assert_unregistered(&env.table);
        assert!(env.queue().is_empty());
    }

    /// Another session's hold on the document lane of `relid` (the advisory lock a running drain,
    /// `backfill_docs` or `untrack_docs` takes), until the guard drops. A `#[pg_test]` is one
    /// transaction, so the lock must not have been taken in it before: the guard goes in first.
    struct FtsLaneHolder {
        name: String,
    }

    impl FtsLaneHolder {
        fn hold(relid: pg_sys::Oid) -> Self {
            let conninfo = dblink_conninfo();
            let name = format!("fts_lane_holder_{}", relid.to_u32());
            fts_run(&format!("SELECT dblink_connect('{name}', '{conninfo}')"));
            let key = relid.to_u32() as i32;
            let magic = crate::docs_drain::DOC_LOCK_MAGIC;
            fts_run(&format!(
                "SELECT * FROM dblink('{name}', 'SELECT pg_advisory_lock({magic}, {key})::text') \
                 AS t(x text)"
            ));
            Self { name }
        }
    }

    impl Drop for FtsLaneHolder {
        fn drop(&mut self) {
            let _ = Spi::run(&format!("SELECT dblink_disconnect('{}')", self.name));
        }
    }

    /// The worker never waits for the lane lock of a table: a user session in
    /// `backfill_docs` or `untrack_docs` makes the worker move on to the next table.
    #[pg_test]
    fn doc_drain_and_backfill_skip_a_lane_another_session_holds() {
        let env = FtsEnv::untracked("fts_m3_lane");
        fts_track_standard(&env.table, &env.index);
        let relid = relid_of(&env.table);
        let _holder = FtsLaneHolder::hold(relid);
        fts_run("SET lock_timeout = '3s'");
        env.run("INSERT INTO fts_m3_lane (id, title) VALUES (1, 'a')");

        let step = crate::docs_drain::drain_doc_step(relid);
        let chunk = crate::docs_backfill::chunk(relid, &mut None);

        assert!(
            matches!(step, DocDrainOutcome::Processed(0)),
            "step = {step:?}"
        );
        let skipped = matches!(chunk, crate::docs_backfill::ChunkOutcome::LockUnavailable);
        assert!(skipped, "chunk = {chunk:?}");
        assert!(env.docs.calls_to(Endpoint::Upsert).is_empty());
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["1".to_string()]
        );
    }

    /// `untrack_docs` says why it waits when a drain holds the lane, then waits.
    #[pg_test]
    fn untrack_docs_says_which_drain_it_waits_for() {
        let env = FtsEnv::untracked("fts_m3_wait");
        fts_track_standard(&env.table, &env.index);
        let _holder = FtsLaneHolder::hold(relid_of(&env.table));
        fts_run("SET lock_timeout = '300ms'");

        let sql = format!("SELECT {FTS_UNTRACK}({})", fts_rel(&env.table));
        let (error, notices) = capture_notices(|| fts_sql_error(&sql));

        fts_assert_error(&error, "55P03", &["lock timeout"]);
        let said = notices
            .iter()
            .find(|n| n.contains("waiting for the running drain"));
        let said = said.unwrap_or_else(|| panic!("notices = {notices:?}"));
        assert!(said.contains("fts_m3_wait"), "{said}");
        fts_assert_registered(&env.table);
    }

    /// A table written to all the time still backfills: a queued live row
    /// does not hold the job back, only a queued `doc_delete_all` does (the wipe must reach
    /// Pinecone before any chunk), and a chunk of such a table goes out.
    #[pg_test]
    fn doc_backfill_runs_a_chunk_for_a_table_with_live_rows_queued_unless_a_wipe_is_queued() {
        let env = FtsEnv::untracked("fts_m3_hot");
        fts_insert_series(&env.table, 5);
        fts_track_standard(&env.table, &env.index);
        let relid = relid_of(&env.table);
        env.run("INSERT INTO fts_m3_hot (id, title, body) VALUES (6, 'live', 'row')");
        let candidates = || crate::docs_backfill::candidates();
        assert!(
            candidates().contains(&relid),
            "a live row does not hold the job back"
        );

        let outcome = crate::docs_backfill::chunk(relid, &mut None);
        let progressed = matches!(
            &outcome,
            crate::docs_backfill::ChunkOutcome::Progress { .. }
        );
        assert!(progressed, "outcome = {outcome:?}");
        let (done, _, _) = fts_backfill_progress(&env.table);
        assert_eq!(
            done, 6,
            "the chunk sent every row the table holds, the live one too"
        );
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["6".to_string()]
        );

        env.run("TRUNCATE fts_m3_hot");
        assert!(!candidates().contains(&relid), "a queued wipe goes first");
        let declined = crate::docs_backfill::chunk(relid, &mut None);
        let idle = matches!(declined, crate::docs_backfill::ChunkOutcome::Idle);
        assert!(idle, "declined = {declined:?}");
    }

    /// m4: the rows of one slice are read in groups bounded by their estimated size, so a batch
    /// of big rows never sits in memory whole. 20 rows of 1.1 MB (one huge token each, which the
    /// document clips to 256 bytes) go out in two groups: 15 fit 16 MiB, the other 5 follow.
    #[pg_test]
    fn doc_drain_reads_big_rows_in_byte_bounded_groups() {
        let env = FtsEnv::tracked("fts_m4_groups");
        env.run(
            "INSERT INTO fts_m4_groups (id, title, body) \
             SELECT i, 't', repeat('x', 1100000) FROM generate_series(1, 20) i",
        );
        let requests = std::rc::Rc::new(std::cell::Cell::new(0));
        let seen = std::rc::Rc::clone(&requests);
        crate::docs_drain::hooks::set_before_request(Some(Box::new(move || {
            seen.set(seen.get() + 1)
        })));

        env.drain();

        crate::docs_drain::hooks::set_before_request(None);
        assert_eq!(requests.get(), 2, "two groups, one request each");
        assert_eq!(env.remote_ids(), fts_id_range(1, 20));
        let body = env.remote_doc("1")["body"]
            .as_str()
            .unwrap_or_default()
            .len();
        assert_eq!(body, 256, "the huge token is clipped");
    }

    /// `status()` reads the registry through `docs_registry::list_visible`: the rows of the tables
    /// the caller can SELECT, with no grant on the registry; a row whose table is gone only for a
    /// superuser.
    #[pg_test]
    fn docs_registry_list_visible_shows_the_tables_the_caller_can_select() {
        create_extension_vector();
        let (_backend, _docs) = fts_mock();
        for table in ["fts_m5_vis_a", "fts_m5_vis_b"] {
            fts_create_table(table);
            fts_track_standard(table, &fts_index_name(table));
        }
        let mut ghost = doc_registry_row("fts_m5_vis_a", "ghost-index", "ghost-namespace");
        ghost.relid = pg_sys::Oid::from(4_000_000_001u32);
        crate::docs_registry::insert(&ghost);
        let role = fts_create_reader("fts_m5_vis");
        fts_run(&format!("GRANT SELECT ON fts_m5_vis_a TO {role}"));
        let visible = || -> BTreeSet<String> {
            let rows = crate::docs_registry::list_visible();
            rows.iter().map(|row| row.index_name.clone()).collect()
        };

        let as_superuser = visible();
        fts_run(&format!("SET ROLE {role}"));
        let as_reader = visible();
        fts_run("RESET ROLE");
        fts_drop_role(&role);

        let (a, b) = (
            fts_index_name("fts_m5_vis_a"),
            fts_index_name("fts_m5_vis_b"),
        );
        let all: BTreeSet<String> = [a.clone(), b, "ghost-index".to_string()].into();
        assert_eq!(as_superuser, all);
        assert_eq!(as_reader, BTreeSet::from([a]));
    }

    /// m1: what would silently stop the sync is refused where it happens: making the table a
    /// partition or inheritance child (or giving it children) hides writes from its statement
    /// triggers, dropping or disabling those triggers stops them, and the id must stay NOT NULL
    /// and UNIQUE. Everything else on the table still goes through.
    #[pg_test]
    fn track_docs_ddl_guard_refuses_changes_that_would_stop_the_sync() {
        let env = FtsEnv::tracked("fts_m1b_guard");
        let t = &env.table;
        fts_run("CREATE TABLE fts_m1b_parent (LIKE fts_m1b_guard) PARTITION BY RANGE (id)");
        fts_run("CREATE TABLE fts_m1b_other (id bigint NOT NULL)");
        let statements = [
            (
                "ALTER TABLE fts_m1b_parent ATTACH PARTITION fts_m1b_guard FOR VALUES FROM (0) TO (100)",
                "partition or inheritance",
            ),
            (
                "ALTER TABLE fts_m1b_guard INHERIT fts_m1b_other",
                "partition or inheritance",
            ),
            (
                "CREATE TABLE fts_m1b_child () INHERITS (fts_m1b_guard)",
                "partition or inheritance",
            ),
            (
                "DROP TRIGGER pg_pinecone_docs_ins ON fts_m1b_guard",
                "pg_pinecone_docs_ins",
            ),
            (
                "DROP TRIGGER pg_pinecone_docs_trunc ON fts_m1b_guard",
                "pg_pinecone_docs_trunc",
            ),
            (
                "ALTER TABLE fts_m1b_guard DISABLE TRIGGER pg_pinecone_docs_upd",
                "pg_pinecone_docs_upd",
            ),
            (
                "ALTER TABLE fts_m1b_guard DISABLE TRIGGER USER",
                "pg_pinecone_docs_",
            ),
            (
                "ALTER TABLE fts_m1b_guard ENABLE REPLICA TRIGGER pg_pinecone_docs_del",
                "pg_pinecone_docs_del",
            ),
            (
                "ALTER TABLE fts_m1b_guard DROP CONSTRAINT fts_m1b_guard_pkey",
                "id column \"id\"",
            ),
        ];
        for (sql, part) in statements {
            let error = fts_sql_error(sql);
            fts_assert_error(&error, "2BP01", &[part, "pinecone.track_docs"]);
            fts_assert_hint(&error, fts_bare(FTS_UNTRACK));
        }

        env.run(&format!("ALTER TABLE {t} ADD COLUMN extra int"));
        env.run(&format!("CREATE INDEX fts_m1b_idx ON {t} (author)"));
        env.run("DROP INDEX fts_m1b_idx");
        env.run(&format!(
            "INSERT INTO {t} (id, title, body) VALUES (1, 'a', 'b')"
        ));
        assert_eq!(fts_queue_ids(t, FTS_OP_UPSERT), vec!["1".to_string()]);
    }

    /// m1/m11: an explicit id column must stay NOT NULL and UNIQUE (a constraint or a plain
    /// unique index, never a DEFERRABLE one, whose duplicates a statement can leave behind in
    /// the trigger's transition table).
    #[pg_test]
    fn track_docs_ddl_guard_keeps_an_explicit_id_column_not_null_and_unique() {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_m1b_code (code text NOT NULL UNIQUE, body text)");
        fts_run("CREATE TABLE fts_m1b_uix (code text NOT NULL, body text)");
        fts_run("CREATE UNIQUE INDEX fts_m1b_uix_code ON fts_m1b_uix (code)");
        for table in ["fts_m1b_code", "fts_m1b_uix"] {
            let args = "text_columns => '{\"body\": {}}'::jsonb, id_column => 'code'";
            fts_run(&fts_track_sql(table, args));
        }
        let statements = [
            "ALTER TABLE fts_m1b_code ALTER COLUMN code DROP NOT NULL",
            "ALTER TABLE fts_m1b_code DROP CONSTRAINT fts_m1b_code_code_key",
            "ALTER TABLE fts_m1b_uix ALTER COLUMN code DROP NOT NULL",
            "DROP INDEX fts_m1b_uix_code",
        ];
        for sql in statements {
            let error = fts_sql_error(sql);
            fts_assert_error(
                &error,
                "2BP01",
                &["id column \"code\"", "pinecone.track_docs"],
            );
            fts_assert_hint(&error, fts_bare(FTS_UNTRACK));
        }
        fts_run("ALTER TABLE fts_m1b_code ADD COLUMN extra int");
        fts_run("CREATE UNIQUE INDEX fts_m1b_extra ON fts_m1b_code (extra)");
        fts_run("DROP INDEX fts_m1b_extra");

        fts_run("CREATE TABLE fts_m1b_deferred (code text NOT NULL UNIQUE DEFERRABLE, body text)");
        let args = "text_columns => '{\"body\": {}}'::jsonb, id_column => 'code'";
        let calls = docs.calls().len();
        let error = fts_sql_error(&fts_track_sql("fts_m1b_deferred", args));
        fts_assert_error(
            &error,
            "42P16",
            &["id column \"code\"", "NOT NULL and UNIQUE"],
        );
        fts_assert_hint(&error, "not DEFERRABLE");
        assert_eq!(
            docs.calls().len(),
            calls,
            "refused before Pinecone is asked"
        );
        fts_assert_unregistered("fts_m1b_deferred");
    }

    /// m7: a trigger of that name that is not ours is refused with the way out, before an index
    /// is created for a table that cannot be tracked.
    #[pg_test]
    fn track_docs_refuses_a_table_with_a_foreign_pg_pinecone_docs_trigger_before_calling_pinecone()
    {
        let (_backend, docs) = fts_mock();
        fts_run("CREATE TABLE fts_m7_trig (id bigint PRIMARY KEY, body text)");
        fts_run(
            "CREATE FUNCTION fts_m7_noop() RETURNS trigger LANGUAGE plpgsql \
             AS $$ BEGIN RETURN NULL; END $$",
        );
        fts_run(
            "CREATE TRIGGER pg_pinecone_docs_ins AFTER INSERT ON fts_m7_trig \
             FOR EACH STATEMENT EXECUTE FUNCTION fts_m7_noop()",
        );

        let args = "text_columns => '{\"body\": {}}'::jsonb";
        let error = fts_sql_error(&fts_track_sql("fts_m7_trig", args));

        fts_assert_error(
            &error,
            "42710",
            &["fts_m7_trig", "trigger named \"pg_pinecone_docs_ins\""],
        );
        fts_assert_hint(&error, "pg_pinecone_docs_");
        assert!(docs.calls().is_empty(), "calls = {:?}", docs.calls());
        let sql = format!("SELECT count(*) FROM {FTS_REGISTRY}");
        assert_eq!(Spi::get_one::<i64>(&sql).expect("count"), Some(0));
    }

    /// Review test 1: MERGE fires the INSERT, UPDATE and DELETE statement triggers with their
    /// transition tables; the queue gets exactly the final operations, and the worker delivers
    /// them.
    #[pg_test]
    fn doc_outbox_merge_enqueues_exactly_the_final_operations() {
        let env = FtsEnv::seeded("fts_t_merge", 3);
        env.run("CREATE TABLE fts_t_merge_src (id bigint, title text, op text)");
        env.run(
            "INSERT INTO fts_t_merge_src VALUES (1, 'changed', 'u'), (2, NULL, 'd'), (4, 'new', 'i')",
        );

        env.run(
            "MERGE INTO fts_t_merge t USING fts_t_merge_src s ON t.id = s.id \
             WHEN MATCHED AND s.op = 'd' THEN DELETE \
             WHEN MATCHED THEN UPDATE SET title = s.title \
             WHEN NOT MATCHED THEN INSERT (id, title, body) VALUES (s.id, s.title, 'merged')",
        );

        let sorted = |ids: Vec<String>| ids.into_iter().collect::<BTreeSet<String>>();
        assert_eq!(
            sorted(fts_queue_ids(&env.table, FTS_OP_UPSERT)),
            fts_set(&["1", "4"])
        );
        assert_eq!(
            sorted(fts_queue_ids(&env.table, FTS_OP_DELETE)),
            fts_set(&["2"])
        );
        env.drain();
        assert_eq!(env.remote_ids(), fts_set(&["1", "3", "4"]));
        assert_eq!(env.remote_doc("1")["title"], json!("changed"));
        assert_eq!(env.remote_doc("4")["body"], json!("merged"));
    }

    /// `INSERT ... ON CONFLICT DO NOTHING` queues only the rows it inserted.
    #[pg_test]
    fn doc_outbox_insert_on_conflict_do_nothing_queues_only_the_inserted_rows() {
        let env = FtsEnv::seeded("fts_t_conflict", 2);
        env.run(
            "INSERT INTO fts_t_conflict (id, title, body) VALUES (1, 'dup', 'dup'), (3, 'new', 'new') \
             ON CONFLICT DO NOTHING",
        );
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["3".to_string()]
        );
        env.run(
            "INSERT INTO fts_t_conflict (id, title, body) VALUES (1, 'dup', 'dup') ON CONFLICT DO NOTHING",
        );
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT),
            vec!["3".to_string()]
        );
    }

    /// uuid and char(n) ids go through the drain's `= ANY(...::uuid[])` and `::bpchar[]` reads:
    /// the padded id of a char(n) key and the canonical text of a uuid round-trip through
    /// insert, update and delete.
    #[pg_test]
    fn doc_drain_round_trips_uuid_and_padded_char_ids_through_update_and_delete() {
        let (_backend, docs) = fts_mock();
        let cases = [
            (
                "uuid",
                "'123E4567-E89B-12D3-A456-426614174000'",
                "123e4567-e89b-12d3-a456-426614174000",
            ),
            ("char(8)", "'ab'", "ab"),
        ];
        for (n, (key_type, literal, id)) in cases.iter().enumerate() {
            let table = format!("fts_t_roundtrip_{n}");
            fts_run(&format!(
                "CREATE TABLE {table} (id {key_type} PRIMARY KEY, body text)"
            ));
            fts_track_minimal(&table);
            fts_drain(&table);
            let namespace = fts_namespace(&table);

            fts_run(&format!("INSERT INTO {table} VALUES ({literal}, 'one')"));
            fts_drain(&table);
            let doc = docs.remote_doc(&namespace, id);
            assert_eq!(doc.expect("delivered")["body"], json!("one"), "{key_type}");
            fts_run(&format!(
                "UPDATE {table} SET body = 'two' WHERE id = {literal}"
            ));
            fts_drain(&table);
            let doc = docs.remote_doc(&namespace, id);
            assert_eq!(doc.expect("updated")["body"], json!("two"), "{key_type}");
            fts_run(&format!("DELETE FROM {table} WHERE id = {literal}"));
            fts_drain(&table);
            assert!(docs.remote_ids(&namespace).is_empty(), "{key_type} deleted");
        }
    }

    /// m3: the trigger reads the rows of its statement once for all its checks and the enqueue
    /// (an UPDATE also joins the old and new transition tables): 100,000 rows still come out as
    /// 100 queue rows of 1,000 ids, and an UPDATE that changes nothing queues nothing.
    #[pg_test]
    fn doc_outbox_update_of_a_hundred_thousand_rows_queues_one_row_per_thousand_ids() {
        let env = FtsEnv::tracked("fts_m3_bulk");
        env.run(
            "INSERT INTO fts_m3_bulk (id, title, body) \
             SELECT i, 't', 'b' FROM generate_series(1, 100000) i",
        );
        env.run(&format!("DELETE FROM {FTS_QUEUE}"));

        env.run("UPDATE fts_m3_bulk SET body = 'c'");

        let rows = env.queue();
        assert_eq!(rows.len(), 100, "100,000 ids in rows of 1,000");
        let ids: usize = rows
            .iter()
            .map(|row| row["payload"].as_array().map_or(0, Vec::len))
            .sum();
        assert_eq!(ids, 100_000);
        assert!(rows.iter().all(|row| row["op"] == json!(FTS_OP_UPSERT)));
        env.run(&format!("DELETE FROM {FTS_QUEUE}"));
        env.run("UPDATE fts_m3_bulk SET body = body");
        assert!(env.queue().is_empty(), "no declared column changed");
    }

    /// m5/m6: under `on_oversize => 'error'` punctuation-dense text counts by its alphanumeric
    /// runs (4,000 words of "a,b,c" are 12,000 tokens), and a value whose only problem is one long
    /// word is refused for that, not for its size.
    #[pg_test]
    fn doc_outbox_error_policy_counts_tokens_and_names_a_long_word() {
        let (_backend, _docs) = fts_mock();
        fts_run("CREATE TABLE fts_m5_policy (id bigint PRIMARY KEY, body text)");
        let args = "text_columns => '{\"body\": {\"on_oversize\": \"error\"}}'::jsonb";
        fts_run(&fts_track_sql("fts_m5_policy", args));
        fts_drain("fts_m5_policy");

        let dense = fts_sql_error("INSERT INTO fts_m5_policy VALUES (1, repeat('a,b,c ', 4000))");
        fts_assert_error(
            &dense,
            "54000",
            &["column \"body\"", "~12000 tokens", "10000 tokens"],
        );
        let url = "'see ' || repeat('u', 300) || ' here'";
        let long = fts_sql_error(&format!("INSERT INTO fts_m5_policy VALUES (2, {url})"));
        let parts = [
            "column \"body\"",
            "contains a 300-byte token",
            "256 bytes per token",
        ];
        fts_assert_error(&long, "54000", &parts);
        assert!(!long.message.contains("100 KB"), "{long:?}");
        fts_assert_hint(&long, "on_oversize => 'truncate'");
        fts_run("INSERT INTO fts_m5_policy VALUES (3, repeat('a b ', 2000))");
        assert_eq!(fts_heap_ids("fts_m5_policy"), fts_set(&["3"]));
    }

    /// Review test 5: a TRUNCATE and later inserts in one batch where the wipe fails: the rows
    /// before the barrier are done (superseded), nothing of them is sent, the retry wipes and
    /// then upserts what came after.
    #[pg_test]
    fn doc_drain_a_failed_wipe_resends_nothing_from_before_the_barrier() {
        let env = FtsEnv::seeded("fts_t_barrier", 3);
        env.run("INSERT INTO fts_t_barrier (id, title, body) VALUES (4, 'before', 'barrier')");
        env.run("TRUNCATE fts_t_barrier");
        env.run("INSERT INTO fts_t_barrier (id, title, body) VALUES (5, 'after', 'a'), (6, 'after', 'b')");
        env.docs.fail_always(Endpoint::Delete, 503, "unavailable");

        assert_eq!(env.round(), "backoff");

        assert_eq!(
            env.remote_ids(),
            fts_set(&["1", "2", "3"]),
            "the wipe did not happen"
        );
        assert!(fts_sent_counts(&env.docs).is_empty(), "no upsert went out");
        let ops = fts_queue_ops(&env.table);
        assert_eq!(
            ops,
            vec![FTS_OP_TRUNCATE.to_string(), FTS_OP_UPSERT.to_string()]
        );
        assert_eq!(
            fts_queue_ids(&env.table, FTS_OP_UPSERT).len(),
            2,
            "5 and 6 wait"
        );

        env.docs.heal_all();
        env.drain();
        assert_eq!(
            env.remote_ids(),
            fts_set(&["5", "6"]),
            "wiped, then 5 and 6"
        );
        assert!(
            !fts_sent_counts(&env.docs).contains_key("4"),
            "4 was never sent"
        );
    }

    fn fts_lane_failures(table: &str) -> i32 {
        let sql = format!(
            "SELECT lane_failures FROM {FTS_REGISTRY} WHERE relid = {}",
            fts_rel(table)
        );
        let count = Spi::get_one::<i32>(&sql).expect("lane_failures");
        count.unwrap_or_else(|| panic!("{table} is not registered"))
    }

    /// Makes the request after the first of every step fail permanently (401), as a lane does
    /// that delivers a row and then runs into its cause.
    fn fts_fail_after_one_request(docs: &DocsHandle) {
        let (docs, requests) = (docs.clone(), std::rc::Rc::new(std::cell::Cell::new(0)));
        crate::docs_drain::hooks::set_before_request(Some(Box::new(move || {
            requests.set(requests.get() + 1);
            if requests.get() == 2 {
                docs.fail_always(Endpoint::Upsert, 401, "invalid api key");
            }
        })));
    }

    /// m9: consecutive permanent failures count on the lane, not on whichever queue row is the
    /// oldest: a step that delivers a row and then fails moves the failure to the next row, which
    /// used to start from zero, so a lane failing like that never parked.
    #[pg_test]
    fn doc_lane_parks_after_consecutive_permanent_failures_whichever_row_is_oldest() {
        let env = FtsEnv::tracked("fts_m9_count");
        fts_run("SET pinecone.outbox_max_attempts = 2");
        fts_insert_series(&env.table, 3_000);
        let relid = relid_of(&env.table);

        fts_fail_after_one_request(&env.docs);
        let first = crate::docs_drain::drain_doc_step(relid);
        assert!(
            matches!(first, DocDrainOutcome::Backoff(_)),
            "first = {first:?}"
        );
        assert_eq!(fts_lane_failures(&env.table), 1);
        assert!(!fts_lane_parked(&env.table));
        assert_eq!(
            env.queue().len(),
            2,
            "the delivered row is done, the next one failed"
        );

        env.docs.heal_all();
        fts_fail_after_one_request(&env.docs);
        let second = crate::docs_drain::drain_doc_step(relid);
        crate::docs_drain::hooks::set_before_request(None);
        assert!(
            matches!(second, DocDrainOutcome::Parked(_)),
            "second = {second:?}"
        );
        assert!(fts_lane_parked(&env.table));
        assert_eq!(env.queue().len(), 1, "row two went out, row three waits");
    }

    /// m9: a step that gets through resets the count, and so does `unpark_docs`.
    #[pg_test]
    fn doc_lane_failure_count_resets_on_success_and_on_unpark() {
        let env = FtsEnv::tracked("fts_m9_reset");
        fts_run("SET pinecone.outbox_max_attempts = 3");
        env.run("INSERT INTO fts_m9_reset (id, title) VALUES (1, 'a')");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        assert_eq!(env.round(), "backoff");
        assert_eq!(fts_lane_failures(&env.table), 1);

        env.docs.heal_all();
        env.drain();
        assert_eq!(fts_lane_failures(&env.table), 0, "a step that got through");

        env.run("INSERT INTO fts_m9_reset (id, title) VALUES (2, 'b')");
        fts_run("SET pinecone.outbox_max_attempts = 1");
        env.docs
            .fail_always(Endpoint::Upsert, 401, "invalid api key");
        assert_eq!(env.round(), "parked");
        assert_eq!(fts_lane_failures(&env.table), 1);
        env.run(&format!("SELECT {FTS_UNPARK}({})", fts_rel(&env.table)));
        assert_eq!(fts_lane_failures(&env.table), 0, "unparked");
        assert!(!fts_lane_parked(&env.table));
    }

