    fn fts_registry_owner() -> String {
        let sql = format!(
            "SELECT pg_catalog.pg_get_userbyid(relowner)::text FROM pg_catalog.pg_class \
             WHERE oid = '{FTS_REGISTRY}'::pg_catalog.regclass"
        );
        let owner = Spi::get_one::<String>(&sql).expect("registry owner");
        owner.expect("the registry has an owner")
    }

    fn fts_hostile_role(tag: &str) -> (String, String) {
        let role = fts_create_reader(&format!("fts_b1_{tag}"));
        let schema = format!("fts_b1_{tag}_evil_{}", std::process::id());
        fts_run(&format!("GRANT CREATE ON SCHEMA public TO {role}"));
        fts_run(&format!("CREATE SCHEMA {schema} AUTHORIZATION {role}"));
        (role, schema)
    }

    fn fts_ran_as(schema: &str, who: &str) -> BTreeMap<String, usize> {
        let sql = format!("SELECT who, via FROM {schema}.ran");
        let rows: Vec<(String, String)> = Spi::connect(|client| {
            let rows = client.select(&sql, None, &[]).expect("read the log");
            rows.map(|row| {
                let who = row.get_by_name::<String, _>("who");
                let via = row.get_by_name::<String, _>("via");
                (who.unwrap().unwrap(), via.unwrap().unwrap())
            })
            .collect()
        });
        let mut counts = BTreeMap::new();
        for (_, via) in rows.into_iter().filter(|(by, _)| by == who) {
            *counts.entry(via).or_insert(0) += 1;
        }
        counts
    }

    fn fts_plant_operator_and_aggregate(schema: &str) {
        let statements = [
            format!("CREATE TABLE {schema}.ran (who text, via text)"),
            format!(
                "CREATE FUNCTION {schema}.same(a pg_catalog.oid, b pg_catalog.oid) \
                 RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN \
                 INSERT INTO {schema}.ran VALUES (current_user, 'operator ='); \
                 RETURN a OPERATOR(pg_catalog.=) b; END $$"
            ),
            format!(
                "CREATE OPERATOR {schema}.= (LEFTARG = pg_catalog.oid, \
                 RIGHTARG = pg_catalog.oid, FUNCTION = {schema}.same)"
            ),
            format!(
                "CREATE FUNCTION {schema}.tick(n bigint) RETURNS bigint LANGUAGE plpgsql AS $$ \
                 BEGIN INSERT INTO {schema}.ran VALUES (current_user, 'aggregate count(*)'); \
                 RETURN n + 1; END $$"
            ),
            format!(
                "CREATE AGGREGATE {schema}.count(*) \
                 (SFUNC = {schema}.tick, STYPE = bigint, INITCOND = '0')"
            ),
        ];
        statements.iter().for_each(|sql| fts_run(sql));
    }

    /// A table owner who can create objects in any schema must not get an operator or aggregate of
    /// its own run as the registry owner by putting that schema first on its `search_path`.
    #[pg_test]
    fn docs_verbs_never_run_a_hostile_operator_or_aggregate_as_the_registry_owner() {
        let (_backend, docs) = fts_mock();
        let owner = fts_registry_owner();
        let (role, schema) = fts_hostile_role("ops");
        fts_run(&format!("GRANT SELECT ON pinecone.tables TO {role}"));
        fts_run(&format!("SET ROLE {role}"));
        fts_plant_operator_and_aggregate(&schema);
        fts_run("CREATE TABLE fts_b1_ops (id bigint PRIMARY KEY, body text)");
        fts_run("INSERT INTO fts_b1_ops VALUES (1, 'a'), (2, 'b')");
        let table = "public.fts_b1_ops";
        let args = "text_columns => '{\"body\": {}}'::jsonb, index_name => 'fts-b1-ops'";
        docs.set_search_matches(&[("2", 2.0), ("1", 1.0)]);

        fts_run(&format!("SET search_path = {schema}, pg_catalog"));
        fts_run(&fts_track_sql(table, args));
        let status = fts_status_row("fts_b1_ops");
        let found = fts_search_rows(&fts_search_args(table, "x", ""));
        let (_flushed, _warnings) = fts_flush(table, 100);
        fts_run(&format!("SELECT {FTS_BACKFILL}({})", fts_rel(table)));
        fts_run("RESET search_path");
        fts_run("RESET ROLE");

        let as_owner = fts_ran_as(&schema, &owner);
        assert!(
            as_owner.is_empty(),
            "hostile code ran as the registry owner {owner}: {as_owner:?}"
        );
        assert_eq!(status["table_name"], json!(table), "status() still works");
        assert_eq!(found.len(), 2, "search_docs still answers: {found:?}");
        fts_assert_registered("fts_b1_ops");
        assert_eq!(fts_queue_ops("fts_b1_ops"), ["doc_backfill"]);
    }

    fn fts_plant_shadow_types(schema: &str) {
        let statements = [
            format!("CREATE TABLE {schema}.ran (who text, via text)"),
            format!(
                "CREATE FUNCTION {schema}.note_oid(v pg_catalog.oid) RETURNS boolean \
                 LANGUAGE plpgsql AS $$ BEGIN \
                 INSERT INTO {schema}.ran VALUES (current_user, 'domain oid'); \
                 RETURN true; END $$"
            ),
            format!(
                "CREATE DOMAIN {schema}.oid AS pg_catalog.oid CHECK ({schema}.note_oid(VALUE))"
            ),
            format!(
                "CREATE FUNCTION {schema}.note_regclass(v pg_catalog.regclass) RETURNS boolean \
                 LANGUAGE plpgsql AS $$ BEGIN \
                 INSERT INTO {schema}.ran VALUES (current_user, 'domain regclass'); \
                 RETURN true; END $$"
            ),
            format!(
                "CREATE DOMAIN {schema}.regclass AS pg_catalog.regclass \
                 CHECK ({schema}.note_regclass(VALUE))"
            ),
        ];
        statements.iter().for_each(|sql| fts_run(sql));
    }

