    /// Regression test: `enqueue_upsert`'s
    /// owner lookup used to be an SPI query casting an unqualified
    /// `internal` type name (`'pinecone._am_handler(internal)'::regprocedure`),
    /// and its outbox insert used to cast its `relid` parameter with an
    /// unqualified textual `$1::oid::regclass` — both resolved by *name*
    /// against the caller's own `search_path`, so a writer with only
    /// `INSERT` on the table (no grant on `pinecone.outbox`/`pinecone.tables`
    /// at all) could shadow `oid`/`regclass` with same-named types in a
    /// schema of their own, put that schema ahead of `pg_catalog` on their
    /// session's `search_path`, and have it resolve there instead of the
    /// real system catalog type. `am::am_handler_owner` (a syscache lookup
    /// keyed by oid, never by name) and `am::insert_outbox_row` (a typed
    /// `oid` datum, no textual cast) make that attack surface disappear
    /// entirely — proven here by attempting it and observing the insert
    /// still succeeds and enqueues correctly regardless.
    #[pg_test]
    fn am_aminsert_security_definer_ignores_hostile_search_path() {
        install_am_opclasses();
        let table = "am_insert_hostile_path";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");
        Spi::run(&format!(
            "DELETE FROM pinecone.outbox WHERE relid = '{table}'::regclass"
        ))
        .expect("clear ambuild's own backfill row");

        let role = format!("pinecone_am_hostile_writer_{}", std::process::id());
        let hostile_schema = format!("pinecone_am_hostile_schema_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT INSERT ON {table} TO {role}")).expect("grant insert");
        Spi::run(&format!(
            "CREATE SCHEMA {hostile_schema} AUTHORIZATION {role}"
        ))
        .expect("create hostile schema owned by the writer");
        // Decoy types shadowing the exact two pg_catalog types the pre-fix
        // code path resolved by unqualified name (`regprocedure`'s own
        // signature parse and `$1::oid::regclass`'s cast target) — inert
        // against the fixed code, which never names either unqualified.
        Spi::run(&format!("CREATE DOMAIN {hostile_schema}.oid AS text"))
            .expect("create decoy oid domain");
        Spi::run(&format!("CREATE DOMAIN {hostile_schema}.regclass AS text"))
            .expect("create decoy regclass domain");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        // Explicitly names pg_catalog (rather than leaving it implicit) so
        // it's searched *after* the attacker's own schema instead of always
        // first — the classic SECURITY DEFINER search_path attack shape.
        Spi::run(&format!(
            "SET search_path = {hostile_schema}, public, pg_catalog"
        ))
        .expect("hostile search_path — attacker schema searched before pg_catalog");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
        ))
        .expect("insert under a hostile search_path should still succeed harmlessly");
        Spi::run("RESET search_path").expect("reset search_path");
        Spi::run("RESET ROLE").expect("RESET ROLE");

        Spi::run(&format!("REVOKE INSERT ON {table} FROM {role}")).expect("revoke insert");
        Spi::run(&format!("DROP SCHEMA {hostile_schema} CASCADE")).expect("drop hostile schema");
        Spi::run(&format!("DROP ROLE {role}")).expect("drop role");

        let ctids = ctid_map(table);
        let (op, payload): (String, JsonB) = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT op, payload FROM pinecone.outbox WHERE relid = '{table}'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("select outbox")
                .next()
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("op").unwrap().unwrap(),
                        row.get_by_name::<JsonB, _>("payload").unwrap().unwrap(),
                    )
                })
                .expect("aminsert enqueues exactly one row despite the hostile search_path")
        });
        assert_eq!(op, "upsert");
        assert_eq!(
            payload.0,
            json!([{"id": ctids.get("1").unwrap(), "values": [1.0, 0.0, 0.0]}])
        );
    }

    /// Regression test: `SecurityDefinerGuard`'s
    /// `Drop` must restore the caller's real userid even when the elevated
    /// statement it wraps (`am::insert_outbox_row`) itself raises — a
    /// Postgres `ERROR` there surfaces to Rust as a stack-unwinding panic
    /// (not a `longjmp` that would skip destructors), so `Drop` still runs
    /// on the way out. Forced here with a `BEFORE INSERT` trigger on
    /// `pinecone.outbox` that always raises.
    #[pg_test]
    fn am_aminsert_restores_userid_after_forced_enqueue_failure() {
        install_am_opclasses();
        let table = "am_insert_raii";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");

        Spi::run(
            "CREATE FUNCTION pg_pinecone_test_outbox_boom() RETURNS trigger LANGUAGE plpgsql AS \
             $$ BEGIN RAISE EXCEPTION 'forced outbox failure'; END $$;",
        )
        .expect("create trigger function");
        Spi::run(
            "CREATE TRIGGER pg_pinecone_test_outbox_boom BEFORE INSERT ON pinecone.outbox \
             FOR EACH ROW EXECUTE FUNCTION pg_pinecone_test_outbox_boom()",
        )
        .expect("create trigger forcing every outbox insert to fail");

        let role = format!("pinecone_am_raii_writer_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT INSERT ON {table} TO {role}")).expect("grant insert");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let current_user_after_failure = Spi::get_one::<String>("SELECT current_user::text")
            .expect("current_user query")
            .expect("current_user is NOT NULL");
        Spi::run("RESET ROLE").expect("RESET ROLE");

        Spi::run(&format!("REVOKE INSERT ON {table} FROM {role}")).expect("revoke insert");
        Spi::run(&format!("DROP ROLE {role}")).expect("drop role");
        Spi::run("DROP TRIGGER pg_pinecone_test_outbox_boom ON pinecone.outbox")
            .expect("drop trigger");
        Spi::run("DROP FUNCTION pg_pinecone_test_outbox_boom()").expect("drop trigger function");

        let message = outcome.expect_err("expected the forced outbox failure to propagate");
        assert!(
            message.contains("forced outbox failure"),
            "message = {message}"
        );
        assert_eq!(
            current_user_after_failure, role,
            "SecurityDefinerGuard must restore the caller's userid even when its own elevated \
             enqueue statement raises"
        );
    }

    /// `pg_relation_size(table)` (bytes) — used to prove a rejected remote-id
    /// sentinel never triggers `ReadBufferExtended`'s "extend the relation"
    /// behavior against the heap (`am::id_to_tid`'s own rustdoc).
    fn heap_relation_size(table: &str) -> i64 {
        Spi::get_one::<i64>(&format!("SELECT pg_relation_size('{table}')"))
            .expect("pg_relation_size query")
            .expect("pg_relation_size is NOT NULL")
    }

    /// Regression test: shared body for the two
    /// sentinel-id tests below. A remote match id encoding one of
    /// `id_to_tid`'s two rejected sentinels (`block == InvalidBlockNumber`/
    /// `offset == 0`) must error clearly *and* leave the heap's own page
    /// count untouched — passing either down to the executor's own tuple
    /// fetch would otherwise silently `ReadBufferExtended` (P_NEW) a new
    /// page while looking for a tuple that was never there.
    fn assert_sentinel_remote_id_rejected_without_heap_growth(table: &str, bad_id: &'static str) {
        install_am_opclasses();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
        ))
        .expect("insert row");

        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                Mock::given(method("POST"))
                    .and(path("/query"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "matches": [{"id": bad_id, "score": 0.0}]
                    })))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");
        Spi::run("SET enable_seqscan = off").expect("disable seqscan");

        let size_before = heap_relation_size(table);

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector LIMIT 3"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("expected a malformed-id error");
        assert!(
            message.contains("malformed remote id"),
            "message = {message}"
        );
        assert!(message.contains(bad_id), "message = {message}");
        assert_eq!(
            heap_relation_size(table),
            size_before,
            "a rejected sentinel TID must never grow the heap"
        );
    }

    #[pg_test]
    fn am_scan_rejects_invalid_block_number_remote_id() {
        assert_sentinel_remote_id_rejected_without_heap_growth("am_scan_bad_block", "4294967295:1");
    }

    #[pg_test]
    fn am_scan_rejects_invalid_offset_remote_id() {
        assert_sentinel_remote_id_rejected_without_heap_growth("am_scan_bad_offset", "1:0");
    }

    /// Regression test: re-running `ambuild` on
    /// an already-registered pg_pinecone access-method index (a REINDEX) must
    /// refresh the existing registry row in place — not duplicate it — and
    /// fully repopulate the remote index via `delete_all` then `backfill`,
    /// while leaving the Pinecone index's own identity (`index_name`/
    /// `namespace`) untouched.
    #[pg_test]
    fn am_reindex_rebuilds_registry_row_and_enqueues_delete_all_then_backfill() {
        install_am_opclasses();
        let table = "am_reindex_rebuild";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");

        let (index_name_before, namespace_before): (Option<String>, Option<String>) =
            Spi::connect(|client| {
                client
                    .select(
                        &format!(
                            "SELECT index_name, namespace FROM pinecone.tables \
                             WHERE relid = '{table}'::regclass"
                        ),
                        None,
                        &[],
                    )
                    .expect("select registry row before REINDEX")
                    .next()
                    .map(|row| {
                        (
                            row.get_by_name::<String, _>("index_name").unwrap(),
                            row.get_by_name::<String, _>("namespace").unwrap(),
                        )
                    })
                    .expect("registry row exists before REINDEX")
            });

        Spi::run(&format!(
            "DELETE FROM pinecone.outbox WHERE relid = '{table}'::regclass"
        ))
        .expect("clear ambuild's own backfill row before REINDEX");

        Spi::run(&format!("REINDEX INDEX {table}_idx")).expect("REINDEX succeeds");

        let registry_rows: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM pinecone.tables WHERE relid = '{table}'::regclass"
        ))
        .expect("count registry rows")
        .expect("count is NOT NULL");
        assert_eq!(
            registry_rows, 1,
            "REINDEX must refresh the existing registry row in place, not duplicate it"
        );

        let (index_name_after, namespace_after): (Option<String>, Option<String>) =
            Spi::connect(|client| {
                client
                    .select(
                        &format!(
                            "SELECT index_name, namespace FROM pinecone.tables \
                             WHERE relid = '{table}'::regclass"
                        ),
                        None,
                        &[],
                    )
                    .expect("select registry row after REINDEX")
                    .next()
                    .map(|row| {
                        (
                            row.get_by_name::<String, _>("index_name").unwrap(),
                            row.get_by_name::<String, _>("namespace").unwrap(),
                        )
                    })
                    .expect("registry row exists after REINDEX")
            });
        assert_eq!(
            index_name_after, index_name_before,
            "REINDEX must not change the Pinecone index's own identity"
        );
        assert_eq!(namespace_after, namespace_before);

        let ops: Vec<String> = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT op FROM pinecone.outbox WHERE relid = '{table}'::regclass \
                         ORDER BY id"
                    ),
                    None,
                    &[],
                )
                .expect("select outbox rows after REINDEX")
                .map(|row| row.get_by_name::<String, _>("op").unwrap().unwrap())
                .collect()
        });
        assert_eq!(
            ops,
            vec!["delete_all".to_string(), "backfill".to_string()],
            "REINDEX must enqueue delete_all then backfill to fully repopulate the remote index"
        );
    }

    /// **Regression test:** a
    /// second `CREATE INDEX ... USING pinecone` of *identical* shape (same
    /// column/metric/dimension) on the same table used to silently fall into
    /// `ambuild`'s REBUILD arm — clobbering `am_index_relid` to the new
    /// index's oid while the first stays fully alive: both then enqueue
    /// their own `aminsert` upserts (double-enqueue on every write), and
    /// dropping the orphaned first no longer matches `pg_pinecone_on_sql_drop`'s
    /// oid lookup, leaking its state forever. Must now be a clear ERROR;
    /// genuine rebuilds (same oid — REINDEX/VACUUM FULL/CLUSTER) keep
    /// working, covered by
    /// `am_reindex_rebuilds_registry_row_and_enqueues_delete_all_then_backfill`
    /// just above.
    #[pg_test]
    fn am_second_identical_create_index_errors_instead_of_becoming_a_rebuild() {
        install_am_opclasses();
        let table = "am_second_index";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("first pg_pinecone access-method index");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "CREATE INDEX {table}_idx2 ON {table} USING pinecone (embedding vector_cosine_ops)"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        // The message assertion alone proves the guard arm fired instead of
        // the REBUILD arm ever running — and since `error!` aborts the whole
        // CREATE INDEX statement's transaction, nothing the second build
        // wrote (registry hijack included) can persist. No post-catch
        // registry re-read: a Postgres error raised *inside a utility
        // command* leaves this test's single caught-not-subtransactioned
        // transaction unable to see its own earlier catalog writes (same
        // pgrx-tests limitation family as the ignored real-VACUUM test),
        // so re-querying `pinecone.tables` here fails on the fixture table's
        // own name resolution, not on anything this fix governs.
        let message = outcome.expect_err("expected a one-index-per-table error");
        assert!(
            message.contains("only one pg_pinecone access-method index per table"),
            "message = {message}"
        );
    }

    /// A mock whose `/query` answers every request with exactly `topK`
    /// matches (so the remote scan is never "exhausted"): the first five are
    /// `table`'s real rows, the rest TIDs no row occupies (offsets wrap at 1,900
    /// to stay below `MaxOffsetNumber`). Returns the mock
    /// (keep it alive) and the log of every requested `topK`.
    fn mount_endless_remote_query(table: &str) -> (MockBackend, Arc<Mutex<Vec<u64>>>) {
        let ctids = ctid_map(table);
        let topks = Arc::new(Mutex::new(Vec::new()));
        let topks_for_mock = Arc::clone(&topks);
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
            Mock::given(method("POST"))
                .and(path("/query"))
                .respond_with(move |req: &Request| {
                    let body: Value = req.body_json().expect("query body is JSON");
                    let top_k = body["topK"].as_u64().expect("topK");
                    topks_for_mock
                        .lock()
                        .expect("topks lock poisoned")
                        .push(top_k);
                    let matches: Vec<Value> = (0..top_k as usize)
                        .map(|j| {
                            let id = ctids
                                .get(&(j + 1).to_string())
                                .cloned()
                                .unwrap_or_else(|| format!("0:{}", 100 + j % 1_900));
                            json!({"id": id, "score": 0.0})
                        })
                        .collect();
                    ResponseTemplate::new(200).set_body_json(json!({"matches": matches}))
                })
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);
        (backend, topks)
    }

    /// Regression test: a scan that outgrows
    /// `pinecone.am_max_topk` regrows once more to exactly the cap (the last
    /// x4 is clamped: 3, 10 rather than an error at 12), then errors clearly
    /// instead of growing past it. Under the default `iterative_scan = auto`, which a remote index
    /// reads as `off`.
    #[pg_test]
    fn am_scan_growth_past_max_topk_errors_clearly() {
        install_am_opclasses();
        let table = "am_scan_topk_capped";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) \
             SELECT i, ARRAY[i::real, 0, 0]::vector FROM generate_series(1, 5) AS i"
        ))
        .expect("insert rows");
        Spi::run("SET pinecone.am_min_topk = 3").expect("set am_min_topk");
        Spi::run("SET pinecone.am_max_topk = 10").expect("set am_max_topk");

        let (_backend, topks) = mount_endless_remote_query(table);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");
        Spi::run("SET enable_seqscan = off").expect("disable seqscan");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector LIMIT 20"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("expected an am_max_topk-exceeded error");
        assert!(
            message.contains("pinecone.am_max_topk"),
            "message = {message}"
        );
        assert!(message.contains("(10)"), "message = {message}");
        assert_eq!(topks.lock().unwrap().clone(), vec![3, 10], "clamped regrow");
    }

    /// Under `relaxed_order`/`strict_order` a remote scan's cap is
    /// `pinecone.max_scan_tuples` rows fetched and it ends quietly, no error;
    /// `am_max_topk` still bounds every request (Pinecone rejects a larger
    /// `topK`).
    #[pg_test]
    fn am_scan_iterative_modes_end_quietly_at_max_scan_tuples() {
        install_am_opclasses();
        let table = "am_scan_iter_capped";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) \
             SELECT i, ARRAY[i::real, 0, 0]::vector FROM generate_series(1, 5) AS i"
        ))
        .expect("insert rows");
        Spi::run("SET pinecone.am_min_topk = 3").expect("set am_min_topk");
        let (_backend, topks) = mount_endless_remote_query(table);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");
        Spi::run("SET enable_seqscan = off").expect("disable seqscan");

        let run = |topks: &Arc<Mutex<Vec<u64>>>| -> Vec<i64> {
            topks.lock().unwrap().clear();
            Spi::connect(|client| {
                client
                    .select(
                        &format!(
                            "SELECT id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector \
                             LIMIT 20"
                        ),
                        None,
                        &[],
                    )
                    .expect("select")
                    .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                    .collect()
            })
        };

        for mode in ["relaxed_order", "strict_order"] {
            set_iterative_scan(mode);
            Spi::run("SET pinecone.max_scan_tuples = 10").expect("set max_scan_tuples");
            Spi::run("SET pinecone.am_max_topk = 10000").expect("set am_max_topk");
            assert_eq!(run(&topks), vec![1, 2, 3, 4, 5], "{mode}");
            assert_eq!(topks.lock().unwrap().clone(), vec![3, 10], "{mode}");
            assert_eq!(last_scan_stats(), (2, 10, true), "{mode}");

            Spi::run("RESET pinecone.max_scan_tuples").expect("reset max_scan_tuples");
            Spi::run("SET pinecone.am_max_topk = 6").expect("set am_max_topk");
            assert_eq!(run(&topks), vec![1, 2, 3, 4, 5], "{mode}");
            assert_eq!(topks.lock().unwrap().clone(), vec![3, 6], "{mode}");
            assert_eq!(last_scan_stats(), (2, 6, true), "{mode}");
        }
    }

    /// m7: at the default GUCs an endless remote scan asks for 100, 400, 1600,
    /// 6400 and 10000 rows. `relaxed_order` ends there quietly (a small
    /// `max_scan_tuples` never cuts the first query); `off` sends the same
    /// five, then errors.
    #[pg_test]
    fn am_scan_default_topk_sequence_is_100_400_1600_6400_10000() {
        install_am_opclasses();
        let table = "am_scan_default_seq";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) \
             SELECT i, ARRAY[i::real, 0, 0]::vector FROM generate_series(1, 5) AS i"
        ))
        .expect("insert rows");
        let (_backend, topks) = mount_endless_remote_query(table);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create index");
        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        let query =
            format!("SELECT id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector LIMIT 20");
        let run = |topks: &Arc<Mutex<Vec<u64>>>| -> Vec<i64> {
            topks.lock().unwrap().clear();
            Spi::connect(|client| {
                client
                    .select(&query, None, &[])
                    .expect("select")
                    .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                    .collect()
            })
        };

        set_iterative_scan("relaxed_order");
        assert_eq!(run(&topks), vec![1, 2, 3, 4, 5]);
        assert_eq!(
            topks.lock().unwrap().clone(),
            vec![100, 400, 1_600, 6_400, 10_000]
        );
        assert_eq!(last_scan_stats(), (5, 10_000, true));

        Spi::run("SET pinecone.max_scan_tuples = 10").expect("set max_scan_tuples");
        assert_eq!(run(&topks), vec![1, 2, 3, 4, 5]);
        assert_eq!(
            topks.lock().unwrap().clone(),
            vec![100],
            "first query is never cut"
        );
        assert_eq!(last_scan_stats(), (1, 100, true));
        Spi::run("RESET pinecone.max_scan_tuples").expect("reset max_scan_tuples");

        // Last: the ERROR leaves the test transaction unusable for SQL.
        set_iterative_scan("off");
        topks.lock().unwrap().clear();
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&query).expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome.expect_err("expected an am_max_topk-exceeded error");
        assert!(
            message.contains("pinecone.am_max_topk"),
            "message = {message}"
        );
        assert!(message.contains("(10000)"), "message = {message}");
        assert_eq!(
            topks.lock().unwrap().clone(),
            vec![100, 400, 1_600, 6_400, 10_000]
        );
    }

    /// `strict_order` over a remote scan skips a re-queried row that ranks
    /// before the last row already served (score sign per metric);
    /// `relaxed_order` serves it.
    #[pg_test]
    fn am_scan_iterative_strict_order_skips_remote_rows_ranking_before_the_last_served() {
        install_am_opclasses();
        // (opclass, operator, metric, first-batch scores, scores of the 12-row
        // re-query in served order). Row 4 beats the last row served (row 3).
        let cases = [
            (
                "vector_cosine_ops",
                "<=>",
                "cosine",
                [0.9, 0.8, 0.7],
                [
                    0.9, 0.8, 0.7, 0.75, 0.6, 0.5, 0.4, 0.3, 0.2, 0.1, 0.05, 0.01,
                ],
            ),
            (
                "vector_l2_ops",
                "<->",
                "l2",
                [1.0, 4.0, 9.0],
                [
                    1.0, 4.0, 9.0, 6.25, 16.0, 25.0, 36.0, 49.0, 64.0, 81.0, 100.0, 121.0,
                ],
            ),
            // Dot product ranks the highest score first; the distance is its negative.
            (
                "vector_ip_ops",
                "<#>",
                "ip",
                [0.9, 0.8, 0.7],
                [
                    0.9, 0.8, 0.7, 0.75, 0.6, 0.5, 0.4, 0.3, 0.2, 0.1, 0.05, 0.01,
                ],
            ),
        ];
        for (opclass, op, metric, scores1, scores2) in cases {
            let table = format!("am_scan_strict_{metric}");
            Spi::run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
            ))
            .expect("create table");
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding) \
                 SELECT i, ARRAY[i::real, 0, 0]::vector FROM generate_series(1, 12) AS i"
            ))
            .expect("insert rows");
            Spi::run("SET pinecone.am_min_topk = 3").expect("set am_min_topk");

            let ctids = ctid_map(&table);
            let ranked = |scores: &[f64]| -> Vec<Value> {
                scores
                    .iter()
                    .enumerate()
                    .map(|(j, s)| json!({"id": ctids[&(j + 1).to_string()], "score": s}))
                    .collect()
            };
            let (batch1, batch2) = (ranked(&scores1), ranked(&scores2));
            let index_name = crate::promote::default_index_name("public", &table);
            let backend = MockBackend::start({
                let (index_name, table) = (index_name.clone(), table.clone());
                move |control_plane, data_plane| async move {
                    let pinecone_metric = match metric {
                        "l2" => "euclidean",
                        "ip" => "dotproduct",
                        other => other,
                    };
                    mount_am_build_success(
                        &control_plane,
                        &data_plane,
                        &index_name,
                        3,
                        pinecone_metric,
                    )
                    .await;
                    for (top_k, matches) in [(3, batch1), (12, batch2)] {
                        Mock::given(method("POST"))
                            .and(path("/query"))
                            .and(body_json(json!({
                                "vector": [1.0, 0.0, 0.0],
                                "topK": top_k,
                                "includeMetadata": false,
                                "namespace": format!("public.{table}"),
                            })))
                            .respond_with(
                                ResponseTemplate::new(200)
                                    .set_body_json(json!({"matches": matches})),
                            )
                            .mount(&data_plane)
                            .await;
                    }
                    (control_plane, data_plane)
                }
            });
            point_at_mock(&backend);
            Spi::run(&format!(
                "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding {opclass})"
            ))
            .expect("create index");
            Spi::run("SET enable_seqscan = off").expect("disable seqscan");

            for (mode, expected) in [
                ("relaxed_order", vec![1, 2, 3, 4, 5, 6]),
                ("strict_order", vec![1, 2, 3, 5, 6, 7]),
            ] {
                set_iterative_scan(mode);
                let got: Vec<i64> = Spi::connect(|client| {
                    client
                        .select(
                            &format!(
                                "SELECT id FROM {table} \
                                 ORDER BY embedding {op} '[1,0,0]'::vector LIMIT 6"
                            ),
                            None,
                            &[],
                        )
                        .expect("select")
                        .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                        .collect()
                });
                assert_eq!(got, expected, "{metric} {mode}");
            }
        }
    }

