    #[pg_test]
    fn create_index_native_emits_the_plain_storage_notice_once() {
        install_am_opclasses();
        let table = "am_plain_notice_ci";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(1024))"
        ))
        .expect("create table");
        let (_, reports) = capture_notice_reports(|| {
            Spi::run(&format!(
                "SELECT pinecone.create_index('{table}', 'embedding', engine => 'native')"
            ))
            .expect("create_index native");
        });
        assert_eq!(plain_storage_notices(&reports).len(), 1);
    }

    #[pg_test]
    fn reindex_after_the_advised_statement_is_silent() {
        let table = "am_plain_notice_reindex";
        let reports = create_local_index_notices(table, 768, None);
        assert_eq!(plain_storage_notices(&reports).len(), 1);
        Spi::run(&format!(
            "ALTER TABLE public.{table} ALTER COLUMN embedding SET STORAGE PLAIN"
        ))
        .expect("advised statement");
        let (_, reports) = capture_notice_reports(|| {
            Spi::run(&format!("REINDEX INDEX {table}_idx")).expect("reindex");
        });
        assert!(plain_storage_notices(&reports).is_empty(), "now PLAIN");
    }

    // =========================================================================
    // Iterative scan (`pinecone.iterative_scan`, `pinecone.max_scan_tuples`,
    // `pinecone.last_scan_stats()`): the native AM keeps probing past its first
    // batch while the executor still wants rows (a residual qual, or a LIMIT
    // above the rescore pool).
    // =========================================================================

    /// `pinecone.last_scan_stats()`: `(batches, rescored, capped)` of this
    /// backend's most recent index scan.
    fn last_scan_stats() -> (i32, i64, bool) {
        let (batches, rescored, capped) = Spi::get_three::<i32, i64, bool>(
            "SELECT batches, rescored, capped FROM pinecone.last_scan_stats()",
        )
        .expect("last_scan_stats query");
        (
            batches.expect("batches is never NULL"),
            rescored.expect("rescored is never NULL"),
            capped.expect("capped is never NULL"),
        )
    }

    fn set_iterative_scan(mode: &str) {
        Spi::run(&format!("SET pinecone.iterative_scan = '{mode}'")).expect("set iterative_scan");
    }

    /// Back to the boot value (`auto`).
    fn reset_iterative_scan() {
        Spi::run("RESET pinecone.iterative_scan").expect("reset iterative_scan");
    }

    /// `auto` is the boot value: a native index reads it as an `off`-sized first batch and a
    /// `relaxed_order` continuation after it, a remote index as `off` (what it was).
    #[pg_test]
    fn am_iterative_scan_gucs_default_auto_and_validate() {
        assert_eq!(
            Spi::get_one::<String>("SHOW pinecone.iterative_scan").expect("SHOW iterative_scan"),
            Some("auto".to_string())
        );
        assert_eq!(
            Spi::get_one::<String>("SHOW pinecone.max_scan_tuples").expect("SHOW max_scan_tuples"),
            Some("20000".to_string())
        );
        for mode in ["relaxed_order", "strict_order", "off", "auto"] {
            set_iterative_scan(mode);
            assert_eq!(
                Spi::get_one::<String>("SHOW pinecone.iterative_scan").unwrap(),
                Some(mode.to_string())
            );
        }
        set_iterative_scan("off");
        reset_iterative_scan();
        assert_eq!(
            Spi::get_one::<String>("SHOW pinecone.iterative_scan").unwrap(),
            Some("auto".to_string()),
            "RESET returns to auto"
        );
        expect_ddl_error(
            "SET pinecone.iterative_scan = 'sideways'",
            "invalid value for parameter \"pinecone.iterative_scan\"",
        );
        expect_ddl_error(
            "SET pinecone.max_scan_tuples = 0",
            "0 is outside the valid range for parameter \"pinecone.max_scan_tuples\"",
        );
        Spi::run("SET pinecone.max_scan_tuples = 1").expect("min is 1");
    }

    /// `last_scan_stats()` counts one batch per native scan (here `off`), in
    /// mode H and mode L alike, and starts over with every scan.
    #[pg_test]
    fn am_last_scan_stats_reports_one_batch_per_native_scan() {
        install_am_opclasses();
        let table = "am_scan_stats";
        let (n, dim, n_tenants) = (3_000, 16, 100);
        let vectors = deterministic_clustered_vectors(23, n, dim, n_tenants);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant int8)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % n_tenants).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 23)"
        ))
        .expect("create filtered local index");

        let lists = Spi::get_one::<i64>(&format!(
            "SELECT count(DISTINCT list_idx) \
             FROM pinecone._debug_local_list_pages('{table}_idx'::regclass)"
        ))
        .expect("list count query")
        .expect("count is never NULL");

        nearest_ids(table, &vectors[5], 10, false);
        assert_eq!(last_scan_mode(), "h");
        let (batches, rescored, capped) = last_scan_stats();
        assert!(batches == 1 && rescored >= 10 && !capped);
        let stats = scan_stats();
        let probed = i64::from(stats.lists_probed);
        assert!(
            stats.deepened == 0 && 0 < probed && probed < lists,
            "{stats:?}"
        );

        // 30 rows carry tenant 7: mode L rescores exactly those.
        filtered_nearest_ids(table, "tenant = 7", &vectors[7], 10, false);
        assert_eq!(last_scan_mode(), "l");
        assert_eq!(last_scan_stats(), (1, 30, false));
        let stats = scan_stats();
        assert!(stats.deepened == 0, "{stats:?}");
        assert_eq!(
            i64::from(stats.lists_probed),
            lists,
            "mode L reads every list"
        );
    }

    /// `(id, distance)` rows of `SELECT .. WHERE where_sql ORDER BY embedding
    /// <-> query LIMIT k`: the pg_pinecone index path (`exact = false`) or the
    /// seqscan ground truth (`exact = true`). [`filtered_nearest_ids`] with
    /// the distances kept, for the order assertions.
    fn ranked_rows(
        table: &str,
        where_sql: &str,
        query: &[f32],
        k: usize,
        exact: bool,
    ) -> Vec<(i64, f64)> {
        Spi::run(if exact {
            "SET enable_seqscan = on"
        } else {
            "SET enable_seqscan = off"
        })
        .expect("set enable_seqscan");
        Spi::run(if exact {
            "SET pinecone.am_enabled = off"
        } else {
            "SET pinecone.am_enabled = on"
        })
        .expect("set pinecone.am_enabled");
        let q = vector_literal(query);
        let rows = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT id, (embedding <-> '{q}'::vector) AS d FROM {table} \
                         WHERE {where_sql} ORDER BY embedding <-> '{q}'::vector LIMIT {k}"
                    ),
                    None,
                    &[],
                )
                .expect("ranked_rows query")
                .map(|row| {
                    (
                        row.get_by_name::<i64, _>("id").unwrap().unwrap(),
                        row.get_by_name::<f64, _>("d").unwrap().unwrap(),
                    )
                })
                .collect()
        });
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        Spi::run("SET pinecone.am_enabled = on").expect("restore pinecone.am_enabled");
        rows
    }

    fn ids_of(rows: &[(i64, f64)]) -> Vec<i64> {
        rows.iter().map(|(id, _)| *id).collect()
    }

    /// Share of `exact` that `got` also contains.
    fn recall_of(exact: &[i64], got: &[i64]) -> f64 {
        let got: std::collections::HashSet<i64> = got.iter().copied().collect();
        exact.iter().filter(|id| got.contains(id)).count() as f64 / exact.len() as f64
    }

    /// `(id, embedding, tenant)` rows over `vectors` (`tenant = row %
    /// n_tenants`) behind a plain local pg_pinecone index: `tenant = k` is a
    /// residual qual that no index key can carry, so the executor applies it
    /// after the AM hands a row back.
    fn build_residual_table(table: &str, vectors: &[Vec<f32>], n_tenants: usize, index_with: &str) {
        let dim = vectors[0].len();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant int8)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, vectors, |i| (i % n_tenants).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', small_n_threshold = 100, {index_with})"
        ))
        .expect("create local index");
    }

    /// [`assert_filtered_plan_uses_index`]'s residual twin: the pg_pinecone index
    /// serves the plan and the qual stays an executor `Filter`, never an
    /// `Index Cond`.
    fn assert_residual_plan_uses_index(table: &str, where_sql: &str, query: &[f32], k: usize) {
        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let plan = explain_lines(&format!(
            "SELECT id FROM {table} WHERE {where_sql} \
             ORDER BY embedding <-> '{}'::vector LIMIT {k}",
            vector_literal(query)
        ))
        .join("\n");
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        assert!(
            plan.contains(&format!("{table}_idx")),
            "plan must use the pg_pinecone index: {plan}"
        );
        assert!(
            plan.contains("Filter:") && !plan.contains("Index Cond"),
            "the qual must stay a residual Filter: {plan}"
        );
    }

    /// Test 1: a residual qual passing ~0.3% of 8k rows. `off` hands the
    /// executor one batch and under-fills `LIMIT 10`; `relaxed_order` keeps
    /// probing the next lists until the executor is satisfied. The probe
    /// fraction is pinned so a batch (10 of 100 lists, ~800 rows) fits the
    /// rescore pool: the pool cut is blind to the residual qual, so list
    /// coverage is all that limits recall here.
    #[pg_test]
    fn am_iterative_scan_relaxed_fills_limit_under_a_selective_residual() {
        install_am_opclasses();
        let table = "am_iter_residual";
        let (n, dim, n_clusters, n_tenants) = (8_000, 24, 20, 333);
        let vectors = deterministic_clustered_vectors(201, n, dim, n_clusters);
        build_residual_table(table, &vectors, n_tenants, "seed = 201, n_lists = 100");
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        assert_residual_plan_uses_index(table, "tenant = 7", &vectors[7], 10);

        let mut total_recall = 0.0;
        let queries = [11usize, 1_009, 2_003, 3_001, 4_999, 5_501, 6_607, 7_919];
        for &row in &queries {
            let where_sql = format!("tenant = {}", (row + 100) % n_tenants);
            let query = &vectors[row];
            let exact = filtered_nearest_ids(table, &where_sql, query, 10, true);
            assert_eq!(exact.len(), 10, "the fixture must have >= 10 matches");

            set_iterative_scan("off");
            let off = filtered_nearest_ids(table, &where_sql, query, 10, false);
            assert!(off.len() < 10, "off must under-fill: {} rows", off.len());
            assert_eq!(last_scan_stats().0, 1, "off scans exactly one batch");

            set_iterative_scan("relaxed_order");
            let relaxed = filtered_nearest_ids(table, &where_sql, query, 10, false);
            assert_eq!(relaxed.len(), 10, "relaxed_order must fill the LIMIT");
            let (batches, _rescored, capped) = last_scan_stats();
            assert!(
                batches > 1,
                "relaxed_order must continue: {batches} batches"
            );
            assert!(!capped);
            total_recall += recall_of(&exact, &relaxed);
        }
        let mean_recall = total_recall / queries.len() as f64;
        eprintln!("pg_pinecone: iterative relaxed_order mean recall@10 = {mean_recall}");
        assert!(mean_recall >= 0.9, "mean recall@10 = {mean_recall}");
    }

    /// Test 2: `strict_order` is ordered but lossy. Uniform random vectors, so
    /// each batch overlaps the previous one in distance: `relaxed_order`
    /// emits out of order, `strict_order` drops the rows that would break the
    /// order and never returns fewer rows than `off`.
    #[pg_test]
    fn am_iterative_scan_strict_order_is_monotone_but_lossy() {
        install_am_opclasses();
        let table = "am_iter_strict";
        let vectors = uniform_random_vectors(202, 6_000, 16);
        build_residual_table(table, &vectors, 33, "seed = 202"); // tenant = 5: ~3% of rows
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        let (where_sql, query, k) = ("tenant = 5", &vectors[17], 100);

        set_iterative_scan("off");
        let off = ranked_rows(table, where_sql, query, k, false);
        set_iterative_scan("relaxed_order");
        let relaxed = ranked_rows(table, where_sql, query, k, false);
        set_iterative_scan("strict_order");
        let strict = ranked_rows(table, where_sql, query, k, false);
        assert!(last_scan_stats().0 > 1, "strict_order must continue too");

        for pair in strict.windows(2) {
            assert!(
                pair[0].1 <= pair[1].1 + 1e-4,
                "strict_order must be monotone: {strict:?}"
            );
        }
        assert!(
            relaxed.windows(2).any(|p| p[0].1 > p[1].1 + 1e-4),
            "the fixture must make relaxed_order emit out of order: {relaxed:?}"
        );
        assert!(
            strict.len() >= off.len(),
            "strict {} rows vs off {}",
            strict.len(),
            off.len()
        );
        let relaxed_ids: std::collections::HashSet<i64> = ids_of(&relaxed).into_iter().collect();
        assert!(
            ids_of(&strict).iter().all(|id| relaxed_ids.contains(id)),
            "strict_order only ever drops rows relaxed_order would emit"
        );
        assert!(
            strict.len() < relaxed.len(),
            "strict_order must drop out-of-order rows: strict {} vs relaxed {}",
            strict.len(),
            relaxed.len()
        );
    }

    /// `rescore_multiplier = 1` makes the pool 100 rows; 4000 uniform rows
    /// keep every batch full.
    fn build_pool_100_table(table: &str) -> Vec<Vec<f32>> {
        let vectors = uniform_random_vectors(203, 4_000, 16);
        build_residual_table(table, &vectors, 7, "seed = 203, rescore_multiplier = 1");
        vectors
    }

    /// Test 3: a `LIMIT` above the rescore pool is filled by continuation
    /// batches; the first batch is exactly what `off` returns.
    #[pg_test]
    fn am_iterative_scan_fills_a_limit_above_the_rescore_pool() {
        install_am_opclasses();
        let table = "am_iter_pool";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        // Iterative scans default to the 0.9.0 list count and `off` to the new one: pin both to 7 lists
        // so the first batch is `off`'s.
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");

        set_iterative_scan("off");
        let off = ranked_rows(table, "true", query, 150, false);
        assert_eq!(off.len(), 100, "off stops at the rescore pool");

        set_iterative_scan("relaxed_order");
        let relaxed = ranked_rows(table, "true", query, 150, false);
        assert_eq!(relaxed.len(), 150, "relaxed_order must fill LIMIT 150");
        assert_eq!(
            ids_of(&relaxed)[..100],
            ids_of(&off)[..],
            "the first batch is exactly what off returns"
        );
        let distinct: std::collections::HashSet<i64> = ids_of(&relaxed).into_iter().collect();
        assert_eq!(distinct.len(), 150, "lists are disjoint: no row twice");
        assert!(last_scan_stats().0 >= 2);
    }

    /// Test 4: `max_scan_tuples` counts rescored rows and is checked between
    /// batches; hitting it ends the scan quietly (no error) and says so in
    /// `last_scan_stats()`.
    #[pg_test]
    fn am_iterative_scan_max_scan_tuples_ends_the_scan_quietly() {
        install_am_opclasses();
        let table = "am_iter_cap";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];

        // 7 of 64 lists per batch: lists are left over when the cap hits. Batch 2
        // is cut to the 50 rows the cap leaves, so the total is the cap itself.
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        Spi::run("SET pinecone.max_scan_tuples = 150").expect("set max_scan_tuples");
        for mode in ["relaxed_order", "strict_order"] {
            set_iterative_scan(mode);
            let rows = ranked_rows(table, "true", query, 1_000, false);
            assert_eq!(
                last_scan_stats(),
                (2, 150, true),
                "{mode}: ends after batch 2"
            );
            assert!(rows.len() <= 150, "{mode}: {} rows", rows.len());
            if mode == "relaxed_order" {
                assert_eq!(rows.len(), 150);
            }
        }

        // Like pgvector, the cap never cuts the first batch.
        Spi::run("SET pinecone.max_scan_tuples = 1").expect("set max_scan_tuples");
        set_iterative_scan("relaxed_order");
        let rows = ranked_rows(table, "true", query, 1_000, false);
        assert_eq!(rows.len(), 100);
        assert_eq!(last_scan_stats(), (1, 100, true));

        // A cap the LIMIT never reaches is not reported as hit.
        Spi::run("RESET pinecone.max_scan_tuples").expect("reset max_scan_tuples");
        let rows = ranked_rows(table, "true", query, 250, false);
        assert_eq!(rows.len(), 250);
        assert!(!last_scan_stats().2);
    }

    /// Test 5: a rescan (nested loop, parameterised scan key or query vector)
    /// starts fresh. Tenant 0 runs mode H and its first batch fills the LIMIT,
    /// leaving lists unprobed; the next execution (tenant 7, mode L) must not
    /// continue them.
    #[pg_test]
    fn am_iterative_scan_rescan_starts_fresh() {
        install_am_opclasses();
        let table = "am_iter_rescan";
        let vectors = deterministic_clustered_vectors(205, 6_000, 24, 20);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(24), tenant int8, \
             grp int8 GENERATED ALWAYS AS (id % 50) STORED)"
        ))
        .expect("create table");
        // tenant 0 = 20% of rows (mode H), tenants 1..=79 ~1% each (mode L).
        bulk_insert_vectors_with_tenant(table, &vectors, |i| {
            if i.is_multiple_of(5) {
                "0".to_string()
            } else {
                (1 + i % 79).to_string()
            }
        });
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 205)"
        ))
        .expect("create filtered local index");
        set_iterative_scan("relaxed_order");

        let query = &vectors[42];
        let q = vector_literal(query);
        let h = filtered_nearest_ids(table, "tenant = 0", query, 200, false);
        assert_eq!(last_scan_mode(), "h");
        assert_eq!(h.len(), 200);
        assert_eq!(last_scan_stats().0, 1, "premise: batch 1 fills the LIMIT");
        let l = filtered_nearest_ids(table, "tenant = 7", query, 200, false);
        assert_eq!(last_scan_mode(), "l");
        assert!(!l.is_empty() && l.len() < 200, "premise: mode L drains");

        let ids_per_row = |sql: &str| -> Vec<(i64, Vec<i64>)> {
            Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
            let plan = explain_lines(sql).join("\n");
            assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");
            let rows = Spi::connect(|client| {
                client
                    .select(sql, None, &[])
                    .expect("nested loop query")
                    .map(|row| {
                        (
                            row.get_by_name::<i64, _>("k").unwrap().unwrap(),
                            row.get_by_name::<Vec<i64>, _>("ids").unwrap().unwrap(),
                        )
                    })
                    .collect()
            });
            Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
            rows
        };

        // Parameterised scan key: H, L, H, L on one scan descriptor.
        let rows = ids_per_row(&format!(
            "SELECT p.tenant AS k, ARRAY(SELECT t.id FROM {table} t WHERE t.tenant = p.tenant \
             ORDER BY t.embedding <-> '{q}'::vector LIMIT 200) AS ids \
             FROM (VALUES (0::int8), (7::int8), (0::int8), (7::int8)) AS p(tenant)"
        ));
        let got: Vec<&Vec<i64>> = rows.iter().map(|(_, ids)| ids).collect();
        assert_eq!(
            got,
            vec![&h, &l, &h, &l],
            "every execution must match a fresh scan"
        );

        // Parameterised query vector with a residual qual.
        let rows = ids_per_row(&format!(
            "SELECT q.id AS k, ARRAY(SELECT t.id FROM {table} t WHERE t.grp = 3 \
             ORDER BY t.embedding <-> q.embedding LIMIT 10) AS ids \
             FROM {table} q WHERE q.id IN (43, 2001, 4003) ORDER BY q.id"
        ));
        assert_eq!(rows.len(), 3);
        for (id, ids) in rows {
            let fresh = ranked_rows(table, "grp = 3", &vectors[id as usize - 1], 10, false);
            assert_eq!(ids, ids_of(&fresh), "query row {id}");
        }
    }

    /// Test 6: a text key (hash match + executor recheck) with a residual
    /// qual. A record whose stored hash collides with the wanted label sits in
    /// a continuation batch; the executor recheck must still drop it, and
    /// NULL labels never match.
    #[pg_test]
    fn am_iterative_scan_text_key_recheck_applies_to_every_batch() {
        install_am_opclasses();
        let table = "am_iter_text";
        let (n, dim) = (6_000, 24);
        let vectors = deterministic_clustered_vectors(206, n, dim, 20);
        let label = |i: usize| (!i.is_multiple_of(13)).then(|| format!("lbl-{}", i % 5));
        let grp = |i: usize| (i / 5) % 25;
        // `grp` is generated: an UPDATE before CREATE INDEX (same transaction)
        // would leave the dead row versions indexed and eat rescore-pool slots.
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant text, \
             grp int8 GENERATED ALWAYS AS (((id - 1) / 5) % 25) STORED)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| {
            label(i).map_or("NULL".to_string(), |l| format!("'{l}'"))
        });
        // rescore_multiplier = 10: the premise is two batches, the first half of the lists whole and
        // then the rest; at the default pool of 300 the first half alone takes two.
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 206, rescore_multiplier = 10)"
        ))
        .expect("create text-filtered local index");
        Spi::run("SET pinecone.force_scan_mode = 'h'").expect("force h");

        let where_sql = "tenant = 'lbl-1' AND grp = 7";
        let query = &vectors[1];
        assert_filtered_plan_uses_index(table, where_sql, query, 100);
        let expected: std::collections::BTreeSet<i64> = (0..n)
            .filter(|&i| label(i).as_deref() == Some("lbl-1") && grp(i) == 7)
            .map(|i| i as i64 + 1)
            .collect();

        // The row the index will claim is a 'lbl-1': it satisfies the residual
        // but its heap label is 'lbl-2', and it is the farthest such row, so
        // it lives in the lists probed last.
        let sq_dist = |a: &[f32]| {
            a.iter()
                .zip(query)
                .map(|(x, y)| (x - y) * (x - y))
                .sum::<f32>()
        };
        let victim = (0..n)
            .filter(|&i| label(i).as_deref() == Some("lbl-2") && grp(i) == 7)
            .max_by(|&a, &b| sq_dist(&vectors[a]).total_cmp(&sq_dist(&vectors[b])))
            .expect("fixture has lbl-2 rows with grp 7");
        let (block, offset) = ctid_map(table)[&(victim + 1).to_string()]
            .split_once(':')
            .map(|(b, o)| (b.parse::<u32>().unwrap(), o.parse::<u16>().unwrap()))
            .expect("block:offset");
        let mut tid = pg_sys::ItemPointerData {
            ip_blkid: pg_sys::BlockIdData { bi_hi: 0, bi_lo: 0 },
            ip_posid: 0,
        };
        pgrx::itemptr::item_pointer_set_all(&mut tid, block, offset);
        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            let meta = crate::local::metapage::read(index);
            let hash = crate::local::pages::fnv1a64(b"lbl-1");
            assert!(crate::local::vacuum::test_overwrite_filter_value(
                index, &meta, tid, hash
            ));
            pg_sys::RelationClose(index);
        }

        let analyze = format!(
            "(ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT id FROM {table} \
             WHERE {where_sql} ORDER BY embedding <-> '{}'::vector LIMIT 100",
            vector_literal(query)
        );
        let analyzed = || {
            Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
            let plan = explain_lines(&analyze).join("\n");
            Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
            plan
        };

        set_iterative_scan("off");
        let plan = analyzed();
        let off = ids_of(&ranked_rows(table, where_sql, query, 100, false));
        assert_eq!(last_scan_mode(), "h");
        assert!(off.len() < expected.len(), "off probes half the lists only");
        assert!(
            !plan.contains("Rows Removed by Index Recheck"),
            "premise: the colliding record is not in the first batch: {plan}"
        );

        set_iterative_scan("relaxed_order");
        let relaxed = ids_of(&ranked_rows(table, where_sql, query, 100, false));
        assert_eq!(last_scan_stats().0, 2);
        assert_eq!(
            relaxed
                .iter()
                .copied()
                .collect::<std::collections::BTreeSet<i64>>(),
            expected,
            "all and only the matching rows: no collision victim, no NULL label"
        );
        let plan = analyzed();
        assert!(
            plan.contains("Rows Removed by Index Recheck: 1"),
            "the continuation batch must be rechecked by the executor: {plan}"
        );
    }

    /// Test 7: mode L and the flat path are complete by construction; both
    /// GUCs leave them untouched.
    #[pg_test]
    fn am_iterative_scan_mode_l_and_flat_ignore_the_gucs() {
        install_am_opclasses();

        // Mode L: 100 tenants = 1% each, tenant == generator cluster.
        let table = "am_iter_mode_l";
        let (n, dim, n_tenants) = (6_000, 24, 100);
        let vectors = deterministic_clustered_vectors(21, n, dim, n_tenants);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant int4)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % n_tenants).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 21)"
        ))
        .expect("create filtered local index");
        for tenant in [0usize, 42, 99] {
            let where_sql = format!("tenant = {tenant}");
            let query = &vectors[tenant + n_tenants];
            let mut runs = Vec::new();
            for mode in ["off", "auto", "relaxed_order", "strict_order"] {
                set_iterative_scan(mode);
                // LIMIT above the 60 matches: the executor asks for more after
                // mode L has drained.
                let rows = ranked_rows(table, &where_sql, query, 200, false);
                assert_eq!(last_scan_mode(), "l");
                assert_eq!(last_scan_stats(), (1, rows.len() as i64, false), "{mode}");
                runs.push(rows);
            }
            assert_eq!(runs[0].len(), 60);
            assert!(
                runs.iter().all(|r| *r == runs[0]),
                "tenant {tenant}: {runs:?}"
            );
        }

        // Flat: 300 rows sit below small_n_threshold, so every row is scored.
        let table = "am_iter_flat";
        let vectors = deterministic_clustered_vectors(22, 300, 16, 6);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(16), tenant int8)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % 10).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create flat local index");
        let exact = ranked_rows(table, "tenant = 3", &vectors[3], 100, true);
        assert_eq!(exact.len(), 30);
        for mode in ["off", "auto", "relaxed_order", "strict_order"] {
            set_iterative_scan(mode);
            let rows = ranked_rows(table, "tenant = 3", &vectors[3], 100, false);
            assert_eq!(last_scan_mode(), "flat");
            assert_eq!(rows, exact, "{mode}");
            let (batches, _, capped) = last_scan_stats();
            assert!(batches == 1 && !capped, "{mode}");
        }
    }

    /// Test 8: the first batch is exactly what `off` returns, so a plain
    /// `ORDER BY .. LIMIT` is unchanged (see also
    /// `am_local_scan_results_are_sorted_by_true_distance`, which runs under
    /// the default `auto`, whose first batch is `off`'s whatever the lists).
    #[pg_test]
    fn am_iterative_scan_first_batch_is_identical_to_off() {
        install_am_opclasses();
        let table = "am_iter_first_batch";
        let vectors = deterministic_clustered_vectors(7, 5_000, 32, 15);
        // Iterative scans default to the 0.9.0 list count and `off` to the new one, and the default pool
        // is 300 rows: the first batch is `off`'s when both probe the same lists and `LIMIT 1000` fits
        // the pool, so pin all three.
        build_residual_table(table, &vectors, 10, "seed = 7, rescore_multiplier = 10");
        Spi::run("SET pinecone.scan_fraction = 0.5").expect("same lists on every path");
        let query = &vectors[123];
        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let plan = explain_lines(&format!(
            "SELECT id FROM {table} ORDER BY embedding <-> '{}'::vector LIMIT 50",
            vector_literal(query)
        ))
        .join("\n");
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");

        // `off` rescores the whole pool whatever `scan_prune` says (it stops `auto`'s first batch
        // only), so a LIMIT of the whole pool is met by the first batch.
        for (prune, limit) in [("off", 50), ("off", 1_000), ("on", 50), ("on", 1_000)] {
            Spi::run(&format!("SET pinecone.scan_prune = {prune}")).expect("scan_prune");
            set_iterative_scan("off");
            let off = ranked_rows(table, "true", query, limit, false);
            assert_eq!(off.len(), limit);
            for mode in ["relaxed_order", "strict_order"] {
                set_iterative_scan(mode);
                let rows = ranked_rows(table, "true", query, limit, false);
                assert_eq!(rows, off, "{mode}, LIMIT {limit}, scan_prune {prune}");
                assert_eq!(
                    last_scan_stats().0,
                    1,
                    "{mode}: the LIMIT is met by batch 1"
                );
            }
        }
    }

    // =========================================================================
    // `pinecone.iterative_scan = auto` (the default): a native index's first batch is exactly what
    // `off` returns, and a `LIMIT` the first batch cannot fill is served by a `relaxed_order`
    // continuation that leaves the rows already handed out aside.
    // =========================================================================

    /// `vectors` behind a native index at its calibrated defaults (`index_with`: more reloptions).
    fn auto_table(table: &str, vectors: &[Vec<f32>], index_with: &str) {
        let dim = vectors[0].len();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        insert_in_chunks(table, "id, embedding", vectors, |_| String::new());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', {index_with})"
        ))
        .expect("create local index");
    }

    /// At the defaults a `LIMIT` above the rescore pool is filled with the nearest rows: the pool is
    /// the calibrated 100-row minimum and `off` cuts `LIMIT 200` and `LIMIT 1000` there.
    #[pg_test]
    fn am_iterative_scan_auto_fills_limit_200_and_1000_on_a_20k_index() {
        install_am_opclasses();
        let table = "am_auto_fill";
        // 6-d uniform rows: the estimate ranks them well at depth (recall@200 reads 0.93). The pool
        // is pinned to the calibrated minimum so it stays below both LIMITs on any CPU.
        let all = uniform_random_vectors(312, 20_030, 6);
        let (rows, queries) = all.split_at(20_000);
        auto_table(table, rows, "seed = 312, rescore_multiplier = 1");
        let meta = index_meta(&format!("{table}_idx"));
        let pool = meta.default_pool() as usize;
        assert_eq!(pool, 100, "premise: the pool is below both LIMITs");

        for k in [200usize, 1_000] {
            let (mut recall, mut off_recall, mut off_rows) = (0.0, 0.0, 0usize);
            for query in queries {
                let exact = nearest_ids(table, query, k, true);

                reset_iterative_scan();
                let got = nearest_ids(table, query, k, false);
                assert_eq!(got.len(), k, "LIMIT {k} is filled at the defaults");
                let distinct: std::collections::HashSet<i64> = got.iter().copied().collect();
                assert_eq!(distinct.len(), k, "no row twice");
                let stats = scan_stats();
                assert!(stats.batches >= 2 && !stats.capped, "{stats:?}");
                assert!(
                    stats.lists_probed as u32 > meta.default_nprobe(),
                    "the continuation reads more lists than the first batch: {stats:?}"
                );
                recall += recall_of(&exact, &got);

                set_iterative_scan("off");
                let short = nearest_ids(table, query, k, false);
                assert!(
                    short.len() <= pool,
                    "off returns the rescored pool at most: {} rows",
                    short.len()
                );
                off_rows += short.len();
                off_recall += recall_of(&exact, &short);
            }
            let c = queries.len() as f64;
            stat_line(&format!(
                "auto fill (20,000 x 6d, pool {pool}): LIMIT {k}: {k} rows at the defaults, \
                 recall@{k} {:.3}; off {:.0} rows, recall {:.3}",
                recall / c,
                off_rows as f64 / c,
                off_recall / c
            ));
            assert!(
                recall / c >= 0.9,
                "recall@{k} at the defaults: {}",
                recall / c
            );
        }
    }

    /// A query the first batch satisfies is what it was: the default's first batch is `off`'s, so
    /// ids, distances and the scan counters equal `off`'s (the pool is pinned to the 100-row floor,
    /// where the early stop saves nothing, so `rescored` agrees too), and it reads the
    /// calibrated lists, not the 0.9.0 count an explicit `relaxed_order` starts with (which costs a
    /// `LIMIT 10` about three times the time on this set).
    #[pg_test]
    fn am_iterative_scan_auto_limit_10_is_what_off_returns() {
        install_am_opclasses();
        let table = "am_auto_first";
        let (n, n_queries, components, dim) = (20_000, 20, 100, 128);
        let all = gaussian_mixture(13, n + n_queries, dim, components, SEPARATION_128D);
        let (rows, queries) = all.split_at(n);
        auto_table(table, rows, "seed = 13, rescore_multiplier = 1");
        let meta = index_meta(&format!("{table}_idx"));
        assert_eq!(
            meta.default_pool(),
            100,
            "premise: the 100-row floor, where the early stop saves nothing"
        );
        let calibrated = meta.default_nprobe() as i32;

        let run = |k: usize, query: &[f32]| {
            let found = ranked_rows(table, "true", query, k, false);
            (found, scan_stats(), scan_detail())
        };
        for query in queries {
            for k in [1usize, 10, 50, 100] {
                set_iterative_scan("off");
                let off = run(k, query);
                reset_iterative_scan();
                let auto = run(k, query);
                assert_eq!(auto, off, "LIMIT {k}: ids, order and counters are off's");
                assert_eq!(auto.1.batches, 1, "LIMIT {k}: one batch");
                assert_eq!(
                    auto.1.lists_probed, calibrated,
                    "LIMIT {k}: the calibrated lists"
                );
            }
        }

        // With the whole pool rescored (`scan_prune = off`, a pool of 300) the first batch is the pool:
        // a `LIMIT` up to it is one batch as well, and the ids are `off`'s.
        Spi::run("SET pinecone.scan_prune = off").expect("rescore the whole pool");
        Spi::run("SET pinecone.rescore_multiplier = 3").expect("a pool of 300");
        for query in queries.iter().take(5) {
            for k in [150usize, 300] {
                set_iterative_scan("off");
                let off = run(k, query);
                assert_eq!(off.0.len(), k, "premise: off rescores the whole pool");
                reset_iterative_scan();
                let auto = run(k, query);
                assert_eq!(auto, off, "LIMIT {k} of a pool of 300");
                assert_eq!(auto.1.batches, 1);
            }
        }
    }

    /// 1 % of the rows behind a key pushed into the index: `LIMIT 10` returns `off`'s rows and
    /// `LIMIT 100` is filled, at the defaults and when the first batch is too small for it (ten
    /// percent of the lists, a pool of 100), where `off` returns less.
    #[pg_test]
    fn am_iterative_scan_auto_fills_limit_100_behind_a_one_percent_key() {
        let case = rq_case("unnormalised_128_l2");
        let data = tk::mixture(&case.spec, 20_000, 40, 0x17E8);
        let tenant = |id: i64| -> i64 { if id % 100 == 0 { 7 } else { id % 6 } };
        let table = "rq_auto_key";
        rq_table(table, 128, ", tenant int4");
        rq_load(table, 1, &data.vectors, Some(&tenant));
        let index = rq_index(table, RQ_L2, ", tenant", "seed = 47");
        rq_assert_format_3(&index);
        let queries: Vec<String> = data.queries.iter().map(|q| rq_literal(q)).collect();

        Spi::run("SET pinecone.force_scan_mode = 'h'").expect("1 % is mode L by default");
        rq_assert_uses_index(table, RQ_L2, "WHERE tenant = 7", &queries[0]);
        Spi::run("SET enable_seqscan = off").expect("index scans only");
        let limit_100 = |query: &String| {
            let ids = rq_ids(&rq_query_sql(table, RQ_L2, "WHERE tenant = 7", query, 100));
            assert!(
                ids.iter().all(|id| id % 100 == 0),
                "only rows of the key come back"
            );
            (ids.len(), last_scan_stats())
        };

        // The shipped defaults: lists, pool and mode as a user has them.
        for query in &queries {
            let (rows, (_, _, capped)) = limit_100(query);
            assert!(
                rows == 100 && !capped,
                "defaults: {rows} rows, capped {capped}"
            );
        }
        assert_eq!(last_scan_mode(), "h");

        // A `LIMIT 10` the first batch satisfies is `off`'s top rows from the same lists, scan phase
        // included; the early stop only rescores fewer of the pool (`off` rescores all of it).
        let limit_10 = |query: &String| {
            let ids = rq_ids(&rq_query_sql(table, RQ_L2, "WHERE tenant = 7", query, 10));
            (ids, scan_stats(), scan_detail())
        };
        for query in queries.iter().take(10) {
            set_iterative_scan("off");
            let off = limit_10(query);
            reset_iterative_scan();
            let auto = limit_10(query);
            assert_eq!(
                (&auto.0, &auto.2),
                (&off.0, &off.2),
                "ids, order, scan phase"
            );
            assert_eq!(
                (auto.1.batches, auto.1.lists_probed),
                (1, off.1.lists_probed)
            );
            assert!(
                auto.1.rescored <= off.1.rescored,
                "{:?} against {:?}",
                auto.1,
                off.1
            );
        }

        // A first batch that cannot fill it.
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("a small first batch");
        rq_set_pool(1);
        set_iterative_scan("off");
        for query in queries.iter().take(20) {
            let (rows, (batches, _, _)) = limit_100(query);
            assert!(rows < 100 && batches == 1, "off under-fills: {rows} rows");
        }
        reset_iterative_scan();
        for query in queries.iter().take(20) {
            let (rows, (batches, rescored, capped)) = limit_100(query);
            assert!(
                rows == 100 && batches > 1 && rescored >= 100 && !capped,
                "the default probes further: {rows} rows, {batches} batches, {rescored} rescored"
            );
        }
    }

    /// A `LIMIT` the first batch cannot fill gets the rest in a continuation that never repeats a
    /// row of the first batch, serves what `off` returned first, and counts every rescored row
    /// against `pinecone.max_scan_tuples` (the first batch is never cut, a later slice is).
    #[pg_test]
    fn am_iterative_scan_auto_continues_without_repeating_the_first_batch() {
        install_am_opclasses();
        let table = "am_auto_cont";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];

        set_iterative_scan("off");
        let off = ranked_rows(table, "true", query, 150, false);
        assert_eq!(off.len(), 100, "off stops at the rescore pool");

        reset_iterative_scan();
        let auto = ranked_rows(table, "true", query, 150, false);
        assert_eq!(auto.len(), 150, "the default fills LIMIT 150");
        assert_eq!(
            ids_of(&auto)[..100],
            ids_of(&off)[..],
            "the first batch is exactly what off returns"
        );
        let distinct: std::collections::HashSet<i64> = ids_of(&auto).into_iter().collect();
        assert_eq!(
            distinct.len(),
            150,
            "the continuation leaves the first batch out"
        );
        assert!(last_scan_stats().0 >= 2);

        let hundred = ranked_rows(table, "true", query, 100, false);
        assert_eq!(
            ids_of(&hundred),
            ids_of(&off),
            "LIMIT 100 is the first batch"
        );
        assert_eq!(last_scan_stats().0, 1, "and needs no continuation");

        Spi::run("SET pinecone.max_scan_tuples = 120").expect("cap");
        let cut = ranked_rows(table, "true", query, 300, false);
        assert_eq!(
            cut.len(),
            120,
            "the first batch of 100 plus the 20 the cap leaves"
        );
        assert!(
            last_scan_stats().2,
            "capped: the cap ended it, not the lists"
        );

        Spi::run("SET pinecone.max_scan_tuples = 50").expect("cap below the first batch");
        let first = ranked_rows(table, "true", query, 300, false);
        assert_eq!(ids_of(&first), ids_of(&off), "the first batch is never cut");
        assert!(last_scan_stats().2);
    }

    /// The continuation leaves out every candidate the first batch fetched, found or not: a row
    /// whose heap tuple is dead (deleted, index entry not yet vacuumed) is not fetched again, and
    /// does not count twice against `pinecone.max_scan_tuples`.
    #[pg_test]
    fn am_iterative_scan_auto_does_not_fetch_a_dead_candidate_of_the_first_batch_again() {
        install_am_opclasses();
        let table = "am_auto_dead";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];

        set_iterative_scan("off");
        let first = ids_of(&ranked_rows(table, "true", query, 100, false));
        assert_eq!(first.len(), 100, "premise: the first batch holds the pool");
        let dead = &first[..60];
        let list: Vec<String> = dead.iter().map(i64::to_string).collect();
        Spi::run(&format!(
            "DELETE FROM {table} WHERE id = ANY(ARRAY[{}])",
            list.join(",")
        ))
        .expect("delete 60 rows of the first batch");
        let live = ids_of(&ranked_rows(table, "true", query, 100, false));
        assert_eq!(
            live,
            first[60..],
            "off: the 40 live rows of the same 100 candidates"
        );
        assert_eq!(last_scan_stats().1, 100, "all 100 candidates were fetched");

        reset_iterative_scan();
        let auto = ids_of(&ranked_rows(table, "true", query, 140, false));
        assert_eq!(auto.len(), 140, "the first batch's 40 and 100 more");
        assert_eq!(auto[..40], first[60..], "the first batch is off's");
        let distinct: std::collections::HashSet<i64> = auto.iter().copied().collect();
        assert_eq!(distinct.len(), 140, "no row twice");
        assert!(auto.iter().all(|id| !dead.contains(id)), "no deleted row");
        let stats = scan_stats();
        assert_eq!(
            (stats.batches, stats.rescored),
            (2, 200),
            "the 60 dead candidates are fetched once, in the first batch: {stats:?}"
        );
    }

    /// A first batch that admits nothing (the pushed key has no rows in the nearest lists) does not
    /// exempt the next slice from `pinecone.max_scan_tuples`: the first slice that finds rows is cut
    /// to the cap, under `auto` and the explicit iterative modes.
    #[pg_test]
    fn am_iterative_scan_cap_holds_after_an_empty_first_batch() {
        let table = "am_iter_empty_first";
        let near = uniform_random_vectors(77, 2_000, 16);
        let far = uniform_random_vectors(78, 2_000, 16)
            .into_iter()
            .map(|v| v.into_iter().map(|x| x + 1_000.0).collect());
        let vectors: Vec<Vec<f32>> = near.into_iter().chain(far).collect();
        let tenant = |id: i64| -> i64 { if id > 2_000 && id % 4 == 0 { 7 } else { id % 6 } };
        rq_table(table, 16, ", tenant int4");
        rq_load(table, 1, &vectors, Some(&tenant));
        let index = rq_index(
            table,
            RQ_L2,
            ", tenant",
            "seed = 77, n_lists = 20, small_n_threshold = 10",
        );
        rq_assert_format_3(&index);
        let query = rq_literal(&vectors[3]);
        let sql = rq_query_sql(table, RQ_L2, "WHERE tenant = 7", &query, 100);

        Spi::run("SET pinecone.force_scan_mode = 'h'").expect("mode H");
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("two lists a step");
        rq_assert_uses_index(table, RQ_L2, "WHERE tenant = 7", &query);
        Spi::run("SET enable_seqscan = off").expect("index scans only");
        set_iterative_scan("off");
        assert!(
            rq_ids(&sql).is_empty(),
            "premise: the nearest lists hold no row of the key"
        );

        Spi::run("SET pinecone.max_scan_tuples = 50").expect("cap below the pool");
        for mode in ["auto", "relaxed_order"] {
            set_iterative_scan(mode);
            let ids = rq_ids(&sql);
            let (_, rescored, capped) = last_scan_stats();
            assert!(
                rescored <= 50 && capped && ids.len() <= 50,
                "{mode}: {} rows, {rescored} rescored, capped {capped}",
                ids.len()
            );
            assert!(!ids.is_empty(), "{mode}: the far lists are reached");
        }
        Spi::run("SET enable_seqscan = on").expect("seqscan on");
    }

    /// A residual `WHERE` the index cannot push (1 in 333 rows) fills a `LIMIT 10` at the defaults:
    /// the first batch holds a few matches (`off` stops there), the continuation finds the rest.
    #[pg_test]
    fn am_iterative_scan_auto_fills_a_selective_residual_where() {
        install_am_opclasses();
        let table = "am_auto_residual";
        let (n, dim, n_clusters, n_tenants) = (8_000, 24, 20, 333);
        let vectors = deterministic_clustered_vectors(201, n, dim, n_clusters);
        build_residual_table(table, &vectors, n_tenants, "seed = 201, n_lists = 100");
        assert_residual_plan_uses_index(table, "tenant = 7", &vectors[7], 10);

        let (mut recall, mut under_filled) = (0.0, 0);
        let queries = [11usize, 1_009, 2_003, 3_001, 4_999, 5_501, 6_607, 7_919];
        for &row in &queries {
            let where_sql = format!("tenant = {}", (row + 100) % n_tenants);
            let query = &vectors[row];
            let exact = filtered_nearest_ids(table, &where_sql, query, 10, true);
            assert_eq!(exact.len(), 10, "the fixture has at least 10 matches");

            set_iterative_scan("off");
            under_filled +=
                usize::from(filtered_nearest_ids(table, &where_sql, query, 10, false).len() < 10);

            reset_iterative_scan();
            let got = filtered_nearest_ids(table, &where_sql, query, 10, false);
            assert_eq!(
                got.len(),
                10,
                "the default fills the LIMIT (query row {row})"
            );
            assert!(last_scan_stats().0 > 1 && !last_scan_stats().2);
            recall += recall_of(&exact, &got);
        }
        assert!(under_filled > 0, "premise: off under-fills here");
        let mean = recall / queries.len() as f64;
        stat_line(&format!(
            "auto residual (8,000 x 24d, 1 in 333): off under-filled {under_filled} of {} queries, \
             default recall@10 {mean:.3}",
            queries.len()
        ));
        assert!(mean >= 0.9, "mean recall@10 = {mean}");
    }

    /// `auto` behind a residual `WHERE` (1 in 333 rows) with `pinecone.max_scan_tuples` below the pool: the
    /// first batch is never cut and nothing is rescored after it (`capped`); a cap just above it cuts the
    /// continuation's first slice to what is left. No error either way, and every row returned still passes
    /// the `WHERE`.
    #[pg_test]
    fn am_iterative_scan_auto_behind_a_residual_where_ends_quietly_at_a_cap_below_the_pool() {
        install_am_opclasses();
        let table = "am_auto_resid_cap";
        let (n, dim, n_clusters, n_tenants) = (8_000, 24, 20, 333);
        let vectors = deterministic_clustered_vectors(201, n, dim, n_clusters);
        build_residual_table(table, &vectors, n_tenants, "seed = 201, n_lists = 100");
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("a batch of 10 lists");
        Spi::run("SET pinecone.rescore_multiplier = 3").expect("a pool of 300");
        Spi::run("SET pinecone.scan_prune = off").expect("the first batch rescores the pool");
        assert_residual_plan_uses_index(table, "tenant = 7", &vectors[7], 10);

        let pool = 300;
        let mut under_filled = 0;
        for &row in &[11usize, 1_009, 2_003, 3_001, 4_999, 5_501, 6_607, 7_919] {
            let tenant = (row + 100) % n_tenants;
            let where_sql = format!("tenant = {tenant}");
            let query = &vectors[row];
            let passes = |id: &i64| (*id as usize - 1) % n_tenants == tenant;

            // The default cap: the continuation fills the LIMIT.
            let rows = filtered_nearest_ids(table, &where_sql, query, 10, false);
            assert_eq!(rows.len(), 10, "query row {row}");
            let (batches, rescored, capped) = last_scan_stats();
            assert!(batches > 1 && rescored > pool && !capped, "row {row}");

            // Below the pool: the first batch, whole, and then the cap.
            Spi::run("SET pinecone.max_scan_tuples = 50").expect("a cap below the pool");
            let rows = filtered_nearest_ids(table, &where_sql, query, 10, false);
            assert_eq!(last_scan_stats(), (1, pool, true), "row {row}");
            assert!(
                rows.len() <= 10 && rows.iter().all(passes),
                "row {row}: {rows:?}"
            );
            under_filled += usize::from(rows.len() < 10);

            // Just above it: the continuation's first slice is cut to the 50 the cap leaves.
            Spi::run("SET pinecone.max_scan_tuples = 350").expect("a cap above the pool");
            let rows = filtered_nearest_ids(table, &where_sql, query, 10, false);
            let (batches, rescored, capped) = last_scan_stats();
            assert!(batches > 1 && rescored == 350 && capped, "row {row}");
            assert!(rows.iter().all(passes), "row {row}: {rows:?}");
            Spi::run("RESET pinecone.max_scan_tuples").expect("default cap");
        }
        assert!(
            under_filled > 0,
            "premise: a cap below the pool leaves the LIMIT short"
        );
    }

    /// A rescan starts fresh whether or not the scan before it needed its continuation: an inner
    /// scan that stopped inside its first batch leaves nothing for the next outer row, and one that
    /// went on does not hand its rows to the next.
    #[pg_test]
    fn am_iterative_scan_auto_rescans_start_fresh() {
        install_am_opclasses();
        let table = "am_auto_rescan";
        let vectors = build_pool_100_table(table);
        for limit in [10usize, 150] {
            Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
            let sql = format!(
                "SELECT q.id AS k, ARRAY(SELECT t.id FROM {table} t \
                 ORDER BY t.embedding <-> q.embedding LIMIT {limit}) AS ids \
                 FROM {table} q WHERE q.id IN (4, 1001, 2002, 3003) ORDER BY q.id"
            );
            let plan = explain_lines(&sql).join("\n");
            assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");
            let rows: Vec<(i64, Vec<i64>)> = Spi::connect(|client| {
                client
                    .select(&sql, None, &[])
                    .expect("nested loop query")
                    .map(|row| {
                        (
                            row.get_by_name::<i64, _>("k").unwrap().unwrap(),
                            row.get_by_name::<Vec<i64>, _>("ids").unwrap().unwrap(),
                        )
                    })
                    .collect()
            });
            Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
            assert_eq!(rows.len(), 4);
            for (id, ids) in rows {
                let fresh = ranked_rows(table, "true", &vectors[id as usize - 1], limit, false);
                assert_eq!(ids.len(), limit, "LIMIT {limit}, outer row {id}");
                assert_eq!(ids, ids_of(&fresh), "LIMIT {limit}, outer row {id}");
            }
        }
    }

    #[derive(Debug, PartialEq)]
    struct ScanStats {
        batches: i32,
        rescored: i64,
        capped: bool,
        deepened: i32,
        lists_probed: i32,
    }

    fn scan_stats() -> ScanStats {
        Spi::connect(|client| {
            let row = client
                .select(
                    "SELECT batches, rescored, capped, deepened, lists_probed \
                     FROM pinecone.last_scan_stats()",
                    None,
                    &[],
                )
                .expect("last_scan_stats query")
                .first();
            ScanStats {
                batches: row.get::<i32>(1).unwrap().unwrap(),
                rescored: row.get::<i64>(2).unwrap().unwrap(),
                capped: row.get::<bool>(3).unwrap().unwrap(),
                deepened: row.get::<i32>(4).unwrap().unwrap(),
                lists_probed: row.get::<i32>(5).unwrap().unwrap(),
            }
        })
    }

    fn relaxed_residual_rows_and_recall(
        table: &str,
        vectors: &[Vec<f32>],
        n_tenants: usize,
    ) -> (f64, f64) {
        set_iterative_scan("relaxed_order");
        let queries: Vec<usize> = (0..20).map(|q| q * 397 + 11).collect();
        let (mut rows, mut recall) = (0.0, 0.0);
        for &row in &queries {
            let where_sql = format!("tenant = {}", (row + 100) % n_tenants);
            let exact = filtered_nearest_ids(table, &where_sql, &vectors[row], 10, true);
            let got = filtered_nearest_ids(table, &where_sql, &vectors[row], 10, false);
            rows += got.len() as f64;
            recall += recall_of(&exact, &got);
        }
        (rows / queries.len() as f64, recall / queries.len() as f64)
    }

    /// Defaults probe 40 of 100 lists (~3200 candidates) but rescore a pool of
    /// 1000; the residual only runs after that cut.
    #[pg_test]
    fn am_iterative_scan_deepens_to_fill_the_limit_at_default_settings() {
        install_am_opclasses();
        let table = "am_iter_deep_clustered";
        let vectors = deterministic_clustered_vectors(201, 8_000, 24, 20);
        build_residual_table(table, &vectors, 333, "seed = 201, n_lists = 100");

        let (rows, recall) = relaxed_residual_rows_and_recall(table, &vectors, 333);
        eprintln!("pg_pinecone: deepen, clustered, defaults: rows {rows}, recall@10 {recall}");
        assert_eq!(rows, 10.0, "relaxed_order must fill every LIMIT 10");
        assert!(recall >= 0.9, "mean recall@10 = {recall}");
        assert!(scan_stats().deepened >= 1, "{:?}", scan_stats());
    }

    /// The 24 matching rows lie anywhere, so at defaults (40 of 100 lists)
    /// recall is bounded by list coverage; with every list probed only the
    /// sketch ranking is left.
    #[pg_test]
    fn am_iterative_scan_deepens_on_uniform_data_too() {
        install_am_opclasses();
        let table = "am_iter_deep_uniform";
        let vectors = uniform_random_vectors(301, 8_000, 24);
        build_residual_table(table, &vectors, 333, "seed = 201, n_lists = 100");

        let (rows, recall) = relaxed_residual_rows_and_recall(table, &vectors, 333);
        eprintln!("pg_pinecone: deepen, uniform, defaults: rows {rows}, recall@10 {recall}");
        assert_eq!(rows, 10.0, "relaxed_order must fill every LIMIT 10");
        assert!(scan_stats().deepened >= 1, "{:?}", scan_stats());

        Spi::run("SET pinecone.scan_fraction = 1.0").expect("set scan_fraction");
        // A 24-d column's code is padded to 256 bits, and with every list probed only the ranking by
        // estimate is left: recall@10 here is 0.925 at a pool of 300 (0.870 on the 64-bit code it
        // had before the minimum width).
        Spi::run("SET pinecone.rescore_multiplier = 3").expect("set rescore_multiplier");
        let (rows, recall) = relaxed_residual_rows_and_recall(table, &vectors, 333);
        eprintln!("pg_pinecone: deepen, uniform, all lists: rows {rows}, recall@10 {recall}");
        assert_eq!(rows, 10.0, "relaxed_order must fill every LIMIT 10");
        assert!(recall >= 0.9, "mean recall@10 = {recall}");
    }

    /// Sets `scan_fraction` 0.1, so `build_pool_100_table` probes 7 of 64
    /// lists, and lists that first set by exact distance: an `off` scan with a
    /// pool big enough for all of them.
    fn first_probed_set(table: &str, query: &[f32]) -> Vec<(i64, f64)> {
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        Spi::run("SET pinecone.rescore_multiplier = 1000").expect("set rescore_multiplier");
        set_iterative_scan("off");
        let set = ranked_rows(table, "true", query, 4_000, false);
        Spi::run("RESET pinecone.rescore_multiplier").expect("reset rescore_multiplier");
        set
    }

    fn id_set(rows: &[(i64, f64)]) -> std::collections::BTreeSet<i64> {
        rows.iter().map(|(id, _)| *id).collect()
    }

    #[pg_test]
    fn am_iterative_scan_exhausts_the_probed_lists_before_probing_more() {
        install_am_opclasses();
        let table = "am_iter_deep_first";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let first = first_probed_set(table, query);
        let c = first.len();
        assert!((300..1_000).contains(&c), "premise: 7 lists hold {c} rows");
        let slices = c.div_ceil(100) as i32;

        set_iterative_scan("relaxed_order");
        let rows = ranked_rows(table, "true", query, c, false);
        assert_eq!(id_set(&rows), id_set(&first), "LIMIT = the first set");
        assert_eq!(
            scan_stats(),
            ScanStats {
                batches: slices,
                rescored: c as i64,
                capped: false,
                deepened: slices - 1,
                lists_probed: 7,
            }
        );

        let rows = ranked_rows(table, "true", query, c + 1, false);
        assert_eq!(
            id_set(&rows[..c]),
            id_set(&first),
            "the first set comes first"
        );
        assert!(!id_set(&first).contains(&rows[c].0), "row {} is new", c + 1);
        assert_eq!(
            scan_stats(),
            ScanStats {
                batches: slices + 1,
                rescored: c as i64 + 100,
                capped: false,
                deepened: slices - 1,
                lists_probed: 14,
            }
        );

        let all = ranked_rows(table, "true", query, 4_000, false);
        assert_eq!(id_set(&all).len(), 4_000, "every row exactly once");
        let stats = scan_stats();
        assert_eq!((stats.rescored, stats.capped), (4_000, false), "{stats:?}");
    }

    /// The residual passes the 30 farthest rows of the first set: the bottom
    /// of its sketch ranking, still short of any new list.
    #[pg_test]
    fn am_iterative_scan_finds_a_deep_residual_match_without_probing_more_lists() {
        install_am_opclasses();
        let table = "am_iter_deep_residual";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let first = first_probed_set(table, query);
        let floor = first[first.len() - 31].1;
        let where_sql = format!(
            "embedding <-> '{}'::vector > {floor}",
            vector_literal(query)
        );
        assert_residual_plan_uses_index(table, &where_sql, query, 5);

        set_iterative_scan("relaxed_order");
        let rows = ranked_rows(table, &where_sql, query, 5, false);
        assert_eq!(rows.len(), 5);
        assert!(
            id_set(&rows).is_subset(&id_set(&first)),
            "a list beyond the first set was probed: {rows:?}"
        );
        let stats = scan_stats();
        assert_eq!(stats.lists_probed, 7, "{stats:?}");
        assert!(stats.deepened >= 2, "{stats:?}");
        assert_eq!(stats.batches, stats.deepened + 1, "{stats:?}");
    }

    #[pg_test]
    fn am_iterative_scan_cap_ends_the_scan_between_deepened_slices() {
        install_am_opclasses();
        let table = "am_iter_deep_cap";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let first = first_probed_set(table, query);
        assert!(first.len() > 200, "premise: {} rows", first.len());

        Spi::run("SET pinecone.max_scan_tuples = 150").expect("set max_scan_tuples");
        for mode in ["relaxed_order", "strict_order"] {
            set_iterative_scan(mode);
            let rows = ranked_rows(table, "true", query, 1_000, false);
            assert!(
                id_set(&rows).is_subset(&id_set(&first)),
                "{mode}: a list beyond the first set was probed"
            );
            assert_eq!(
                scan_stats(),
                ScanStats {
                    batches: 2,
                    rescored: 150,
                    capped: true,
                    deepened: 1,
                    lists_probed: 7,
                },
                "{mode}"
            );
        }
    }

    #[pg_test]
    fn am_iterative_scan_deepens_under_a_pushed_key() {
        install_am_opclasses();
        let table = "am_iter_deep_key";
        let vectors = uniform_random_vectors(207, 4_000, 16);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(16), tenant int8)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % 4).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 207, rescore_multiplier = 1)"
        ))
        .expect("create filtered local index");
        set_iterative_scan("relaxed_order");

        let ids = filtered_nearest_ids(table, "tenant = 2", &vectors[5], 300, false);
        assert_eq!(last_scan_mode(), "h");
        assert_eq!(ids.len(), 300);
        assert!(ids.iter().all(|id| (id - 1) % 4 == 2), "only tenant 2");
        let distinct: std::collections::HashSet<i64> = ids.iter().copied().collect();
        assert_eq!(distinct.len(), 300, "lists are disjoint: no row twice");
        let stats = scan_stats();
        assert_eq!(stats.lists_probed, 32, "{stats:?}");
        assert_eq!((stats.batches, stats.deepened), (3, 2), "{stats:?}");
    }

    #[pg_test]
    fn am_iterative_scan_strict_order_stays_monotone_across_deepened_slices() {
        install_am_opclasses();
        let table = "am_iter_deep_strict";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");

        // A LIMIT above the 7 probed lists' rows: below it strict_order refills from rows relaxed_order
        // returns too, as soon as the 256-bit codes rank well enough that few rows are dropped.
        set_iterative_scan("relaxed_order");
        let relaxed = ranked_rows(table, "true", query, 4_000, false);
        set_iterative_scan("strict_order");
        let strict = ranked_rows(table, "true", query, 4_000, false);
        let stats = scan_stats();

        assert!(
            strict.windows(2).all(|p| p[0].1 <= p[1].1 + 1e-4),
            "strict_order must be monotone: {strict:?}"
        );
        assert!(
            relaxed.windows(2).any(|p| p[0].1 > p[1].1 + 1e-4),
            "premise: slices overlap in distance"
        );
        assert!(
            strict.len() >= 100 && strict.len() < relaxed.len(),
            "strict {} rows vs relaxed {}",
            strict.len(),
            relaxed.len()
        );
        assert!(stats.deepened >= 1, "{stats:?}");
    }

    #[pg_test]
    fn am_iterative_scan_rescan_discards_the_unserved_candidates() {
        install_am_opclasses();
        let table = "am_iter_deep_rescan";
        let vectors = build_pool_100_table(table);
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        set_iterative_scan("relaxed_order");

        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let sql = format!(
            "SELECT q.id AS k, ARRAY(SELECT t.id FROM {table} t \
             ORDER BY t.embedding <-> q.embedding LIMIT 150) AS ids \
             FROM {table} q WHERE q.id IN (4, 1001, 3001) ORDER BY q.id"
        );
        let plan = explain_lines(&sql).join("\n");
        assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");
        let rows: Vec<(i64, Vec<i64>)> = Spi::connect(|client| {
            client
                .select(&sql, None, &[])
                .expect("nested loop query")
                .map(|row| {
                    (
                        row.get_by_name::<i64, _>("k").unwrap().unwrap(),
                        row.get_by_name::<Vec<i64>, _>("ids").unwrap().unwrap(),
                    )
                })
                .collect()
        });
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");

        assert_eq!(rows.len(), 3);
        for (id, ids) in rows {
            let fresh = ranked_rows(table, "true", &vectors[id as usize - 1], 150, false);
            assert_eq!(ids, ids_of(&fresh), "query row {id}");
        }
    }

    /// m1, widen path: a pool as large as the first set makes batch 2 a freshly
    /// probed set. The cap cuts it to the rows it leaves.
    #[pg_test]
    fn am_iterative_scan_cap_cuts_a_widened_batch_to_the_rows_left() {
        install_am_opclasses();
        let table = "am_iter_cap_widen_slice";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let c = first_probed_set(table, query).len() as i64;
        Spi::run("SET pinecone.rescore_multiplier = 1000").expect("set rescore_multiplier");
        Spi::run(&format!("SET pinecone.max_scan_tuples = {}", c + 50)).expect("set cap");
        set_iterative_scan("relaxed_order");

        let rows = ranked_rows(table, "true", query, 4_000, false);
        assert_eq!(
            rows.len() as i64,
            c + 50,
            "batch 1 = the first set, batch 2 = 50 rows"
        );
        assert_eq!(
            scan_stats(),
            ScanStats {
                batches: 2,
                rescored: c + 50,
                capped: true,
                deepened: 0,
                lists_probed: 14,
            }
        );
    }

    /// Pinned: the scan widens only after every candidate of the probed
    /// lists is rescored, and the cap counts rescored rows. A cap below the
    /// first set's size ends it before a second list is read, so a residual
    /// whose matches lie in unprobed lists finds nothing (at 1M rows the
    /// default cap is that cap). A cap at the set's size lets it widen.
    #[pg_test]
    fn am_iterative_scan_cap_below_the_first_set_never_widens() {
        install_am_opclasses();
        let table = "am_iter_cap_no_widen";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let first = first_probed_set(table, query);
        let c = first.len() as i64;
        assert!(c > 250, "premise: the first set holds {c} rows");
        let in_first: Vec<String> = first.iter().map(|(id, _)| id.to_string()).collect();
        let where_sql = format!("id <> ALL ('{{{}}}'::bigint[])", in_first.join(","));
        assert_residual_plan_uses_index(table, &where_sql, query, 10);
        set_iterative_scan("relaxed_order");

        Spi::run("SET pinecone.max_scan_tuples = 150").expect("set cap");
        let rows = ranked_rows(table, &where_sql, query, 10, false);
        assert!(
            rows.is_empty(),
            "no match lies in the probed lists: {rows:?}"
        );
        let stats = scan_stats();
        assert!(stats.capped, "{stats:?}");
        assert_eq!(stats.lists_probed, 7, "never widens: {stats:?}");
        assert!(
            stats.rescored < c,
            "the cap ended it inside the first set: {stats:?}"
        );

        Spi::run(&format!("SET pinecone.max_scan_tuples = {}", c + 100)).expect("raise the cap");
        let rows = ranked_rows(table, &where_sql, query, 10, false);
        assert_eq!(rows.len(), 10, "a cap at the set's size lets it widen");
        let stats = scan_stats();
        assert!(!stats.capped && stats.lists_probed > 7, "{stats:?}");
    }

    /// `(id, distance)` rows of an arbitrary query selecting `id` and `d`.
    fn rows_of_sql(sql: &str) -> Vec<(i64, f64)> {
        Spi::connect(|client| {
            client
                .select(sql, None, &[])
                .expect("rows_of_sql query")
                .map(|row| {
                    (
                        row.get_by_name::<i64, _>("id").unwrap().unwrap(),
                        row.get_by_name::<f64, _>("d").unwrap().unwrap(),
                    )
                })
                .collect()
        })
    }

    /// `relaxed_order` is batch-wise for every plan node that consumes the
    /// index order. An Incremental Sort (secondary `ORDER BY` column) trusts it
    /// and emits a later batch's rows out of order; `strict_order` stays
    /// monotone.
    #[pg_test]
    fn am_iterative_scan_order_consuming_nodes_see_the_batch_wise_order() {
        install_am_opclasses();
        let table = "am_iter_incsort";
        let vectors = build_pool_100_table(table);
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        let q = vector_literal(&vectors[3]);
        let sql = format!(
            "SELECT id, embedding <-> '{q}'::vector AS d FROM {table} \
             ORDER BY embedding <-> '{q}'::vector, id LIMIT 250"
        );
        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let plan = explain_lines(&sql).join("\n");
        assert!(plan.contains("Incremental Sort"), "plan: {plan}");
        assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");

        set_iterative_scan("relaxed_order");
        let relaxed = rows_of_sql(&sql);
        assert_eq!(relaxed.len(), 250);
        assert!(
            relaxed.windows(2).any(|p| p[0].1 > p[1].1 + 1e-4),
            "the Incremental Sort must pass the later batches' order on: {relaxed:?}"
        );

        set_iterative_scan("strict_order");
        let strict = rows_of_sql(&sql);
        assert!(
            strict.len() >= 100,
            "batch 1 passes in full: {}",
            strict.len()
        );
        assert!(
            strict.windows(2).all(|p| p[0].1 <= p[1].1 + 1e-4),
            "strict_order must be monotone through the sort: {strict:?}"
        );
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
    }

    /// Pinned: on uniform data later slices mostly hold rows closer than
    /// the last one served, so `strict_order` drops them and rescores until the
    /// lists run out (here the whole table) for the rows `off` already had. An
    /// early end loses rows on clustered data (probe), so the bill
    /// stays and the docs steer to `relaxed_order` plus a CTE re-sort.
    #[pg_test]
    fn am_iterative_scan_strict_order_pays_for_the_whole_table_on_uniform_data() {
        install_am_opclasses();
        let table = "am_iter_strict_burn";
        let n = 8_000;
        let vectors = uniform_random_vectors(301, n, 24);
        build_residual_table(table, &vectors, 333, "seed = 201, n_lists = 100");

        let queries: Vec<usize> = (0..20).map(|q| q * 397 + 11).collect();
        let (mut off_rows, mut relaxed_rows, mut strict_rows) = (0, 0, 0);
        for &row in &queries {
            let where_sql = format!("tenant = {}", (row + 100) % 333);
            let query = &vectors[row];
            set_iterative_scan("off");
            off_rows += filtered_nearest_ids(table, &where_sql, query, 10, false).len();
            set_iterative_scan("relaxed_order");
            relaxed_rows += filtered_nearest_ids(table, &where_sql, query, 10, false).len();
            set_iterative_scan("strict_order");
            strict_rows += filtered_nearest_ids(table, &where_sql, query, 10, false).len();
            let stats = scan_stats();
            assert_eq!(
                (stats.rescored, stats.capped),
                (n as i64, false),
                "strict_order rescored the whole table: {stats:?}"
            );
        }
        assert_eq!(
            relaxed_rows,
            10 * queries.len(),
            "relaxed_order fills every LIMIT"
        );
        assert!(
            off_rows <= strict_rows && strict_rows < relaxed_rows * 7 / 10,
            "off {off_rows}, strict {strict_rows}, relaxed {relaxed_rows} rows over {} queries",
            queries.len()
        );
    }

    /// m2: a probe step the pushed key empties (no record of the next lists
    /// carries it) is an empty batch: counted, no heap fetch, and the scan
    /// walks on to the lists that hold the key's rows. Tenant 1 is the cluster
    /// farthest from the query, so the nearest lists match nothing.
    #[pg_test]
    fn am_iterative_scan_walks_past_probe_steps_the_pushed_key_empties() {
        install_am_opclasses();
        let table = "am_iter_empty_step";
        let (n, dim, n_clusters) = (6_000, 24, 20);
        let vectors = deterministic_clustered_vectors(208, n, dim, n_clusters);
        let query = &vectors[0];
        let sq = |v: &[f32]| -> f32 { v.iter().zip(query).map(|(a, b)| (a - b) * (a - b)).sum() };
        let far_cluster = (0..n)
            .max_by(|&a, &b| sq(&vectors[a]).total_cmp(&sq(&vectors[b])))
            .unwrap()
            % n_clusters;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant int8)"
        ))
        .expect("create table");
        bulk_insert_vectors_with_tenant(table, &vectors, |i| {
            u8::from(i % n_clusters == far_cluster).to_string()
        });
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 100, seed = 208)"
        ))
        .expect("create filtered local index");
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        Spi::run("SET pinecone.force_scan_mode = 'h'").expect("force mode H");
        set_iterative_scan("relaxed_order");
        assert_filtered_plan_uses_index(table, "tenant = 1", query, 10);

        let ids = filtered_nearest_ids(table, "tenant = 1", query, 10, false);
        assert_eq!(last_scan_mode(), "h");
        assert_eq!(ids.len(), 10);
        let stats = scan_stats();
        assert!(
            stats.lists_probed >= 32,
            "the first steps match nothing: {stats:?}"
        );
        assert!(
            0 < stats.rescored && stats.rescored <= 300,
            "only the key's rows are rescored: {stats:?}"
        );
    }

    /// m4: `last_scan_stats()` belongs to the session. A scan zeroes it on its
    /// first batch and every later batch of any scan adds to it, so two scans
    /// in one statement report the one that started last (in a nested loop its
    /// last inner rescan) plus later batches of the other.
    #[pg_test]
    fn am_iterative_scan_stats_follow_the_scan_that_started_last() {
        install_am_opclasses();
        let (outer, inner) = ("am_iter_stats_outer", "am_iter_stats_inner");
        let vectors = build_pool_100_table(outer);
        build_pool_100_table(inner);
        set_iterative_scan("relaxed_order");
        let (q_outer, q_inner) = (&vectors[3], &vectors[5]);
        let (lit_outer, lit_inner) = (vector_literal(q_outer), vector_literal(q_inner));

        // Each scan alone: two batches for LIMIT 150 over a pool of 100.
        ranked_rows(inner, "true", q_inner, 150, false);
        let inner_alone = scan_stats();
        ranked_rows(outer, "true", q_outer, 150, false);
        let outer_alone = scan_stats();
        assert_eq!((inner_alone.batches, outer_alone.batches), (2, 2));

        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let run = |sql: &str| -> usize {
            let plan = explain_lines(sql).join("\n");
            assert!(plan.contains(&format!("{outer}_idx")), "plan: {plan}");
            assert!(plan.contains(&format!("{inner}_idx")), "plan: {plan}");
            Spi::connect(|client| client.select(sql, None, &[]).expect("query").count())
        };

        // Nested loop: the outer scan serves 3 rows from its first batch and
        // each of them rescans the inner one, which resets the counters.
        let nested = format!(
            "SELECT o.id AS k, x.id AS id FROM \
             (SELECT id, embedding FROM {outer} ORDER BY embedding <-> '{lit_outer}'::vector \
              LIMIT 3) o \
             CROSS JOIN LATERAL (SELECT i.id FROM {inner} i \
              ORDER BY i.embedding <-> o.embedding LIMIT 150) x"
        );
        assert_eq!(run(&nested), 3 * 150);
        let nested_stats = scan_stats();
        let last_outer = ids_of(&ranked_rows(outer, "true", q_outer, 3, false))[2];
        ranked_rows(inner, "true", &vectors[last_outer as usize - 1], 150, false);
        assert_eq!(
            nested_stats,
            scan_stats(),
            "the last inner rescan, not the outer scan"
        );

        // An uncorrelated subquery runs once, on the first outer row, between
        // the outer scan's first and second batch: the second adds to what the
        // inner scan left.
        let interleaved = format!(
            "SELECT o.id AS id, (SELECT count(*) FROM (SELECT i.id FROM {inner} i \
              ORDER BY i.embedding <-> '{lit_inner}'::vector LIMIT 150) s) AS n \
             FROM (SELECT id FROM {outer} ORDER BY embedding <-> '{lit_outer}'::vector \
              LIMIT 150) o"
        );
        assert_eq!(run(&interleaved), 150);
        assert_eq!(
            scan_stats(),
            ScanStats {
                batches: inner_alone.batches + outer_alone.batches - 1,
                rescored: inner_alone.rescored + outer_alone.rescored - 100,
                capped: false,
                deepened: inner_alone.deepened + outer_alone.deepened,
                lists_probed: inner_alone.lists_probed,
            }
        );
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
    }

    /// `FETCH {how} FROM {cursor}`: the ids it returns.
    fn fetch_ids(cursor: &str, how: &str) -> Vec<i64> {
        Spi::connect_mut(|client| {
            client
                .update(&format!("FETCH {how} FROM {cursor}"), None, &[])
                .expect("fetch")
                .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                .collect()
        })
    }

    /// Missing test 1: an index sweep between two fetches of an open cursor.
    /// The continuation holds heap TIDs and reads pages a sweep compacts in
    /// place: nothing may be skipped or served twice. A real VACUUM cannot
    /// purge a row the cursor's snapshot sees; this sweep is the worst case
    /// (entries of rows deleted after DECLARE vanish from unprobed lists, held
    /// candidates stay visible).
    #[pg_test]
    fn am_iterative_scan_survives_an_index_sweep_between_fetches() {
        install_am_opclasses();
        let table = "am_iter_sweep";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let first = id_set(&first_probed_set(table, query));
        set_iterative_scan("relaxed_order");
        let all = id_set(&ranked_rows(table, "true", query, 4_000, false));
        assert_eq!(all.len(), 4_000);

        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        let sql = format!(
            "SELECT id FROM {table} ORDER BY embedding <-> '{}'::vector",
            vector_literal(query)
        );
        let plan = explain_lines(&sql).join("\n");
        assert!(plan.contains(&format!("{table}_idx")), "plan: {plan}");
        Spi::run(&format!("DECLARE c CURSOR FOR {sql}")).expect("declare cursor");
        let served = fetch_ids("c", "100");
        assert_eq!(served.len(), 100, "batch 1 is served");

        let deleted: std::collections::BTreeSet<i64> =
            all.iter().copied().filter(|id| id % 5 == 0).collect();
        let ctids = ctid_map(table);
        let dead: std::collections::HashSet<(pg_sys::BlockNumber, pg_sys::OffsetNumber)> = deleted
            .iter()
            .map(|id| {
                let (block, offset) = ctids[&id.to_string()]
                    .split_once(':')
                    .expect("block:offset");
                (block.parse().unwrap(), offset.parse().unwrap())
            })
            .collect();
        Spi::run(&format!("DELETE FROM {table} WHERE id % 5 = 0")).expect("delete");
        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        let swept = unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            let meta = crate::local::metapage::read(index);
            let stats = crate::local::vacuum::ambulkdelete_local(
                index,
                &meta,
                crate::local::vacuum::dead_set_predicate(dead),
            );
            pg_sys::RelationClose(index);
            stats
        };
        assert_eq!(
            swept.dead,
            deleted.len() as u64,
            "the sweep dropped them all"
        );

        let rest = fetch_ids("c", "ALL");
        let union: Vec<i64> = served.iter().chain(&rest).copied().collect();
        let distinct: std::collections::BTreeSet<i64> = union.iter().copied().collect();
        assert_eq!(distinct.len(), union.len(), "no row served twice");
        let expected: std::collections::BTreeSet<i64> = all
            .iter()
            .copied()
            .filter(|id| !deleted.contains(id) || first.contains(id))
            .collect();
        assert_eq!(
            distinct, expected,
            "every surviving row, plus the deleted ones already probed (the snapshot sees them)"
        );
        Spi::run("CLOSE c").expect("close cursor");
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
    }

    /// Missing test 2: an ERROR mid-continuation (the live `IvfCont` is dropped
    /// by the memory-context callback, not `amendscan`) leaves the next
    /// statement unaffected. The qual raises on a batch-2 row, or the AM
    /// raises probing a corrupt list of its second step.
    fn recovers_from_an_error_mid_continuation(table: &str, mode: &str) {
        install_am_opclasses();
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        let q = vector_literal(query);
        let c = first_probed_set(table, query).len();
        set_iterative_scan(mode);
        let baseline = ranked_rows(table, "true", query, 4_000, false);
        assert_eq!(baseline.len(), 4_000);
        set_iterative_scan("off");
        let off = ranked_rows(table, "true", query, 100, false);
        set_iterative_scan(mode);
        assert_eq!(
            baseline[..100],
            off[..],
            "premise: batch 1 is what off returns"
        );

        // (1) The qual raises on a row served from batch 2.
        let boom_id = baseline[120].0;
        Spi::run(
            "CREATE FUNCTION am_iter_boom(bigint, bigint) RETURNS boolean LANGUAGE plpgsql AS \
             $f$ BEGIN IF $1 = $2 THEN RAISE EXCEPTION 'am_iter_boom'; END IF; RETURN true; \
             END $f$",
        )
        .expect("create function");
        assert_residual_plan_uses_index(table, &format!("am_iter_boom(id, {boom_id})"), query, 300);
        let raising = format!(
            "DO $do$ BEGIN \
             PERFORM id FROM {table} WHERE am_iter_boom(id, {boom_id}) \
               ORDER BY embedding <-> '{q}'::vector LIMIT 300; \
             RAISE EXCEPTION 'the qual did not raise'; \
             EXCEPTION WHEN raise_exception THEN \
               IF SQLERRM <> 'am_iter_boom' THEN RAISE; END IF; \
             END $do$"
        );
        for _ in 0..3 {
            // `ranked_rows` turns the seqscan back on.
            Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
            Spi::run(&raising).expect("the DO block swallows the qual's error");
            assert_eq!(ranked_rows(table, "true", query, 4_000, false), baseline);
        }

        // (2) The AM raises: a row of the second set lives on a page whose
        // chain loops back to itself, so the widen step fails.
        let row_in_second_set = baseline[c + 10].0;
        let (blkno, next) = Spi::get_two::<i64, i64>(&format!(
            "SELECT p.blkno, p.next_blkno \
             FROM pinecone._debug_local_list_pages('{table}_idx'::regclass) p \
             WHERE (SELECT ctid::text FROM {table} WHERE id = {row_in_second_set}) = ANY(p.tids)"
        ))
        .expect("page query");
        let (blkno, next) = (blkno.expect("page") as u32, next.expect("next"));
        let next = if next < 0 {
            crate::local::metapage::INVALID_BLOCK
        } else {
            next as u32
        };
        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        let poke = |to: u32| unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            crate::local::vacuum::test_set_next_block(index, blkno, to);
            pg_sys::RelationClose(index);
        };
        poke(blkno);
        let corrupt = format!(
            "DO $do$ BEGIN \
             PERFORM id FROM {table} ORDER BY embedding <-> '{q}'::vector LIMIT 4000; \
             RAISE EXCEPTION 'the scan did not raise'; \
             EXCEPTION WHEN OTHERS THEN \
               IF SQLERRM NOT LIKE '%cyclic%' THEN RAISE; END IF; \
             END $do$"
        );
        Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
        for _ in 0..3 {
            Spi::run(&corrupt).expect("the DO block swallows the scan's error");
        }
        poke(next);
        assert_eq!(ranked_rows(table, "true", query, 4_000, false), baseline);
    }

    #[pg_test]
    fn am_iterative_scan_recovers_from_an_error_mid_continuation() {
        recovers_from_an_error_mid_continuation("am_iter_error", "relaxed_order");
    }

    /// The same under `auto`, whose continuation starts over (a fresh `IvfCont`) after the first batch.
    #[pg_test]
    fn am_iterative_scan_auto_recovers_from_an_error_mid_continuation() {
        recovers_from_an_error_mid_continuation("am_iter_error_auto", "auto");
    }

    /// A first batch that probed every list and fetched every row has nothing left to find, so
    /// `auto` reads what `off` reads; with a pool below the table it does go on.
    #[pg_test]
    fn am_iterative_scan_auto_starts_no_continuation_after_a_whole_first_batch() {
        install_am_opclasses();
        let table = "am_auto_whole";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        Spi::run("SET pinecone.scan_fraction = 1.0").expect("probe every list");
        Spi::run("SET pinecone.rescore_multiplier = 50").expect("a pool above the 4,000 rows");
        Spi::run("SET pinecone.scan_prune = off").expect("fetch the whole pool");

        for where_sql in ["true", "tenant = 3"] {
            let all = ranked_rows(table, where_sql, query, 5_000, true).len();
            set_iterative_scan("off");
            let off = ranked_rows(table, where_sql, query, 5_000, false);
            let off_stats = scan_stats();
            reset_iterative_scan();
            let auto = ranked_rows(table, where_sql, query, 5_000, false);
            assert_eq!(auto.len(), all, "{where_sql}: every row");
            assert_eq!(auto, off, "{where_sql}");
            assert_eq!(scan_stats(), off_stats, "{where_sql}: no second scan");
        }

        Spi::run("SET pinecone.rescore_multiplier = 1").expect("a pool below the table");
        set_iterative_scan("off");
        ranked_rows(table, "true", query, 5_000, false);
        let off_lists = scan_stats().lists_probed;
        reset_iterative_scan();
        assert_eq!(ranked_rows(table, "true", query, 5_000, false).len(), 4_000);
        let stats = scan_stats();
        assert!(stats.lists_probed > off_lists, "{stats:?}");
    }

    /// Missing test 3: cursor `FETCH` across a batch boundary, `MOVE` and
    /// `SCROLL`. The AM cannot scan backward (`amcanbackward = false`), so the
    /// planner puts a Material node on a scrollable cursor and replays the
    /// stream.
    #[pg_test]
    fn am_iterative_scan_serves_cursor_fetch_move_and_scroll() {
        install_am_opclasses();
        let table = "am_iter_cursor";
        let vectors = build_pool_100_table(table);
        let query = &vectors[3];
        Spi::run("SET pinecone.scan_fraction = 0.1").expect("set scan_fraction");
        // `auto` serves the same stream through its continuation (the first batch, then a
        // relaxed_order scan that leaves it out).
        for mode in ["relaxed_order", "auto"] {
            set_iterative_scan(mode);
            let plain = ids_of(&ranked_rows(table, "true", query, 4_000, false));
            assert_eq!(plain.len(), 4_000, "{mode}");

            Spi::run("SET enable_seqscan = off").expect("set enable_seqscan off");
            let sql = format!(
                "SELECT id FROM {table} ORDER BY embedding <-> '{}'::vector",
                vector_literal(query)
            );
            let scroll_plan =
                explain_lines(&format!("DECLARE c SCROLL CURSOR FOR {sql}")).join("\n");
            assert!(scroll_plan.contains("Materialize"), "plan: {scroll_plan}");
            assert!(
                scroll_plan.contains(&format!("{table}_idx")),
                "plan: {scroll_plan}"
            );
            let forward_plan = explain_lines(&format!("DECLARE c CURSOR FOR {sql}")).join("\n");
            assert!(
                !forward_plan.contains("Materialize"),
                "plan: {forward_plan}"
            );
            assert!(
                forward_plan.contains(&format!("{table}_idx")),
                "plan: {forward_plan}"
            );

            // Forward only: FETCH across the batch boundary (100), MOVE, FETCH ALL.
            Spi::run(&format!("DECLARE f CURSOR FOR {sql}")).expect("declare cursor");
            assert_eq!(fetch_ids("f", "150"), plain[..150]);
            Spi::run("MOVE FORWARD 20 IN f").expect("move");
            assert_eq!(fetch_ids("f", "10"), plain[170..180]);
            assert_eq!(fetch_ids("f", "ALL"), plain[180..]);

            // Scrollable: backward and absolute fetches replay the same stream.
            Spi::run(&format!("DECLARE s SCROLL CURSOR FOR {sql}")).expect("declare scroll cursor");
            assert_eq!(fetch_ids("s", "150"), plain[..150]);
            let back: Vec<i64> = plain[99..149].iter().rev().copied().collect();
            assert_eq!(fetch_ids("s", "BACKWARD 50"), back);
            Spi::run("MOVE ABSOLUTE 0 IN s").expect("move to the start");
            assert_eq!(fetch_ids("s", "200"), plain[..200]);
            assert_eq!(fetch_ids("s", "ALL"), plain[200..]);
            let reversed: Vec<i64> = plain.iter().rev().copied().collect();
            assert_eq!(fetch_ids("s", "BACKWARD ALL"), reversed);
            Spi::run("CLOSE f").expect("close cursor");
            Spi::run("CLOSE s").expect("close scroll cursor");
            Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        }
    }

    // =========================================================================
    // Worker-driven maintenance for the local engine
    // (`maintain.rs`) — drift metric, schedule_maintenance, and
    // auto_maintain-gated REINDEX. `crate::maintain::run_round` is called
    // directly (Rust-internal — no SQL surface), same pattern
    // `outbox::Scheduler::drain_round` uses in its own tests above.
    // =========================================================================

    /// Builds a flat (small-N bootstrap — every count here is well below the
    /// default `small_n_threshold` of 10_000) local pg_pinecone index on `table`
    /// with `n_build` rows, then inserts `n_extra` more via ordinary
    /// `INSERT` (exercising `aminsert_local`'s `inserted_since_build` bump,
    /// unlike `ambuild`'s own collect scan). Returns every vector, in
    /// insertion/id order.
    fn build_local_index_with_drift(
        table: &str,
        seed: u64,
        n_build: usize,
        n_extra: usize,
    ) -> Vec<Vec<f32>> {
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(seed, n_build + n_extra, dim, 5);
        bulk_insert_vectors(table, &vectors[..n_build]);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");
        insert_more_vectors(table, &vectors, n_build, n_build + n_extra);
        vectors
    }

    /// Inserts `vectors[start..end]` into `table(id, embedding)` with ids
    /// `start+1..=end` — never overlapping `bulk_insert_vectors`' own
    /// `1..=n` numbering, so this is always the "more rows after the initial
    /// build" step.
    fn insert_more_vectors(table: &str, vectors: &[Vec<f32>], start: usize, end: usize) {
        let mut sql = format!("INSERT INTO {table} (id, embedding) VALUES ");
        for (i, v) in vectors[start..end].iter().enumerate() {
            if i > 0 {
                sql.push(',');
            }
            sql.push_str(&format!(
                "({}, '{}'::vector)",
                start + i + 1,
                vector_literal(v)
            ));
        }
        Spi::run(&sql).expect("insert additional vectors");
    }

    /// `pinecone.index_drift(index_name)`'s three columns, read directly.
    fn drift_of(index_name: &str) -> (i64, i64, f64) {
        Spi::connect(|client| {
            let mut rows = client
                .select(
                    &format!("SELECT * FROM pinecone.index_drift('{index_name}'::regclass)"),
                    None,
                    &[],
                )
                .expect("index_drift query");
            let row = rows.next().expect("index_drift returned a row");
            (
                row.get_by_name::<i64, _>("inserted_since_build")
                    .unwrap()
                    .unwrap(),
                row.get_by_name::<i64, _>("total").unwrap().unwrap(),
                row.get_by_name::<f64, _>("drift_fraction")
                    .unwrap()
                    .unwrap(),
            )
        })
    }

    #[pg_test]
    fn maintenance_index_drift_build_1000_insert_300() {
        install_am_opclasses();
        let table = "maint_drift_basic";
        build_local_index_with_drift(table, 1, 1000, 300);

        let (inserted, total, drift_fraction) = drift_of(&format!("{table}_idx"));
        assert_eq!(inserted, 300);
        assert_eq!(total, 1300);
        assert!(
            (drift_fraction - 300.0 / 1300.0).abs() < 1e-9,
            "drift_fraction = {drift_fraction}"
        );
        assert!((drift_fraction - 0.230769).abs() < 1e-5);
    }

    #[pg_test]
    fn maintenance_index_drift_errors_on_remote_mode_index() {
        let table = "maint_drift_remote_guard";
        setup_am_table(table);

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT * FROM pinecone.index_drift('{table}_idx')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message =
            outcome.expect_err("index_drift must error on a remote-mode pg_pinecone index");
        assert!(
            message.contains("not a local-mode pg_pinecone index"),
            "message = {message}"
        );
    }

    #[pg_test]
    fn maintenance_schedule_maintenance_errors_on_remote_mode_index_and_schedules_nothing() {
        let table = "maint_schedule_remote_guard";
        setup_am_table(table);

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.schedule_maintenance('{table}_idx')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome
            .expect_err("schedule_maintenance must error on a remote-mode pg_pinecone index");
        assert!(
            message.contains("not a local-mode pg_pinecone index"),
            "message = {message}"
        );

        // The remote-mode row is never touched by anything in `maintain.rs`
        // — nothing gets scheduled, and a maintenance round (even with
        // auto_maintain on) has nothing to act on for it.
        let scheduled = Spi::get_one::<i64>("SELECT count(*) FROM pinecone.index_maintenance")
            .expect("count query")
            .expect("count(*) is never NULL");
        assert_eq!(scheduled, 0);
    }

    #[pg_test]
    fn maintenance_auto_maintain_on_reindexes_past_threshold_and_resets_drift() {
        install_am_opclasses();
        let table = "maint_round_reindex";
        build_local_index_with_drift(table, 2, 1000, 300);

        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{table}_idx', 0.2)"
        ))
        .expect("schedule_maintenance");
        Spi::run("SET pinecone.auto_maintain = on").expect("enable auto_maintain");

        let reindexed = crate::maintain::run_round();
        assert_eq!(
            reindexed, 1,
            "one scheduled index over threshold must be reindexed this round"
        );

        let (inserted, total, drift_fraction) = drift_of(&format!("{table}_idx"));
        assert_eq!(inserted, 0, "REINDEX must reset inserted_since_build");
        assert_eq!(total, 1300, "REINDEX must recount the full current table");
        assert_eq!(drift_fraction, 0.0);
    }

    #[pg_test]
    fn maintenance_threshold_not_reached_skips_reindex() {
        install_am_opclasses();
        let table = "maint_threshold_not_met";
        build_local_index_with_drift(table, 4, 1000, 300); // drift ~0.2308

        // Threshold ABOVE the actual drift — must not fire.
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{table}_idx', 0.5)"
        ))
        .expect("schedule_maintenance");
        Spi::run("SET pinecone.auto_maintain = on").expect("enable auto_maintain");

        let reindexed = crate::maintain::run_round();
        assert_eq!(reindexed, 0, "drift below threshold must not reindex");

        let (inserted, ..) = drift_of(&format!("{table}_idx"));
        assert_eq!(
            inserted, 300,
            "an unfired schedule must leave the counter untouched"
        );
    }

    /// A native index below format 3 is offline until rebuilt, so the maintenance round counts it as
    /// fully drifted and rebuilds it however little it has drifted.
    #[pg_test]
    fn maintenance_auto_maintain_rebuilds_an_offline_index_far_below_its_threshold() {
        install_am_opclasses();
        let table = "maint_offline";
        build_local_index_with_drift(table, 7, 1000, 300); // drift ~0.2308
        let index = format!("{table}_idx");
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{index}', 0.5)"
        ))
        .expect("schedule_maintenance");
        Spi::run("SET pinecone.auto_maintain = on").expect("enable auto_maintain");
        am_format_set(&index, 1);
        assert_eq!(am_format_of(&index), (Some(1), false), "premise: offline");

        let reindexed = crate::maintain::run_round();

        assert_eq!(
            reindexed, 1,
            "an offline index is rebuilt in the next round"
        );
        assert_eq!(am_format_of(&index), (Some(3), true));
        let (inserted, ..) = drift_of(&index);
        assert_eq!(inserted, 0, "the rebuild reset the counter");
        let parked = Spi::get_one::<bool>(&format!(
            "SELECT queue_parked FROM pinecone.index_maintenance WHERE index_relid = '{index}'::regclass"
        ))
        .expect("read the schedule")
        .expect("a schedule row");
        assert!(!parked, "the schedule is not parked");
    }

    #[pg_test]
    fn maintenance_auto_maintain_off_never_fires() {
        install_am_opclasses();
        let table = "maint_auto_off";
        build_local_index_with_drift(table, 5, 1000, 300); // drift ~0.2308

        // Threshold well below the actual drift — would fire if enabled.
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{table}_idx', 0.1)"
        ))
        .expect("schedule_maintenance");
        // `pinecone.auto_maintain` is left at its coded default (off) —
        // deliberately no `SET` here.

        let reindexed = crate::maintain::run_round();
        assert_eq!(reindexed, 0, "auto_maintain=off must never reindex");

        let (inserted, ..) = drift_of(&format!("{table}_idx"));
        assert_eq!(
            inserted, 300,
            "a gated-off round must leave the counter untouched"
        );
    }

    #[pg_test]
    fn maintenance_repeated_failures_park_then_reschedule_clears_it() {
        install_am_opclasses();
        let schema = "maint_park_schema";
        let table = format!("{schema}.maint_park_case");
        let owner_role = "maint_park_owner";

        // `_maintenance_attempt`'s REINDEX line
        // now always runs under a `SET ROLE` to the table's CURRENT OWNER
        // (never the caller of `run_round`/the worker's own identity) — so
        // the only way to make a real (not simulated) REINDEX attempt
        // genuinely fail here is for the OWNER itself to lack some privilege
        // the rebuild needs. A schema-qualified `REINDEX INDEX schema.idx`
        // needs `USAGE` on `schema` to even resolve the name — a SEPARATE
        // ACL check from owning the table itself — so an owner with no
        // grant on a freshly-created schema (no `PUBLIC` default here,
        // unlike `public`) hits a genuine "permission denied for schema"
        // error every attempt.
        Spi::run(&format!("CREATE SCHEMA {schema}")).expect("create schema");
        Spi::run(&format!("CREATE ROLE {owner_role}")).expect("create role");
        // The grant bundle ANY plain-role-owned pg_pinecone index needs for its
        // REINDEX to work at all, worker-driven or manual alike — core's own
        // `index_build` switches to the TABLE OWNER before `ambuild` runs,
        // so `resolve_mode`'s engine-stickiness upsert into
        // `pinecone._am_engine` always executes as the owner (see the
        // runbook's maintenance section). Granted BEFORE the park phase
        // deliberately: the park-phase failures below must come from the
        // missing USAGE on `{schema}` itself, nothing else.
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {owner_role}"))
            .expect("grant pg_pinecone schema usage");
        Spi::run(&format!(
            "GRANT SELECT, INSERT, UPDATE ON pinecone._am_engine TO {owner_role}"
        ))
        .expect("grant _am_engine access");

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(4))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(6, 1300, 4, 5); // drift ~0.2308
        bulk_insert_vectors(&table, &vectors[..1000]);
        Spi::run(&format!(
            "CREATE INDEX maint_park_case_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");
        insert_more_vectors(&table, &vectors, 1000, 1300);
        let index = format!("{schema}.maint_park_case_idx");
        Spi::run(&format!("ALTER TABLE {table} OWNER TO {owner_role}"))
            .expect("transfer table ownership");

        // Scheduling itself is done by this (superuser) test connection —
        // ownership transfer doesn't change who's ALLOWED to schedule
        // (the ownership check bypasses for superuser, same as REINDEX's
        // own rule), only who the REINDEX actually runs as.
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{index}', 0.1)"
        ))
        .expect("schedule_maintenance");
        Spi::run("SET pinecone.auto_maintain = on").expect("enable auto_maintain");

        let max_attempts =
            Spi::get_one::<i32>("SELECT current_setting('pinecone.outbox_max_attempts')::int")
                .expect("read outbox_max_attempts")
                .expect("outbox_max_attempts is never NULL");

        for i in 0..max_attempts {
            let reindexed = crate::maintain::run_round();
            assert_eq!(
                reindexed, 0,
                "attempt {i}: an owner lacking schema USAGE must never actually reindex"
            );
        }

        let (attempts, queue_parked, last_error) = Spi::connect(|client| {
            let mut rows = client
                .select(
                    &format!(
                        "SELECT attempts, queue_parked, last_error FROM pinecone.index_maintenance \
                         WHERE index_relid = '{index}'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("read maintenance row");
            let row = rows.next().expect("maintenance row exists");
            (
                row.get_by_name::<i32, _>("attempts").unwrap().unwrap(),
                row.get_by_name::<bool, _>("queue_parked").unwrap().unwrap(),
                row.get_by_name::<String, _>("last_error").unwrap(),
            )
        });
        assert!(
            queue_parked,
            "must park after {max_attempts} consecutive failures (attempts={attempts})"
        );
        assert!(
            last_error
                .as_deref()
                .unwrap_or("")
                .to_lowercase()
                .contains("permission denied"),
            "last_error = {last_error:?}"
        );

        // A parked schedule is skipped even though drift still clears the
        // threshold — the poison escape valve, not a silent infinite retry.
        let reindexed = crate::maintain::run_round();
        assert_eq!(reindexed, 0, "a parked schedule must be skipped");

        // The operator fixes the actual underlying problem (grants the
        // owner schema USAGE), then re-schedules — the one retry hatch this
        // module has — which clears the park, and the next round succeeds.
        Spi::run(&format!("GRANT USAGE ON SCHEMA {schema} TO {owner_role}"))
            .expect("grant schema usage — fixes the real underlying problem");
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{index}', 0.1)"
        ))
        .expect("re-schedule clears the park");
        let reindexed = crate::maintain::run_round();
        assert_eq!(
            reindexed, 1,
            "re-scheduling must clear the park and let the next round reindex"
        );

        Spi::run(&format!("DROP SCHEMA {schema} CASCADE")).expect("drop schema (and its table)");
        Spi::run(&format!(
            "REVOKE ALL ON pinecone._am_engine FROM {owner_role}"
        ))
        .expect("revoke _am_engine access");
        Spi::run(&format!(
            "REVOKE USAGE ON SCHEMA pinecone FROM {owner_role}"
        ))
        .expect("revoke pg_pinecone schema usage");
        Spi::run(&format!("DROP ROLE {owner_role}")).expect("drop role");
    }

    #[pg_test]
    fn maintenance_status_reports_scheduled_indexes() {
        install_am_opclasses();
        let table = "maint_status_case";
        build_local_index_with_drift(table, 7, 1000, 300);
        Spi::run(&format!(
            "SELECT pinecone.schedule_maintenance('{table}_idx', 0.2)"
        ))
        .expect("schedule_maintenance");

        let (index_name, drift_threshold, inserted, total, drift_fraction, queue_parked) =
            Spi::connect(|client| {
                let mut rows = client
                    .select("SELECT * FROM pinecone.maintenance_status()", None, &[])
                    .expect("maintenance_status query");
                let row = rows.next().expect("maintenance_status returned a row");
                (
                    row.get_by_name::<String, _>("index_name").unwrap().unwrap(),
                    row.get_by_name::<f64, _>("drift_threshold")
                        .unwrap()
                        .unwrap(),
                    row.get_by_name::<i64, _>("inserted_since_build").unwrap(),
                    row.get_by_name::<i64, _>("total").unwrap(),
                    row.get_by_name::<f64, _>("drift_fraction").unwrap(),
                    row.get_by_name::<bool, _>("queue_parked").unwrap().unwrap(),
                )
            });
        assert_eq!(index_name, format!("{table}_idx"));
        assert_eq!(drift_threshold, 0.2);
        assert_eq!(inserted, Some(300));
        assert_eq!(total, Some(1300));
        assert!(drift_fraction.is_some_and(|f| (f - 0.230769).abs() < 1e-5));
        assert!(!queue_parked);
    }

    // =========================================================================
    // Security: schedule_maintenance
    // ownership, cached_directory/read_list_heads corruption bounds, chain
    // cycle guards, index_drift/_debug_local_list_pages infoleak, NaN
    // poisoning.
    // =========================================================================

    /// Only the table owner (or a superuser)
    /// may schedule maintenance on an index — a non-owner's attempt must
    /// error. NOTE: nothing (not even a catalog probe) runs after the
    /// `PgTryBuilder` catch — see the reloption-validation tests' shared note
    /// on why (`am_local_invalid_mode_reloption_errors` et al.) — so the
    /// `SET ROLE` happens BEFORE entering the try, and the test ends right
    /// after asserting on the message.
    #[pg_test]
    fn maintenance_schedule_maintenance_requires_table_ownership() {
        install_am_opclasses();
        let table = "maint_owner_guard";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(20, 100, dim, 3);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        let role = "maint_non_owner";
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.schedule_maintenance('{table}_idx')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("a non-owner must not be able to schedule maintenance");
        assert!(message.contains("must own"), "message = {message}");
    }

    /// Neither engine evaluates `ii_Predicate`
    /// anywhere, so a partial pg_pinecone index would silently behave as a full
    /// one — rejected outright at `CREATE INDEX` time. NOTE: nothing runs
    /// after the `PgTryBuilder` catch (see the note above).
    #[pg_test]
    fn am_ambuild_rejects_partial_index() {
        install_am_opclasses();
        let table = "am_partial_index_guard";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(21, 50, dim, 3);
        bulk_insert_vectors(table, &vectors);

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
                 WITH (mode = 'local') WHERE id > 10"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message =
            outcome.expect_err("a partial pg_pinecone index must be rejected at CREATE INDEX");
        assert!(message.contains("partial index"), "message = {message}");
    }

    /// `index_drift` computes straight from the
    /// metapage buffer, entirely outside SQL's own ACL machinery — without
    /// its own `SELECT`-privilege check it would leak an approximate row
    /// count/drift fraction to any caller with bare `EXECUTE` (PUBLIC by
    /// default), regardless of whether they can read the table itself. NOTE:
    /// nothing runs after the `PgTryBuilder` catch (see the note above) — the
    /// "granting SELECT then works" half is a separate test.
    #[pg_test]
    fn maintenance_index_drift_requires_select_privilege() {
        install_am_opclasses();
        let table = "maint_drift_acl_guard";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(22, 100, dim, 3);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        let role = "maint_drift_no_select";
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        // Deliberately no grant on `table` itself.

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT * FROM pinecone.index_drift('{table}_idx')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("index_drift must require SELECT on the underlying table");
        assert!(
            message.contains("insufficient privilege"),
            "message = {message}"
        );
    }

    /// The other half of the test above: granting `SELECT` (no
    /// ownership needed) is enough for `index_drift` to succeed — a separate
    /// test/connection from the rejection case above since nothing may run
    /// after a `PgTryBuilder`-caught error in the SAME test.
    #[pg_test]
    fn maintenance_index_drift_succeeds_with_select_privilege() {
        install_am_opclasses();
        let table = "maint_drift_select_ok";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(23, 100, dim, 3);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        let role = "maint_drift_with_select";
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!("GRANT SELECT ON {table} TO {role}")).expect("grant select");

        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let (inserted, total, drift_fraction) = Spi::connect(|client| {
            let mut rows = client
                .select(
                    &format!("SELECT * FROM pinecone.index_drift('{table}_idx')"),
                    None,
                    &[],
                )
                .expect("index_drift must succeed with SELECT granted");
            let row = rows.next().expect("index_drift returned a row");
            (
                row.get_by_name::<i64, _>("inserted_since_build")
                    .unwrap()
                    .unwrap(),
                row.get_by_name::<i64, _>("total").unwrap().unwrap(),
                row.get_by_name::<f64, _>("drift_fraction")
                    .unwrap()
                    .unwrap(),
            )
        });
        Spi::run("RESET ROLE").expect("RESET ROLE");

        assert_eq!(inserted, 0, "no post-build inserts happened");
        assert_eq!(total, 100);
        assert_eq!(drift_fraction, 0.0);
    }

    /// `_debug_local_list_pages` used to read
    /// block 0 of WHATEVER relation it was pointed at and interpret it as a
    /// metapage — for a non-pg_pinecone relation that's a plain heap page,
    /// producing an "unknown version N" error that echoed 4 raw bytes of
    /// that page back to the caller. It must now reject any non-pg_pinecone-AM
    /// relation outright, before ever reading a page.
    #[pg_test]
    fn debug_local_list_pages_rejects_non_pg_pinecone_relation() {
        let table = "debug_pages_non_pg_pinecone_guard";
        Spi::run(&format!("CREATE TABLE {table} (id bigint PRIMARY KEY)")).expect("create table");
        Spi::run(&format!("INSERT INTO {table} VALUES (1)")).expect("insert one row");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT * FROM pinecone._debug_local_list_pages('{table}')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("must reject a plain (non-pg_pinecone-AM) relation");
        assert!(
            message.contains("is not a pg_pinecone access-method index"),
            "message = {message}"
        );
    }

    /// `metapage::read`'s own defense-in-depth
    /// bound on `n_lists` (`validate_untrusted_fields`) — a corrupt on-disk
    /// value above the `n_lists` reloption's own ceiling must raise a clean
    /// "corrupt metapage" error, not silently drive a downstream
    /// allocation/loop with a bogus count.
    #[pg_test]
    fn metapage_read_rejects_corrupt_n_lists() {
        install_am_opclasses();
        let table = "metapage_corrupt_n_lists";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(83, 50, dim, 3);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 83)"
        ))
        .expect("create clustered local pg_pinecone index");

        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            // Well above MAX_N_LISTS (1_000_000).
            crate::local::metapage::test_corrupt_n_lists(index, 5_000_000);
            pg_sys::RelationClose(index);
        }

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT * FROM pinecone.index_drift('{table}_idx')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("a corrupt n_lists must raise a clean ERROR");
        assert!(message.contains("corrupt metapage"), "message = {message}");
    }

    // ---- metapage format version (in-place upgrades) ----

    /// The format word a build of this version writes: the format in its low byte, the page layout in the next.
    fn current_format_word() -> i64 {
        i64::from(crate::local::metapage::Stored::CURRENT.word())
    }

    /// The format word `index`'s `fork` stores on disk: the page header (24 bytes), then the last word
    /// of the metapage payload, little-endian.
    fn am_format_stored(index: &str, fork: &str) -> i64 {
        Spi::run("CREATE EXTENSION IF NOT EXISTS pageinspect").expect("create pageinspect");
        let at = 24 + crate::local::metapage::FORMAT_OFFSET;
        Spi::get_one::<i64>(&format!(
            "SELECT get_byte(p, {at})::bigint + (get_byte(p, {})::bigint << 8) \
                    + (get_byte(p, {})::bigint << 16) + (get_byte(p, {})::bigint << 24) \
             FROM get_raw_page('{index}', '{fork}', 0) p",
            at + 1,
            at + 2,
            at + 3
        ))
        .expect("format word query")
        .expect("format word is not NULL")
    }

    /// `pinecone.index_format(index)` as `(format_version, readable)`.
    fn am_format_of(index: &str) -> (Option<i32>, bool) {
        let (format, readable) = Spi::get_two::<i32, bool>(&format!(
            "SELECT format_version, readable FROM pinecone.index_format('{index}')"
        ))
        .expect("index_format query");
        (format, readable.expect("readable is not NULL"))
    }

    fn am_format_oid(relation: &str) -> pg_sys::Oid {
        Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{relation}'::regclass::oid"))
            .expect("oid query")
            .expect("oid not null")
    }

    /// Overwrites the `u32` at `offset` of `index`'s metapage payload (0: the layout tag).
    fn am_format_write(index: &str, offset: usize, value: u32) {
        unsafe {
            let rel = pg_sys::RelationIdGetRelation(am_format_oid(index));
            crate::local::metapage::test_write_u32(rel, offset, value);
            pg_sys::RelationClose(rel);
        }
    }

    /// Stores `value` as `index`'s format word: 0 is what 0.9 wrote.
    fn am_format_set(index: &str, value: u32) {
        am_format_write(index, crate::local::metapage::FORMAT_OFFSET, value);
    }

    /// One `ambulkdelete` pass over `index` through Postgres's own entry point (a real `VACUUM`
    /// cannot run in a test's transaction), with a callback that kills nothing.
    fn am_format_bulk_delete(index: &str, heap: &str) {
        unsafe extern "C-unwind" fn keep(
            _tid: *mut pg_sys::ItemPointerData,
            _state: *mut std::ffi::c_void,
        ) -> bool {
            false
        }
        const LOCK: pg_sys::LOCKMODE = pg_sys::RowExclusiveLock as pg_sys::LOCKMODE;
        unsafe {
            let index_rel = pg_sys::index_open(am_format_oid(index), LOCK);
            let heap_rel = pg_sys::table_open(am_format_oid(heap), LOCK);
            let mut info: pg_sys::IndexVacuumInfo = std::mem::zeroed();
            info.index = index_rel;
            info.heaprel = heap_rel;
            info.message_level = pg_sys::DEBUG1 as i32;
            pg_sys::index_bulk_delete(
                &mut info,
                std::ptr::null_mut(),
                Some(keep),
                std::ptr::null_mut(),
            );
            pg_sys::table_close(heap_rel, LOCK);
            pg_sys::index_close(index_rel, LOCK);
        }
    }

    /// A 300-row clustered native index (`small_n_threshold = 10`: IVF lists exist), plain or with a
    /// `tenant` filter column; returns the vectors.
    fn am_format_native(table: &str, filtered: bool) -> Vec<Vec<f32>> {
        install_am_opclasses();
        let (dim, n) = (4, 300);
        let tenant = if filtered { ", tenant int4" } else { "" };
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}){tenant})"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(91, n, dim, 6);
        if filtered {
            bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % 5).to_string());
        } else {
            bulk_insert_vectors(table, &vectors);
        }
        let key = if filtered { ", tenant" } else { "" };
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops{key}) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 91)"
        ))
        .expect("create native pg_pinecone index");
        vectors
    }

    /// An index built by this release carries format 3: native plain (v2 layout), native filtered
    /// (v3 layout), the init fork of an unlogged one, and a remote-mode index.
    #[pg_test]
    fn am_format_fresh_indexes_report_3() {
        for (table, filtered) in [("am_fmt_plain", false), ("am_fmt_filtered", true)] {
            am_format_native(table, filtered);
            let index = format!("{table}_idx");
            assert_eq!(am_format_of(&index), (Some(3), true), "{table}");
            assert_eq!(
                am_format_stored(&index, "main"),
                current_format_word(),
                "{table}"
            );
        }

        install_am_opclasses();
        Spi::run(
            "CREATE UNLOGGED TABLE am_fmt_unlogged (id bigint PRIMARY KEY, embedding vector(4))",
        )
        .expect("create unlogged table");
        Spi::run(
            "CREATE INDEX am_fmt_unlogged_idx ON am_fmt_unlogged USING pinecone \
             (embedding vector_l2_ops) WITH (mode = 'local')",
        )
        .expect("create unlogged index");
        assert_eq!(
            am_format_stored("am_fmt_unlogged_idx", "init"),
            current_format_word()
        );

        setup_am_table("am_fmt_remote");
        assert_eq!(
            index_mode("am_fmt_remote_idx"),
            crate::local::metapage::Mode::Remote
        );
        assert_eq!(am_format_of("am_fmt_remote_idx"), (Some(3), true));
        assert_eq!(
            am_format_stored("am_fmt_remote_idx", "main"),
            current_format_word()
        );
    }

    /// A 0.9 page has zero in the format word: it reads as format 1, and a native index of that
    /// format is refused (its codes are the old sketch). An in-place page update keeps the word, and
    /// REINDEX stamps the new format. A remote index of that format keeps working
    /// (`native_format_remote_index_is_unaffected_by_the_refusal`).
    #[pg_test]
    fn am_format_zero_is_format_1_and_a_native_one_is_refused() {
        use crate::local::metapage::{FORMAT_OFFSET, Mode};
        for (table, filtered) in [("am_fmt_zero", false), ("am_fmt_zero_f", true)] {
            let vectors = am_format_native(table, filtered);
            let index = format!("{table}_idx");
            let query = &vectors[7];

            // An insert bumps the counter and a mode flip rewrites a byte, in place: neither touches
            // the word.
            let extra = vector_literal(&vectors[0]);
            let tenant = if filtered { ", 1" } else { "" };
            let columns = if filtered { ", tenant" } else { "" };
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding{columns}) VALUES (9000, '{extra}'::vector{tenant})"
            ))
            .expect("insert into a format-3 index");
            am_format_bulk_delete(&index, table);
            let before = nearest_ids(table, query, 10, false);
            assert!(!before.is_empty(), "{table}");

            am_format_set(&index, 0);
            assert_eq!(
                am_format_of(&index),
                (Some(1), false),
                "{table}: zero reads as 1, and a native index of format 1 is not readable"
            );
            unsafe {
                let rel = pg_sys::RelationIdGetRelation(am_format_oid(&index));
                crate::local::metapage::flip_mode(rel, Mode::Promoting);
                crate::local::metapage::flip_mode(rel, Mode::Local);
                pg_sys::RelationClose(rel);
            }
            assert_eq!(
                am_format_stored(&index, "main"),
                0,
                "{table}: in-place updates keep it"
            );
            // An explicit 1 is the same layout.
            am_format_write(&index, FORMAT_OFFSET, 1);
            assert_eq!(am_format_of(&index), (Some(1), false), "{table}");

            let named = format!("pg_pinecone index '{index}' has format version 1");
            Spi::run("SET enable_seqscan = off").expect("force the index");
            let error = fts_sql_error(&format!(
                "SELECT id FROM {table} ORDER BY embedding <-> '{}'::vector LIMIT 3",
                vector_literal(query)
            ));
            Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
            fts_assert_error(&error, "55000", &[&named, "this build reads", "REINDEX it"]);

            Spi::run(&format!("REINDEX INDEX {index}")).expect("REINDEX");
            assert_eq!(am_format_of(&index), (Some(3), true), "{table}");
            assert_eq!(
                am_format_stored(&index, "main"),
                current_format_word(),
                "{table}"
            );
            assert_eq!(
                nearest_ids(table, query, 10, false),
                before,
                "{table}: scan"
            );
        }
    }

    /// A newer format (4) is refused on scan, insert, vacuum and the drift readers with 55000 and
    /// the REINDEX hint, `index_format` still reports it, and REINDEX repairs the index.
    #[pg_test]
    fn am_format_newer_native_index_is_refused_until_reindex() {
        let table = "am_fmt_newer";
        let vectors = am_format_native(table, false);
        let index = format!("{table}_idx");
        let query = vector_literal(&vectors[7]);
        let before = nearest_ids(table, &vectors[7], 10, false);
        Spi::run(&format!("SELECT pinecone.schedule_maintenance('{index}')"))
            .expect("schedule maintenance");

        am_format_set(&index, 4);
        assert_eq!(am_format_of(&index), (Some(4), false));

        let named = format!("pg_pinecone index '{index}' has format version 4");
        let refused = |error: FtsError| {
            fts_assert_error(&error, "55000", &[&named, "reads up to 3", "REINDEX it"]);
        };
        Spi::run("SET enable_seqscan = off").expect("force the index");
        refused(fts_sql_error(&format!(
            "SELECT id FROM {table} ORDER BY embedding <-> '{query}'::vector LIMIT 3"
        )));
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        refused(fts_sql_error(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (9000, '{query}'::vector)"
        )));
        refused(fts_error_of(|| am_format_bulk_delete(&index, table)));
        refused(fts_sql_error(&format!(
            "SELECT * FROM pinecone.index_drift('{index}')"
        )));
        refused(fts_sql_error("SELECT * FROM pinecone.maintenance_status()"));

        Spi::run(&format!("REINDEX INDEX {index}")).expect("REINDEX");
        assert_eq!(am_format_of(&index), (Some(3), true));
        assert_eq!(nearest_ids(table, &vectors[7], 10, false), before);
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (9000, '{query}'::vector)"
        ))
        .expect("insert after REINDEX");
    }

    /// The same for a remote-mode index: refused on scan, insert and vacuum before any Pinecone call,
    /// repaired by REINDEX.
    #[pg_test]
    fn am_format_newer_remote_index_is_refused_until_reindex() {
        let table = "am_fmt_newer_remote";
        setup_am_table(table);
        let index = format!("{table}_idx");

        am_format_set(&index, 4);
        assert_eq!(am_format_of(&index), (Some(4), false));

        let named = format!("pg_pinecone index '{index}' has format version 4");
        let refused = |error: FtsError| {
            fts_assert_error(&error, "55000", &[&named, "reads up to 3", "REINDEX it"]);
        };
        Spi::run("SET enable_seqscan = off").expect("force the index");
        refused(fts_sql_error(&format!(
            "SELECT id FROM {table} ORDER BY embedding <=> '[1,0,0]'::vector LIMIT 3"
        )));
        Spi::run("SET enable_seqscan = on").expect("restore enable_seqscan");
        refused(fts_sql_error(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
        )));
        refused(fts_error_of(|| am_format_bulk_delete(&index, table)));

        Spi::run(&format!("REINDEX INDEX {index}")).expect("REINDEX");
        assert_eq!(am_format_of(&index), (Some(3), true));
        assert_eq!(index_mode(&index), crate::local::metapage::Mode::Remote);
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
        ))
        .expect("insert after REINDEX");
    }

    /// `index_format` takes a pg_pinecone index only, and reports a block 0 it does not know as NULL.
    #[pg_test]
    fn am_format_index_format_rejects_other_relations_and_unknown_pages() {
        am_format_native("am_fmt_misc", false);
        for relation in ["am_fmt_misc", "am_fmt_misc_pkey"] {
            let error = fts_sql_error(&format!(
                "SELECT * FROM pinecone.index_format('{relation}')"
            ));
            assert!(
                error.message.contains(relation)
                    && error
                        .message
                        .contains("is not a pg_pinecone access-method index"),
                "{error:?}"
            );
        }
        am_format_write("am_fmt_misc_idx", 0, 99);
        assert_eq!(am_format_of("am_fmt_misc_idx"), (None, false));
    }

    /// `cached_directory`'s own per-page bound
    /// — a directory page whose on-page `n_entries` header claims more
    /// entries than could ever physically fit must raise a clean "corrupt"
    /// ERROR instead of copying past the page (or the destination
    /// allocation)'s bounds.
    #[pg_test]
    fn scan_cached_directory_rejects_oversized_n_entries() {
        install_am_opclasses();
        let table = "scan_dir_corrupt_n_entries";
        let dim = 4;
        let n = 300;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(81, n, dim, 5);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 81)"
        ))
        .expect("create clustered local pg_pinecone index");

        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            let meta = crate::local::metapage::read(index);
            assert!(!meta.is_flat, "fixture sanity: clustered build");
            crate::local::scan::test_corrupt_directory_n_entries(
                index,
                meta.centroid_dir_start,
                u32::MAX / 2,
            );
            pg_sys::RelationClose(index);
        }

        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        Spi::run("SET pinecone.am_enabled = on").expect("enable pg_pinecone am");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT id FROM {table} ORDER BY embedding <-> '[0.1,0.2,0.3,0.4]'::vector LIMIT 5"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message =
            outcome.expect_err("an oversized n_entries must raise a clean ERROR, not crash");
        assert!(message.contains("corrupt"), "message = {message}");
    }

    /// The filter-stats page's bound: a header claiming more entries than the writer ever stores
    /// must raise a clean "corrupt" ERROR on a filtered scan, not size an allocation from it (which
    /// aborts the backend where the OS refuses it).
    #[pg_test]
    fn scan_filter_stats_page_rejects_an_oversized_n_entries() {
        install_am_opclasses();
        let table = "scan_stats_corrupt_n_entries";
        let (dim, n, n_tenants) = (4, 600, 5);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}), tenant int8)"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(82, n, dim, n_tenants);
        bulk_insert_vectors_with_tenant(table, &vectors, |i| (i % n_tenants).to_string());
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops, tenant) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 82)"
        ))
        .expect("create filtered clustered local index");

        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            let meta = crate::local::metapage::read(index);
            assert!(!meta.is_flat, "fixture sanity: clustered build");
            assert_ne!(
                meta.stats_start,
                crate::local::metapage::INVALID_BLOCK,
                "fixture sanity: a filtered index has a stats page"
            );
            crate::local::stats::test_corrupt_n_entries(index, meta.stats_start, u32::MAX);
            pg_sys::RelationClose(index);
        }

        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        Spi::run("SET pinecone.am_enabled = on").expect("enable pg_pinecone am");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT id FROM {table} WHERE tenant = 3 \
                 ORDER BY embedding <-> '[0.1,0.2,0.3,0.4]'::vector LIMIT 5"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("an oversized n_entries must raise a clean ERROR");
        assert!(
            message.contains("corrupt stats page") && message.contains("exceeds"),
            "message = {message}"
        );
    }

    /// A cyclic list-page chain (crafted by
    /// pointing a single-page list's `next_block` back at itself) must raise
    /// a clean ERROR naming the corruption, never hang the backend.
    #[pg_test]
    fn scan_list_chain_cycle_errors_cleanly_not_hang() {
        install_am_opclasses();
        let table = "scan_list_cycle_guard";
        let dim = 4;
        let n = 300;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(84, n, dim, 5);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 84, n_lists = 1)"
        ))
        .expect("create single-list clustered local pg_pinecone index");

        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        unsafe {
            let index = pg_sys::RelationIdGetRelation(index_oid);
            let meta = crate::local::metapage::read(index);
            assert!(!meta.is_flat, "fixture sanity: clustered build");
            let heads = crate::local::vacuum::read_list_heads(index, &meta);
            let head = heads[0];
            assert_ne!(
                head,
                crate::local::metapage::INVALID_BLOCK,
                "fixture sanity: the single list must have records"
            );
            // Self-loop: the list's own (only) page points its `next_block`
            // back at itself.
            crate::local::vacuum::test_set_next_block(index, head, head);
            pg_sys::RelationClose(index);
        }

        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        Spi::run("SET pinecone.am_enabled = on").expect("enable pg_pinecone am");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT id FROM {table} ORDER BY embedding <-> '[0.1,0.2,0.3,0.4]'::vector LIMIT 5"
            ))
            .expect("statement should raise a Postgres ERROR, not an SpiError (or hang)");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message =
            outcome.expect_err("a cyclic list-page chain must raise a clean ERROR, not hang");
        assert!(
            message.to_lowercase().contains("cyclic") || message.to_lowercase().contains("corrupt"),
            "message = {message}"
        );
    }

    /// The BUILD/INSERT-path completion of the scan-path fix: a
    /// stored vector whose finite,
    /// pgvector-accepted 1e20-magnitude components overflow to Inf inside
    /// our own arithmetic (cosine: `Inf/Inf = NaN` in the similarity) must
    /// abort neither the clustered `CREATE INDEX` (k-means/final-assign
    /// `nearest_centroid`) nor a later `INSERT`'s nearest-centroid append —
    /// both used `partial_cmp().expect("NaN distance")` before this fix.
    #[pg_test]
    fn am_local_build_and_insert_tolerate_inf_overflow_vectors() {
        install_am_opclasses();
        let table = "am_nan_build";
        let dim = 4;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(23, 200, dim, 4);
        bulk_insert_vectors(table, &vectors);
        // The poison row: finite f32 components whose squared magnitude
        // overflows f32 (1e20^2 = 1e40 > f32::MAX) — same vector class as
        // the query-side test.
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (9001, '[1e20,1e20,1e20,1e20]')"
        ))
        .expect("insert overflow row");

        // Clustered COSINE build: final assign runs nearest_centroid over
        // EVERY row, the poison one included — panicked pre-fix.
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 23)"
        ))
        .expect("clustered build over an Inf-overflow row must not panic");

        // Insert path: aminsert's own nearest-centroid append on another
        // poison row — panic-free too.
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (9002, '[-1e20,1e20,-1e20,1e20]')"
        ))
        .expect("aminsert of an Inf-overflow row must not panic");

        // The index still answers a normal query.
        Spi::run("SET enable_seqscan = off").expect("seqscan off");
        let n: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM (SELECT id FROM {table} \
             ORDER BY embedding <=> '{}'::vector LIMIT 10) s",
            vector_literal(&vectors[0])
        ))
        .expect("post-build scan")
        .expect("count NOT NULL");
        Spi::run("SET enable_seqscan = on").expect("seqscan on");
        assert_eq!(n, 10, "the index must still serve normal queries");
    }

    /// A query vector engineered so the
    /// calibrated-Hamming distance ESTIMATE overflows to `Infinity - Infinity`
    /// (NaN) for essentially every candidate must never abort the scan —
    /// `total_cmp` (not `partial_cmp().expect(...)`) sorts a NaN candidate to
    /// the "worse" end instead of panicking mid-sort/mid-selection.
    #[pg_test]
    fn scan_nan_estimated_distance_never_errors_the_scan() {
        install_am_opclasses();
        let table = "scan_nan_guard";
        let dim = 4;
        let n = 300;
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}))"
        ))
        .expect("create table");
        let vectors = deterministic_clustered_vectors(85, n, dim, 5);
        bulk_insert_vectors(table, &vectors);
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local', small_n_threshold = 10, seed = 85)"
        ))
        .expect("create clustered local pg_pinecone index");

        Spi::run("SET enable_seqscan = off").expect("disable seqscan");
        Spi::run("SET pinecone.am_enabled = on").expect("enable pg_pinecone am");

        // `1e20` is a perfectly valid (finite) `f32` component pgvector
        // itself accepts — the overflow to `Infinity` (and, downstream in
        // `estimate_distance`'s `Infinity - Infinity` L2 formula, to NaN)
        // happens entirely inside pg_pinecone's own arithmetic, on ordinary SQL
        // input, no page corruption needed.
        let ids: Vec<i64> = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT id FROM {table} ORDER BY embedding <-> '[1e20,0,0,0]'::vector \
                         LIMIT 5"
                    ),
                    None,
                    &[],
                )
                .expect("a NaN-inducing query must not error the scan")
                .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                .collect()
        });
        assert!(!ids.is_empty(), "must still return some rows, not zero");
    }

    // =========================================================================
    // Lifecycle surface (`lifecycle.rs`) — promote_index/
    // demote_index (the pg_pinecone-AM's own local<->remote flip) and the engine
    // surface (create_index/set_engine).
    // =========================================================================

    /// Happy path: a local-mode pg_pinecone index, `promote_index`'d, serves LOCAL
    /// throughout the promoting window (no `/query` mock mounted at all — a
    /// stray remote dispatch would surface as an HTTP failure, not a silent
    /// wrong answer) and flips to `remote` (metapage AND registry alike) the
    /// moment the worker's TID backfill drains.
    #[pg_test]
    fn lifecycle_promote_index_serves_local_then_flips_to_remote_after_backfill() {
        install_am_opclasses();
        let table = "lc_promote_happy";
        let index_name = crate::promote::default_index_name("public", table);
        let upserts = Arc::new(Mutex::new(Vec::<Value>::new()));
        let upserts_for_mock = Arc::clone(&upserts);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(move |req: &Request| {
                        let body: Value = req.body_json().expect("upsert body should be JSON");
                        upserts_for_mock
                            .lock()
                            .expect("upserts lock poisoned")
                            .push(body);
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0}))
                    })
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run_with_args(
            &format!(
                "INSERT INTO {table} (id, embedding) \
                 SELECT i, ARRAY[i::real, 0.0]::vector FROM generate_series(1, $1) AS i"
            ),
            &[5i64.into()],
        )
        .expect("insert fixture rows");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Local
        );

        Spi::run(&format!("SELECT pinecone.promote_index('{table}_idx')")).expect("promote_index");

        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Promoting
        );
        let (mode, synced_by, engine): (String, String, Option<String>) = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT mode, synced_by, engine FROM pinecone.tables \
                         WHERE relid = '{table}'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("select registry row")
                .next()
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("mode").unwrap().unwrap(),
                        row.get_by_name::<String, _>("synced_by").unwrap().unwrap(),
                        row.get_by_name::<String, _>("engine").unwrap(),
                    )
                })
                .expect("registry row exists")
        });
        assert_eq!(mode, "promoting");
        assert_eq!(synced_by, "am");
        assert_eq!(engine, Some("remote".to_string()));

        // Serves LOCAL right now: a plain ORDER BY query must still return
        // every fixture row correctly — no `/query` mock is mounted, so a
        // stray remote dispatch would fail loudly instead of silently
        // returning a wrong (empty/partial) answer.
        let n: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM (SELECT id FROM {table} ORDER BY embedding <-> '[0,0]' \
             LIMIT 10) s"
        ))
        .expect("ordered query while promoting")
        .expect("count NOT NULL");
        assert_eq!(n, 5, "local scan must still see every row while promoting");

        // Drain the TID backfill (mirrors am_worker_drains_tid_backfill's own
        // pattern) — once exhausted, the worker flips both the registry row
        // and the AM index's own metapage.
        let mut scheduler = crate::outbox::Scheduler::new();
        let mut rounds = 0;
        while outbox_count(table) > 0 {
            rounds += 1;
            assert!(rounds <= 10, "backfill never exhausted");
            scheduler.drain_round();
        }

        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Remote,
            "metapage must flip promoting -> remote once the backfill drains"
        );
        let mode: String = Spi::get_one(&format!(
            "SELECT mode FROM pinecone.tables WHERE relid = '{table}'::regclass"
        ))
        .expect("select mode")
        .expect("mode NOT NULL");
        assert_eq!(mode, "remote");
        let pushed_vectors: usize = upserts
            .lock()
            .expect("lock poisoned")
            .iter()
            .map(|body| body["vectors"].as_array().expect("vectors array").len())
            .sum();
        assert_eq!(
            pushed_vectors, 5,
            "every fixture row must have been pushed during the backfill (possibly batched \
             into fewer than 5 HTTP calls)"
        );
    }

    /// A worker crash between the metapage's
    /// durable `Promoting -> Remote` flip and the enclosing round's own
    /// transaction commit rolls back that round's `pinecone._am_engine` upsert
    /// (an ordinary transactional heap write) while the flip itself survives
    /// (one atomic `GenericXLog` record, durable independent of whatever
    /// transaction issued it — see `outbox::flip_am_index_promoting_to_
    /// remote`'s own rustdoc). Simulated here without an actual process
    /// kill: the metapage is flipped to `Remote` directly
    /// (`local::metapage::flip_mode`) BEFORE the backfill drains, standing in
    /// for "an earlier round already flipped it durably, then crashed before
    /// its sticky-map upsert committed" — `pinecone._am_engine` is left exactly
    /// where `CREATE INDEX` put it (`'local'`), the stale value a real crash
    /// would leave behind. The backfill chunking itself
    /// (`promote::try_tid_backfill_chunk`) only ever reads the HEAP relation,
    /// never the index's own metapage, so pre-flipping it doesn't perturb
    /// the drain.
    ///
    /// Before the fix, the drain's completing round sees
    /// `meta.mode == Remote` already (not `Promoting`) and skips the sticky
    /// upsert entirely — `pinecone._am_engine` would stay `'local'` forever,
    /// silently reverting a later `REINDEX` (mode=auto) back to local. After
    /// the fix, that same completing round repairs it.
    #[pg_test]
    fn lifecycle_promote_flip_repairs_stale_sticky_after_simulated_crash() {
        install_am_opclasses();
        let table = "lc_promote_8a_repair";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0})),
                    )
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run_with_args(
            &format!(
                "INSERT INTO {table} (id, embedding) \
                 SELECT i, ARRAY[i::real, 0.0]::vector FROM generate_series(1, $1) AS i"
            ),
            &[3i64.into()],
        )
        .expect("insert fixture rows");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        let index_oid =
            Spi::get_one::<pg_sys::Oid>(&format!("SELECT '{table}_idx'::regclass::oid"))
                .expect("index oid query")
                .expect("index oid not null");
        // Scalar subquery (NULL on no match), not a bare `SELECT ... WHERE
        // ...` — mirrors `am::lookup_engine_mode`'s own rustdoc on why: a
        // `get_one` on a zero-row result errors instead of returning `None`.
        let sticky_mode = || -> Option<String> {
            Spi::get_one_with_args(
                "SELECT (SELECT mode FROM pinecone._am_engine WHERE index_relid = $1)",
                &[index_oid.into()],
            )
            .expect("sticky-mode probe")
        };
        assert_eq!(
            sticky_mode().as_deref(),
            Some("local"),
            "a plain local-mode CREATE INDEX must persist 'local' as its sticky resolution"
        );

        Spi::run(&format!("SELECT pinecone.promote_index('{table}_idx')")).expect("promote_index");
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Promoting
        );

        // THE simulated crash: the metapage is already durably `Remote` (as
        // an earlier, crashed round would have left it), but the sticky map
        // hasn't moved off its pre-promotion 'local' value (that round's
        // upsert never committed).
        {
            let idx = pgrx::PgRelation::open_with_name_and_share_lock(&format!("{table}_idx"))
                .expect("open index relation");
            unsafe {
                crate::local::metapage::flip_mode(
                    idx.as_ptr(),
                    crate::local::metapage::Mode::Remote,
                );
            }
        }
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Remote,
            "the simulated pre-flip must take"
        );
        assert_eq!(
            sticky_mode().as_deref(),
            Some("local"),
            "sticky map must still read the stale pre-crash value right after the simulated flip"
        );

        // Drain the TID backfill to exhaustion, same as the happy path — its
        // completing round is the one that must now repair the sticky value.
        let mut scheduler = crate::outbox::Scheduler::new();
        let mut rounds = 0;
        while outbox_count(table) > 0 {
            rounds += 1;
            assert!(rounds <= 10, "backfill never exhausted");
            scheduler.drain_round();
        }

        assert_eq!(
            sticky_mode().as_deref(),
            Some("remote"),
            "8a: the next round must repair a stale sticky value once the metapage already \
             reads Remote, not just when this round performs the flip itself"
        );
    }

    /// The promote_index recovery arm (metapage `Promoting`, no registry
    /// row — a rolled-back enclosing transaction or a flip-vs-commit crash),
    /// simulated by flipping the metapage directly: a re-run must repair
    /// (registry row + backfill job recreated) while SKIPPING the metapage
    /// flip it already has. Also the execution vehicle for the re-broadcast
    /// (`CacheInvalidateRelcacheByRelid` on this arm): the broadcast itself is
    /// only observable from a warm SECOND
    /// backend — the same committed-state dblink limitation that keeps
    /// `lifecycle_flip_mode_invalidates_other_backends_cached_mode`
    /// #[ignore]d — so this test proves the arm (including the new call)
    /// executes and repairs; the cross-backend delivery mechanism is the
    /// same one that test verifies standalone.
    #[pg_test]
    fn lifecycle_promote_index_recovery_arm_repairs_missing_registry_row() {
        install_am_opclasses();
        let table = "lc_promote_repair";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0]')"
        ))
        .expect("insert fixture row");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        // Simulate the residual window: flip durable, transactional writes
        // gone (no registry row was ever committed).
        {
            let idx = pgrx::PgRelation::open_with_name_and_share_lock(&format!("{table}_idx"))
                .expect("open index relation");
            unsafe {
                crate::local::metapage::flip_mode(
                    idx.as_ptr(),
                    crate::local::metapage::Mode::Promoting,
                );
            }
        }
        let rows: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM pinecone.tables WHERE relid = '{table}'::regclass"
        ))
        .expect("registry count")
        .expect("count NOT NULL");
        assert_eq!(rows, 0, "the simulated window has no registry row");

        Spi::run(&format!("SELECT pinecone.promote_index('{table}_idx')"))
            .expect("re-run must repair, not error");

        let (mode, synced_by): (String, String) = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT mode, synced_by FROM pinecone.tables \
                         WHERE relid = '{table}'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("select registry row")
                .next()
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("mode").unwrap().unwrap(),
                        row.get_by_name::<String, _>("synced_by").unwrap().unwrap(),
                    )
                })
                .expect("registry row recreated")
        });
        assert_eq!(mode, "promoting");
        assert_eq!(synced_by, "am");
        assert!(
            outbox_count(table) > 0,
            "the backfill job must be re-enqueued"
        );
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Promoting,
            "the already-durable flip must be kept, not re-applied"
        );
    }

