    /// Happy path: a remote-mode pg_pinecone index, `demote_index`'d, serves
    /// REMOTE while queued, then the worker's round performs the local
    /// REINDEX (`ALTER INDEX ... SET (mode = 'local'); REINDEX;`), deletes
    /// the now-superseded remote index, and removes the registry row —
    /// matching a plain local-built index's own "no pinecone.tables row"
    /// invariant.
    #[pg_test]
    fn lifecycle_demote_index_rebuilds_local_and_cleans_up_remote() {
        install_am_opclasses();
        let table = "lc_demote_happy";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("DELETE"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(202))
                    .mount(&control_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run_with_args(
            &format!(
                "INSERT INTO {table} (id, embedding) \
                 SELECT i, ARRAY[i::real, 0.0]::vector FROM generate_series(1, $1) AS i"
            ),
            &[5i64.into()],
        )
        .expect("insert fixture rows");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'remote')"
        ))
        .expect("create remote pg_pinecone index");
        // Drain the initial backfill so this starts from a clean, fully
        // remote-synced state (not required for demote_index itself, but
        // keeps this test's setup honest about what a "real" remote index
        // looks like).
        let mut scheduler = crate::outbox::Scheduler::new();
        while outbox_count(table) > 0 {
            scheduler.drain_round();
        }
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Remote
        );

        Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')")).expect("demote_index");
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Demoting
        );
        let pending: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM pinecone.pending_demotes WHERE index_relid = '{table}_idx'::regclass"
        ))
        .expect("pending_demotes count")
        .expect("count NOT NULL");
        assert_eq!(pending, 1);

        let completed = crate::lifecycle::run_round();
        assert_eq!(
            completed, 1,
            "the worker round must complete the one pending demote"
        );

        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Local,
            "the REINDEX must have rebuilt the index as local-mode"
        );
        let registry_rows: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM pinecone.tables WHERE relid = '{table}'::regclass"
        ))
        .expect("registry row count")
        .expect("count NOT NULL");
        assert_eq!(
            registry_rows, 0,
            "a demoted-back-to-local AM index must have no pinecone.tables row, matching a plain \
             local-built one"
        );
        let pending_after: i64 = Spi::get_one("SELECT count(*) FROM pinecone.pending_demotes")
            .expect("pending_demotes count after")
            .expect("count NOT NULL");
        assert_eq!(pending_after, 0);

        // The rebuild actually repopulated the local index from the live
        // heap (ambuild_local's own table_index_build_scan) — a plain
        // ORDER BY query must still see every fixture row, with no `/query`
        // mock needed at all now.
        let n: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM (SELECT id FROM {table} ORDER BY embedding <-> '[0,0]' \
             LIMIT 10) s"
        ))
        .expect("ordered query after demote")
        .expect("count NOT NULL");
        assert_eq!(n, 5, "local scan must see every row after the rebuild");
    }

    /// `remote_cleanup`'s `shared` flag is
    /// captured inside `demote_step`'s transaction, but the cleanup HTTP
    /// call runs in a LATER one (worker.rs's per-step transactions) — a
    /// table promoted onto the same index name in between would have its
    /// whole index deleted on the strength of the stale capture. The fix
    /// re-checks the registry inside `remote_cleanup`'s own transaction and
    /// downgrades to namespace-only when a new claimant exists. Driven
    /// through the split functions directly (`pending_demotes` ->
    /// `demote_step` -> interleaved claimant INSERT -> `remote_cleanup`),
    /// exactly the worker's own call shape; asserted through the mock:
    /// DELETE /indexes/{name} must never fire, POST /vectors/delete must.
    #[pg_test]
    fn lifecycle_remote_cleanup_rechecks_registry_before_deleting_index() {
        install_am_opclasses();
        let table = "lc_demote_race";
        let claimant = "lc_demote_race_claimant";
        let index_name = crate::promote::default_index_name("public", table);
        let index_deletes = Arc::new(Mutex::new(0u32));
        let namespace_deletes = Arc::new(Mutex::new(0u32));
        let index_deletes_for_mock = Arc::clone(&index_deletes);
        let namespace_deletes_for_mock = Arc::clone(&namespace_deletes);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("DELETE"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(move |_req: &Request| {
                        *index_deletes_for_mock
                            .lock()
                            .expect("index_deletes lock poisoned") += 1;
                        ResponseTemplate::new(202)
                    })
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(move |_req: &Request| {
                        *namespace_deletes_for_mock
                            .lock()
                            .expect("namespace_deletes lock poisoned") += 1;
                        ResponseTemplate::new(200).set_body_json(json!({}))
                    })
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0]'), (2, '[0,1]')"
        ))
        .expect("insert fixture rows");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'remote')"
        ))
        .expect("create remote pg_pinecone index");
        let mut scheduler = crate::outbox::Scheduler::new();
        while outbox_count(table) > 0 {
            scheduler.drain_round();
        }

        Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')")).expect("demote_index");
        let pending = crate::lifecycle::pending_demotes();
        assert_eq!(pending.len(), 1, "exactly one pending demote");

        // Phase 1 (transactional): rebuild + registry-row delete + capture,
        // now persisting the cleanup obligation to pinecone.pending_cleanups.
        let done = crate::lifecycle::demote_step(&pending[0]);
        assert!(done, "demote_step must complete");
        let cleanups = crate::lifecycle::pending_cleanups();
        assert_eq!(
            cleanups.len(),
            1,
            "a remote registration must persist exactly one cleanup obligation"
        );
        let cleanup = &cleanups[0];

        // THE race: between phase 1's commit and phase 2's HTTP call, a new
        // table claims the same remote index (what a concurrent
        // pinecone.promote(..., index_name => ...) commits). Inserted directly —
        // same superuser-fixture pattern as the upgrade drill.
        Spi::run(&format!(
            "CREATE TABLE {claimant} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create claimant table");
        Spi::run(&format!(
            "INSERT INTO pinecone.tables (relid, vector_column, id_column, metric, dimension, \
             mode, sync_mode, synced_by, index_name, namespace) \
             VALUES ('{claimant}'::regclass, 'embedding', 'id', 'l2', 2, 'remote', 'async', \
             'trigger', '{index_name}', 'claimant-ns')"
        ))
        .expect("insert claimant registry row");

        // Phase 2: must now see the claimant and downgrade to namespace-only.
        crate::lifecycle::remote_cleanup(cleanup);

        assert_eq!(
            *index_deletes.lock().expect("index_deletes lock poisoned"),
            0,
            "the whole index must NOT be deleted once a new claimant registered onto it"
        );
        assert_eq!(
            *namespace_deletes
                .lock()
                .expect("namespace_deletes lock poisoned"),
            1,
            "the demoted table's own namespace must still be emptied"
        );
    }

    /// `demote_index`'s remote cleanup is RETRIABLE — a
    /// Pinecone partition/outage during phase 2 must never permanently orphan
    /// the superseded index (the bug: phase 1 purged the only retry record,
    /// so a failed best-effort phase 2 orphaned it forever). The
    /// `pinecone.pending_cleanups` row survives across worker rounds while the
    /// delete keeps failing transiently, the local demote converges
    /// regardless, and once the remote confirms gone (a 404 here) the row is
    /// purged. Driven through `lifecycle::run_round()` — the same
    /// demote_step -> pending_cleanups -> remote_cleanup path the worker runs.
    #[pg_test]
    fn lifecycle_demote_remote_cleanup_retries_until_gone() {
        install_am_opclasses();
        let table = "lc_demote_retry";
        let index_name = crate::promote::default_index_name("public", table);
        // DELETE /indexes/{name}: fail transiently (503) the first 3 times,
        // then 404 (already gone) — the confirmed-gone signal.
        let delete_attempts = Arc::new(Mutex::new(0u32));
        let delete_attempts_for_mock = Arc::clone(&delete_attempts);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("DELETE"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(move |_req: &Request| {
                        let mut n = delete_attempts_for_mock
                            .lock()
                            .expect("delete_attempts lock poisoned");
                        *n += 1;
                        if *n <= 3 {
                            ResponseTemplate::new(503)
                                .set_body_json(json!({"message": "simulated partition"}))
                        } else {
                            ResponseTemplate::new(404)
                                .set_body_json(json!({"message": "index not found"}))
                        }
                    })
                    .mount(&control_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0]'), (2, '[0,1]')"
        ))
        .expect("insert fixture rows");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'remote')"
        ))
        .expect("create remote pg_pinecone index");
        let mut scheduler = crate::outbox::Scheduler::new();
        while outbox_count(table) > 0 {
            scheduler.drain_round();
        }

        Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')")).expect("demote_index");

        let pending_cleanups = || -> i64 {
            Spi::get_one("SELECT count(*) FROM pinecone.pending_cleanups")
                .expect("pending_cleanups count")
                .expect("count NOT NULL")
        };

        // Round 1: phase 1 completes (local demote converges) + the first
        // cleanup attempt fails transiently — the obligation must survive.
        let completed = crate::lifecycle::run_round();
        assert_eq!(completed, 1, "the pending demote must complete in round 1");
        assert_eq!(
            index_mode(&format!("{table}_idx")),
            crate::local::metapage::Mode::Local,
            "the local demote must converge regardless of remote-cleanup state"
        );
        let registry_rows: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM pinecone.tables WHERE relid = '{table}'::regclass"
        ))
        .expect("registry count")
        .expect("count NOT NULL");
        assert_eq!(
            registry_rows, 0,
            "a demoted table has no pinecone.tables row"
        );
        assert_eq!(
            pending_cleanups(),
            1,
            "the cleanup obligation must survive a transient delete failure"
        );

        // The table serves native correctly throughout — independent of the
        // still-pending remote cleanup.
        let n: i64 = Spi::get_one(&format!(
            "SELECT count(*) FROM (SELECT id FROM {table} ORDER BY embedding <-> '[0,0]' \
             LIMIT 10) s"
        ))
        .expect("ordered query after demote")
        .expect("count NOT NULL");
        assert_eq!(n, 2, "local scan must serve every row after the demote");

        // Rounds 2 and 3 keep failing transiently — still NOT purged, and a
        // transient failure never accrues attempts (a long outage retries
        // forever rather than parking).
        for round in 2..=3 {
            crate::lifecycle::run_round();
            assert_eq!(
                pending_cleanups(),
                1,
                "cleanup must not be purged while the delete keeps failing (round {round})"
            );
        }
        let (attempts, parked) = Spi::get_two::<i32, bool>(
            "SELECT attempts, queue_parked FROM pinecone.pending_cleanups",
        )
        .expect("select attempts/parked");
        assert_eq!(
            attempts,
            Some(0),
            "a transient cleanup failure must never count toward parking"
        );
        assert_eq!(parked, Some(false), "a transient failure must never park");

        // Round 4: the delete now 404s (confirmed gone) — the obligation is
        // discharged and the row purged.
        crate::lifecycle::run_round();
        assert_eq!(
            pending_cleanups(),
            0,
            "the cleanup must be purged once the remote is confirmed gone (404)"
        );
        assert!(
            *delete_attempts
                .lock()
                .expect("delete_attempts lock poisoned")
                >= 4,
            "the retry must have re-issued the delete across rounds until it succeeded"
        );
    }

    #[pg_test]
    fn lifecycle_demote_index_rejects_non_remote_mode() {
        install_am_opclasses();
        let table = "lc_demote_not_remote";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')"))
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();

        let message = outcome.expect_err("expected a refusal to demote a local index");
        assert!(message.contains("not remote-mode"), "message = {message}");
    }

    /// The demote retry hatch: a PARKED pending demote (its REINDEX failed
    /// `pinecone.outbox_max_attempts` times) is unparked by re-running
    /// `pinecone.demote_index` — the same "re-run the enqueue verb" convention
    /// `pinecone.schedule_maintenance` uses; a live (unparked) in-flight demote
    /// still errors "already in progress".
    #[pg_test]
    fn lifecycle_demote_index_rerun_unparks_a_parked_demote_but_rejects_a_live_one() {
        install_am_opclasses();
        let table = "lc_demote_unpark";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "l2").await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'remote')"
        ))
        .expect("create remote pg_pinecone index");
        Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')")).expect("demote_index");

        // A LIVE in-flight demote: re-running errors.
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')"))
                .expect("statement should raise a Postgres ERROR, not an SpiError");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome.expect_err("a live in-flight demote must reject a re-run");
        assert!(
            message.contains("already has a demote"),
            "message = {message}"
        );

        // Park it (simulating outbox_max_attempts consecutive REINDEX
        // failures), then re-run: must unpark and reset the counters.
        Spi::run(&format!(
            "UPDATE pinecone.pending_demotes SET queue_parked = true, parked_reason = 'boom', \
             attempts = 10, last_error = 'boom' \
             WHERE index_relid = '{table}_idx'::regclass"
        ))
        .expect("park the pending demote");
        Spi::run(&format!("SELECT pinecone.demote_index('{table}_idx')"))
            .expect("re-running demote_index on a parked demote must unpark, not error");
        let (parked, attempts): (bool, i32) = Spi::connect(|client| {
            let mut rows = client
                .select(
                    &format!(
                        "SELECT queue_parked, attempts FROM pinecone.pending_demotes \
                         WHERE index_relid = '{table}_idx'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("read pending demote");
            let row = rows.next().expect("pending demote row exists");
            (
                row.get_by_name::<bool, _>("queue_parked").unwrap().unwrap(),
                row.get_by_name::<i32, _>("attempts").unwrap().unwrap(),
            )
        });
        assert!(!parked, "re-run must unpark");
        assert_eq!(attempts, 0, "re-run must reset attempts");
    }

    /// The engine surface: `create_index` builds the right physical index
    /// for each engine, and `set_engine` routes `native <-> remote` through
    /// `promote_index`/`demote_index` — but names `pgvector` transitions as
    /// unsupported rather than silently no-opping or guessing.
    #[pg_test]
    fn lifecycle_create_index_pgvector_engine_builds_hnsw() {
        install_am_opclasses();
        let table = "lc_create_pgvector";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.create_index('{table}', 'embedding', engine => 'pgvector')"
        ))
        .expect("create_index pgvector");

        // `{table}` also has its own PRIMARY KEY btree index — filter to the
        // `hnsw` one specifically rather than assuming query/scan order.
        let am_name: Option<String> = Spi::get_one(&format!(
            "SELECT a.amname::text FROM pg_catalog.pg_index i \
             JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid \
             JOIN pg_catalog.pg_am a ON a.oid = c.relam \
             WHERE i.indrelid = '{table}'::regclass AND a.amname = 'hnsw'"
        ))
        .expect("index am query");
        assert_eq!(
            am_name,
            Some("hnsw".to_string()),
            "a real hnsw index must exist"
        );

        let (mode, synced_by, engine): (String, String, Option<String>) = Spi::connect(|client| {
            client
                .select(
                    &format!(
                        "SELECT mode, synced_by, engine FROM pinecone.tables \
                         WHERE relid = '{table}'::regclass"
                    ),
                    None,
                    &[],
                )
                .expect("select registry row")
                .next()
                .map(|row| {
                    (
                        row.get_by_name::<String, _>("mode").unwrap().unwrap(),
                        row.get_by_name::<String, _>("synced_by").unwrap().unwrap(),
                        row.get_by_name::<String, _>("engine").unwrap(),
                    )
                })
                .expect("registry row exists")
        });
        assert_eq!(mode, "local");
        assert_eq!(synced_by, "engine");
        assert_eq!(engine, Some("pgvector".to_string()));
    }

    /// The access methods of `table`'s indexes other than its primary key, e.g. `Some("hnsw")`.
    fn index_access_methods(table: &str) -> Option<String> {
        Spi::get_one::<String>(&format!(
            "SELECT string_agg(a.amname::text, ',' ORDER BY a.amname) FROM pg_catalog.pg_index i \
             JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid \
             JOIN pg_catalog.pg_am a ON a.oid = c.relam \
             WHERE i.indrelid = '{table}'::regclass AND NOT i.indisprimary"
        ))
        .expect("index am query")
    }

    /// Without `engine`, `create_index` builds the native engine, the planner serves an `ORDER BY`
    /// from it, and `engine => 'pgvector'` still builds hnsw.
    #[pg_test]
    fn lifecycle_create_index_defaults_to_the_native_engine() {
        install_am_opclasses();
        let (default, pgvector) = ("lc_create_default", "lc_create_default_pgvector");
        for table in [default, pgvector] {
            Spi::run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2)); \
                 INSERT INTO {table} SELECT g, ARRAY[g, g * 2]::real[]::vector FROM generate_series(1, 20) g"
            ))
            .expect("create table");
        }

        Spi::run(&format!(
            "SELECT pinecone.create_index('{default}', 'embedding')"
        ))
        .expect("create_index without engine");
        assert_eq!(index_access_methods(default).as_deref(), Some("pinecone"));
        let index = format!("{default}_embedding_pinecone_idx");
        assert_eq!(index_mode(&index), crate::local::metapage::Mode::Local);
        Spi::run("SET LOCAL enable_seqscan = off").expect("set enable_seqscan");
        let plan = explain_lines(&format!(
            "SELECT id FROM {default} ORDER BY embedding <=> '[1,2]' LIMIT 5"
        ))
        .join("\n");
        assert!(
            plan.contains(&format!("Index Scan using {index}")),
            "plan = {plan}"
        );

        Spi::run(&format!(
            "SELECT pinecone.create_index('{pgvector}', 'embedding', engine => 'pgvector')"
        ))
        .expect("create_index pgvector");
        assert_eq!(index_access_methods(pgvector).as_deref(), Some("hnsw"));
    }

    #[pg_test]
    fn lifecycle_create_index_native_then_set_engine_round_trips_to_remote_and_back() {
        install_am_opclasses();
        let table = "lc_create_native_roundtrip";
        let index_name = crate::promote::default_index_name("public", table);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 2, "cosine").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 0})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("DELETE"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(202))
                    .mount(&control_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.create_index('{table}', 'embedding', engine => 'native')"
        ))
        .expect("create_index native");

        let am_index = Spi::get_one::<pg_sys::Oid>(&format!(
            "SELECT c.oid::oid FROM pg_catalog.pg_index i \
             JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid \
             JOIN pg_catalog.pg_am a ON a.oid = c.relam \
             WHERE i.indrelid = '{table}'::regclass AND a.amname = 'pinecone'"
        ))
        .expect("am index oid query")
        .expect("a pg_pinecone AM index must exist after create_index(native)");
        assert_eq!(
            unsafe {
                let idx = pg_sys::RelationIdGetRelation(am_index);
                let mode = crate::local::metapage::read(idx).mode;
                pg_sys::RelationClose(idx);
                mode
            },
            crate::local::metapage::Mode::Local
        );

        // native -> remote routes through promote_index.
        Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'remote')"))
            .expect("set_engine native -> remote");
        let mut scheduler = crate::outbox::Scheduler::new();
        while outbox_count(table) > 0 {
            scheduler.drain_round();
        }
        let mode_after_promote = unsafe {
            let idx = pg_sys::RelationIdGetRelation(am_index);
            let mode = crate::local::metapage::read(idx).mode;
            pg_sys::RelationClose(idx);
            mode
        };
        assert_eq!(mode_after_promote, crate::local::metapage::Mode::Remote);

        // remote -> native routes through demote_index (queue + worker round).
        Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'native')"))
            .expect("set_engine remote -> native");
        let completed = crate::lifecycle::run_round();
        assert_eq!(completed, 1);
        let mode_after_demote = unsafe {
            let idx = pg_sys::RelationIdGetRelation(am_index);
            let mode = crate::local::metapage::read(idx).mode;
            pg_sys::RelationClose(idx);
            mode
        };
        assert_eq!(mode_after_demote, crate::local::metapage::Mode::Local);
    }

    /// A pgvector row `track` or `promote` also owns (create_index after `track`, `promote` after
    /// create_index, or a demote that kept the Pinecone index) is a live registration: `DROP INDEX`
    /// of its hnsw index keeps it, and `set_engine(.., 'native')` refuses it.
    #[pg_test]
    fn lifecycle_drop_index_keeps_a_pgvector_row_track_or_promote_owns() {
        install_am_opclasses();
        let (tracked, promoted, demoted) = (
            "lc_pgvector_tracked",
            "lc_pgvector_promoted",
            "lc_pgvector_demoted",
        );
        Spi::run(&format!(
            "CREATE TABLE {tracked} (id bigint PRIMARY KEY, embedding vector(2)); \
             CREATE TABLE {promoted} (LIKE {tracked} INCLUDING ALL); \
             CREATE TABLE {demoted} (LIKE {tracked} INCLUDING ALL); \
             SELECT pinecone.track('{tracked}'); \
             SELECT pinecone.create_index('{tracked}', 'embedding', engine => 'pgvector'); \
             SELECT pinecone.create_index('{promoted}', 'embedding', engine => 'pgvector'); \
             SELECT pinecone.create_index('{demoted}', 'embedding', engine => 'pgvector'); \
             UPDATE pinecone.tables SET mode = 'remote', index_name = 'lc-promoted', \
                    namespace = 'public.{promoted}' WHERE relid = '{promoted}'::regclass; \
             UPDATE pinecone.tables SET index_name = 'lc-demoted', namespace = 'public.{demoted}' \
                    WHERE relid = '{demoted}'::regclass"
        ))
        .expect("pgvector rows track and promote own");
        for table in [tracked, promoted, demoted] {
            Spi::run(&format!("DROP INDEX {table}_embedding_pinecone_idx")).expect("drop index");
            assert!(
                am_registry_row_exists(relid_of(table)),
                "{table}: DROP INDEX must keep a row track or promote owns"
            );
            let outcome: Result<(), String> = PgTryBuilder::new(|| {
                Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'native')"))
                    .expect("statement should raise a Postgres ERROR, not an SpiError");
                Ok(())
            })
            .catch_others(|caught| Err(error_message(caught)))
            .execute();
            let message = outcome.expect_err("set_engine must refuse a row track or promote owns");
            assert!(
                message.contains("also registered by pinecone.track or promote"),
                "message = {message}"
            );
        }
    }

    /// `set_engine(.., 'native')` refuses a partitioned table and a vector column renamed since
    /// `create_index`; the renamed table's row survives an unrelated `DROP INDEX` (its hnsw index
    /// is still there).
    #[pg_test]
    fn lifecycle_set_engine_refuses_a_partitioned_table_and_a_renamed_column() {
        install_am_opclasses();
        let (parted, renamed) = ("lc_pgvector_parted", "lc_pgvector_renamed");
        Spi::run(&format!(
            "CREATE TABLE {parted} (id bigint PRIMARY KEY, embedding vector(2)) PARTITION BY RANGE (id); \
             CREATE TABLE {parted}_1 PARTITION OF {parted} FOR VALUES FROM (0) TO (100); \
             SELECT pinecone.create_index('{parted}', 'embedding', engine => 'pgvector'); \
             CREATE TABLE {renamed} (id bigint PRIMARY KEY, note text, embedding vector(2)); \
             CREATE INDEX {renamed}_note_idx ON {renamed} (note); \
             SELECT pinecone.create_index('{renamed}', 'embedding', engine => 'pgvector'); \
             ALTER TABLE {renamed} RENAME COLUMN embedding TO emb; \
             DROP INDEX {renamed}_note_idx"
        ))
        .expect("a partitioned and a renamed pgvector-engine table");
        assert!(
            am_registry_row_exists(relid_of(renamed)),
            "an unrelated DROP INDEX keeps the row"
        );
        for (table, expected) in [
            (parted, "is partitioned"),
            (renamed, "column \"embedding\" not found"),
        ] {
            let outcome: Result<(), String> = PgTryBuilder::new(|| {
                Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'native')"))
                    .expect("statement should raise a Postgres ERROR, not an SpiError");
                Ok(())
            })
            .catch_others(|caught| Err(error_message(caught)))
            .execute();
            let message = outcome.expect_err("set_engine must refuse it");
            assert!(message.contains(expected), "message = {message}");
        }
    }

    /// `set_engine` names what it cannot do in place: `pgvector -> remote` goes through `native`,
    /// `native -> pgvector` is a drop plus `create_index`, and a second hnsw index on the column is
    /// not guessed between.
    #[pg_test]
    fn lifecycle_set_engine_names_the_pgvector_transitions_it_cannot_make() {
        install_am_opclasses();
        let (pgvector, native) = ("lc_set_engine_pgvector_gap", "lc_set_engine_native_gap");
        Spi::run(&format!(
            "CREATE TABLE {pgvector} (id bigint PRIMARY KEY, embedding vector(2)); \
             CREATE TABLE {native} (LIKE {pgvector} INCLUDING ALL); \
             SELECT pinecone.create_index('{pgvector}', 'embedding', engine => 'pgvector'); \
             SELECT pinecone.create_index('{native}', 'embedding')"
        ))
        .expect("create a pgvector-engine and a native table");
        let refusal = |sql: String| {
            PgTryBuilder::new(|| {
                Spi::run(&sql).expect("statement should raise a Postgres ERROR, not an SpiError");
                None
            })
            .catch_others(|caught| Some(error_message(caught)))
            .execute()
            .unwrap_or_else(|| panic!("{sql} must be refused"))
        };

        let message = refusal(format!(
            "SELECT pinecone.set_engine('{pgvector}', 'remote')"
        ));
        assert!(
            message.contains("not supported yet")
                && message.contains(&format!("set_engine('public.{pgvector}', 'native') first")),
            "message = {message}"
        );
        let message = refusal(format!(
            "SELECT pinecone.set_engine('{native}', 'pgvector')"
        ));
        assert!(
            message.contains("not supported yet") && message.contains("DROP INDEX"),
            "message = {message}"
        );

        Spi::run(&format!(
            "CREATE INDEX {pgvector}_second ON {pgvector} USING hnsw (embedding vector_l2_ops)"
        ))
        .expect("a second hnsw index");
        let message = refusal(format!(
            "SELECT pinecone.set_engine('{pgvector}', 'native')"
        ));
        assert!(
            message.contains("has 2 hnsw indexes on \"embedding\"")
                && message.contains(&format!("{pgvector}_embedding_pinecone_idx"))
                && message.contains(&format!("{pgvector}_second")),
            "message = {message}"
        );
    }

    /// The way off the pre-0.10.1 default: `set_engine(.., 'native')` on a `create_index(engine =>
    /// 'pgvector')` table builds the native index (same metric) under the hnsw index's name, drops the
    /// hnsw index and its registry row, and the planner uses the native one. On the table or the index.
    #[pg_test]
    fn lifecycle_set_engine_moves_a_pgvector_index_to_native() {
        install_am_opclasses();
        for (table, index_name, index, target) in [
            (
                "lc_pgvector_to_native",
                "NULL",
                "lc_pgvector_to_native_embedding_pinecone_idx",
                "lc_pgvector_to_native",
            ),
            (
                "lc_pgvector_to_native_i",
                "'lc_custom_hnsw'",
                "lc_custom_hnsw",
                "lc_custom_hnsw",
            ),
        ] {
            Spi::run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2)); \
                 INSERT INTO {table} SELECT g, ARRAY[g, g * 2]::real[]::vector FROM generate_series(1, 20) g; \
                 SELECT pinecone.create_index('{table}', 'embedding', engine => 'pgvector', metric => 'l2', \
                                              index_name => {index_name})"
            ))
            .expect("create a pgvector-engine table");
            let relid = relid_of(table);
            assert!(am_registry_row_exists(relid));

            Spi::run(&format!("SELECT pinecone.set_engine('{target}', 'native')"))
                .expect("set_engine pgvector -> native");

            assert_eq!(index_access_methods(table).as_deref(), Some("pinecone"));
            assert_eq!(index_mode(index), crate::local::metapage::Mode::Local);
            assert_eq!(
                crate::catalog::index_first_opclass_name(relid_of(index)).as_deref(),
                Some("vector_l2_ops")
            );
            assert!(
                !am_registry_row_exists(relid),
                "a native index has no registry row"
            );
            Spi::run("SET LOCAL enable_seqscan = off").expect("set enable_seqscan");
            let plan = explain_lines(&format!(
                "SELECT id FROM {table} ORDER BY embedding <-> '[1,2]' LIMIT 5"
            ))
            .join("\n");
            assert!(
                plan.contains(&format!("Index Scan using {index}")),
                "plan = {plan}"
            );
            Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'native')"))
                .expect("set_engine to the current engine is a no-op");
        }
    }

    /// A pgvector row whose hnsw index is gone (what 0.10.0 left after a `DROP INDEX`; here the event
    /// trigger is off): `set_engine(.., 'native')` still builds the native index, under
    /// `create_index`'s default name, and deletes the row.
    #[pg_test]
    fn lifecycle_set_engine_moves_a_stale_pgvector_row_to_native() {
        install_am_opclasses();
        let table = "lc_pgvector_stale_row";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2)); \
             SELECT pinecone.create_index('{table}', 'embedding', engine => 'pgvector'); \
             ALTER EVENT TRIGGER pg_pinecone_on_sql_drop DISABLE; \
             DROP INDEX {table}_embedding_pinecone_idx; \
             ALTER EVENT TRIGGER pg_pinecone_on_sql_drop ENABLE"
        ))
        .expect("a pgvector row without its hnsw index");
        let relid = relid_of(table);
        assert!(am_registry_row_exists(relid));

        Spi::run(&format!("SELECT pinecone.set_engine('{table}', 'native')"))
            .expect("set_engine pgvector -> native");
        assert_eq!(index_access_methods(table).as_deref(), Some("pinecone"));
        assert_eq!(
            index_mode(&format!("{table}_embedding_pinecone_idx")),
            crate::local::metapage::Mode::Local
        );
        assert!(!am_registry_row_exists(relid));
    }

    /// `DROP INDEX` of the hnsw index `create_index(engine => 'pgvector')` built forgets its registry
    /// row, as it does a pg_pinecone index's, so `create_index` takes the table again; dropping another
    /// index of the table keeps the row, and `DROP TABLE` forgets it too.
    #[pg_test]
    fn lifecycle_drop_index_of_a_pgvector_index_forgets_its_registry_row() {
        install_am_opclasses();
        let (table, dropped) = ("lc_pgvector_drop_index", "lc_pgvector_drop_table");
        for t in [table, dropped] {
            Spi::run(&format!(
                "CREATE TABLE {t} (id bigint PRIMARY KEY, note text, embedding vector(2)); \
                 CREATE INDEX {t}_note_idx ON {t} (note); \
                 SELECT pinecone.create_index('{t}', 'embedding', engine => 'pgvector')"
            ))
            .expect("create a pgvector-engine table");
        }
        let relid = relid_of(table);
        Spi::run(&format!("DROP INDEX {table}_note_idx")).expect("drop another index");
        assert!(
            am_registry_row_exists(relid),
            "dropping another index keeps the row"
        );

        Spi::run(&format!("DROP INDEX {table}_embedding_pinecone_idx"))
            .expect("drop the hnsw index");
        assert!(
            !am_registry_row_exists(relid),
            "DROP INDEX must forget the pgvector row"
        );
        Spi::run(&format!(
            "SELECT pinecone.create_index('{table}', 'embedding')"
        ))
        .expect("create_index takes the table again");
        assert_eq!(index_access_methods(table).as_deref(), Some("pinecone"));

        let dropped_relid = relid_of(dropped);
        assert!(am_registry_row_exists(dropped_relid));
        Spi::run(&format!("DROP TABLE {dropped}")).expect("drop table");
        assert!(
            !am_registry_row_exists(dropped_relid),
            "DROP TABLE must forget the pgvector row"
        );
    }

    /// A second `create_index` against a table that
    /// already has an engine-surface-managed index rejects clearly, naming
    /// the switch verb — never stacks a second physical index.
    #[pg_test]
    fn lifecycle_create_index_rejects_conflicting_engine_row() {
        install_am_opclasses();
        let table = "lc_create_conflict";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.create_index('{table}', 'embedding', engine => 'native')"
        ))
        .expect("create_index native");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.create_index('{table}', 'embedding', engine => 'pgvector')"
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message =
            outcome.expect_err("a second create_index on a managed table must be rejected");
        assert!(
            message.contains("already managed with engine 'native'")
                && message.contains("set_engine"),
            "message = {message}"
        );
    }

