    // =========================================================================
    // Lifecycle-verb ownership. Non-owners must be
    // rejected on all three verbs (mirrors maintenance_schedule_maintenance_
    // requires_table_ownership's pattern — SET ROLE before the try, nothing
    // after the assert), and _demote_attempt's rebuild must run AS THE TABLE
    // OWNER (proven by a real owner-privilege failure, not a simulation).
    // =========================================================================

    /// Shared fixture: a local pg_pinecone index on `table` plus an unprivileged
    /// role (schema USAGE on pg_pinecone only), left as the CURRENT role — callers
    /// must not run further SQL after their PgTryBuilder catch.
    fn lifecycle_owner_guard_fixture(table: &str, role: &str) {
        install_am_opclasses();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
             WITH (mode = 'local')"
        ))
        .expect("create local pg_pinecone index");
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant schema usage");
        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
    }

