    /// The centerpiece suppression proof: the
    /// local `UPDATE` a recover chunk performs must enqueue NOTHING —
    /// `pinecone._is_recovering()` (the per-backend static behind it) suppresses
    /// `_sync_trigger` for exactly that write — while a genuinely separate,
    /// ordinary write on the SAME table immediately afterward still enqueues
    /// normally, proving the suppression is scoped to the recover write-back
    /// and doesn't leak.
    #[pg_test]
    fn recover_from_remote_suppresses_its_own_write_but_not_a_later_write() {
        create_extension_vector();
        let table = "recover_guc_suppress";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (5, NULL)"
        ))
        .expect("insert fixture row");

        let mut remote_values = HashMap::new();
        remote_values.insert("5".to_string(), vec![4.0f32, 5.0]);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "5"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid);
        assert_eq!(outbox_count(table), 0);

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");
        drain_until_empty(relid);

        assert_eq!(vector_of(table, 5, "embedding"), Some(vec![4.0, 5.0]));
        assert_eq!(
            outbox_count(table),
            0,
            "the recover job's own local write must enqueue NOTHING — pinecone._is_recovering() \
             must have suppressed _sync_trigger for it"
        );

        Spi::run(&format!(
            "UPDATE {table} SET embedding = '[7,7]'::vector WHERE id = 5"
        ))
        .expect("ordinary concurrent write");
        assert_eq!(
            outbox_count(table),
            1,
            "an ordinary write on the SAME table right afterward must still enqueue normally — \
             the suppression must not leak past the recover write-back"
        );
        let rows = outbox_rows(table);
        assert_eq!(rows[0].op, "upsert");
    }

    /// Regression test: suppression must not be reachable
    /// from SQL at all. The old design was a `pinecone._recovering` GUC checked
    /// by name from `_sync_trigger`'s plpgsql — spoofable in a no-preload
    /// deployment, where `SET pinecone._recovering = on` creates an unreserved
    /// placeholder (no privilege check, library never loaded) that silently
    /// bypasses the outbox forever. Now suppression lives in a per-backend
    /// Rust static behind `pinecone._is_recovering()` (a C function — calling
    /// it forces the library load), and the GUC is GONE: with the library
    /// loaded (as here), `SET pinecone._recovering` must be rejected outright,
    /// and `_is_recovering` must read false for any relid outside a recover
    /// write-back.
    #[pg_test]
    fn recovering_suppression_is_not_sql_settable() {
        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run("SET pinecone._recovering = on").expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let message = outcome.expect_err("SET pinecone._recovering must no longer be a real GUC");
        // With the library loaded, `MarkGUCPrefixReserved` makes any
        // undefined `pinecone.*` SET fail with "invalid configuration parameter
        // name". Without preload there is no reservation yet (the exact gap
        // the old design had) — the placeholder SET succeeds there, but
        // nothing reads it anymore: suppression only ever comes from the
        // Rust static behind pinecone._is_recovering().
        assert!(
            message.contains("invalid configuration parameter name"),
            "message = {message}"
        );

        assert!(
            !Spi::get_one::<bool>("SELECT pinecone._is_recovering('pg_class'::regclass::oid)")
                .expect("call _is_recovering")
                .expect("bool NOT NULL"),
            "outside a recover write-back, _is_recovering must be false for every relid"
        );
    }

    /// Per-relid suppression scope: a user trigger on the recovered table cascading a write
    /// to a DIFFERENT promoted table mid-recover must still enqueue for that
    /// other table — only the relid actually being recovered is suppressed.
    /// (The old transaction-wide GUC suppressed BOTH, silently desyncing the
    /// cascade target.)
    #[pg_test]
    fn recover_from_remote_suppression_is_scoped_to_the_recovered_relid() {
        create_extension_vector();
        let (table_a, table_b) = ("recover_cascade_a", "recover_cascade_b");
        let (index_a, index_b) = ("pv-recover-cascade-a", "pv-recover-cascade-b");

        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![4.0f32, 5.0]);

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            for index in [index_a, index_b] {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
            }
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})))
                .mount(&data_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/vectors/list"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "vectors": [{"id": "1"}],
                })))
                .mount(&data_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/vectors/fetch"))
                .respond_with(recover_fetch_responder(remote_values))
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        for (table, initial, index) in [
            (table_a, "NULL", index_a),
            (table_b, "'[1,1]'::vector", index_b),
        ] {
            Spi::run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
            ))
            .expect("create table");
            Spi::run(&format!(
                "INSERT INTO {table} (id, embedding) VALUES (1, {initial})"
            ))
            .expect("insert fixture row");
            Spi::run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
                quote_literal(table),
                quote_literal(index),
            ))
            .expect("promote");
            drain_until_empty(relid_of(table));
        }
        assert_eq!(outbox_count(table_a), 0);
        assert_eq!(outbox_count(table_b), 0);

        // A user trigger on A that cascades a genuine vector write to B —
        // fired by the recover write-back's own UPDATE on A.
        Spi::run(&format!(
            "CREATE FUNCTION recover_cascade_fn() RETURNS trigger LANGUAGE plpgsql AS $$ \
             BEGIN \
                 UPDATE {table_b} SET embedding = '[5,5]'::vector WHERE id = 1; \
                 RETURN NULL; \
             END $$"
        ))
        .expect("create cascade trigger fn");
        Spi::run(&format!(
            "CREATE TRIGGER recover_cascade_trg AFTER UPDATE ON {table_a} \
             FOR EACH STATEMENT EXECUTE FUNCTION recover_cascade_fn()"
        ))
        .expect("create cascade trigger");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table_a)
        ))
        .expect("recover_from_remote");
        drain_until_empty(relid_of(table_a));

        assert_eq!(
            vector_of(table_a, 1, "embedding"),
            Some(vec![4.0, 5.0]),
            "A's own NULL vector must be recovered"
        );
        assert_eq!(
            vector_of(table_b, 1, "embedding"),
            Some(vec![5.0, 5.0]),
            "the cascade must have written B locally"
        );
        assert_eq!(
            outbox_count(table_a),
            0,
            "A's own recover write-back must enqueue nothing"
        );
        assert_eq!(
            outbox_count(table_b),
            1,
            "the cascaded write to B — a DIFFERENT promoted table — must still sync: \
             suppression is scoped to the relid being recovered, not the whole transaction"
        );
        let rows = outbox_rows(table_b);
        assert_eq!(rows[0].op, "upsert");
    }

    /// Resumability across a persisted `pagination_token` cursor
    /// (one chunk per worker drain round, resumable
    /// across worker restarts). Two independent
    /// `outbox::drain_step` calls (nothing but the `pinecone.outbox` row itself
    /// carries state between them, mirroring a worker process actually
    /// restarting) must jointly recover all three rows, the second call
    /// picking up exactly where the first's persisted cursor left off.
    #[pg_test]
    fn recover_from_remote_resumes_across_pages_via_persisted_cursor() {
        create_extension_vector();
        let table = "recover_resume";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL), (2, NULL), (3, NULL)"
        ))
        .expect("insert fixture rows");

        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![1.0f32, 1.0]);
        remote_values.insert("2".to_string(), vec![2.0f32, 2.0]);
        remote_values.insert("3".to_string(), vec![3.0f32, 3.0]);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .and(query_param_is_missing("paginationToken"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}, {"id": "2"}],
                        "pagination": {"next": "page-2"},
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .and(query_param("paginationToken", "page-2"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "3"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid); // all-NULL table: no upsert needed for the initial backfill

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");

        // Round 1 ("worker session #1"): only the first page.
        let step =
            crate::outbox::drain_step_reporting(relid, crate::backend::DrainCredentials::Worker);
        match step.outcome {
            crate::outbox::DrainOutcome::Processed(_) => {}
            other => panic!("round 1: expected Processed, got {other:?}"),
        }
        assert!(step.chunks_left, "a page is left: the worker does not nap");
        assert_eq!(vector_of(table, 1, "embedding"), Some(vec![1.0, 1.0]));
        assert_eq!(vector_of(table, 2, "embedding"), Some(vec![2.0, 2.0]));
        assert_eq!(
            vector_of(table, 3, "embedding"),
            None,
            "row 3 must not be touched until the second page is processed"
        );
        assert_eq!(
            outbox_count(table),
            1,
            "the job must still be queued, mid-flight"
        );
        assert_eq!(
            recover_job_field(table, "pagination_token").as_deref(),
            Some("page-2"),
            "the persisted cursor must advance to the next page's token"
        );

        // Round 2 ("worker session #2", after a simulated restart): nothing
        // but the outbox row's own persisted cursor carries state here.
        let step =
            crate::outbox::drain_step_reporting(relid, crate::backend::DrainCredentials::Worker);
        match step.outcome {
            crate::outbox::DrainOutcome::Processed(_) => {}
            other => panic!("round 2: expected Processed, got {other:?}"),
        }
        assert!(!step.chunks_left, "the last page ended the job");
        assert_eq!(vector_of(table, 3, "embedding"), Some(vec![3.0, 3.0]));
        assert_eq!(
            outbox_count(table),
            0,
            "the job must complete once the last page exhausts"
        );
    }

    /// `ghosts => 'delete'`: a remote id with no matching local row gets an
    /// additional `'delete'` outbox row enqueued (cleanup on the remote
    /// index) once the recover job's own chunk finishes — the opposite of
    /// the default `'report'` behavior asserted by the NULL-guard test above.
    #[pg_test]
    fn recover_from_remote_ghosts_delete_enqueues_remote_cleanup() {
        create_extension_vector();
        let table = "recover_ghosts_delete";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL)"
        ))
        .expect("insert fixture row");

        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![1.0f32, 1.0]);
        remote_values.insert("ghost-9".to_string(), vec![9.0f32, 9.0]);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}, {"id": "ghost-9"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid);

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({}, ghosts => 'delete')",
            quote_literal(table)
        ))
        .expect("recover_from_remote");

        // One round completes the (single-page) recover job and enqueues
        // the ghost delete right behind it — not yet drained.
        match crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker) {
            crate::outbox::DrainOutcome::Processed(_) => {}
            other => panic!("expected Processed, got {other:?}"),
        }
        let rows = outbox_rows(table);
        assert_eq!(rows.len(), 1, "rows = {rows:?}");
        assert_eq!(rows[0].op, "delete");
        let ids: Vec<String> = rows[0]
            .payload
            .as_ref()
            .expect("delete payload must be present")
            .as_array()
            .expect("delete payload must be a jsonb array")
            .iter()
            .map(|v| v.as_str().expect("delete id must be a string").to_string())
            .collect();
        assert_eq!(ids, vec!["ghost-9".to_string()]);

        drain_until_empty(relid); // flush the ghost delete through the mocked /vectors/delete
        assert_eq!(outbox_count(table), 0);
    }

    /// Regression test: a hostile/mismatched remote payload
    /// must PARK the recover job, never crash-loop the worker. A remote
    /// vector whose dimension doesn't match the registry (here 3 values for
    /// a vector(2) table) previously hit the write-back SQL's `::vector`
    /// assignment error as an uncaught panic — aborting the whole drain
    /// round's transaction, so `attempts` never incremented and the same
    /// poison chunk retried forever: a remote-controlled DoS of every
    /// table's sync in the database. Now it's a permanent-class failure
    /// (Rust-side validation, before any SQL), so max-attempts parking
    /// applies — and a DIFFERENT table's queue still drains in the same
    /// round pattern afterward.
    #[pg_test]
    fn recover_from_remote_wrong_dimension_payload_parks_instead_of_crash_looping() {
        create_extension_vector();
        let (table, healthy) = ("recover_bad_dim", "recover_bad_dim_healthy");
        let (index_a, index_b) = ("pv-recover-bad-dim", "pv-recover-bad-dim-healthy");

        // Hostile remote: 3 values for a vector(2) registration.
        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![1.0f32, 2.0, 3.0]);

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let index_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                .mount(&control_plane)
                .await;
            for index in [index_a, index_b] {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
            }
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                .mount(&data_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/upsert"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})))
                .mount(&data_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/vectors/list"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                    "vectors": [{"id": "1"}],
                })))
                .mount(&data_plane)
                .await;
            Mock::given(method("GET"))
                .and(path("/vectors/fetch"))
                .respond_with(recover_fetch_responder(remote_values))
                .mount(&data_plane)
                .await;
            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        for (t, index) in [(table, index_a), (healthy, index_b)] {
            Spi::run(&format!(
                "CREATE TABLE {t} (id bigint PRIMARY KEY, embedding vector(2))"
            ))
            .expect("create table");
            Spi::run(&format!("INSERT INTO {t} (id, embedding) VALUES (1, NULL)"))
                .expect("insert fixture row");
            Spi::run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
                quote_literal(t),
                quote_literal(index),
            ))
            .expect("promote");
            drain_until_empty(relid_of(t));
        }

        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("lower max_attempts");
        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");

        let relid = relid_of(table);
        match crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker) {
            crate::outbox::DrainOutcome::Parked(e) => {
                let message = format!("{e}");
                assert!(message.contains("3"), "message = {message}");
                assert!(
                    message.contains("dimension") || message.contains("dimensions"),
                    "message = {message}"
                );
            }
            other => panic!("expected Parked, got {other:?}"),
        }
        assert_eq!(
            vector_of(table, 1, "embedding"),
            None,
            "the hostile payload must never have been written locally"
        );

        // The poison job is parked, not crash-looping — a DIFFERENT table's
        // sync still works in this same session/worker pattern.
        Spi::run(&format!(
            "UPDATE {healthy} SET embedding = '[7,7]'::vector WHERE id = 1"
        ))
        .expect("ordinary write to the healthy table");
        drain_until_empty(relid_of(healthy));
        assert_eq!(
            outbox_count(healthy),
            0,
            "the healthy table's queue must still drain"
        );
        assert_eq!(
            outbox_count(table),
            1,
            "the parked recover job stays queued for an operator"
        );
    }

    /// Same regression, the SQL-error half: a payload that passes the Rust-side
    /// dimension check but fails INSIDE the write-back SQL (here: metadata
    /// `"count": "not-a-number"` for a bigint metadata column, whose
    /// `::bigint` cast raises) must also become a permanent-class parked
    /// failure — the chunk's SPI now runs inside its own subtransaction, so
    /// the error rolls back only the chunk and the round's transaction stays
    /// healthy enough to record attempts/last_error and park.
    #[pg_test]
    fn recover_from_remote_uncastable_metadata_parks_instead_of_crash_looping() {
        create_extension_vector();
        let table = "recover_bad_meta";
        let index_name = crate::promote::default_index_name("public", table);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": {
                            "1": {
                                "id": "1",
                                "values": [1.0, 2.0],
                                "metadata": {"count": "not-a-number"},
                            }
                        },
                    })))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2), count bigint)"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL)"
        ))
        .expect("insert fixture row");
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metadata_columns => ARRAY['count'], \
             sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid);

        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("lower max_attempts");
        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");

        match crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker) {
            crate::outbox::DrainOutcome::Parked(e) => {
                let message = format!("{e}");
                assert!(
                    message.contains("bigint") || message.contains("invalid input syntax"),
                    "message = {message}"
                );
            }
            other => panic!("expected Parked, got {other:?}"),
        }
        assert_eq!(
            vector_of(table, 1, "embedding"),
            None,
            "the failed chunk's subtransaction must have rolled back its partial write"
        );
        let parked: bool = Spi::get_one_with_args::<bool>(
            "SELECT queue_parked FROM pinecone.tables WHERE relid = $1::oid",
            &[relid.into()],
        )
        .expect("select queue_parked")
        .expect("queue_parked NOT NULL");
        assert!(
            parked,
            "the SQL-error chunk must park the queue, not crash-loop it"
        );
    }

    /// Regression test (CVE-2022-1552 class): the recover
    /// write-back UPDATE runs arbitrary user code — the table's own
    /// triggers, CHECK constraints, index expressions — and the worker is
    /// effectively superuser. Without an identity switch, a hostile table
    /// owner's trigger escalates to superuser the moment an operator
    /// recovers that owner's table. The write-back must therefore run as the
    /// TABLE OWNER (with SECURITY_RESTRICTED_OPERATION set): a user trigger
    /// recording `current_user` during the recover UPDATE must see the
    /// owner role, never the superuser the worker connected as.
    #[pg_test]
    fn recover_write_back_runs_user_triggers_as_table_owner_not_superuser() {
        create_extension_vector();
        let table = "recover_owner_switch";
        let role = "recover_owner_role";
        let index_name = crate::promote::default_index_name("public", table);

        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![4.0f32, 5.0]);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL)"
        ))
        .expect("insert fixture row");
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid);

        // A user trigger that records the identity it runs as, then hand the
        // table to an unprivileged role — from here on, anything the
        // write-back's UPDATE executes is that owner's code.
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run("CREATE TABLE recover_owner_log (who text)").expect("create log table");
        Spi::run(&format!("GRANT INSERT ON recover_owner_log TO {role}"))
            .expect("grant log insert");
        Spi::run(
            "CREATE FUNCTION recover_owner_probe() RETURNS trigger LANGUAGE plpgsql AS $$ \
             BEGIN \
                 INSERT INTO public.recover_owner_log (who) VALUES (current_user); \
                 RETURN NULL; \
             END $$",
        )
        .expect("create probe fn");
        Spi::run(&format!(
            "CREATE TRIGGER recover_owner_probe_trg AFTER UPDATE ON {table} \
             FOR EACH STATEMENT EXECUTE FUNCTION recover_owner_probe()"
        ))
        .expect("create probe trigger");
        Spi::run(&format!("ALTER TABLE {table} OWNER TO {role}")).expect("hand table to role");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");
        drain_until_empty(relid);

        assert_eq!(
            vector_of(table, 1, "embedding"),
            Some(vec![4.0, 5.0]),
            "the recover must still succeed under the switched identity"
        );
        let who = Spi::get_one::<String>("SELECT who FROM recover_owner_log LIMIT 1")
            .expect("select probe log")
            .expect("the probe trigger must have fired during the write-back");
        assert_eq!(
            who, role,
            "the write-back's user trigger must run as the TABLE OWNER, not the (superuser) \
             worker identity — a hostile owner's trigger must never escalate"
        );
        let superuser = Spi::get_one::<String>("SELECT current_user::text")
            .expect("current_user")
            .expect("NOT NULL");
        assert_ne!(who, superuser, "probe recorded the worker's own identity");
    }

    /// `synced_by = 'am'` miss detection: a
    /// fetched TID with NO matching row at all fails the WHOLE chunk with a
    /// clear error (rather than silently skipping it), and — after
    /// `pinecone.outbox_max_attempts` consecutive such failures — parks the
    /// relid's queue with the job's cursor untouched, while its persisted
    /// `misses` counter still records that it happened.
    #[pg_test]
    fn recover_from_remote_am_path_fails_chunk_on_miss_and_parks() {
        install_am_opclasses();
        let table = "recover_am_miss";
        let index_name = crate::promote::default_index_name("public", table);
        let real_tid_cell: Arc<Mutex<Option<String>>> = Arc::new(Mutex::new(None));
        let real_tid_for_mock = Arc::clone(&real_tid_cell);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(move |_req: &Request| {
                        let real_tid = real_tid_for_mock
                            .lock()
                            .expect("real_tid_cell lock poisoned")
                            .clone()
                            .expect("real_tid_cell must be set before recover_from_remote runs");
                        ResponseTemplate::new(200).set_body_json(json!({
                            "vectors": [{"id": real_tid}, {"id": "999999:1"}],
                        }))
                    })
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(|req: &Request| {
                        let mut vectors = serde_json::Map::new();
                        for (k, v) in req.url.query_pairs() {
                            if k == "ids" {
                                vectors.insert(
                                    v.to_string(),
                                    json!({"id": v, "values": [1.0, 0.0, 0.0]}),
                                );
                            }
                        }
                        ResponseTemplate::new(200)
                            .set_body_json(json!({"vectors": Value::Object(vectors)}))
                    })
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create pg_pinecone access-method index");
        let relid = relid_of(table);
        drain_until_empty(relid); // the initial (empty-table) TID backfill job

        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,0,0]'::vector)"
        ))
        .expect("insert fixture row");
        drain_until_empty(relid); // aminsert's own per-row 'upsert' enqueue

        let real_tid = ctid_map(table)
            .get("1")
            .expect("row 1 must have a ctid")
            .clone();
        *real_tid_cell.lock().expect("real_tid_cell lock poisoned") = Some(real_tid);

        Spi::run("SET pinecone.outbox_max_attempts = 1").expect("lower max_attempts for this test");
        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");

        match crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Worker) {
            crate::outbox::DrainOutcome::Parked(e) => {
                let message = format!("{e}");
                assert!(
                    message.contains("no matching row at all"),
                    "message = {message}"
                );
                assert!(message.contains("quiescence"), "message = {message}");
            }
            other => panic!("expected Parked, got {other:?}"),
        }

        assert_eq!(
            outbox_count(table),
            1,
            "the parked job must stay queued, not be dropped"
        );
        assert_eq!(
            recover_job_field(table, "misses").as_deref(),
            Some("1"),
            "the miss must be recorded even though the chunk's cursor did not advance"
        );
        assert_eq!(
            recover_job_field(table, "pagination_token"),
            None,
            "a failed chunk must not advance the cursor"
        );
        let parked: bool = Spi::get_one_with_args::<bool>(
            "SELECT queue_parked FROM pinecone.tables WHERE relid = $1::oid",
            &[relid.into()],
        )
        .expect("select queue_parked")
        .expect("queue_parked NOT NULL");
        assert!(
            parked,
            "the relid's queue must be parked after the permanent-class failure"
        );
    }

    /// `on_miss => 'quarantine'` escapes the parked-on-misses
    /// dead-end. Same fixture as the park test above (one real TID, one
    /// relocated/dead TID the remote still lists), but the job must ADVANCE
    /// past the miss and complete: the real TID's vector written back, the
    /// missed id's fetched bytes copied — byte-exact, no text round-trip —
    /// into pinecone.recover_quarantine, the job's report counting both, and a
    /// completion WARNING (not the clean NOTICE) naming the quarantine.
    #[pg_test]
    fn recover_from_remote_quarantine_advances_past_misses_and_preserves_bytes() {
        install_am_opclasses();
        let table = "recover_am_quarantine";
        let index_name = crate::promote::default_index_name("public", table);
        let real_tid_cell: Arc<Mutex<Option<String>>> = Arc::new(Mutex::new(None));
        let real_tid_for_mock = Arc::clone(&real_tid_cell);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_am_build_success(&control_plane, &data_plane, &index_name, 3, "cosine").await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(move |_req: &Request| {
                        let real_tid = real_tid_for_mock
                            .lock()
                            .expect("real_tid_cell lock poisoned")
                            .clone()
                            .expect("real_tid_cell must be set before recover_from_remote runs");
                        ResponseTemplate::new(200).set_body_json(json!({
                            "vectors": [{"id": real_tid}, {"id": "999999:1"}],
                        }))
                    })
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(|req: &Request| {
                        let mut vectors = serde_json::Map::new();
                        for (k, v) in req.url.query_pairs() {
                            if k == "ids" {
                                // 0.100000001490116... class values would be
                                // the stronger raw-bit probe, but serde_json
                                // round-trips f32-exact dyadics losslessly and
                                // the drill covers raw-Pinecone bytes — here
                                // the point is the FETCHED bytes land in
                                // quarantine unmodified.
                                let vals = if v == "999999:1" {
                                    json!([0.625, -0.375, 0.125])
                                } else {
                                    json!([1.0, 0.0, 0.0])
                                };
                                vectors.insert(v.to_string(), json!({"id": v, "values": vals}));
                            }
                        }
                        ResponseTemplate::new(200)
                            .set_body_json(json!({"vectors": Value::Object(vectors)}))
                    })
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(3))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_cosine_ops)"
        ))
        .expect("create pg_pinecone access-method index");
        let relid = relid_of(table);
        drain_until_empty(relid); // the initial (empty-table) TID backfill job

        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL)"
        ))
        .expect("insert fixture row");
        drain_until_empty(relid); // aminsert's own enqueue (NULL vector: no-op push)

        let real_tid = ctid_map(table)
            .get("1")
            .expect("row 1 must have a ctid")
            .clone();
        *real_tid_cell.lock().expect("real_tid_cell lock poisoned") = Some(real_tid);

        let ((), warnings) = capture_warnings(|| {
            Spi::run(&format!(
                "SELECT pinecone.recover_from_remote({}, on_miss => 'quarantine')",
                quote_literal(table)
            ))
            .expect("recover_from_remote");
            drain_until_empty(relid);
        });

        assert_eq!(
            vector_of(table, 1, "embedding"),
            Some(vec![1.0, 0.0, 0.0]),
            "the real TID's vector must still be written back"
        );
        assert_eq!(
            outbox_count(table),
            0,
            "the job must ADVANCE past the miss and complete — the whole point of quarantine"
        );

        let (q_relid, q_embedding) = Spi::connect(|client| {
            let mut rows = client
                .select(
                    "SELECT relid::oid AS relid, embedding FROM pinecone.recover_quarantine \
                     WHERE remote_id = '999999:1'",
                    None,
                    &[],
                )
                .expect("select quarantine row");
            let row = rows.next().expect("exactly one quarantine row must exist");
            (
                row.get_by_name::<pg_sys::Oid, _>("relid")
                    .expect("get relid")
                    .expect("relid NOT NULL"),
                row.get_by_name::<Vec<Option<f32>>, _>("embedding")
                    .expect("get embedding")
                    .expect("embedding NOT NULL"),
            )
        });
        assert_eq!(q_relid, relid);
        assert_eq!(
            q_embedding,
            vec![Some(0.625), Some(-0.375), Some(0.125)],
            "the quarantined bytes must be exactly what the fetch returned"
        );

        let warning = warnings
            .iter()
            .find(|w| w.contains("recover_from_remote") && w.contains("finished"))
            .unwrap_or_else(|| {
                panic!("expected a completion WARNING naming the quarantine, got {warnings:?}")
            });
        assert!(warning.contains("quarantined 1"), "warning = {warning}");
        assert!(
            warning.contains("recover_quarantine"),
            "warning = {warning}"
        );
        assert!(warning.contains("misses 1"), "warning = {warning}");
    }

    /// The operator path out of a parked job: calling
    /// `recover_from_remote` again while a recover job is already queued must
    /// UPDATE that job's options in place (cursor and counts preserved, still
    /// exactly one job) instead of erroring — so a job parked under the
    /// default `on_miss => 'park'` can be switched to `'quarantine'` and then
    /// resumed with a plain `pinecone.outbox_retry`.
    #[pg_test]
    fn recover_from_remote_updates_a_queued_jobs_options_in_place() {
        create_extension_vector();
        let table = "recover_policy_update";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_promote_success(&control_plane, &data_plane, &index_name).await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("enqueue recover job");
        assert_eq!(recover_job_field(table, "on_miss").as_deref(), Some("park"));

        // Simulate accumulated state a policy update must not clobber.
        Spi::run(&format!(
            "UPDATE pinecone.outbox SET payload = payload || \
             '{{\"pagination_token\": \"page-9\", \"recovered\": 7}}'::jsonb \
             WHERE relid = {}::regclass AND op = 'recover'",
            quote_literal(table)
        ))
        .expect("seed cursor/counts");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({}, overwrite => true, on_miss => 'quarantine')",
            quote_literal(table)
        ))
        .expect("second call must update options, not error");

        assert_eq!(outbox_count(table), 1, "still exactly one recover job");
        assert_eq!(
            recover_job_field(table, "on_miss").as_deref(),
            Some("quarantine"),
            "the queued job's on_miss must be switched in place"
        );
        assert_eq!(
            recover_job_field(table, "overwrite").as_deref(),
            Some("true")
        );
        assert_eq!(
            recover_job_field(table, "pagination_token").as_deref(),
            Some("page-9"),
            "the persisted cursor must be preserved by a policy update"
        );
        assert_eq!(
            recover_job_field(table, "recovered").as_deref(),
            Some("7"),
            "accumulated counts must be preserved by a policy update"
        );
    }

    /// `pinecone.repoint` validates dimension AND metric against the registry
    /// row before updating `index_name` — refusing either mismatch without
    /// touching the registry, and only updating it once both match.
    #[pg_test]
    fn repoint_refuses_dimension_or_metric_mismatch_then_succeeds_on_match() {
        create_extension_vector();
        let table = "repoint_basic";
        let old_index = "pv-repoint-old";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");

        let backend = MockBackend::start(move |control_plane, data_plane| async move {
            let old_body = json!({
                "host": data_plane.uri(),
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("POST"))
                .and(path("/indexes"))
                .respond_with(ResponseTemplate::new(201).set_body_json(old_body.clone()))
                .mount(&control_plane)
                .await;
            Mock::given(method("GET"))
                .and(path(format!("/indexes/{old_index}")))
                .respond_with(ResponseTemplate::new(200).set_body_json(old_body))
                .mount(&control_plane)
                .await;
            Mock::given(method("POST"))
                .and(path("/vectors/delete"))
                .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                .mount(&data_plane)
                .await;

            let baddim_body = json!({
                "host": "unused-baddim.svc.pinecone.io",
                "dimension": 3,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("GET"))
                .and(path("/indexes/idx-new-baddim"))
                .respond_with(ResponseTemplate::new(200).set_body_json(baddim_body))
                .mount(&control_plane)
                .await;

            let badmetric_body = json!({
                "host": "unused-badmetric.svc.pinecone.io",
                "dimension": 2,
                "metric": "euclidean",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("GET"))
                .and(path("/indexes/idx-new-badmetric"))
                .respond_with(ResponseTemplate::new(200).set_body_json(badmetric_body))
                .mount(&control_plane)
                .await;

            let ok_body = json!({
                "host": "unused-ok.svc.pinecone.io",
                "dimension": 2,
                "metric": "cosine",
                "vector_type": "dense",
                "status": {"ready": true, "state": "Ready"},
            });
            Mock::given(method("GET"))
                .and(path("/indexes/idx-new-ok"))
                .respond_with(ResponseTemplate::new(200).set_body_json(ok_body))
                .mount(&control_plane)
                .await;

            (control_plane, data_plane)
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(old_index),
        ))
        .expect("promote");

        let index_name_of = || {
            Spi::get_one::<String>(&format!(
                "SELECT index_name FROM pinecone.tables WHERE relid = {}::regclass",
                quote_literal(table)
            ))
            .expect("select index_name")
            .expect("index_name NOT NULL")
        };
        assert_eq!(index_name_of(), old_index);

        let dim_outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.repoint({}, 'idx-new-baddim')",
                quote_literal(table)
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let msg = dim_outcome.expect_err("dimension mismatch must error");
        assert!(msg.contains("dimension mismatch"), "message = {msg}");
        assert_eq!(
            index_name_of(),
            old_index,
            "a refused repoint must not touch the registry"
        );

        let metric_outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.repoint({}, 'idx-new-badmetric')",
                quote_literal(table)
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let msg = metric_outcome.expect_err("metric mismatch must error");
        assert!(msg.contains("metric mismatch"), "message = {msg}");
        assert_eq!(index_name_of(), old_index);

        Spi::run(&format!(
            "SELECT pinecone.repoint({}, 'idx-new-ok')",
            quote_literal(table)
        ))
        .expect("repoint should succeed on a matching index");
        assert_eq!(index_name_of(), "idx-new-ok");
    }

    /// `pinecone.repoint` must refuse while a `'recover'` job
    /// is queued for the table — the job's persisted pagination token (and
    /// any already-fetched page of ids) belongs to the CURRENT index;
    /// repointing under it would replay a stale cursor against the new one.
    #[pg_test]
    fn repoint_refuses_while_a_recover_job_is_queued() {
        create_extension_vector();
        let table = "repoint_during_recover";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                mount_promote_success(&control_plane, &data_plane, &index_name).await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("enqueue recover job");

        let outcome: Result<(), String> = PgTryBuilder::new(|| {
            Spi::run(&format!(
                "SELECT pinecone.repoint({}, 'idx-anything')",
                quote_literal(table)
            ))
            .expect("should raise ERROR");
            Ok(())
        })
        .catch_others(|caught| Err(error_message(caught)))
        .execute();
        let msg = outcome.expect_err("repoint must refuse while a recover job is queued");
        assert!(msg.contains("recover job"), "message = {msg}");
        assert_eq!(
            outbox_count(table),
            1,
            "the queued recover job must be untouched by the refused repoint"
        );
    }

    /// An INLINE drain (`sync_mode = 'sync'`, the writer's
    /// own statement) must skip a `'recover'` head-of-line row and leave it
    /// for the worker — a user's INSERT must not eat the recover chunk's
    /// list+fetch HTTP round-trips (nor abort the user's statement on a
    /// transient fetch error). The write itself still enqueues behind the
    /// job (FIFO preserved); a worker drain afterward converges both.
    #[pg_test]
    fn inline_drain_skips_a_recover_head_and_leaves_it_for_the_worker() {
        create_extension_vector();
        let table = "recover_inline_skip";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, NULL)"
        ))
        .expect("insert fixture row");

        let mut remote_values = HashMap::new();
        remote_values.insert("1".to_string(), vec![4.0f32, 5.0]);

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote sync-mode");

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("enqueue recover job");
        assert_eq!(outbox_count(table), 1);

        // A sync-mode INSERT fires the inline drain — which must SKIP the
        // 'recover' head (worker-only work) and return without error, leaving
        // both the job and the just-enqueued upsert queued in FIFO order.
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (2, '[9,9]'::vector)"
        ))
        .expect("sync-mode INSERT must succeed without draining the recover head inline");
        let rows = outbox_rows(table);
        assert_eq!(
            rows.iter().map(|r| r.op.as_str()).collect::<Vec<_>>(),
            vec!["recover", "upsert"],
            "the recover head must stay queued, the user's write behind it"
        );

        // The worker path drains both: recover chunk first, then the upsert.
        drain_until_empty(relid_of(table));
        assert_eq!(outbox_count(table), 0);
        assert_eq!(
            vector_of(table, 1, "embedding"),
            Some(vec![4.0, 5.0]),
            "the worker must have completed the recover job"
        );
    }

    /// A fetched vector's remote metadata restores the table's registered
    /// metadata columns — a key the remote object carries is written, a key
    /// it lacks leaves the local column untouched, and (the edge) a remote
    /// metadata payload that is a bare jsonb SCALAR equal to a column name
    /// must ALSO leave the column untouched: `'"category"'::jsonb ?
    /// 'category'` is true (string `?` tests equality), while `->>` on a
    /// scalar yields NULL — without a jsonb_typeof guard that combination
    /// NULLed the column.
    #[pg_test]
    fn recover_restores_metadata_columns_and_survives_scalar_metadata_payloads() {
        create_extension_vector();
        let table = "recover_metadata";
        let index_name = crate::promote::default_index_name("public", table);
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2), \
             category text, count bigint)"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding, category, count) VALUES \
             (1, NULL, NULL, NULL), \
             (2, NULL, 'local-kept', NULL), \
             (3, NULL, 'safe', 5)"
        ))
        .expect("insert fixture rows");

        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/upsert"))
                    .respond_with(
                        ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 1})),
                    )
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/list"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": [{"id": "1"}, {"id": "2"}, {"id": "3"}],
                    })))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                        "vectors": {
                            // Full object: both columns restored.
                            "1": {"id": "1", "values": [1.0, 1.0],
                                  "metadata": {"category": "drama", "count": 42}},
                            // Key absent: category untouched, count restored.
                            "2": {"id": "2", "values": [2.0, 2.0],
                                  "metadata": {"count": 7}},
                            // Hostile edge: a bare jsonb scalar equal to a
                            // column name — must touch NEITHER column.
                            "3": {"id": "3", "values": [3.0, 3.0],
                                  "metadata": "category"},
                        },
                    })))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, \
             metadata_columns => ARRAY['category', 'count'], sync_mode => 'async')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        let relid = relid_of(table);
        drain_until_empty(relid);

        Spi::run(&format!(
            "SELECT pinecone.recover_from_remote({})",
            quote_literal(table)
        ))
        .expect("recover_from_remote");
        drain_until_empty(relid);

        let text_of = |id: i64, col: &str| -> Option<String> {
            Spi::get_one_with_args::<String>(
                &format!("SELECT {col} FROM {table} WHERE id = $1"),
                &[id.into()],
            )
            .expect("select metadata column")
        };
        let int_of = |id: i64, col: &str| -> Option<i64> {
            Spi::get_one_with_args::<i64>(
                &format!("SELECT {col} FROM {table} WHERE id = $1"),
                &[id.into()],
            )
            .expect("select metadata column")
        };

        assert_eq!(vector_of(table, 1, "embedding"), Some(vec![1.0, 1.0]));
        assert_eq!(text_of(1, "category").as_deref(), Some("drama"));
        assert_eq!(int_of(1, "count"), Some(42));

        assert_eq!(
            text_of(2, "category").as_deref(),
            Some("local-kept"),
            "a key the remote metadata object lacks must leave the local column untouched"
        );
        assert_eq!(int_of(2, "count"), Some(7));

        assert_eq!(
            text_of(3, "category").as_deref(),
            Some("safe"),
            "a bare scalar metadata payload equal to the column name must not NULL the column"
        );
        assert_eq!(
            int_of(3, "count"),
            Some(5),
            "a scalar metadata payload must leave every metadata column untouched"
        );
        assert_eq!(
            vector_of(table, 3, "embedding"),
            Some(vec![3.0, 3.0]),
            "the vector itself still restores regardless of the metadata payload shape"
        );
    }

    // ---- pinecone.backup_readiness ----

    /// Mounts the standard `pinecone.promote` control+data-plane pair (2-dim
    /// index) plus, for `pinecone.backup_readiness`, `describe_index_stats`
    /// (data plane), `list_backups`/`get_backup_schedule` (control plane).
    /// `backups`/`schedule`: `Err(template)` mounts that response verbatim
    /// (e.g. a 403 plan-gate body) instead of a 200.
    async fn mount_backup_readiness_fixture(
        control_plane: &wiremock::MockServer,
        data_plane: &wiremock::MockServer,
        index_name: &str,
        stats_namespaces: &[(&str, u64)],
        backups: Result<Vec<Value>, ResponseTemplate>,
        schedule: Result<Option<Value>, ResponseTemplate>,
    ) {
        let index_body = json!({
            "host": data_plane.uri(),
            "dimension": 2,
            "metric": "cosine",
            "vector_type": "dense",
            "status": {"ready": true, "state": "Ready"},
        });
        Mock::given(method("POST"))
            .and(path("/indexes"))
            .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
            .mount(control_plane)
            .await;
        Mock::given(method("GET"))
            .and(path(format!("/indexes/{index_name}")))
            .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
            .mount(control_plane)
            .await;
        Mock::given(method("POST"))
            .and(path("/vectors/delete"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
            .mount(data_plane)
            .await;
        Mock::given(method("POST"))
            .and(path("/vectors/upsert"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({"upsertedCount": 3})))
            .mount(data_plane)
            .await;

        let ns_obj: serde_json::Map<String, Value> = stats_namespaces
            .iter()
            .map(|(name, count)| ((*name).to_string(), json!({"vectorCount": count})))
            .collect();
        let total: u64 = stats_namespaces.iter().map(|(_, c)| *c).sum();
        Mock::given(method("POST"))
            .and(path("/describe_index_stats"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "totalVectorCount": total,
                "namespaces": ns_obj,
            })))
            .mount(data_plane)
            .await;

        match backups {
            Ok(list) => {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}/backups")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({"data": list})))
                    .mount(control_plane)
                    .await;
            }
            Err(template) => {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}/backups")))
                    .respond_with(template)
                    .mount(control_plane)
                    .await;
            }
        }

        match schedule {
            Ok(Some(body)) => {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}/backups/schedule")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(body))
                    .mount(control_plane)
                    .await;
            }
            Ok(None) => {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}/backups/schedule")))
                    .respond_with(ResponseTemplate::new(404))
                    .mount(control_plane)
                    .await;
            }
            Err(template) => {
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}/backups/schedule")))
                    .respond_with(template)
                    .mount(control_plane)
                    .await;
            }
        }
    }

    /// One backup's JSON object, in the snake_case shape
    /// `pg_pinecone_client::client::ApiBackupInfo` deserializes.
    fn backup_json(
        id: &str,
        status: &str,
        created_at: &str,
        namespace_count: u64,
        dimension: u32,
    ) -> Value {
        json!({
            "backup_id": id,
            "status": status,
            "created_at": created_at,
            "namespace_count": namespace_count,
            "dimension": dimension,
        })
    }

    /// A `created_at` string `interval` in the past, formatted by Postgres
    /// itself (`(now() - interval '...')::text`) — this client never parses
    /// it beyond `backup_age_seconds`'s own `$1::timestamptz` SQL cast, so
    /// Postgres's own text output round-trips exactly, no RFC3339 formatting
    /// needed on the Rust side.
    fn pg_timestamp_ago(interval: &str) -> String {
        Spi::get_one::<String>(&format!("SELECT (now() - interval '{interval}')::text"))
            .expect("compute timestamp")
            .expect("timestamp NOT NULL")
    }

    /// Every `pinecone.backup_readiness(tbl)` row, keyed by `check`.
    fn backup_readiness_rows(table: &str) -> HashMap<String, (String, String)> {
        Spi::connect(|client| {
            client
                .select(
                    &format!(
                        // `check` is a reserved SQL keyword — must be quoted
                        // when referenced as a bare column in a SELECT list
                        // (unlike as an `OUT` parameter name, which Postgres
                        // accepts unquoted in a CREATE FUNCTION signature).
                        "SELECT \"check\", status, detail FROM pinecone.backup_readiness({}::regclass)",
                        quote_literal(table)
                    ),
                    None,
                    &[],
                )
                .expect("select backup_readiness")
                .map(|row| {
                    let check = row
                        .get_by_name::<String, _>("check")
                        .expect("check")
                        .expect("check NOT NULL");
                    let status = row
                        .get_by_name::<String, _>("status")
                        .expect("status")
                        .expect("status NOT NULL");
                    let detail = row
                        .get_by_name::<String, _>("detail")
                        .expect("detail")
                        .expect("detail NOT NULL");
                    (check, (status, detail))
                })
                .collect()
        })
    }

    #[pg_test]
    fn backup_readiness_reports_ok_across_all_three_checks_when_healthy() {
        create_extension_vector();
        let table = "br_happy";
        let index_name = "idx-br-happy";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES \
             (1, '[1,1]'::vector), (2, '[2,2]'::vector), (3, '[3,3]'::vector)"
        ))
        .expect("insert rows");

        let created_at = pg_timestamp_ago("10 minutes");
        let backend = MockBackend::start({
            let index_name = index_name.to_string();
            move |control_plane, data_plane| async move {
                mount_backup_readiness_fixture(
                    &control_plane,
                    &data_plane,
                    &index_name,
                    &[("ns-a", 3)],
                    Ok(vec![backup_json("bkp-1", "Ready", &created_at, 1, 2)]),
                    Ok(Some(json!({"frequency": "daily"}))),
                )
                .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, namespace => 'ns-a', sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(index_name),
        ))
        .expect("promote");

        let rows = backup_readiness_rows(table);
        assert_eq!(
            rows.get("sync").map(|(s, _)| s.as_str()),
            Some("ok"),
            "{rows:?}"
        );
        assert_eq!(
            rows.get("coverage").map(|(s, _)| s.as_str()),
            Some("ok"),
            "{rows:?}"
        );
        assert!(
            rows["coverage"].1.contains("ONLY namespace"),
            "detail = {}",
            rows["coverage"].1
        );
        assert_eq!(
            rows.get("freshness").map(|(s, _)| s.as_str()),
            Some("ok"),
            "{rows:?}"
        );
    }

