    /// The plan-gated 403 (the `backup_forbidden` mapping)
    /// on `list_backups`/`get_backup_schedule` must surface as its own
    /// `'unavailable (plan does not include backups)'` status, quoting the
    /// server's own message in `detail` — and must NOT affect the `sync`
    /// check, which never touches the backup surface at all.
    #[pg_test]
    fn backup_readiness_unavailable_when_plan_lacks_backups_403() {
        create_extension_vector();
        let table = "br_plan_gated";
        let index_name = "idx-br-plan-gated";
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
        ))
        .expect("create table");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding) VALUES (1, '[1,1]'::vector)"
        ))
        .expect("insert row");

        fn plan_gate_403() -> ResponseTemplate {
            ResponseTemplate::new(403).set_body_json(json!({
                "error": {
                    "code": "FORBIDDEN",
                    "message": "Your organization's plan does not include backups. To use \
                                backups, upgrade to the Standard or Enterprise plan."
                },
                "status": 403,
            }))
        }

        let backend = MockBackend::start({
            let index_name = index_name.to_string();
            move |control_plane, data_plane| async move {
                mount_backup_readiness_fixture(
                    &control_plane,
                    &data_plane,
                    &index_name,
                    &[("ns-l", 1)],
                    Err(plan_gate_403()),
                    Err(plan_gate_403()),
                )
                .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, namespace => 'ns-l', sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(index_name),
        ))
        .expect("promote");

        let rows = backup_readiness_rows(table);
        assert_eq!(
            rows.get("sync").map(|(s, _)| s.as_str()),
            Some("ok"),
            "the sync check must be unaffected by a backup-surface 403: {rows:?}"
        );
        for check in ["coverage", "freshness"] {
            let (status, detail) = &rows[check];
            assert_eq!(
                status, "unavailable (plan does not include backups)",
                "{check}: detail = {detail}"
            );
            assert!(
                detail.contains("plan does not include backups"),
                "{check}: the server's own message must survive verbatim: {detail}"
            );
        }
    }

