    /// An unchanged, still non-`NULL` vector (a test-only leftover — a real
    /// `detach_storage()` NULLs every row) whose metadata changes is an
    /// ordinary full re-upsert: the write guard already proved the vector
    /// itself never took on a genuinely new value, and the real values are
    /// already sitting right here locally.
    #[pg_test]
    fn sync_trigger_detached_unchanged_nonnull_vector_metadata_change_upserts() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("detach_meta_nonnull", "async");
        Spi::run(
            "INSERT INTO detach_meta_nonnull (id, embedding, category) VALUES (1, '[1,0]', 'a')",
        )
        .expect("seed row");
        set_storage_detached("detach_meta_nonnull");

        Spi::run("UPDATE detach_meta_nonnull SET category = 'b' WHERE id = 1")
            .expect("metadata-only edit on a leftover non-NULL vector must not error");

        assert!(upserts.lock().expect("lock poisoned").is_empty());
        assert!(deletes.lock().expect("lock poisoned").is_empty());
        let rows = outbox_rows("detach_meta_nonnull");
        let last = rows.last().expect("at least the update's own row");
        assert_eq!(last.op, "upsert");
        let vectors = batch_vectors_by_id(last.payload.as_ref().expect("payload"));
        assert_eq!(vectors["1"]["values"], json!([1, 0]));
        assert_eq!(vectors["1"]["metadata"], json!({"category": "b"}));
    }

    /// The scoped metadata-divergence fix, merge leg: a metadata-only SET
    /// on a row whose vector stays `NULL`, where the changed field's new
    /// value is non-`NULL`, becomes a cheap `'update'` outbox op (merge-only
    /// `setMetadata`) — not silence, and not a full re-upsert.
    #[pg_test]
    fn sync_trigger_detached_metadata_merge_enqueues_update_op() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("detach_meta_merge", "async");
        Spi::run("INSERT INTO detach_meta_merge (id, embedding, category) VALUES (1, NULL, 'a')")
            .expect("seed row with NULL vector");
        set_storage_detached("detach_meta_merge");

        Spi::run("UPDATE detach_meta_merge SET category = 'b' WHERE id = 1")
            .expect("metadata-only set on a NULL-vector detached row");

        assert!(upserts.lock().expect("lock poisoned").is_empty());
        assert!(deletes.lock().expect("lock poisoned").is_empty());
        let rows = outbox_rows("detach_meta_merge");
        let last = rows.last().expect("at least the update's own row");
        assert_eq!(last.op, "update");
        let items = last
            .payload
            .as_ref()
            .expect("payload")
            .as_array()
            .expect("array");
        assert_eq!(items.len(), 1, "items = {items:?}");
        assert_eq!(items[0]["id"], json!("1"));
        assert_eq!(items[0]["metadata"], json!({"category": "b"}));
    }

    /// The scoped metadata-divergence fix, the `->NULL` leg: a metadata
    /// field being CLEARED (its new value is `NULL`) on a `NULL`-vector
    /// detached row can't go through the merge-only `'update'` op (Pinecone's
    /// setMetadata can never unset a key) — it must become a `'reupsert'`
    /// op instead.
    #[pg_test]
    fn sync_trigger_detached_metadata_clear_enqueues_reupsert_op() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("detach_meta_clear", "async");
        Spi::run("INSERT INTO detach_meta_clear (id, embedding, category) VALUES (1, NULL, 'a')")
            .expect("seed row with NULL vector");
        set_storage_detached("detach_meta_clear");

        Spi::run("UPDATE detach_meta_clear SET category = NULL WHERE id = 1")
            .expect("metadata clear on a NULL-vector detached row");

        assert!(upserts.lock().expect("lock poisoned").is_empty());
        assert!(deletes.lock().expect("lock poisoned").is_empty());
        let rows = outbox_rows("detach_meta_clear");
        let last = rows.last().expect("at least the update's own row");
        assert_eq!(last.op, "reupsert");
        let items = last
            .payload
            .as_ref()
            .expect("payload")
            .as_array()
            .expect("array");
        assert_eq!(items.len(), 1, "items = {items:?}");
        assert_eq!(items[0]["id"], json!("1"));
        assert_eq!(
            items[0]["metadata"],
            json!({}),
            "the cleared field must be stripped, not sent as null: {:?}",
            items[0]
        );
    }

    /// One statement-level UPDATE touching two detached rows must split
    /// them correctly between the two ops: one row keeps a non-NULL
    /// replacement metadata value (merge-eligible), the other clears its
    /// only metadata field (needs the reupsert leg).
    #[pg_test]
    fn sync_trigger_detached_metadata_mixed_batch_splits_update_and_reupsert() {
        create_extension_vector();
        let (_backend, upserts, deletes) =
            setup_sync_trigger_table_mode("detach_meta_mixed", "async");
        Spi::run(
            "INSERT INTO detach_meta_mixed (id, embedding, category) VALUES \
             (1, NULL, 'a'), (2, NULL, 'b')",
        )
        .expect("seed rows with NULL vectors");
        set_storage_detached("detach_meta_mixed");

        Spi::run(
            "UPDATE detach_meta_mixed SET category = CASE WHEN id = 1 THEN 'a2' ELSE NULL END \
             WHERE id IN (1, 2)",
        )
        .expect("mixed metadata edit");

        assert!(upserts.lock().expect("lock poisoned").is_empty());
        assert!(deletes.lock().expect("lock poisoned").is_empty());
        let rows = outbox_rows("detach_meta_mixed");
        let update_row = rows
            .iter()
            .rev()
            .find(|r| r.op == "update")
            .unwrap_or_else(|| panic!("expected an 'update' row: {rows:?}"));
        let reupsert_row = rows
            .iter()
            .rev()
            .find(|r| r.op == "reupsert")
            .unwrap_or_else(|| panic!("expected a 'reupsert' row: {rows:?}"));

        let update_items = update_row
            .payload
            .as_ref()
            .expect("payload")
            .as_array()
            .expect("array");
        assert_eq!(update_items.len(), 1, "update_items = {update_items:?}");
        assert_eq!(update_items[0]["id"], json!("1"));
        assert_eq!(update_items[0]["metadata"], json!({"category": "a2"}));

        let reupsert_items = reupsert_row
            .payload
            .as_ref()
            .expect("payload")
            .as_array()
            .expect("array");
        assert_eq!(
            reupsert_items.len(),
            1,
            "reupsert_items = {reupsert_items:?}"
        );
        assert_eq!(reupsert_items[0]["id"], json!("2"));
        assert_eq!(reupsert_items[0]["metadata"], json!({}));
    }

    /// Wire-level: the `'update'` op's dispatch actually sends a merge-only
    /// `setMetadata` PATCH (`POST /vectors/update`), not a full upsert — no
    /// `/vectors/upsert` mock is mounted at all, so an accidental extra
    /// upsert call would surface as a hard (unmocked-404) client error. The
    /// mounted `/vectors/fetch` (returning the id) satisfies the dispatch's
    /// ghost pre-check (a live-verified 200-no-op on a missing id
    /// carries no signal, so existence is checked via fetch first — see
    /// `try_update_metadata`'s rustdoc); the ghost path itself is
    /// `outbox_update_op_skips_and_warns_on_ghost_ids` below.
    #[pg_test]
    fn outbox_update_op_sends_merge_setmetadata_patch() {
        create_extension_vector();
        let table = "detach_wire_update";
        let index_name = crate::promote::default_index_name("public", table);
        let update_bodies: BodySink = Arc::new(Mutex::new(Vec::new()));
        let update_bodies_for_mock = Arc::clone(&update_bodies);
        let backend = MockBackend::start({
            let index_name = index_name.clone();
            move |control_plane, data_plane| async move {
                let index_body = json!({
                    "host": data_plane.uri(),
                    "dimension": 2,
                    "metric": "cosine",
                    "vector_type": "dense",
                    "status": {"ready": true, "state": "Ready"},
                });
                Mock::given(method("POST"))
                    .and(path("/indexes"))
                    .respond_with(ResponseTemplate::new(201).set_body_json(index_body.clone()))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("GET"))
                    .and(path(format!("/indexes/{index_name}")))
                    .respond_with(ResponseTemplate::new(200).set_body_json(index_body))
                    .mount(&control_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/delete"))
                    .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
                    .mount(&data_plane)
                    .await;
                Mock::given(method("POST"))
                    .and(path("/vectors/update"))
                    .respond_with(move |req: &Request| {
                        let body: Value = req.body_json().expect("update body should be JSON");
                        update_bodies_for_mock
                            .lock()
                            .expect("lock poisoned")
                            .push(body);
                        ResponseTemplate::new(200).set_body_json(json!({}))
                    })
                    .mount(&data_plane)
                    .await;
                let mut remote_values = HashMap::new();
                remote_values.insert("1".to_string(), vec![0.5f32, 0.5]);
                Mock::given(method("GET"))
                    .and(path("/vectors/fetch"))
                    .respond_with(recover_fetch_responder(remote_values))
                    .mount(&data_plane)
                    .await;
                (control_plane, data_plane)
            }
        });
        point_at_mock(&backend);

        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2), category text)"
        ))
        .expect("create table");
        Spi::run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, metadata_columns => ARRAY['category'], \
             sync_mode => 'sync')",
            quote_literal(table),
            quote_literal(&index_name),
        ))
        .expect("promote");
        Spi::run(&format!(
            "INSERT INTO {table} (id, embedding, category) VALUES (1, NULL, 'a')"
        ))
        .expect("seed row with NULL vector");
        set_storage_detached(table);

        Spi::run(&format!("UPDATE {table} SET category = 'b' WHERE id = 1"))
            .expect("metadata merge while detached");

        let bodies = update_bodies.lock().expect("lock poisoned").clone();
        assert_eq!(bodies.len(), 1, "bodies = {bodies:?}");
        assert_eq!(bodies[0]["id"], json!("1"));
        assert_eq!(bodies[0]["setMetadata"], json!({"category": "b"}));
        assert_eq!(outbox_count(table), 0, "sync_mode = 'sync' drains inline");
    }

    /// Wire-level: the `'reupsert'` op's dispatch fetches the real values
    /// from Pinecone (`GET /vectors/fetch`) and re-upserts them combined
    /// with the freshly stripped metadata (`POST /vectors/upsert`) — the
    /// cleared field must not survive into the re-upsert.
