    /// The pair is declared together or not at all, and the kind is one the namespaces support.
    #[pg_test]
    fn partition_columns_must_be_both_set_or_both_null_with_a_known_kind() {
        doc_table("part_check_vec");
        doc_table("part_check_doc");
        let vector = |extra_columns: &str, extra_values: &str| {
            format!(
                "INSERT INTO pinecone.tables (relid, vector_column, id_column, metric, dimension, \
                 index_name, namespace{extra_columns}) VALUES ('part_check_vec'::regclass, \
                 'embedding', 'id', 'cosine', 2, 'i', 'n'{extra_values})"
            )
        };
        let document = |extra_columns: &str, extra_values: &str| {
            format!(
                "INSERT INTO pinecone.doc_tables (relid, id_column, id_type, text_columns, \
                 index_name, namespace, schema, state{extra_columns}) VALUES \
                 ('part_check_doc'::regclass, 'id', 'int8', '{{}}', 'i', 'n', '{{}}', 'ready'\
                 {extra_values})"
            )
        };
        for build in [&vector as &dyn Fn(&str, &str) -> String, &document] {
            for (columns, values) in [
                (", partition_column", ", 'tenant_id'"),
                (", partition_kind", ", 'int8'"),
                (
                    ", partition_column, partition_kind",
                    ", 'tenant_id', 'bigint'",
                ),
                (
                    ", partition_column, partition_kind",
                    ", 'tenant_id', 'INT8'",
                ),
            ] {
                let sql = build(columns, values);
                let error = doc_sql_error(&sql);
                assert_eq!(error.sqlstate, "23514", "{sql}: {}", error.message);
            }
            for kind in ["int2", "int4", "int8", "text", "uuid"] {
                let sql = build(
                    ", partition_column, partition_kind",
                    &format!(", 'tenant_id', '{kind}'"),
                );
                Spi::run(&sql).unwrap_or_else(|e| panic!("{sql}: {e}"));
                Spi::run("DELETE FROM pinecone.tables").expect("clean vector registry");
                Spi::run("DELETE FROM pinecone.doc_tables").expect("clean doc registry");
            }
        }
    }

    #[pg_test]
    fn partitions_register_is_idempotent_and_lists_by_table_and_lane() {
        let first = doc_table("part_reg_first");
        let second = doc_table("part_reg_second");
        let register = |relid, lane, value: &str, namespace: &str| {
            partition_registry::register_partition(relid, lane, value, namespace)
        };
        assert!(partition_registry::partitions_of(first, Lane::Vector).is_empty());
        register(first, Lane::Vector, "7", "public.t:7");
        register(first, Lane::Vector, "10", "public.t:10");
        register(first, Lane::Vector, "7", "public.t:7");
        register(first, Lane::Docs, "7", "public.t:7");
        register(second, Lane::Vector, "a:b", "public.u:a%3Ab");
        let names = |relid, lane| partition_registry::partitions_of(relid, lane);
        assert_eq!(
            names(first, Lane::Vector),
            vec![
                ("10".to_string(), "public.t:10".to_string()),
                ("7".to_string(), "public.t:7".to_string()),
            ],
            "ordered by namespace, once each"
        );
        assert_eq!(
            names(first, Lane::Docs),
            vec![("7".to_string(), "public.t:7".to_string())]
        );
        assert_eq!(
            names(second, Lane::Vector),
            vec![("a:b".to_string(), "public.u:a%3Ab".to_string())]
        );
        assert!(names(second, Lane::Docs).is_empty());
    }

    #[pg_test]
    fn partition_registering_again_keeps_the_first_seen_time() {
        let relid = doc_table("part_reg_first_seen");
        partition_registry::register_partition(relid, Lane::Vector, "7", "public.t:7");
        Spi::run("UPDATE pinecone.partitions SET first_seen = '2020-01-01 00:00:00+00'")
            .expect("backdate");
        partition_registry::register_partition(relid, Lane::Vector, "7", "public.t:7");
        let kept = Spi::get_one::<bool>(
            "SELECT first_seen = '2020-01-01 00:00:00+00'::timestamptz FROM pinecone.partitions",
        )
        .expect("first_seen query");
        assert_eq!(kept, Some(true));
    }

    #[pg_test]
    fn partition_forgetting_removes_one_table_and_lane_only() {
        let first = doc_table("part_forget_first");
        let second = doc_table("part_forget_second");
        for (relid, lane) in [
            (first, Lane::Vector),
            (first, Lane::Docs),
            (second, Lane::Vector),
        ] {
            partition_registry::register_partition(relid, lane, "1", "public.t:1");
            partition_registry::register_partition(relid, lane, "2", "public.t:2");
        }
        partition_registry::forget_partitions(first, Lane::Vector);
        assert!(partition_registry::partitions_of(first, Lane::Vector).is_empty());
        assert_eq!(
            partition_registry::partitions_of(first, Lane::Docs).len(),
            2
        );
        assert_eq!(
            partition_registry::partitions_of(second, Lane::Vector).len(),
            2
        );
        partition_registry::forget_partitions(first, Lane::Vector);
    }

    /// The registry of partitions is dumped with the extension, so a restore keeps what was seen.
    #[pg_test]
    fn partitions_is_dumped_with_the_extension() {
        let sql = "SELECT coalesce(jsonb_agg(c::regclass::text), '[]'::jsonb) \
                   FROM pg_extension e, unnest(e.extconfig) c WHERE e.extname = 'pg_pinecone'";
        let dumped = Spi::get_one::<JsonB>(sql)
            .expect("extconfig")
            .expect("aggregate")
            .0;
        let names: BTreeSet<String> = serde_json::from_value(dumped).expect("an array of names");
        assert!(names.contains("pinecone.partitions"), "{names:?}");
    }

    /// `REVOKE ALL ... FROM PUBLIC`: only the owner and the helpers (which switch to it) touch the table.
    #[pg_test]
    fn partitions_denies_every_statement_to_an_unprivileged_role() {
        let relid = doc_table("part_acl_target");
        let statements = [
            "SELECT * FROM pinecone.partitions".to_string(),
            "DELETE FROM pinecone.partitions".to_string(),
            "UPDATE pinecone.partitions SET value = 'x'".to_string(),
            format!(
                "INSERT INTO pinecone.partitions (relid, lane, value, namespace) \
                 VALUES ({relid}::oid::regclass, 'vector', '1', 'n:1')"
            ),
        ];
        let errors = doc_as_unprivileged_role("part_acl", || {
            statements
                .iter()
                .map(|sql| doc_sql_error(sql))
                .collect::<Vec<_>>()
        });
        for (sql, error) in statements.iter().zip(&errors) {
            assert_eq!(error.sqlstate, "42501", "{sql}: {}", error.message);
            assert!(error.message.contains("permission denied"), "{sql}");
        }
    }

    /// The helpers run as the registry's owner, so any role that may write the table may use them.
    #[pg_test]
    fn partition_helpers_work_for_a_role_without_grants() {
        let relid = doc_table("part_definer_target");
        let seen = doc_as_unprivileged_role("part_definer", || {
            partition_registry::register_partition(relid, Lane::Vector, "7", "public.t:7");
            partition_registry::register_partition(relid, Lane::Vector, "8", "public.t:8");
            let before = partition_registry::partitions_of(relid, Lane::Vector);
            partition_registry::forget_partitions(relid, Lane::Vector);
            (
                before,
                partition_registry::partitions_of(relid, Lane::Vector),
            )
        });
        assert_eq!(seen.0.len(), 2);
        assert!(seen.1.is_empty());
    }

    #[pg_test]
    fn partitions_constraints_reject_bad_rows() {
        let relid = doc_table("part_constraints");
        let insert = |lane: &str, value: &str, namespace: &str| {
            format!(
                "INSERT INTO pinecone.partitions (relid, lane, value, namespace) \
                 VALUES ({relid}::oid::regclass, {}, {}, {})",
                quote_literal(lane),
                quote_literal(value),
                quote_literal(namespace)
            )
        };
        let error = doc_sql_error(&insert("fts", "1", "n:1"));
        assert_eq!(
            error.sqlstate, "23514",
            "only the two lanes: {}",
            error.message
        );
        Spi::run(&insert("vector", "1", "n:1")).expect("first row");
        let error = doc_sql_error(&insert("vector", "1", "n:1"));
        assert_eq!(
            error.sqlstate, "23505",
            "(relid, lane, namespace) is unique"
        );
        Spi::run(&insert("docs", "1", "n:1")).expect("the same namespace in the other lane");
        for (lane, value, namespace) in [
            ("NULL", "'v'", "'n:9'"),
            ("'vector'", "NULL", "'n:9'"),
            ("'vector'", "'v'", "NULL"),
        ] {
            let error = doc_sql_error(&format!(
                "INSERT INTO pinecone.partitions (relid, lane, value, namespace) \
                 VALUES ({relid}::oid::regclass, {lane}, {value}, {namespace})"
            ));
            assert_eq!(
                error.sqlstate, "23502",
                "{lane} {value} {namespace}: {}",
                error.message
            );
        }
    }

    fn claim_row(table: &str, index: &str, claim: Claim<'_>) -> RegistryRow {
        let partition =
            matches!(claim, Claim::Family(_)).then(|| spec("tenant_id", PartitionKind::Int8));
        part_row(table, index, claim.namespace(), partition)
    }

    fn claim_doc_row(table: &str, index: &str, claim: Claim<'_>) -> DocRegistryRow {
        let mut row = doc_registry_row(table, index, claim.namespace());
        row.partition =
            matches!(claim, Claim::Family(_)).then(|| spec("tenant_id", PartitionKind::Int8));
        row
    }

    fn matrix_claims() -> Vec<Claim<'static>> {
        ["a", "a:1", "a:1:2", "a:", "ab", "b", "b:a", ":"]
            .into_iter()
            .flat_map(|name| [Claim::Exact(name), Claim::Family(name)])
            .collect()
    }

    /// Every registered claim against every asked claim: the SQL agrees with `Claim::conflicts_with`.
    #[pg_test]
    fn partition_vector_registry_claims_clash_exactly_as_the_pure_rule_says() {
        let holder = doc_table("part_matrix_vec_holder");
        let probe = doc_table("part_matrix_vec_probe");
        let claims = matrix_claims();
        for held in &claims {
            registry::insert(&claim_row("part_matrix_vec_holder", "idx", *held));
            for asked in &claims {
                let found = registry::claim_owner("idx", *asked, probe);
                assert_eq!(
                    found.is_some(),
                    held.conflicts_with(*asked),
                    "{held:?} is held, {asked:?} is asked"
                );
                if let Some(found) = found {
                    assert_eq!(found.relid, holder);
                    assert_eq!(found.namespace, held.namespace());
                    assert_eq!(found.partitioned, matches!(held, Claim::Family(_)));
                }
                assert!(
                    registry::claim_owner("other-idx", *asked, probe).is_none(),
                    "claims never cross indexes: {held:?} {asked:?}"
                );
                assert!(
                    registry::claim_owner("idx", *asked, holder).is_none(),
                    "a table never clashes with itself: {held:?} {asked:?}"
                );
            }
            registry::delete(holder);
        }
    }

    #[pg_test]
    fn partition_doc_registry_claims_clash_exactly_as_the_pure_rule_says() {
        let holder = doc_table("part_matrix_doc_holder");
        let probe = doc_table("part_matrix_doc_probe");
        let claims = matrix_claims();
        for held in &claims {
            docs_registry::insert(&claim_doc_row("part_matrix_doc_holder", "idx", *held));
            for asked in &claims {
                let expected = held.conflicts_with(*asked);
                let docs_side = docs_registry::claim_owner("idx", *asked);
                let vector_side = registry::claim_owner("idx", *asked, probe);
                for found in [&docs_side, &vector_side] {
                    assert_eq!(
                        found.is_some(),
                        expected,
                        "{held:?} is held, {asked:?} is asked"
                    );
                    if let Some(found) = found {
                        assert_eq!(found.relid, holder);
                        assert_eq!(found.namespace, held.namespace());
                        assert_eq!(found.partitioned, matches!(held, Claim::Family(_)));
                    }
                }
                assert!(docs_registry::claim_owner("other-idx", *asked).is_none());
                assert_eq!(
                    docs_registry::claim_owner("idx", *asked).is_some(),
                    expected,
                    "the document registry has no own-table exemption"
                );
            }
            docs_registry::delete(holder);
        }
    }

    #[pg_test]
    fn partition_a_partitioned_vector_table_reserves_its_family_against_exact_namespaces() {
        let tenant = doc_table("part_fam_vec");
        let probe = doc_table("part_fam_vec_probe");
        registry::insert(&part_row(
            "part_fam_vec",
            "shared",
            "public.docs",
            Some(spec("tenant_id", PartitionKind::Int8)),
        ));
        let exact =
            |index: &str, namespace: &str| registry::index_namespace_owner(index, namespace, probe);
        for inside in [
            "public.docs:42",
            "public.docs:",
            "public.docs:a%3Ab",
            "public.docs",
        ] {
            assert_eq!(exact("shared", inside), Some(tenant), "{inside}");
        }
        for outside in [
            "public.docs2",
            "public.doc",
            "public.docs2:1",
            "x:public.docs:1",
            "public",
        ] {
            assert_eq!(exact("shared", outside), None, "{outside}");
        }
        assert_eq!(exact("another-index", "public.docs:42"), None);
        let family = |prefix: &str| {
            registry::claim_owner("shared", Claim::Family(prefix), probe).map(|o| o.relid)
        };
        for clashing in ["public.docs", "public.docs:x", "public.docs:x:y"] {
            assert_eq!(family(clashing), Some(tenant), "{clashing}");
        }
        for free in ["public.docs2", "public", "public.doc"] {
            assert_eq!(family(free), None, "{free}");
        }
    }

