    #[pg_test]
    fn partition_partitioned_rows_count_as_users_of_their_index_in_both_registries() {
        let vector = doc_table("part_users_vec");
        let document = doc_table("part_users_doc");
        let probe = doc_table("part_users_probe");
        registry::insert(&part_row(
            "part_users_vec",
            "vec-idx",
            "public.v",
            Some(spec("tenant_id", PartitionKind::Int4)),
        ));
        let mut row = doc_registry_row("part_users_doc", "doc-idx", "public.d");
        row.partition = Some(spec("tenant_id", PartitionKind::Int4));
        docs_registry::insert(&row);
        assert!(registry::lookup(vector).expect("row").partition.is_some());
        assert!(
            docs_registry::lookup(document)
                .expect("row")
                .partition
                .is_some()
        );

        assert!(registry::other_row_uses_index("vec-idx", probe));
        assert!(!registry::other_row_uses_index("vec-idx", vector));
        assert!(registry::any_row_uses_index("vec-idx"));
        assert!(registry::other_row_uses_index("doc-idx", probe));
        assert!(registry::other_row_uses_index("doc-idx", document));
        assert!(registry::any_row_uses_index("doc-idx"));
        assert!(docs_registry::other_row_uses_index("doc-idx", probe));
        assert!(!docs_registry::other_row_uses_index("doc-idx", document));
        assert!(!registry::any_row_uses_index("free-idx"));
    }

    /// A vector-only role still never reads the document registry, families included.
    #[pg_test]
    fn partition_family_claims_ignore_document_tables_for_roles_that_cannot_read_them() {
        let doc = doc_table("part_blind_docs");
        let probe = doc_table("part_blind_probe");
        let mut row = doc_registry_row("part_blind_docs", "blind-idx", "public.b");
        row.partition = Some(spec("tenant_id", PartitionKind::Int8));
        docs_registry::insert(&row);
        let role = format!("pinecone_part_blind_{}", std::process::id());
        Spi::run(&format!("CREATE ROLE {role}")).expect("create role");
        Spi::run(&format!("GRANT USAGE ON SCHEMA pinecone TO {role}")).expect("grant usage");
        Spi::run(&format!("GRANT SELECT ON pinecone.tables TO {role}")).expect("grant tables");
        let asked = || {
            registry::claim_owner("blind-idx", Claim::Exact("public.b:7"), probe).map(|o| o.relid)
        };
        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let blind = asked();
        Spi::run("RESET ROLE").expect("RESET ROLE");
        Spi::run(&format!("GRANT SELECT ON pinecone.doc_tables TO {role}")).expect("grant docs");
        Spi::run(&format!("SET ROLE {role}")).expect("SET ROLE");
        let sighted = asked();
        Spi::run("RESET ROLE").expect("RESET ROLE");
        assert_eq!((blind, sighted), (None, Some(doc)));
    }

    #[pg_test]
    fn partition_refusing_a_family_clash_raises_42710_and_lets_exact_pairs_through() {
        // A relation that exists in every snapshot; the verbs' own tests pin names of new tables.
        let holder = relid_of("pinecone.tables");
        let family = partition_registry::Owner {
            relid: holder,
            namespace: "public.docs".to_string(),
            partitioned: true,
        };
        let error = doc_error_of(|| {
            partition_registry::refuse_family_clash(
                "pinecone.promote",
                "idx",
                Claim::Exact("public.docs:7"),
                &family,
            )
        });
        assert_eq!(error.sqlstate, "42710", "{}", error.message);
        assert_eq!(
            error.message,
            "pinecone.promote: index 'idx' namespace 'public.docs:7' falls in the partition \
             family 'public.docs:*' of pinecone.tables"
        );
        assert_eq!(error.hint.as_deref(), Some(crate::partition::CLASH_HINT));

        let error = doc_error_of(|| {
            partition_registry::refuse_family_clash(
                "pinecone.create_index",
                "idx",
                Claim::Family("public.x"),
                &partition_registry::Owner {
                    partitioned: false,
                    namespace: "public.x:1".to_string(),
                    ..family
                },
            )
        });
        assert_eq!(error.sqlstate, "42710");
        assert!(
            error
                .message
                .contains("collides with namespace 'public.x:1'")
        );

        partition_registry::refuse_family_clash(
            "pinecone.promote",
            "idx",
            Claim::Exact("ns"),
            &partition_registry::Owner {
                relid: holder,
                namespace: "ns".to_string(),
                partitioned: false,
            },
        );
    }

    fn family_owner_row(table: &str, index: &str, prefix: &str) -> RegistryRow {
        claim_row(table, index, Claim::Family(prefix))
    }

    fn assert_family_clash(error: &DocError, message: &str) {
        assert_eq!(error.sqlstate, "42710", "{}", error.message);
        assert_eq!(error.message, message);
        assert_eq!(error.hint.as_deref(), Some(crate::partition::CLASH_HINT));
    }

