        assert!(
            matches!(first, crate::outbox::DrainOutcome::Backoff(_)),
            "{first:?}"
        );
        assert!(
            matches!(second, crate::outbox::DrainOutcome::Parked(_)),
            "{second:?}"
        );
        assert!(part_failed_rows(table).is_empty());
