    #[pg_test]
    fn partition_failed_an_unpartitioned_table_parks_as_before() {
        let table = "part_g9_plain";
        let env = PartEnv::untracked(table, "bigint");
        fts_run(&format!(
            "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
            quote_literal(table),
            quote_literal(crate::promote::default_index_name("public", table)),
        ));
        part_drain(table);
        env.vectors.clear_calls();
        fts_run("SET pinecone.outbox_max_attempts = 2");
        env.vectors
            .fail_always(VecEndpoint::Upsert, 400, "bad request body");
        env.insert("(1, 1, '[1,0]', 'a'), (2, 2, '[0,1]', 'b')");

        let first = part_step(table);
        let second = part_step(table);

        assert!(
            matches!(first, crate::outbox::DrainOutcome::Backoff(_)),
            "{first:?}"
        );
        assert!(
            matches!(second, crate::outbox::DrainOutcome::Parked(_)),
            "{second:?}"
        );
        let calls = env.vectors.calls();
        assert_eq!(calls.len(), 2, "{calls:?}");
        for call in &calls {
            assert_eq!(call.endpoint, VecEndpoint::Upsert);
            assert_eq!(call.namespace.as_deref(), Some(env.prefix.as_str()));
            assert_eq!(call.status, 400);
            let body = call.body.clone().unwrap_or_default();
            let vectors = body["vectors"].as_array().cloned().unwrap_or_default();
            let ids: Vec<&str> = vectors.iter().filter_map(|v| v["id"].as_str()).collect();
            assert_eq!(ids, ["1", "2"]);
        }
        let queued = part_outbox(table);
        assert_eq!(queued.len(), 1);
        assert_eq!(queued[0]["attempts"], json!(2));
        let row = part_status(table);
        assert_eq!(row["queue_state"], json!("parked"));
        assert_eq!(row["failed_partitions"], json!(0));
        let last = row["last_error"].as_str().unwrap_or_default();
        assert!(last.contains("bad request body"), "{row}");
    }

