    #[pg_test]
    fn partition_failed_partitions_are_listed_for_the_owner_only() {
        let table = "part_g10_list";
        let env = part_with_failed_tenant(table, "async");
        env.run("CREATE ROLE part_g10_owner_role");
        env.run("GRANT USAGE ON SCHEMA pinecone TO part_g10_owner_role");
        env.run(&format!("ALTER TABLE {table} OWNER TO part_g10_owner_role"));
        env.run("CREATE ROLE part_g10_other_role");
        env.run("GRANT USAGE ON SCHEMA pinecone TO part_g10_other_role");

        env.run("SET ROLE part_g10_owner_role");
        let failed = part_failed_partitions(table);
        let all = Spi::get_one::<JsonB>(&format!(
            "SELECT jsonb_agg(to_jsonb(p) ORDER BY p.namespace) FROM pinecone.partitions_of({}) p",
            fts_rel(table)
        ))
        .expect("partitions_of")
        .expect("rows")
        .0;
        env.run("RESET ROLE");

        assert_eq!(failed.len(), 1, "{failed:?}");
        assert_eq!(failed[0]["value"], json!("2"));
        assert_eq!(failed[0]["namespace"], json!(env.ns("2")));
        assert!(failed[0]["failed_at"].is_string(), "{failed:?}");
        let error = failed[0]["last_error"].as_str().unwrap_or_default();
        assert!(error.contains(PART_REFUSED), "{failed:?}");
        let all = all.as_array().cloned().unwrap_or_default();
        let state: Vec<(Value, bool)> = all
            .iter()
            .map(|r| (r["value"].clone(), !r["failed_at"].is_null()))
            .collect();
        let expected = [(json!("1"), false), (json!("2"), true), (json!("3"), false)];
        assert_eq!(state, expected);
        assert!(all[1]["last_error"].is_string() && all[0]["last_error"].is_null());

        env.run("SET ROLE part_g10_other_role");
        let error = fts_sql_error(&format!("SELECT * FROM {PART_FAILED_LIST}('{table}')"));
        env.run("RESET ROLE");
        fts_assert_error(&error, "42501", &["must be owner", table]);
    }

    #[pg_test]
    fn partition_failed_retry_all_rebuilds_every_failed_partition_and_nothing_else() {
        let table = "part_g11_all";
        let env = PartEnv::declared(table, "async");
        for tenant in ["2", "3"] {
            let reason = format!("{PART_REFUSED} {tenant}");
            env.vectors
                .fail_namespace(VecEndpoint::Upsert, &env.ns(tenant), 400, &reason);
        }
        env.insert(
            "(1, 1, '[1,0]', 'a'), (2, 2, '[0,1]', 'b'), (3, 3, '[1,1]', 'c'), (4, 3, '[1,0]', 'd')",
        );
        part_drain(table);
        assert_eq!(part_failed_rows(table).len(), 2);

        for value in ["1", "77"] {
            let error = fts_sql_error(&format!("SELECT {PART_RETRY}('{table}', {value})"));
            fts_assert_error(&error, "22023", &["not failed"]);
        }

        env.vectors.heal_all();
        env.vectors.clear_calls();
        let retried = Spi::get_one::<i32>(&format!("SELECT {PART_RETRY_ALL}('{table}')"));
        part_drain(table);

        assert_eq!(retried.expect("retry_failed_partitions"), Some(2));
        assert_eq!(env.ids("2"), part_strings(&["2"]));
        assert_eq!(env.ids("3"), part_strings(&["3", "4"]));
        assert_eq!(env.ids("1"), part_strings(&["1"]));
        assert!(part_failed_rows(table).is_empty());
        assert_eq!(part_calls_to(&env.vectors, &env.ns("1")), 0);
        let again = Spi::get_one::<i32>(&format!("SELECT {PART_RETRY_ALL}('{table}')"));
        assert_eq!(again.expect("nothing left to retry"), Some(0));
    }

