        env.run(&format!("SELECT {PART_RETRY}('{table}', 2)"));
        part_one_chunk_per_round(&env.vectors);

        part_step(table);
        let set = |sql: &str| env.run(&format!("UPDATE {table} SET {sql}"));
        set("embedding = '[9,9]' WHERE id IN (110, 2000)");
        env.insert("(50, 2, '[5,5]', 'n'), (5000, 2, '[6,6]', 'n')");
        set("tenant_id = 3 WHERE id IN (120, 2100)");
        set("tenant_id = 2 WHERE id = 1");
        env.run(&format!("DELETE FROM {table} WHERE id IN (130, 2200)"));
        part_drain(table);

        part_assert_matches_heap(&env, &[1, 2, 3]);
