    #[pg_test]
    fn partition_failed_access_method_rebuilds_of_many_partitions_share_a_round() {
        let table = "part_i12_am_many";
        let env = PartAm::declared(table);
        for tenant in 1..=5 {
            let reason = format!("{PART_REFUSED} {tenant}");
            let namespace = env.ns(&tenant.to_string());
            env.vectors
                .fail_namespace(VecEndpoint::Upsert, &namespace, 400, &reason);
        }
        env.insert(
            "(1, 1, '[1,0]', 'a'), (2, 2, '[0,1]', 'b'), (3, 3, '[1,1]', 'c'), \
             (4, 4, '[1,0]', 'd'), (5, 5, '[0,1]', 'e'), (6, 5, '[1,1]', 'f')",
        );
        env.drain();
        assert_eq!(part_failed_rows(table).len(), 5);
        env.vectors.heal_all();
        env.vectors.clear_calls();
        let retried = Spi::get_one::<i32>(&format!("SELECT {PART_RETRY_ALL}('{table}')"));
        assert_eq!(retried.expect("retry_failed_partitions"), Some(5));
        fts_run("SET pinecone.backfill_round_ms = 60000");

        let mut rounds = 0;
        while outbox_count(table) > 0 && rounds < 50 {
            part_step(table);
            rounds += 1;
        }

        assert_eq!(rounds, 1, "5 rebuilds took {rounds} rounds");
        assert!(part_failed_rows(table).is_empty());
        for (tenant, ids) in [("1", ["1"].as_slice()), ("5", ["5", "6"].as_slice())] {
            let tids: Vec<String> = ids.iter().map(|id| env.tid(id)).collect();
            let tids: Vec<&str> = tids.iter().map(String::as_str).collect();
            assert_eq!(env.remote(tenant), part_strings(&tids), "tenant {tenant}");
        }
        assert_eq!(env.vectors.count(VecEndpoint::NamespaceDelete), 5);
    }

