    // ---- end of the partition column tests ----

    // ---- backfill chunks per round, first fetch of an access-method scan (0.10) ----
    //
    // Round and request counts against the vectors mock, never wall-clock: a round budget
    // (`pinecone.backfill_round_ms`) of 60 s lets a round run every chunk on any machine, and a
    // 50 ms budget against a mock that answers no faster than 60 ms ends every round after one.

    /// Milliseconds the wiremock upsert answers of the tests that look at a backfill between its
    /// chunks wait (see [`one_chunk_per_round`]).
    static UPSERT_DELAY_MS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

    /// Ends every backfill round after its first chunk, on any machine: a 50 ms budget against
    /// upsert answers that take 60 ms. The worker runs a round's chunks back to back, so a test that
    /// looks at the job between two chunks has to say so.
    fn one_chunk_per_round() {
        fts_run("SET pinecone.backfill_round_ms = 50");
        UPSERT_DELAY_MS.store(60, std::sync::atomic::Ordering::Relaxed);
    }

    /// `answer`, held back as [`one_chunk_per_round`] says (not at all by default).
    fn slow_upsert(answer: ResponseTemplate) -> ResponseTemplate {
        let delay = UPSERT_DELAY_MS.load(std::sync::atomic::Ordering::Relaxed);
        answer.set_delay(std::time::Duration::from_millis(delay))
    }

    /// A table of 2-d vectors on an arc (distinct cosine distances to `[1,0]`), the vectors mock,
    /// and the lane it is on.
    struct RoundEnv {
        _backend: MockBackend,
        vectors: VectorsHandle,
        table: String,
        namespace: String,
    }

    impl RoundEnv {
        fn create_table(table: &str, rows: i64) {
            create_extension_vector();
            fts_run(&format!(
                "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector(2))"
            ));
            fts_run(&format!(
                "INSERT INTO {table} (id, embedding) SELECT i, \
                 ARRAY[cos(i * 0.005), sin(i * 0.005)]::real[]::vector FROM generate_series(1, {rows}) i"
            ));
        }

        /// `pinecone.promote(.., sync_mode => 'async')`: the trigger lane, `delete_all` and backfill queued.
        fn trigger(table: &str, rows: i64) -> Self {
            Self::create_table(table, rows);
            Self::promote_trigger(table)
        }

        fn promote_trigger(table: &str) -> Self {
            let (backend, vectors) = PartEnv::mock();
            fts_run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
                quote_literal(table),
                quote_literal(crate::promote::default_index_name("public", table))
            ));
            vectors.clear_calls();
            Self::of(backend, vectors, table)
        }

        /// `create_index(.., engine => 'remote')`: the access method, its TID backfill queued.
        fn access_method(table: &str, rows: i64) -> Self {
            install_am_opclasses();
            Self::create_table(table, rows);
            Self::create_remote_index(table)
        }

        fn create_remote_index(table: &str) -> Self {
            let (backend, vectors) = PartEnv::mock();
            fts_run(&format!(
                "SELECT pinecone.create_index({}, 'embedding', engine => 'remote')",
                quote_literal(table)
            ));
            vectors.clear_calls();
            Self::of(backend, vectors, table)
        }

        fn of(backend: MockBackend, vectors: VectorsHandle, table: &str) -> Self {
            Self {
                _backend: backend,
                vectors,
                table: table.to_string(),
                namespace: part_prefix(table),
            }
        }

        fn step(&self) -> crate::outbox::DrainOutcome {
            part_step(&self.table)
        }

        /// Worker rounds (`Scheduler::drain_round`) until the queue is empty, and the time they took.
        fn rounds(&self, cap: u32) -> (u32, std::time::Duration) {
            let mut scheduler = crate::outbox::Scheduler::new();
            let started = std::time::Instant::now();
            let mut rounds = 0;
            while outbox_count(&self.table) > 0 {
                assert!(
                    rounds < cap,
                    "{}: queue not empty after {cap} rounds",
                    self.table
                );
                scheduler.drain_round();
                rounds += 1;
            }
            (rounds, started.elapsed())
        }

        fn cursor(&self) -> Option<String> {
            Spi::get_one::<String>(&format!(
                "SELECT payload->>'after_id' FROM pinecone.outbox WHERE relid = {} AND op = 'backfill'",
                fts_rel(&self.table)
            ))
            .expect("read the backfill cursor")
        }

        fn job(&self) -> Value {
            let rows = part_outbox(&self.table);
            let job = rows.into_iter().find(|r| r["op"] == json!("backfill"));
            job.expect("a backfill job is queued")
        }

        fn remote(&self) -> BTreeSet<String> {
            self.vectors.ids(&self.namespace)
        }

        fn mode(&self) -> Value {
            part_status(&self.table)["mode"].clone()
        }

        /// Ids of the successful upserts, per request, in arrival order.
        fn upserted(&self) -> Vec<Vec<String>> {
            let sent = part_upserts(&self.vectors).into_iter();
            sent.map(|(_, items)| {
                let ids = items.iter().filter_map(|v| v["id"].as_str());
                ids.map(str::to_string).collect()
            })
            .collect()
        }
    }

    /// Rows per second a worker delivers at the configured `worker_naptime_ms`: its work plus a
    /// nap between two rounds (none after the last).
    fn rows_per_second(rows: i64, rounds: u32, work: std::time::Duration) -> f64 {
        let nap = Spi::get_one::<String>("SHOW pinecone.worker_naptime_ms")
            .expect("SHOW worker_naptime_ms")
            .and_then(|ms| ms.parse::<f64>().ok())
            .expect("a number of milliseconds");
        let naps = f64::from(rounds.saturating_sub(1)) * nap / 1000.0;
        rows as f64 / (work.as_secs_f64() + naps)
    }

    const ROUND_ROWS: i64 = 20_000;

    /// 20,000 rows are 20 chunks. Every worker round used to run one of them and then nap, so the
    /// backfill took 21 rounds (the last one reads nothing and flips the mode); the rounds now
    /// run chunks back to back until `backfill_round_ms` (1 s) is spent. Requests are unchanged:
    /// one per chunk of 1,000 rows.
    #[pg_test]
    fn backfill_round_trigger_lane_20k_rows_take_a_handful_of_rounds() {
        let env = RoundEnv::trigger("round_trigger_20k", ROUND_ROWS);

        let (rounds, work) = env.rounds(60);

        let rate = rows_per_second(ROUND_ROWS, rounds, work);
        assert!(rounds <= 4, "{ROUND_ROWS} rows took {rounds} rounds");
        assert!(rate >= 1_000.0, "{rate:.0} rows/s at the default naptime");
        assert_eq!(
            env.vectors.count(VecEndpoint::Upsert),
            20,
            "one request per chunk"
        );
        assert_eq!(
            env.vectors.record_count(&env.namespace),
            ROUND_ROWS as usize
        );
        assert_eq!(env.mode(), json!("remote"));
    }

    /// The same for the access method's TID backfill: a chunk ends at a heap block boundary.
    #[pg_test]
    fn backfill_round_access_method_20k_rows_take_a_handful_of_rounds() {
        let env = RoundEnv::access_method("round_am_20k", ROUND_ROWS);

        let (rounds, work) = env.rounds(60);

        let rate = rows_per_second(ROUND_ROWS, rounds, work);
        assert!(rounds <= 4, "{ROUND_ROWS} rows took {rounds} rounds");
        assert!(rate >= 1_000.0, "{rate:.0} rows/s at the default naptime");
        let tids: BTreeSet<String> = ctid_map(&env.table).into_values().collect();
        assert_eq!(env.remote(), tids, "every row, by its TID, exactly once");
        assert_eq!(env.mode(), json!("remote"));
    }

    /// Under a 60 s budget one round runs every chunk, the empty read that ends the job included:
    /// the registry flips to `remote` in that round.
    #[pg_test]
    fn backfill_round_runs_every_chunk_in_one_round_under_a_long_budget() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let trigger = RoundEnv::trigger("round_long_trigger", 3_500);
        let (rounds, _) = trigger.rounds(10);
        assert_eq!(rounds, 1, "trigger lane");
        assert_eq!(trigger.remote().len(), 3_500);
        assert_eq!(trigger.mode(), json!("remote"));

        let am = RoundEnv::access_method("round_long_am", 3_500);
        let (rounds, _) = am.rounds(10);
        assert_eq!(rounds, 1, "access method");
        assert_eq!(am.remote().len(), 3_500);
        assert_eq!(am.mode(), json!("remote"));
    }

    /// A request slower than the round budget ends the round after its chunk, so the budget still
    /// bounds a round: one chunk per round, the cursor advancing each time.
    #[pg_test]
    fn backfill_round_ends_after_one_chunk_when_a_request_outlasts_the_budget() {
        let env = RoundEnv::trigger("round_slow", 2_500);
        fts_run("SET pinecone.backfill_round_ms = 50");
        env.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));

        for last_id in [1_000, 2_000, 2_500] {
            assert!(matches!(
                env.step(),
                crate::outbox::DrainOutcome::Processed(_)
            ));
            assert_eq!(env.cursor(), Some(last_id.to_string()), "one more chunk");
            assert_eq!(env.remote().len(), last_id, "one more chunk");
        }
        assert_eq!(
            env.mode(),
            json!("promoting"),
            "the empty read is a round of its own"
        );
        assert!(matches!(
            env.step(),
            crate::outbox::DrainOutcome::Processed(1)
        ));
        assert_eq!(env.mode(), json!("remote"));
        assert_eq!(outbox_count(&env.table), 0);
    }

    /// The inline drain (a `sync_mode = 'sync'` writer, in its own statement) still runs one chunk of
    /// a job and stops: only the worker runs a round's chunks back to back.
    #[pg_test]
    fn backfill_round_inline_drain_runs_one_chunk() {
        let env = RoundEnv::trigger("round_inline", 3_000);
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let relid = relid_of(&env.table);
        let inline =
            |relid| crate::outbox::drain_step(relid, crate::backend::DrainCredentials::Inline);

        inline(relid);
        assert_eq!(
            env.vectors.count(VecEndpoint::Upsert),
            1,
            "the first chunk, nothing more"
        );
        assert_eq!(env.cursor().as_deref(), Some("1000"));
        inline(relid);
        assert_eq!(
            env.vectors.count(VecEndpoint::Upsert),
            2,
            "one chunk per inline step"
        );
        assert_eq!(env.cursor().as_deref(), Some("2000"));
    }

    /// Two tables promoted in the trigger lane against one vectors mock, each with a backfill queued.
    fn round_two_tables(first: &str, second: &str, rows: i64) -> (MockBackend, VectorsHandle) {
        RoundEnv::create_table(first, rows);
        RoundEnv::create_table(second, rows);
        let (backend, vectors) = PartEnv::mock();
        for table in [first, second] {
            fts_run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
                quote_literal(table),
                quote_literal(crate::promote::default_index_name("public", table))
            ));
        }
        vectors.clear_calls();
        (backend, vectors)
    }

    /// The last id the backfill job of `table` has sent (0 before its first chunk).
    fn round_cursor(table: &str) -> i64 {
        let cursor = Spi::get_one::<String>(&format!(
            "SELECT payload->>'after_id' FROM pinecone.outbox WHERE relid = {} AND op = 'backfill'",
            fts_rel(table)
        ))
        .expect("read the backfill cursor");
        cursor.map_or(0, |id| id.parse().expect("a numeric cursor"))
    }

    /// The round budget is the round's, not each table's: the first table runs chunks until it is
    /// spent, every other table still gets its one chunk, and the table that leads moves on each
    /// round. With a budget of 1.5 s against 0.5 s requests the leader runs two or three chunks and
    /// the other exactly one; a budget per table would give both of them two or three.
    #[pg_test]
    fn backfill_round_budget_is_shared_by_the_tables_of_a_round() {
        let (_backend, vectors) = round_two_tables("round_share_a", "round_share_b", 8_000);
        fts_run("SET pinecone.backfill_round_ms = 1500");
        vectors.set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(500));
        let tables = ["round_share_a", "round_share_b"];
        let mut scheduler = crate::outbox::Scheduler::new();

        let round = scheduler.round();
        let after_first = tables.map(round_cursor);
        let (lead, follow) = if after_first[0] > after_first[1] {
            (0, 1)
        } else {
            (1, 0)
        };
        assert_eq!(
            after_first[follow], 1_000,
            "one chunk for the table after the leader: {after_first:?}"
        );
        assert!(
            after_first[lead] >= 2_000,
            "the leader ran until the budget was spent: {after_first:?}"
        );
        assert_eq!(
            vectors.count(VecEndpoint::Upsert) as i64,
            (after_first[0] + after_first[1]) / 1_000,
            "a request per chunk"
        );
        assert!(round.chunks_left, "both jobs have chunks left");

        scheduler.round();
        let after_second = tables.map(round_cursor);
        assert_eq!(
            after_second[lead] - after_first[lead],
            1_000,
            "the leader of round 1 follows in round 2: {after_second:?}"
        );
        assert!(
            after_second[follow] - after_first[follow] >= 2_000,
            "and the other leads: {after_first:?} then {after_second:?}"
        );
    }

    /// Raises `ShutdownRequestPending` once the vectors mock has seen an upsert, as pgrx's SIGTERM
    /// handler does in a worker; lowers it again on drop.
    struct ShutdownRequest {
        stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
        watcher: Option<std::thread::JoinHandle<()>>,
    }

    impl ShutdownRequest {
        fn after_first_upsert(vectors: &VectorsHandle) -> Self {
            use std::sync::atomic::{AtomicBool, Ordering};
            let stop = std::sync::Arc::new(AtomicBool::new(false));
            let (seen, vectors) = (std::sync::Arc::clone(&stop), vectors.clone());
            let watcher = std::thread::spawn(move || {
                while !seen.load(Ordering::Relaxed) {
                    if vectors.count(VecEndpoint::Upsert) > 0 {
                        unsafe { (&raw mut pg_sys::ShutdownRequestPending).write_volatile(1) };
                        return;
                    }
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            });
            Self {
                stop,
                watcher: Some(watcher),
            }
        }
    }

    impl Drop for ShutdownRequest {
        fn drop(&mut self) {
            self.stop.store(true, std::sync::atomic::Ordering::Relaxed);
            if let Some(watcher) = self.watcher.take() {
                let _ = watcher.join();
            }
            unsafe { (&raw mut pg_sys::ShutdownRequestPending).write_volatile(0) };
        }
    }

    /// A shutdown request ends a round after the chunk in flight: the 60 s budget is not spent, the
    /// cursor is where that chunk left it, and the table behind it is not started. (The real
    /// worker raises the flag from its SIGTERM handler: `worker_bgw_sigterm_ends_a_backfill_round`.)
    #[pg_test]
    fn backfill_round_ends_after_the_current_chunk_on_a_shutdown_request() {
        let (_backend, vectors) = round_two_tables("round_stop_a", "round_stop_b", 8_000);
        fts_run("SET pinecone.backfill_round_ms = 60000");
        vectors.set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(300));
        let request = ShutdownRequest::after_first_upsert(&vectors);

        let round = crate::outbox::Scheduler::new().round();
        drop(request);

        assert_eq!(
            vectors.count(VecEndpoint::Upsert),
            1,
            "the chunk in flight and nothing after it"
        );
        let cursors = ["round_stop_a", "round_stop_b"].map(round_cursor);
        assert_eq!(
            cursors.iter().sum::<i64>(),
            1_000,
            "one chunk in all: {cursors:?}"
        );
        assert!(
            round.chunks_left,
            "the job is still queued, to resume at the cursor"
        );
        assert_eq!(
            outbox_count("round_stop_a") + outbox_count("round_stop_b"),
            3,
            "both backfill jobs are still queued, and the delete_all of the table behind the first"
        );
    }

    /// Writes queued behind a backfill job keep their place: they go out after the job's chunks, in
    /// the round the job ends (the first one, under a long budget). A row the job has passed keeps
    /// its old vector remote until then, and the write is the last request of its round.
    #[pg_test]
    fn backfill_round_writes_queued_behind_the_job_go_out_when_it_ends() {
        let vector_of = |env: &RoundEnv, id: &str| {
            env.vectors
                .record(&env.namespace, id)
                .map(|record| record["values"].clone())
        };
        let slow = RoundEnv::trigger("round_behind_slow", 2_500);
        fts_run("SET pinecone.backfill_round_ms = 50");
        slow.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));
        slow.step(); // `delete_all` and ids 1 to 1,000
        let old = vector_of(&slow, "5").expect("id 5 is remote");
        fts_run("UPDATE round_behind_slow SET embedding = '[0,1]' WHERE id = 5");

        slow.step(); // 1,001 to 2,000
        slow.step(); // 2,001 to 2,500
        assert_eq!(
            vector_of(&slow, "5"),
            Some(old),
            "the write waits for the job"
        );
        slow.step(); // the empty read ends the job, the write goes out behind it

        assert_eq!(vector_of(&slow, "5"), Some(json!([0.0, 1.0])));
        assert_eq!(slow.upserted().last(), Some(&vec!["5".to_string()]));
        assert_eq!(outbox_count(&slow.table), 0);

        let fast = RoundEnv::trigger("round_behind_fast", 2_500);
        fts_run("UPDATE round_behind_fast SET embedding = '[0,1]' WHERE id = 5");
        fts_run("SET pinecone.backfill_round_ms = 60000");

        fast.step();

        assert_eq!(
            outbox_count(&fast.table),
            0,
            "the job and the write in one round"
        );
        assert_eq!(
            fast.upserted().last(),
            Some(&vec!["5".to_string()]),
            "the write is last"
        );
        assert_eq!(fast.remote().len(), 2_500);
    }

    /// A chunk that fails in the middle of a round leaves the cursor at the last chunk that went
    /// out, committed with the round; the next round resumes there. Nothing is skipped and what
    /// was delivered is not sent again. A 503 is retried by the client (three attempts), so the
    /// third request fails on all three.
    #[pg_test]
    fn backfill_round_trigger_lane_failed_chunk_resumes_after_the_last_good_one() {
        let env = RoundEnv::trigger("round_fail_trigger", 5_000);
        fts_run("SET pinecone.backfill_round_ms = 60000");
        env.vectors
            .fail_range(VecEndpoint::Upsert, 3, 3, 503, "outage");

        let first = env.step();

        assert!(
            matches!(first, crate::outbox::DrainOutcome::Backoff(_)),
            "{first:?}"
        );
        assert_eq!(
            env.cursor().as_deref(),
            Some("2000"),
            "two chunks went out before the third failed"
        );
        let ids: BTreeSet<String> = (1..=2_000).map(|i| i.to_string()).collect();
        assert_eq!(env.remote(), ids);
        let job = env.job();
        assert!(
            job["last_error"]
                .as_str()
                .unwrap_or_default()
                .contains("outage"),
            "{job}"
        );
        assert_eq!(job["attempts"], json!(0), "a 503 is no attempt");

        env.vectors.heal_all();
        env.vectors.clear_calls();
        env.rounds(10);

        let resent: Vec<String> = env.upserted().concat();
        assert_eq!(resent.first().map(String::as_str), Some("2001"));
        assert!(
            resent
                .iter()
                .all(|id| id.parse::<i64>().is_ok_and(|n| n > 2_000)),
            "nothing sent again"
        );
        assert_eq!(env.remote().len(), 5_000);
        assert_eq!(env.mode(), json!("remote"));
    }

    /// The same for the TID backfill, where the cursor is a heap block: after the failed round every
    /// row in blocks up to the cursor is remote and no other row is; the next round starts at the
    /// next block. A 400 is not retried and is no outage: it counts an attempt.
    #[pg_test]
    fn backfill_round_access_method_failed_chunk_resumes_after_the_last_good_one() {
        let env = RoundEnv::access_method("round_fail_am", 5_000);
        fts_run("SET pinecone.backfill_round_ms = 60000");
        env.vectors.fail_nth(VecEndpoint::Upsert, 3, 400, "refused");
        let blocks = |tids: &BTreeSet<String>| -> BTreeSet<u32> {
            tids.iter()
                .filter_map(|t| t.split(':').next()?.parse().ok())
                .collect()
        };
        let all: BTreeSet<String> = ctid_map(&env.table).into_values().collect();

        let first = env.step();

        assert!(
            matches!(first, crate::outbox::DrainOutcome::Backoff(_)),
            "{first:?}"
        );
        let cursor: u32 = env
            .cursor()
            .expect("a block cursor")
            .parse()
            .expect("a block number");
        let want: BTreeSet<String> = all
            .iter()
            .filter(|t| {
                t.split(':')
                    .next()
                    .and_then(|b| b.parse::<u32>().ok())
                    .is_some_and(|b| b <= cursor)
            })
            .cloned()
            .collect();
        assert!(
            !want.is_empty() && want.len() < all.len(),
            "the cursor is mid-table: block {cursor}"
        );
        assert_eq!(
            env.remote(),
            want,
            "rows up to the cursor, and only those, are remote"
        );
        let job = env.job();
        assert!(
            job["last_error"]
                .as_str()
                .unwrap_or_default()
                .contains("refused"),
            "{job}"
        );
        assert_eq!(job["attempts"], json!(1));

        env.vectors.heal_all();
        env.vectors.clear_calls();
        env.rounds(10);

        let resent: BTreeSet<String> = env.upserted().concat().into_iter().collect();
        assert!(
            blocks(&resent).iter().all(|b| *b > cursor),
            "nothing sent again"
        );
        assert_eq!(env.remote(), all);
        assert_eq!(env.mode(), json!("remote"));
    }

    /// What a request log says about a partitioned backfill: `(tenant, ids)` per request, in order.
    fn partition_request_log(vectors: &VectorsHandle) -> Vec<(Option<i64>, Vec<String>)> {
        let sent = part_upserts(vectors).into_iter();
        sent.map(|(namespace, items)| {
            for item in &items {
                assert_eq!(
                    part_item_tenant(item),
                    part_ns_tenant(&namespace),
                    "{namespace} mixes tenants"
                );
            }
            assert!(
                items.len() <= 1_000,
                "{namespace}: {} vectors in a request",
                items.len()
            );
            let ids = items.iter().filter_map(|v| v["id"].as_str());
            (
                part_ns_tenant(&namespace),
                ids.map(str::to_string).collect(),
            )
        })
        .collect()
    }

    /// A partitioned access-method backfill reads a window of rows and sends one request per
    /// namespace of it, however the tenants alternate in the heap. Under the round loop the windows
    /// follow one another in a round and the requests are exactly those of one window per round.
    #[pg_test]
    fn backfill_round_partitioned_access_method_groups_per_namespace_per_window() {
        let rows = 12_000;
        let run = |table: &str, one_chunk_per_round: bool| {
            let env = PartAm::untracked(table, "bigint");
            env.run(&format!(
                "INSERT INTO {table} (id, tenant_id, embedding, category) \
                 SELECT i, (i % 3) + 1, ARRAY[i, 1]::vector, 'c' FROM generate_series(1, {rows}) i"
            ));
            env.run(&PartAm::create_index_sql(table));
            env.vectors.clear_calls();
            if one_chunk_per_round {
                part_one_chunk_per_round(&env.vectors);
            } else {
                fts_run("SET pinecone.backfill_round_ms = 60000");
            }
            let mut scheduler = crate::outbox::Scheduler::new();
            let mut rounds = 0;
            while outbox_count(table) > 0 && rounds < 60 {
                scheduler.drain_round();
                rounds += 1;
            }
            assert_eq!(outbox_count(table), 0, "{table}: not drained");
            (
                partition_request_log(&env.vectors),
                rounds,
                env.registered().len(),
            )
        };

        let (windows, window_rounds, _) = run("round_part_am_windows", true);
        let (together, together_rounds, namespaces) = run("round_part_am_together", false);

        assert!(
            window_rounds >= 4,
            "the table spans several windows: {window_rounds} rounds"
        );
        assert_eq!(together_rounds, 1);
        assert_eq!(namespaces, 3);
        assert_eq!(together, windows, "the same requests, in the same order");
    }

    /// The same for the trigger lane, whose chunk is 1,000 rows in `(tenant, id)` order: a chunk
    /// that ends inside a tenant continues it in the next, which still sends one request per
    /// namespace and chunk.
    #[pg_test]
    fn backfill_round_partitioned_trigger_lane_groups_per_namespace_per_chunk() {
        let rows = 4_500;
        let run = |table: &str, one_chunk_per_round: bool| {
            let env = PartEnv::untracked(table, "bigint");
            fts_run(&format!(
                "INSERT INTO {table} (id, tenant_id, embedding, category) \
                 SELECT i, (i % 3) + 1, ARRAY[i, 1]::vector, 'c' FROM generate_series(1, {rows}) i"
            ));
            fts_run(&PartEnv::promote_sql(table, "async", ""));
            env.vectors.clear_calls();
            if one_chunk_per_round {
                part_one_chunk_per_round(&env.vectors);
            } else {
                fts_run("SET pinecone.backfill_round_ms = 60000");
            }
            let mut scheduler = crate::outbox::Scheduler::new();
            let mut rounds = 0;
            while outbox_count(table) > 0 && rounds < 60 {
                scheduler.drain_round();
                rounds += 1;
            }
            assert_eq!(outbox_count(table), 0, "{table}: not drained");
            (
                partition_request_log(&env.vectors),
                rounds,
                env.registered().len(),
            )
        };

        let (chunks, chunk_rounds, _) = run("round_part_pk_chunks", true);
        let (together, together_rounds, namespaces) = run("round_part_pk_together", false);

        assert!(
            chunk_rounds >= 5,
            "the table spans several chunks: {chunk_rounds} rounds"
        );
        assert_eq!(together_rounds, 1);
        assert_eq!(namespaces, 3);
        assert_eq!(together, chunks, "the same requests, in the same order");
    }

    /// Nothing but the loop changed for an unpartitioned table: the requests of a backfill are those
    /// of one chunk per round (the two partitioned tests above compare the logs) and, for the
    /// first chunk, exactly the ones listed here, as 0.9.0 sent them: trigger lane `delete_all`
    /// of the namespace and one upsert of the rows by primary key; access method one upsert by
    /// TID. Vectors only, no metadata, in table order.
    #[pg_test]
    fn backfill_round_unpartitioned_requests_are_unchanged() {
        create_extension_vector();
        fts_run("CREATE TABLE round_golden_trigger (id bigint PRIMARY KEY, embedding vector(2))");
        fts_run("INSERT INTO round_golden_trigger VALUES (1, '[1,0]'), (2, '[0,1]'), (3, '[1,1]')");
        let trigger = RoundEnv::promote_trigger("round_golden_trigger");
        trigger.step();
        let namespace = trigger.namespace.clone();
        let log = |env: &RoundEnv| -> Vec<(VecEndpoint, Option<Value>)> {
            let calls = env.vectors.calls().into_iter();
            calls.map(|c| (c.endpoint, c.body)).collect()
        };
        assert_eq!(
            log(&trigger),
            vec![
                (VecEndpoint::IndexDescribe, None),
                (
                    VecEndpoint::Delete,
                    Some(json!({"deleteAll": true, "namespace": namespace}))
                ),
                (
                    VecEndpoint::Upsert,
                    Some(json!({
                        "vectors": [
                            {"id": "1", "values": [1.0, 0.0]},
                            {"id": "2", "values": [0.0, 1.0]},
                            {"id": "3", "values": [1.0, 1.0]},
                        ],
                        "namespace": namespace,
                    }))
                ),
            ]
        );

        install_am_opclasses();
        fts_run("CREATE TABLE round_golden_am (id bigint PRIMARY KEY, embedding vector(2))");
        fts_run("INSERT INTO round_golden_am VALUES (1, '[1,0]'), (2, '[0,1]'), (3, '[1,1]')");
        let am = RoundEnv::create_remote_index("round_golden_am");
        let tids = ctid_map("round_golden_am");
        am.step();
        assert_eq!(
            log(&am),
            vec![
                (VecEndpoint::IndexDescribe, None),
                (
                    VecEndpoint::Upsert,
                    Some(json!({
                        "vectors": [
                            {"id": tids["1"], "values": [1.0, 0.0]},
                            {"id": tids["2"], "values": [0.0, 1.0]},
                            {"id": tids["3"], "values": [1.0, 1.0]},
                        ],
                        "namespace": am.namespace,
                    }))
                ),
            ]
        );
    }

    // ---- continuous backfill rounds and upsert requests sized to the API limits ----
    //
    // The worker loop is a latch around `Scheduler::round`; between two rounds it waits
    // `worker::pause_after`. These tests run the rounds and add up the pauses instead of sleeping
    // them. `UpsertSize::counted_bytes` is what Pinecone counts against its 2 MB (4 bytes a value,
    // the id and the metadata), `wire_bytes` the JSON body.

    /// What the worker loop did for a table: rounds, naps (pauses of `worker_naptime_ms`) and the
    /// time its rounds worked.
    #[derive(Default)]
    struct LoopRun {
        rounds: u32,
        naps: u32,
        work: std::time::Duration,
        asleep: std::time::Duration,
    }

    impl LoopRun {
        fn total(&self) -> std::time::Duration {
            self.work + self.asleep
        }
    }

    fn worker_naptime() -> std::time::Duration {
        let ms = Spi::get_one::<String>("SHOW pinecone.worker_naptime_ms")
            .expect("SHOW worker_naptime_ms")
            .and_then(|ms| ms.parse::<u64>().ok());
        std::time::Duration::from_millis(ms.expect("a number of milliseconds"))
    }

    /// Rounds until `table`'s queue is empty, as the worker loop runs them.
    fn run_worker_loop(table: &str, cap: u32) -> LoopRun {
        let naptime = worker_naptime();
        let mut scheduler = crate::outbox::Scheduler::new();
        let mut run = LoopRun::default();
        loop {
            assert!(
                run.rounds < cap,
                "{table}: queue not empty after {cap} rounds"
            );
            let started = std::time::Instant::now();
            let round = scheduler.round();
            run.work += started.elapsed();
            run.rounds += 1;
            if outbox_count(table) == 0 {
                return run;
            }
            let pause = crate::worker::pause_after(round.chunks_left, naptime);
            if !pause.is_zero() {
                run.naps += 1;
                run.asleep += pause;
            }
        }
    }

    /// `rows` rows of `dims` full-precision floats (what an embedding model returns) and a
    /// `body` of `body_chars` characters.
    fn create_wide_table(table: &str, rows: i64, dims: i64, body_chars: i64) {
        create_extension_vector();
        fts_run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dims}), body text)"
        ));
        fts_run(&format!(
            "INSERT INTO {table} (id, embedding, body) SELECT i, (SELECT array_agg(\
             sin(i * 0.37 + j * 0.0113)::real ORDER BY j) FROM generate_series(1, {dims}) j)::vector, \
             left(repeat(md5(i::text), {body_chars} / 32 + 1), {body_chars}) \
             FROM generate_series(1, {rows}) i"
        ));
    }

    impl RoundEnv {
        /// The trigger lane over `rows` rows of `dims` floats; `body` is metadata when `with_body`.
        fn trigger_wide(
            table: &str,
            rows: i64,
            dims: i64,
            body_chars: i64,
            with_body: bool,
        ) -> Self {
            create_wide_table(table, rows, dims, body_chars);
            let (backend, vectors) = PartEnv::mock();
            let metadata = if with_body {
                ", metadata_columns => ARRAY['body']"
            } else {
                ""
            };
            fts_run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async'{metadata})",
                quote_literal(table),
                quote_literal(crate::promote::default_index_name("public", table))
            ));
            vectors.clear_calls();
            Self::of(backend, vectors, table)
        }

        fn access_method_wide(table: &str, rows: i64, dims: i64) -> Self {
            install_am_opclasses();
            create_wide_table(table, rows, dims, 0);
            Self::create_remote_index(table)
        }

        fn sizes(&self) -> Vec<crate::mock_backend::vectors::UpsertSize> {
            self.vectors.upsert_sizes()
        }
    }

    const REQUEST_LIMIT_BYTES: usize = 2_000_000;
    const REQUEST_LIMIT_RECORDS: usize = 1_000;

    /// Every request is accepted, within both limits and compact JSON (about 12 bytes a float on
    /// the wire for 4 counted).
    fn assert_within_the_limits(sizes: &[crate::mock_backend::vectors::UpsertSize]) {
        assert!(!sizes.is_empty(), "no upsert was sent");
        for (n, size) in sizes.iter().enumerate() {
            assert_eq!(size.status, 200, "request {n} was refused: {size:?}");
            assert!(
                size.records <= REQUEST_LIMIT_RECORDS,
                "request {n}: {size:?}"
            );
            assert!(
                size.counted_bytes <= REQUEST_LIMIT_BYTES,
                "request {n}: {size:?}"
            );
            assert!(
                size.wire_bytes <= 4 * size.counted_bytes,
                "request {n} is {} bytes of JSON for {} counted: {size:?}",
                size.wire_bytes,
                size.counted_bytes
            );
        }
    }

    /// 20,000 rows at 50 ms a request in rounds of 100 ms: several rounds, no nap between them, the
    /// time the requests take.
    #[pg_test]
    fn worker_loop_trigger_lane_20k_rows_do_not_nap_between_rounds() {
        let env = RoundEnv::trigger("loop_trigger_20k", ROUND_ROWS);
        fts_run("SET pinecone.backfill_round_ms = 100");
        env.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(50));

        let run = run_worker_loop(&env.table, 200);

        let before = std::time::Duration::from_secs(2) * (ROUND_ROWS as u32 / 1_000);
        assert!(run.rounds >= 5, "rounds of 100 ms: {} of them", run.rounds);
        assert_eq!(run.naps, 0, "{} naps in {} rounds", run.naps, run.rounds);
        assert!(
            run.total() < std::time::Duration::from_secs(8),
            "{:?} for 20 chunks, {before:?} with a nap after each",
            run.total()
        );
        assert_eq!(
            env.vectors.count(VecEndpoint::Upsert),
            20,
            "one request per chunk"
        );
        assert_eq!(
            env.vectors.record_count(&env.namespace),
            ROUND_ROWS as usize
        );
        assert_eq!(env.mode(), json!("remote"));
    }

    /// The same for the TID backfill of the access method.
    #[pg_test]
    fn worker_loop_access_method_20k_rows_do_not_nap_between_rounds() {
        let env = RoundEnv::access_method("loop_am_20k", ROUND_ROWS);
        fts_run("SET pinecone.backfill_round_ms = 100");
        env.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(50));

        let run = run_worker_loop(&env.table, 200);

        assert!(run.rounds >= 5, "rounds of 100 ms: {} of them", run.rounds);
        assert_eq!(run.naps, 0, "{} naps in {} rounds", run.naps, run.rounds);
        assert!(
            run.total() < std::time::Duration::from_secs(8),
            "{:?}",
            run.total()
        );
        let tids: BTreeSet<String> = ctid_map(&env.table).into_values().collect();
        assert_eq!(env.remote(), tids, "every row, by its TID, exactly once");
        assert_eq!(env.mode(), json!("remote"));
    }

    /// A job has chunks left from its first chunk to the one before the empty read that ends it:
    /// three rounds with a chunk each, then the round of the empty read.
    #[pg_test]
    fn worker_loop_a_round_reports_chunks_left_until_the_job_ends() {
        let env = RoundEnv::trigger("loop_reports", 2_500);
        fts_run("SET pinecone.backfill_round_ms = 50");
        env.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));
        let mut scheduler = crate::outbox::Scheduler::new();

        let rounds: Vec<crate::outbox::Round> = (0..4).map(|_| scheduler.round()).collect();

        let left: Vec<bool> = rounds.iter().map(|r| r.chunks_left).collect();
        assert_eq!(left, [true, true, true, false], "{rounds:?}");
        assert!(rounds.iter().all(|r| r.active), "{rounds:?}");
        assert_eq!(outbox_count(&env.table), 0);
        assert_eq!(env.mode(), json!("remote"));
        let idle = scheduler.round();
        assert!(
            !idle.active && !idle.chunks_left,
            "an empty queue naps: {idle:?}"
        );
    }

    /// Blocked work is not work left: a row Pinecone refuses backs the table off, so the loop naps
    /// and the table sits out its backoff window.
    #[pg_test]
    fn worker_loop_a_table_in_backoff_leaves_the_naps_alone() {
        let env = RoundEnv::trigger("loop_blocked", 2_500);
        fts_run("SET pinecone.backfill_round_ms = 60000");
        env.vectors.fail_always(VecEndpoint::Upsert, 400, "refused");
        let mut scheduler = crate::outbox::Scheduler::new();
        let naptime = worker_naptime();

        let failed = scheduler.round();

        assert_eq!(env.vectors.count(VecEndpoint::Upsert), 1);
        assert!(failed.active && !failed.chunks_left, "{failed:?}");
        assert_eq!(
            crate::worker::pause_after(failed.chunks_left, naptime),
            naptime
        );

        let waiting = scheduler.round();

        assert!(waiting.active && !waiting.chunks_left, "{waiting:?}");
        assert_eq!(
            env.vectors.count(VecEndpoint::Upsert),
            1,
            "the table sits out its backoff window"
        );
    }

    /// A table in backoff does not make the loop nap while another has chunks left; it naps once
    /// only the blocked one remains.
    #[pg_test]
    fn worker_loop_a_healthy_table_runs_on_while_another_is_in_backoff() {
        let (blocked, healthy) = ("loop_two_blocked", "loop_two_healthy");
        create_wide_table(blocked, 50, 2, 0);
        create_wide_table(healthy, 2_500, 2, 0);
        let (backend, vectors) = PartEnv::mock();
        for table in [blocked, healthy] {
            fts_run(&format!(
                "SELECT pinecone.promote({}, index_name => {}, sync_mode => 'async')",
                quote_literal(table),
                quote_literal(crate::promote::default_index_name("public", table))
            ));
        }
        vectors.clear_calls();
        vectors.fail_namespace(VecEndpoint::Upsert, &part_prefix(blocked), 400, "refused");
        fts_run("SET pinecone.backfill_round_ms = 50");
        vectors.set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));
        let mut scheduler = crate::outbox::Scheduler::new();

        let mut rounds = Vec::new();
        while outbox_count(healthy) > 0 && rounds.len() < 10 {
            rounds.push(scheduler.round());
        }

        let left: Vec<bool> = rounds.iter().map(|r| r.chunks_left).collect();
        assert_eq!(left, [true, true, true, false], "{rounds:?}");
        assert_eq!(part_status(healthy)["mode"], json!("remote"));
        assert!(outbox_count(blocked) > 0, "the blocked table waits");
        drop(backend);
    }

    /// A rebuild runs on round after round, and a live write issued meanwhile goes out in the next
    /// round, ahead of the rebuild's next chunk.
    #[pg_test]
    fn worker_loop_a_rebuild_runs_on_and_live_writes_go_out_each_round() {
        let table = "loop_rebuild";
        let env = part_with_failed_tenant(table, "async");
        part_heap_only_rows(table, 2, 100, 5_000);
        env.vectors.heal_all();
        env.run(&format!("SELECT {PART_RETRY}('{table}', 2)"));
        part_one_chunk_per_round(&env.vectors);
        let mut scheduler = crate::outbox::Scheduler::new();

        let first = scheduler.round();

        assert!(first.chunks_left, "the rebuild has chunks left: {first:?}");
        let sent = env.ids("2").len();
        assert!(
            sent > 0 && sent < 5_001,
            "one chunk of the load went out: {sent}"
        );
        env.insert("(900001, 3, '[1,0]', 'x')");

        let second = scheduler.round();

        assert!(
            env.ids("3").contains("900001"),
            "the write goes out in the next round"
        );
        assert!(second.chunks_left, "and the rebuild goes on: {second:?}");
        let mut rounds = 2;
        let mut last = second;
        while outbox_count(table) > 0 && rounds < 40 {
            last = scheduler.round();
            rounds += 1;
        }
        assert!(!last.chunks_left, "the rebuild is done: {last:?}");
        assert_eq!(env.ids("2").len(), 5_001);
        part_assert_matches_heap(&env, &[1, 2, 3]);
    }

    /// A write that arrives during a backfill waits behind the job and goes out in the round the
    /// job ends, with no round or nap of its own.
    #[pg_test]
    fn worker_loop_a_write_during_a_backfill_goes_out_when_the_job_ends() {
        let env = RoundEnv::trigger("loop_write_behind", 2_500);
        fts_run("SET pinecone.backfill_round_ms = 50");
        env.vectors
            .set_latency(VecEndpoint::Upsert, std::time::Duration::from_millis(60));
        let mut scheduler = crate::outbox::Scheduler::new();
        let naptime = worker_naptime();
        let mut naps = 0;

        let first = scheduler.round();
        fts_run("UPDATE loop_write_behind SET embedding = '[0,1]' WHERE id = 5");
        let mut rounds = 1;
        let mut round = first;
        while outbox_count(&env.table) > 0 && rounds < 10 {
            if !crate::worker::pause_after(round.chunks_left, naptime).is_zero() {
                naps += 1;
            }
            round = scheduler.round();
            rounds += 1;
        }

        assert_eq!(rounds, 4, "three chunks, then the empty read and the write");
        assert_eq!(naps, 0, "no nap on the way");
        let remote = env.vectors.record(&env.namespace, "5");
        assert_eq!(remote.map(|r| r["values"].clone()), Some(json!([0.0, 1.0])));
        assert_eq!(env.mode(), json!("remote"));
    }

    // ---- request sizes ----

    /// 6,000 rows of 768 floats, trigger lane: a request holds what the limits allow, about 610.
    #[pg_test]
    fn backfill_size_trigger_lane_768d_requests_fill_the_limits() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::trigger_wide("size_trigger_768", 6_000, 768, 0, false);

        env.rounds(10);

        let sizes = env.sizes();
        assert_within_the_limits(&sizes);
        assert!(
            sizes.len() <= 11,
            "{} requests for 6,000 rows (63 before)",
            sizes.len()
        );
        let (last, full) = sizes.split_last().expect("requests");
        assert!(
            full.iter().all(|s| s.counted_bytes >= 1_850_000),
            "every request but the last is full: {full:?}"
        );
        assert!(last.records > 0);
        assert_eq!(env.vectors.record_count(&env.namespace), 6_000);
        assert_eq!(env.mode(), json!("remote"));
    }

    /// The same for the TID backfill: a chunk ends before the heap block that would overflow its
    /// request, so a chunk is one request, nearly full.
    #[pg_test]
    fn backfill_size_access_method_768d_requests_fill_the_limits() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::access_method_wide("size_am_768", 6_000, 768);

        env.rounds(10);

        let sizes = env.sizes();
        assert_within_the_limits(&sizes);
        assert!(
            sizes.len() <= 14,
            "{} requests for 6,000 rows (88 before)",
            sizes.len()
        );
        let tids: BTreeSet<String> = ctid_map(&env.table).into_values().collect();
        assert_eq!(env.remote(), tids, "every row, by its TID, exactly once");
        assert_eq!(env.mode(), json!("remote"));
    }

    /// 2-d vectors are cut by the 1,000 records, and a TID chunk is one request of whole blocks.
    #[pg_test]
    fn backfill_size_access_method_small_vectors_fill_the_records_limit() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::access_method("size_am_2d", ROUND_ROWS);

        env.rounds(10);

        let sizes = env.sizes();
        assert!(
            sizes.iter().all(|s| s.status == 200 && s.records <= 1_000),
            "{sizes:?}"
        );
        assert!(
            sizes.len() <= 24,
            "{} requests for 20,000 rows (37 before)",
            sizes.len()
        );
    }

    /// Metadata counts: 12 KB of text a row leaves room for about 120 vectors of 768 floats.
    #[pg_test]
    fn backfill_size_counts_the_metadata() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::trigger_wide("size_metadata", 600, 768, 12_000, true);

        env.rounds(10);

        let sizes = env.sizes();
        assert_within_the_limits(&sizes);
        let (_, full) = sizes.split_last().expect("requests");
        assert!(
            full.iter()
                .all(|s| s.counted_bytes >= 1_850_000 && s.records < 130),
            "full requests of fewer, bigger records: {full:?}"
        );
        assert_eq!(env.vectors.record_count(&env.namespace), 600);
    }

    /// A partitioned index sends one request per namespace and window, each within the limits:
    /// 5 tenants of 400 rows, 768 floats each, read in one window of 2,000 rows.
    #[pg_test]
    fn backfill_size_partitioned_768d_sends_one_request_per_namespace_per_window() {
        install_am_opclasses();
        create_extension_vector();
        fts_run(
            "CREATE TABLE size_part_wide (id bigint PRIMARY KEY, tenant_id bigint NOT NULL, \
             embedding vector(768))",
        );
        fts_run(
            "INSERT INTO size_part_wide SELECT i, (i % 5) + 1, (SELECT array_agg(\
             sin(i * 0.37 + j * 0.0113)::real ORDER BY j) FROM generate_series(1, 768) j)::vector \
             FROM generate_series(1, 2000) i",
        );
        let (backend, vectors) = PartEnv::mock();
        fts_run(&PartAm::create_index_sql("size_part_wide"));
        vectors.clear_calls();
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::of(backend, vectors, "size_part_wide");

        env.rounds(10);

        let sizes = env.sizes();
        assert_within_the_limits(&sizes);
        let requests = partition_request_log(&env.vectors);
        assert_eq!(requests.len(), 5, "one request per tenant: {sizes:?}");
        assert!(
            requests
                .iter()
                .all(|(tenant, ids)| tenant.is_some() && ids.len() == 400)
        );
    }

    /// Live writes are packed the same way: one statement of 1,300 rows of 768 floats is 3 requests.
    #[pg_test]
    fn push_size_one_big_statement_goes_out_in_limit_sized_requests() {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::trigger_wide("size_push_768", 1, 768, 0, false);
        env.rounds(10);
        assert_eq!(env.mode(), json!("remote"));
        env.vectors.clear_calls();
        fts_run(
            "INSERT INTO size_push_768 (id, embedding) SELECT 1000 + i, (SELECT array_agg(\
             cos(i * 0.31 + j * 0.0071)::real ORDER BY j) FROM generate_series(1, 768) j)::vector \
             FROM generate_series(1, 1300) i",
        );

        env.rounds(10);

        let sizes = env.sizes();
        assert_within_the_limits(&sizes);
        assert!(
            sizes.len() <= 3,
            "{} requests for 1,300 rows (8 before)",
            sizes.len()
        );
        assert_eq!(env.vectors.record_count(&env.namespace), 1_301);
    }

    // ---- the first request of an access-method scan ----
    //
    // Nothing in Postgres 17 or 18 tells an index access method the `LIMIT` above it: the
    // executor's tuple bound (`ExecSetTupleBound`) stops at Sort, Append, Result, SubqueryScan and
    // Gather, `IndexScanDesc` has no field for it and `amrescan` gets the keys only. So the first
    // request asks for `pinecone.am_min_topk` and a scan that wants more asks again, four times
    // larger each time.

    /// A backfilled remote index over `rows` rows of the arc, its requests forgotten.
    fn scan_env(table: &str, rows: i64) -> RoundEnv {
        fts_run("SET pinecone.backfill_round_ms = 60000");
        let env = RoundEnv::access_method(table, rows);
        env.rounds(10);
        env.vectors.clear_calls();
        env
    }

    /// Ids of `ORDER BY embedding <=> '[1,0]' LIMIT k` under the current planner settings.
    fn scan_nearest(table: &str, k: i64) -> Vec<String> {
        let sql = format!(
            "SELECT coalesce(jsonb_agg(id::text ORDER BY ord), '[]'::jsonb) FROM (SELECT id, \
             row_number() OVER () AS ord FROM (SELECT id FROM {table} \
             ORDER BY embedding <=> '[1,0]'::vector LIMIT {k}) q) t"
        );
        let ids = Spi::get_one::<JsonB>(&sql)
            .expect("nearest")
            .expect("aggregate")
            .0;
        let ids = ids.as_array().cloned().unwrap_or_default();
        ids.iter()
            .filter_map(|i| i.as_str().map(str::to_string))
            .collect()
    }

    /// What the table itself says (a sequential scan and a sort), the ground truth of a scan.
    fn scan_exact(table: &str, k: i64) -> Vec<String> {
        fts_run("SET enable_indexscan = off");
        fts_run("SET enable_seqscan = on");
        let ids = scan_nearest(table, k);
        fts_run("SET enable_indexscan = on");
        fts_run("SET enable_seqscan = off");
        ids
    }

    /// The `topK` of every `/query` the mock received, in order.
    fn scan_top_ks(vectors: &VectorsHandle) -> Vec<u64> {
        let calls = vectors.calls_to(VecEndpoint::Query).into_iter();
        calls.filter_map(|c| c.body?["topK"].as_u64()).collect()
    }

    #[pg_test]
    fn guc_am_min_topk_defaults_to_100() {
        assert_eq!(
            Spi::get_one::<String>("SHOW pinecone.am_min_topk").expect("SHOW am_min_topk"),
            Some("100".to_string())
        );
    }

    /// `LIMIT 100` is one `/query` at the default settings, and returns the table's own 100 nearest
    /// rows: the recall of the scan is that of the remote index (exact here), whatever the size of
    /// the first request.
    #[pg_test]
    fn am_first_request_serves_limit_100_in_one_query() {
        let env = scan_env("scan_limit_100", 300);
        let exact = scan_exact(&env.table, 100);
        assert_eq!(exact.len(), 100);
        assert!(
            explain_lines(&format!(
                "SELECT id FROM {} ORDER BY embedding <=> '[1,0]'::vector LIMIT 100",
                env.table
            ))
            .iter()
            .any(|line| line.contains("Index Scan")),
            "the planner uses the index"
        );
        env.vectors.clear_calls();

        let ids = scan_nearest(&env.table, 100);

        assert_eq!(scan_top_ks(&env.vectors), [100], "one request");
        assert_eq!(ids, exact);
    }

    /// `LIMIT 10` is one request too (of the default size: the scan cannot tell it from `LIMIT 100`).
    #[pg_test]
    fn am_first_request_serves_limit_10_in_one_query() {
        let env = scan_env("scan_limit_10", 300);
        let exact = scan_exact(&env.table, 10);
        env.vectors.clear_calls();

        let ids = scan_nearest(&env.table, 10);

        assert_eq!(scan_top_ks(&env.vectors), [100]);
        assert_eq!(ids, exact);
    }

    /// With the old floor of 50 a `LIMIT 100` needs a second request of four times the size, and
    /// returns the same rows as the single request does.
    #[pg_test]
    fn am_first_request_below_the_limit_asks_again_four_times_larger() {
        let env = scan_env("scan_limit_50", 300);
        let exact = scan_exact(&env.table, 100);
        fts_run("SET pinecone.am_min_topk = 50");
        env.vectors.clear_calls();

        let ids = scan_nearest(&env.table, 100);

        assert_eq!(scan_top_ks(&env.vectors), [50, 200]);
        assert_eq!(ids, exact);
    }

    /// Past the default the second request is four times larger: `LIMIT 150` asks for 100, then 400.
    #[pg_test]
    fn am_first_request_limit_150_regrows_from_the_default() {
        let env = scan_env("scan_limit_150", 300);
        let exact = scan_exact(&env.table, 150);
        env.vectors.clear_calls();

        let ids = scan_nearest(&env.table, 150);

        assert_eq!(scan_top_ks(&env.vectors), [100, 400]);
        assert_eq!(ids, exact);
    }

    // =========================================================================
    // RaBitQ quantiser: recall, on-disk codes and format refusal. The math these pin lives in
    // `local::{rotation, rabitq, kernel}`, the f64 oracle in `local::testkit`.
    // =========================================================================

    use crate::local::testkit as tk;

    #[derive(Clone, Copy)]
    struct RqMetric {
        local: crate::local::metric::Metric,
        op: &'static str,
        opclass: &'static str,
    }

    const RQ_L2: RqMetric = RqMetric {
        local: crate::local::metric::Metric::L2,
        op: "<->",
        opclass: "vector_l2_ops",
    };
    const RQ_COSINE: RqMetric = RqMetric {
        local: crate::local::metric::Metric::Cosine,
        op: "<=>",
        opclass: "vector_cosine_ops",
    };
    const RQ_IP: RqMetric = RqMetric {
        local: crate::local::metric::Metric::Ip,
        op: "<#>",
        opclass: "vector_ip_ops",
    };

    fn rq_literal(v: &[f32]) -> String {
        let parts: Vec<String> = v.iter().map(f32::to_string).collect();
        format!("[{}]", parts.join(","))
    }

    /// `PLAIN` keeps a 768-d row inline: the exact seqscan oracle then reads the heap, not TOAST.
    fn rq_table(table: &str, dim: usize, extra_columns: &str) {
        install_am_opclasses();
        Spi::run(&format!(
            "CREATE TABLE {table} (id bigint PRIMARY KEY, embedding vector({dim}){extra_columns})"
        ))
        .expect("create table");
        Spi::run(&format!(
            "ALTER TABLE {table} ALTER COLUMN embedding SET STORAGE PLAIN"
        ))
        .expect("keep vectors inline");
    }

    /// Ids are `first_id..`; `tenant(id)` fills the `tenant` column when the table has one.
    fn rq_load(
        table: &str,
        first_id: i64,
        vectors: &[Vec<f32>],
        tenant: Option<&dyn Fn(i64) -> i64>,
    ) {
        const CHUNK: usize = 250;
        let columns = if tenant.is_some() { ", tenant" } else { "" };
        for (chunk_no, chunk) in vectors.chunks(CHUNK).enumerate() {
            let mut sql = format!("INSERT INTO {table} (id, embedding{columns}) VALUES ");
            for (i, v) in chunk.iter().enumerate() {
                let id = first_id + (chunk_no * CHUNK + i) as i64;
                if i > 0 {
                    sql.push(',');
                }
                sql.push_str(&format!("({id}, '{}'::vector", rq_literal(v)));
                if let Some(tenant) = tenant {
                    sql.push_str(&format!(", {}", tenant(id)));
                }
                sql.push(')');
            }
            Spi::run(&sql).expect("load vectors");
        }
    }

    /// Builds a native index named `<table>_idx`; `key` is an extra filter column (`", tenant"`).
    fn rq_index(table: &str, metric: RqMetric, key: &str, options: &str) -> String {
        let index = format!("{table}_idx");
        Spi::run(&format!(
            "CREATE INDEX {index} ON {table} USING pinecone (embedding {}{key}) \
             WITH (mode = 'local', {options})",
            metric.opclass
        ))
        .expect("create native pg_pinecone index");
        index
    }

    fn rq_assert_format_3(index: &str) {
        assert_eq!(
            am_format_of(index),
            (Some(3), true),
            "{index}: a fresh native build must be format 3 (RaBitQ codes)"
        );
    }

    fn rq_ids(sql: &str) -> Vec<i64> {
        Spi::connect(|client| {
            client
                .select(sql, None, &[])
                .expect("select ids")
                .map(|row| row.get_by_name::<i64, _>("id").unwrap().unwrap())
                .collect()
        })
    }

    fn rq_query_sql(
        table: &str,
        metric: RqMetric,
        where_sql: &str,
        query: &str,
        k: usize,
    ) -> String {
        format!(
            "SELECT id FROM {table} {where_sql} ORDER BY embedding {} '{query}'::vector LIMIT {k}",
            metric.op
        )
    }

    /// The exact answers: a seqscan with the pg_pinecone access method out of the planner's reach.
    fn rq_exact(
        table: &str,
        metric: RqMetric,
        where_sql: &str,
        queries: &[String],
        k: usize,
    ) -> Vec<Vec<i64>> {
        Spi::run("SET enable_seqscan = on").expect("seqscan on");
        Spi::run("SET pinecone.am_enabled = off").expect("am off");
        let out = queries
            .iter()
            .map(|q| rq_ids(&rq_query_sql(table, metric, where_sql, q, k)))
            .collect();
        Spi::run("SET pinecone.am_enabled = on").expect("am on");
        out
    }

    /// The answers of the pg_pinecone index (the planner is held to it; see [`rq_assert_uses_index`]).
    fn rq_via_index(
        table: &str,
        metric: RqMetric,
        where_sql: &str,
        queries: &[String],
        k: usize,
    ) -> Vec<Vec<i64>> {
        Spi::run("SET enable_seqscan = off").expect("seqscan off");
        Spi::run("SET pinecone.am_enabled = on").expect("am on");
        let out = queries
            .iter()
            .map(|q| rq_ids(&rq_query_sql(table, metric, where_sql, q, k)))
            .collect();
        Spi::run("SET enable_seqscan = on").expect("seqscan on");
        out
    }

    fn rq_assert_uses_index(table: &str, metric: RqMetric, where_sql: &str, query: &str) {
        Spi::run("SET enable_seqscan = off").expect("seqscan off");
        let plan = explain_lines(&rq_query_sql(table, metric, where_sql, query, 10)).join("\n");
        Spi::run("SET enable_seqscan = on").expect("seqscan on");
        assert!(
            plan.contains(&format!("{table}_idx")),
            "the query must run on the pg_pinecone index: {plan}"
        );
    }

    fn rq_recall(found: &[Vec<i64>], truth: &[Vec<i64>]) -> f64 {
        let (mut hits, mut slots) = (0usize, 0usize);
        for (f, t) in found.iter().zip(truth) {
            hits += t.iter().filter(|id| f.contains(id)).count();
            slots += t.len();
        }
        hits as f64 / slots as f64
    }

    fn rq_set_pool(multiplier: i32) {
        Spi::run(&format!("SET pinecone.rescore_multiplier = {multiplier}")).expect("set pool");
    }

    struct RqCase {
        spec: tk::MixtureSpec,
        metric: RqMetric,
        data_seed: u64,
        index_seed: u32,
        queries: &'static [RqQueries],
    }

    /// Where the queries of a recall check come from: the data's own distribution, the same vectors
    /// scaled to unit norm (far from centroids of norm ~10), the two interleaved, and isotropic unit
    /// vectors unrelated to the data's directions (a recall floor only: no one-bit estimate
    /// separates them well at pool 200).
    #[derive(Clone, Copy)]
    enum RqQueries {
        DataLike,
        UnitScaled,
        Mixed,
        IsotropicUnit,
    }

    /// Datasets for the recall tests: Gaussian mixtures with latent factors and noise, at 20,000 rows.
    /// A common offset (all components) makes the data anisotropic, as unnormalised embeddings are;
    /// `offset_cluster` has it on one component only.
    fn rq_case(name: &str) -> RqCase {
        let spec = |dim,
                    components,
                    centre_norm,
                    offset_norm,
                    rank: usize,
                    factor_var: f64,
                    noise_norm,
                    scale_range| {
            tk::MixtureSpec {
                dim,
                components,
                centre_norm,
                offset_norm,
                offset_components: 0,
                rank,
                factor_std: (factor_var / rank as f64).sqrt(),
                noise_norm,
                scale_range,
            }
        };
        const DATA_LIKE: &[RqQueries] = &[RqQueries::DataLike];
        match name {
            "mixture_768_cosine" => RqCase {
                spec: spec(768, 20, 1.0, 6.0, 128, 0.7, 1.5, None),
                metric: RQ_COSINE,
                data_seed: 0xA11CE,
                index_seed: 7,
                queries: DATA_LIKE,
            },
            "unnormalised_128_l2" => RqCase {
                spec: spec(128, 20, 1.0, 6.0, 64, 0.7, 1.0, None),
                metric: RQ_L2,
                data_seed: 0xB0B,
                index_seed: 11,
                queries: DATA_LIKE,
            },
            "offset_cluster_256_ip" => RqCase {
                spec: tk::MixtureSpec {
                    offset_components: 1,
                    ..spec(256, 16, 3.0, 10.0, 16, 2.0, 0.8, None)
                },
                metric: RQ_IP,
                data_seed: 0xC0FFEE,
                index_seed: 13,
                queries: &[
                    RqQueries::DataLike,
                    RqQueries::UnitScaled,
                    RqQueries::Mixed,
                    RqQueries::IsotropicUnit,
                ],
            },
            "common_offset_256_ip" => RqCase {
                spec: spec(256, 16, 2.0, 10.0, 16, 2.0, 0.8, None),
                metric: RQ_IP,
                data_seed: 0xC0FFEE,
                index_seed: 13,
                queries: DATA_LIKE,
            },
            "unnormalised_cosine_200" => RqCase {
                spec: spec(200, 20, 1.0, 4.0, 64, 0.7, 1.0, Some((0.01, 100.0))),
                metric: RQ_COSINE,
                data_seed: 0xD00D,
                index_seed: 17,
                queries: DATA_LIKE,
            },
            other => panic!("unknown case {other}"),
        }
    }

    const RQ_PROBED_LISTS: f64 = 25.0;

    /// Recall of the index at pool 200 and 1,000 against the exact seqscan, and against the
    /// exact-estimator ceiling: the same index with a pool larger than any probed set
    /// (`rescore_multiplier = 1000`), so every scanned record is rescored exactly and only the probed
    /// lists limit it.
    fn rq_recall_case(name: &str) {
        let case = rq_case(name);
        let (n, n_queries) = (20_000, 200);
        let data = tk::mixture(&case.spec, n, n_queries, case.data_seed);
        let table = format!("rq_recall_{name}");
        rq_table(&table, case.spec.dim, "");
        rq_load(&table, 1, &data.vectors, None);
        let index = rq_index(
            &table,
            case.metric,
            "",
            &format!("seed = {}", case.index_seed),
        );
        rq_assert_format_3(&index);
        Spi::run("SET pinecone.iterative_scan = 'off'").expect("no iterative scan");
        let n_lists = f64::from(index_meta(&index).n_lists);
        Spi::run(&format!(
            "SET pinecone.scan_fraction = {}",
            (RQ_PROBED_LISTS - 0.5) / n_lists
        ))
        .expect("probe the lists these thresholds were set at, not the calibrated count");

        let literals = |queries: &[Vec<f32>]| -> Vec<String> {
            queries.iter().map(|q| rq_literal(q)).collect()
        };
        for kind in case.queries {
            let (label, queries, floor_only) = match kind {
                RqQueries::DataLike => ("data-like queries", data.queries.clone(), false),
                RqQueries::UnitScaled => (
                    "data-like queries scaled to unit norm",
                    data.queries
                        .iter()
                        .take(100)
                        .map(|q| tk::unit_f32(q))
                        .collect(),
                    false,
                ),
                RqQueries::Mixed => (
                    "data-like and unit-norm queries interleaved",
                    data.queries
                        .iter()
                        .take(100)
                        .enumerate()
                        .map(|(i, q)| {
                            if i % 2 == 0 {
                                q.clone()
                            } else {
                                tk::unit_f32(q)
                            }
                        })
                        .collect(),
                    false,
                ),
                RqQueries::IsotropicUnit => {
                    let mut rng = tk::Rng::new(case.data_seed ^ 0xFA4);
                    (
                        "isotropic unit queries",
                        (0..100)
                            .map(|_| tk::to_f32(&rng.unit(case.spec.dim)))
                            .collect(),
                        true,
                    )
                }
            };
            rq_check_recall(
                &format!("{name}, {label}"),
                &table,
                case.metric,
                &literals(&queries),
                floor_only,
            );
        }
    }

    fn rq_check_recall(
        label: &str,
        table: &str,
        metric: RqMetric,
        queries: &[String],
        floor_only: bool,
    ) {
        rq_assert_uses_index(table, metric, "", &queries[0]);
        let truth = rq_exact(table, metric, "", queries, 10);
        if floor_only {
            rq_set_pool(10);
            let recall_1000 = rq_recall(&rq_via_index(table, metric, "", queries, 10), &truth);
            eprintln!("rabitq {label}: pool 1000 {recall_1000:.4}");
            assert!(
                recall_1000 >= 0.97,
                "{label}: recall@10 at pool 1000 is {recall_1000:.4}"
            );
            return;
        }

        let ceiling_queries = 40;
        rq_set_pool(1000);
        let ceiling_found = rq_via_index(table, metric, "", &queries[..ceiling_queries], 10);
        let ceiling = rq_recall(&ceiling_found, &truth[..ceiling_queries]);
        rq_set_pool(2);
        let pool_200 = rq_via_index(table, metric, "", queries, 10);
        let (recall_200, recall_200_on_ceiling_queries) = (
            rq_recall(&pool_200, &truth),
            rq_recall(&pool_200[..ceiling_queries], &truth[..ceiling_queries]),
        );
        rq_set_pool(10);
        let recall_1000 = rq_recall(&rq_via_index(table, metric, "", queries, 10), &truth);
        eprintln!(
            "rabitq {label}: exact-estimator ceiling {ceiling:.4}, pool 200 {recall_200:.4} \
             (same queries as the ceiling {recall_200_on_ceiling_queries:.4}), pool 1000 {recall_1000:.4}"
        );

        assert!(
            ceiling >= 0.99,
            "{label}: the probed lists must hold the neighbours (ceiling {ceiling:.4})"
        );
        assert!(
            recall_200_on_ceiling_queries >= 0.98 * ceiling,
            "{label}: pool 200 reaches {recall_200_on_ceiling_queries:.4} of the {ceiling:.4} an exact estimator gets on the same lists"
        );
        assert!(
            recall_200 >= 0.95,
            "{label}: recall@10 at pool 200 is {recall_200:.4}"
        );
        assert!(
            recall_1000 >= 0.99,
            "{label}: recall@10 at pool 1000 is {recall_1000:.4}"
        );
    }

    #[pg_test]
    fn rabitq_recall_mixture_768_cosine() {
        rq_recall_case("mixture_768_cosine");
    }

    #[pg_test]
    fn rabitq_recall_unnormalised_128_l2() {
        rq_recall_case("unnormalised_128_l2");
    }

    #[pg_test]
    fn rabitq_recall_offset_cluster_256_ip() {
        rq_recall_case("offset_cluster_256_ip");
    }

    #[pg_test]
    fn rabitq_recall_unnormalised_cosine_200() {
        rq_recall_case("unnormalised_cosine_200");
    }

    #[pg_test]
    fn rabitq_recall_common_offset_256_ip() {
        rq_recall_case("common_offset_256_ip");
    }

    struct RqRecord {
        tid: (u32, u16),
        bits: Vec<u64>,
        rnorm: f32,
        dot: f32,
        rc: f32,
        fval: i64,
        fnull: bool,
    }

    struct RqPages {
        dim: usize,
        seed: u64,
        centroids: Vec<Vec<f32>>,
        lists: Vec<Vec<RqRecord>>,
    }

    fn rq_page(index: &str, block: u32) -> Vec<u8> {
        Spi::get_one::<Vec<u8>>(&format!("SELECT get_raw_page('{index}', 'main', {block})"))
            .expect("get_raw_page")
            .expect("page is not NULL")
    }

    /// Where a list page's code blocks start (the page contents are 24 bytes into a page).
    const RQ_CODES_AT: usize = 40;

    /// The block width of a list page: the widest of 64, 32 and 16 records whose page holds the most
    /// records, found by trying every record count against the layout of `local::pages`' module docs
    /// (this is a second implementation of the rule, so the engine's cannot drift unseen).
    fn rq_block_geometry(code_bytes: usize, filtered: bool) -> (usize, usize) {
        let per = 20 + if filtered { 9 } else { 0 };
        let usable = 8168usize;
        let capacity = |lanes: usize| {
            (0..=usable)
                .rev()
                .find(|&n| {
                    n == 0
                        || RQ_CODES_AT + n.div_ceil(lanes) * lanes * code_bytes + n * per <= usable
                })
                .unwrap_or(0)
        };
        let mut best = (16, 0);
        for lanes in [64, 32, 16] {
            let c = capacity(lanes);
            if c > best.1 {
                best = (lanes, c);
            }
        }
        best
    }

    /// Reads a format-3 clustered index's directory and list pages. A list page is a header
    /// `(next_block u32, n u32)`, padding up to byte 40, then the arrays `codes (blocks of `lanes`
    /// records, byte-interleaved: byte j of record r of block b is at b * lanes * D/8 + j * lanes +
    /// r, the last block zero-padded), rnorm f32, dot f32, rc f32, pb u16 (the code's popcount),
    /// tids (block u32 + offset u16), [fvals i64, fnulls u8]`, each `n` long. The directory is
    /// unchanged: `(next, n)` then per entry `dim` f32, `list_head u32`, `list_count u32`.
    fn rq_decode(index: &str, filtered: bool) -> RqPages {
        rq_assert_format_3(index);
        let (dim, seed, directory, flat) = unsafe {
            let rel = pg_sys::RelationIdGetRelation(am_format_oid(index));
            let meta = crate::local::metapage::read(rel);
            pg_sys::RelationClose(rel);
            (
                meta.dim as usize,
                meta.seed,
                meta.centroid_dir_start,
                meta.is_flat,
            )
        };
        assert!(!flat, "{index}: decoding needs a clustered index");
        Spi::run("CREATE EXTENSION IF NOT EXISTS pageinspect").expect("create pageinspect");
        let invalid = crate::local::metapage::INVALID_BLOCK;
        let u32_at = |p: &[u8], at: usize| u32::from_le_bytes(p[at..at + 4].try_into().unwrap());
        let f32_at = |p: &[u8], at: usize| f32::from_le_bytes(p[at..at + 4].try_into().unwrap());
        let code_bytes = tk::padded(dim) / 8;
        let (lanes, _) = rq_block_geometry(code_bytes, filtered);
        assert!(code_bytes.is_multiple_of(8) && (24 + RQ_CODES_AT).is_multiple_of(64));

        let (mut centroids, mut heads) = (Vec::new(), Vec::new());
        let mut block = directory;
        while block != invalid {
            let page = rq_page(index, block);
            let body = &page[24..];
            let (next, n) = (u32_at(body, 0), u32_at(body, 4) as usize);
            for entry in 0..n {
                let at = 8 + entry * (dim * 4 + 8);
                centroids.push(
                    (0..dim)
                        .map(|i| f32_at(body, at + 4 * i))
                        .collect::<Vec<f32>>(),
                );
                heads.push(u32_at(body, at + 4 * dim));
            }
            block = next;
        }

        let lists = heads
            .iter()
            .map(|&head| {
                let mut records = Vec::new();
                let mut block = head;
                while block != invalid {
                    let page = rq_page(index, block);
                    let body = &page[24..];
                    let (next, n) = (u32_at(body, 0), u32_at(body, 4) as usize);
                    assert!(n > 0, "a list page is written with a record");
                    let block_bytes = lanes * code_bytes;
                    let rnorm_at = RQ_CODES_AT + n.div_ceil(lanes) * block_bytes;
                    let dot_at = rnorm_at + 4 * n;
                    let rc_at = dot_at + 4 * n;
                    let pb_at = rc_at + 4 * n;
                    let tid_at = pb_at + 2 * n;
                    let fval_at = tid_at + 6 * n;
                    let fnull_at = fval_at + 8 * n;
                    assert!(
                        body[8..RQ_CODES_AT].iter().all(|b| *b == 0),
                        "padding before the first block"
                    );
                    let byte = |i: usize, j: usize| {
                        body[RQ_CODES_AT + (i / lanes) * block_bytes + j * lanes + i % lanes]
                    };
                    for i in n..n.div_ceil(lanes) * lanes {
                        assert!((0..code_bytes).all(|j| byte(i, j) == 0), "dead lane {i}");
                    }
                    for i in 0..n {
                        let code: Vec<u8> = (0..code_bytes).map(|j| byte(i, j)).collect();
                        let pb = u16::from_le_bytes(
                            body[pb_at + 2 * i..pb_at + 2 * i + 2].try_into().unwrap(),
                        );
                        assert_eq!(
                            u32::from(pb),
                            code.iter().map(|b| b.count_ones()).sum::<u32>(),
                            "pb of record {i}"
                        );
                        records.push(RqRecord {
                            tid: (
                                u32_at(body, tid_at + 6 * i),
                                u16::from_le_bytes(
                                    body[tid_at + 6 * i + 4..tid_at + 6 * i + 6]
                                        .try_into()
                                        .unwrap(),
                                ),
                            ),
                            bits: code
                                .as_chunks::<8>()
                                .0
                                .iter()
                                .map(|w| u64::from_le_bytes(*w))
                                .collect(),
                            rnorm: f32_at(body, rnorm_at + 4 * i),
                            dot: f32_at(body, dot_at + 4 * i),
                            rc: f32_at(body, rc_at + 4 * i),
                            fval: if filtered {
                                i64::from_le_bytes(
                                    body[fval_at + 8 * i..fval_at + 8 * i + 8]
                                        .try_into()
                                        .unwrap(),
                                )
                            } else {
                                0
                            },
                            fnull: filtered && body[fnull_at + i] != 0,
                        });
                    }
                    block = next;
                }
                records
            })
            .collect();
        RqPages {
            dim,
            seed,
            centroids,
            lists,
        }
    }

    fn rq_tid_ids(table: &str) -> std::collections::HashMap<(u32, u16), i64> {
        Spi::connect(|client| {
            client
                .select(
                    &format!("SELECT ctid::text AS ctid, id FROM {table}"),
                    None,
                    &[],
                )
                .expect("select ctids")
                .map(|row| {
                    let ctid = row.get_by_name::<String, _>("ctid").unwrap().unwrap();
                    let (block, offset) = ctid
                        .trim_matches(|c| c == '(' || c == ')')
                        .split_once(',')
                        .unwrap();
                    (
                        (block.parse().unwrap(), offset.parse().unwrap()),
                        row.get_by_name::<i64, _>("id").unwrap().unwrap(),
                    )
                })
                .collect()
        })
    }

    /// Every live row is in exactly one list page record, and `sample` of them (spread over the
    /// lists), plus the rows `extra_ids` names, carry exactly the code, `rnorm`, `dot` and `rc` the
    /// f64 oracle derives from the stored vector and the list's centroid. Cosine indexes encode the
    /// unit vector `x / |x|`.
    fn rq_assert_pages_hold_reference_codes(
        index: &str,
        table: &str,
        metric: RqMetric,
        filtered: bool,
        sample: usize,
        extra_ids: &[i64],
    ) -> RqPages {
        let pages = rq_decode(index, filtered);
        let tids = rq_tid_ids(table);
        let mut seen = std::collections::HashSet::new();
        for record in pages.lists.iter().flatten() {
            assert!(
                tids.contains_key(&record.tid),
                "{index}: a record for TID {:?}, which is no heap row",
                record.tid
            );
            assert!(
                seen.insert(record.tid),
                "{index}: TID {:?} stored twice",
                record.tid
            );
        }
        assert_eq!(
            seen.len(),
            tids.len(),
            "{index}: every live row has exactly one record"
        );

        let oracle = tk::oracle_rotation(pages.seed, pages.dim);
        let sqrt_d = (oracle.dp as f64).sqrt();
        let positions: Vec<(usize, usize)> = pages
            .lists
            .iter()
            .enumerate()
            .flat_map(|(list, records)| (0..records.len()).map(move |i| (list, i)))
            .collect();
        let stride = (positions.len() / sample).max(1);
        let chosen: Vec<(usize, usize)> = positions
            .iter()
            .copied()
            .enumerate()
            .filter(|(k, (list, i))| {
                k % stride == 0 || extra_ids.contains(&tids[&pages.lists[*list][*i].tid])
            })
            .map(|(_, p)| p)
            .collect();
        assert!(
            chosen.len() >= sample.min(positions.len()),
            "{index}: sampled too few records"
        );
        for (list, i) in chosen {
            let record = &pages.lists[list][i];
            let id = tids[&record.tid];
            let stored = vector_of(table, id, "embedding").expect("stored vector");
            let x = if metric.local == crate::local::metric::Metric::Cosine {
                tk::unit_f32(&stored)
            } else {
                stored
            };
            let want = tk::oracle_encode(&oracle, &x, &pages.centroids[list]);
            let label = format!("{index}: list {list}, id {id}");
            assert_eq!(
                record.bits.len(),
                oracle.dp / 64,
                "{label}: code width is D bits"
            );
            let mut compared = 0;
            for bit in 0..oracle.dp {
                if want.rotated[bit].abs() * sqrt_d >= 1e-3 {
                    compared += 1;
                    assert_eq!(
                        tk::oracle_bit(&record.bits, bit),
                        tk::oracle_bit(&want.bits, bit),
                        "{label}: bit {bit}"
                    );
                }
            }
            assert!(
                compared + 8 >= oracle.dp,
                "{label}: fixture too close to bit flips"
            );
            assert!(
                (record.rnorm as f64 - want.rnorm).abs() <= 1e-5 * want.rnorm,
                "{label}: rnorm {} vs {}",
                record.rnorm,
                want.rnorm
            );
            assert!(
                (record.dot as f64 - want.dot).abs() <= 1e-5,
                "{label}: dot {} vs {}",
                record.dot,
                want.dot
            );
            assert!(
                (record.rc as f64 - want.rc).abs() <= 1e-4 * (1.0 + want.rc.abs()),
                "{label}: rc {} vs {}",
                record.rc,
                want.rc
            );
        }
        pages
    }

    /// What a fresh build of each metric stores, for unnormalised vectors with a
    /// norm spread (cosine must encode `x / |x|`) and a dimension that is not a multiple of 64.
    fn rq_pages_case(metric: RqMetric, table: &str) {
        let spec = tk::MixtureSpec {
            dim: 100,
            components: 12,
            centre_norm: 2.0,
            offset_norm: if metric.local == crate::local::metric::Metric::Ip {
                10.0
            } else {
                3.0
            },
            offset_components: 0,
            rank: 8,
            factor_std: 0.4,
            noise_norm: 0.8,
            scale_range: Some((0.05, 20.0)),
        };
        let data = tk::mixture(&spec, 2_400, 1, 0xDA7A);
        rq_table(table, spec.dim, "");
        rq_load(table, 1, &data.vectors, None);
        let index = rq_index(table, metric, "", "small_n_threshold = 100, seed = 31");
        let pages = rq_assert_pages_hold_reference_codes(&index, table, metric, false, 250, &[]);
        let non_empty = pages.lists.iter().filter(|l| !l.is_empty()).count();
        assert!(non_empty > 10, "clustered into several lists");
    }

