    fn calib_weak_mixture(dim: usize) -> tk::MixtureSpec {
        tk::MixtureSpec {
            dim,
            components: 50,
            centre_norm: 1.0,
            offset_norm: 0.0,
            offset_components: 0,
            rank: 4,
            factor_std: (0.3f64 / 4.0).sqrt(),
            noise_norm: 2.5,
            scale_range: None,
        }
    }

    fn calib_uniform(seed: u64, n: usize, dim: usize) -> Vec<Vec<f32>> {
        let mut rng = tk::Rng::new(seed);
        (0..n)
            .map(|_| (0..dim).map(|_| rng.uniform() as f32).collect())
            .collect()
    }

