            Spi::run(&format!(
                "CREATE INDEX {table}_idx ON {table} USING pinecone (embedding vector_l2_ops) \
                 WITH (mode = 'local', small_n_threshold = 100, seed = 5, n_lists = 1)"
            ))
            .expect("create index");
